@import "tailwindcss";

/* =========================================================
   PHARMAFLOW — DESIGN SYSTEM GLOBAL
   ========================================================= */

:root {
  --pf-primary: #0f766e;
  --pf-primary-dark: #115e59;
  --pf-primary-light: #ccfbf1;
  --pf-primary-soft: #f0fdfa;

  --pf-background: #f8fafc;
  --pf-surface: #ffffff;
  --pf-surface-soft: #f1f5f9;

  --pf-text: #0f172a;
  --pf-text-secondary: #475569;
  --pf-text-muted: #64748b;
  --pf-text-light: #94a3b8;

  --pf-border: #e2e8f0;
  --pf-border-light: #f1f5f9;

  --pf-success: #16a34a;
  --pf-success-bg: #f0fdf4;

  --pf-warning: #d97706;
  --pf-warning-bg: #fffbeb;

  --pf-danger: #dc2626;
  --pf-danger-bg: #fef2f2;

  --pf-info: #2563eb;
  --pf-info-bg: #eff6ff;

  --pf-radius-sm: 8px;
  --pf-radius-md: 12px;
  --pf-radius-lg: 16px;
  --pf-radius-xl: 20px;

  --pf-shadow-sm: 0 1px 3px rgba(15, 23, 42, 0.06);
  --pf-shadow-md:
    0 8px 25px rgba(15, 23, 42, 0.07);
  --pf-shadow-lg:
    0 20px 50px rgba(15, 23, 42, 0.1);

  --pf-sidebar-width: 260px;
  --pf-header-height: 72px;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  padding: 0;
  background: var(--pf-background);
  color: var(--pf-text);
  font-family:
    Arial,
    Helvetica,
    sans-serif;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
}

/* =========================================================
   SCROLLBAR
   ========================================================= */

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: #f1f5f9;
}

::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 999px;
}

::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}

/* =========================================================
   GLOBAL CONTAINER
   ========================================================= */

.pf-container {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
}

/* =========================================================
   LOGO
   ========================================================= */

.pf-logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--pf-text);
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.6px;
}

.pf-logo span {
  color: var(--pf-primary);
}

.pf-logo-icon {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: var(--pf-primary);
  color: white;
  box-shadow:
    0 8px 20px rgba(15, 118, 110, 0.22);
}

.pf-logo-icon svg {
  width: 23px;
  height: 23px;
}

/* =========================================================
   PUBLIC HEADER
   ========================================================= */

.pf-header {
  position: sticky;
  top: 0;
  z-index: 100;
  width: 100%;
  background: rgba(255, 255, 255, 0.94);
  border-bottom: 1px solid rgba(226, 232, 240, 0.85);
  backdrop-filter: blur(16px);
}

.pf-nav {
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
}

.pf-nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  color: var(--pf-text-secondary);
  font-size: 14px;
  font-weight: 600;
}

.pf-nav-links a {
  transition: color 0.2s ease;
}

.pf-nav-links a:hover {
  color: var(--pf-primary);
}

.pf-nav-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* =========================================================
   BUTTONS
   ========================================================= */

.pf-btn {
  min-height: 44px;
  padding: 0 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: var(--pf-radius-sm);
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease;
}

.pf-btn:hover {
  transform: translateY(-1px);
}

.pf-btn:active {
  transform: translateY(0);
}

.pf-btn-primary {
  background: var(--pf-primary);
  color: white;
  box-shadow:
    0 8px 18px rgba(15, 118, 110, 0.18);
}

.pf-btn-primary:hover {
  background: var(--pf-primary-dark);
  box-shadow:
    0 10px 24px rgba(15, 118, 110, 0.25);
}

.pf-btn-secondary {
  background: white;
  color: var(--pf-text-secondary);
  border-color: var(--pf-border);
}

.pf-btn-secondary:hover {
  background: #f8fafc;
  border-color: #cbd5e1;
}

.pf-btn-danger {
  background: var(--pf-danger);
  color: white;
}

.pf-btn-success {
  background: var(--pf-success);
  color: white;
}

.pf-btn-ghost {
  background: transparent;
  color: var(--pf-text-secondary);
}

.pf-btn-ghost:hover {
  background: var(--pf-surface-soft);
}

/* =========================================================
   PUBLIC HERO
   ========================================================= */

.pf-hero {
  position: relative;
  overflow: hidden;
  padding: 88px 0 80px;
  background:
    radial-gradient(
      circle at 82% 18%,
      rgba(20, 184, 166, 0.13),
      transparent 30%
    ),
    radial-gradient(
      circle at 10% 35%,
      rgba(15, 118, 110, 0.07),
      transparent 28%
    ),
    var(--pf-background);
}

.pf-hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  align-items: center;
  gap: 60px;
}

.pf-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  margin-bottom: 20px;
  border: 1px solid #bbf7d0;
  border-radius: 999px;
  background: #ecfdf5;
  color: #047857;
  font-size: 13px;
  font-weight: 700;
}

.pf-badge-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #10b981;
}

.pf-hero h1 {
  max-width: 700px;
  margin: 0;
  color: var(--pf-text);
  font-size: clamp(42px, 5vw, 68px);
  line-height: 1.03;
  letter-spacing: -3px;
  font-weight: 850;
}

.pf-hero h1 span {
  color: var(--pf-primary);
}

.pf-hero-description {
  max-width: 620px;
  margin: 24px 0 30px;
  color: var(--pf-text-muted);
  font-size: 18px;
  line-height: 1.75;
}

.pf-hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.pf-trial-note {
  margin-top: 16px;
  color: var(--pf-text-muted);
  font-size: 13px;
}

.pf-trial-note strong {
  color: var(--pf-text-secondary);
}

/* =========================================================
   PUBLIC DASHBOARD PREVIEW
   ========================================================= */

.pf-preview {
  position: relative;
}

.pf-preview-window {
  overflow: hidden;
  border: 1px solid #dbe5e3;
  border-radius: var(--pf-radius-xl);
  background: white;
  box-shadow: var(--pf-shadow-lg);
  transform: rotate(1deg);
}

.pf-preview-top {
  height: 48px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 17px;
  border-bottom: 1px solid var(--pf-border);
}

.pf-window-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #cbd5e1;
}

.pf-preview-body {
  display: grid;
  grid-template-columns: 105px 1fr;
  min-height: 360px;
}

.pf-preview-sidebar {
  padding: 17px 10px;
  background: #f8fafc;
  border-right: 1px solid var(--pf-border);
}

.pf-preview-menu {
  height: 31px;
  margin-bottom: 7px;
  border-radius: 7px;
  background: #e2e8f0;
}

.pf-preview-menu.active {
  background: #ccfbf1;
}

.pf-preview-content {
  padding: 22px;
}

.pf-preview-title {
  width: 150px;
  height: 16px;
  margin-bottom: 20px;
  border-radius: 5px;
  background: #0f172a;
}

.pf-preview-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 18px;
}

.pf-mini-card {
  padding: 13px;
  border: 1px solid var(--pf-border);
  border-radius: 10px;
}

.pf-mini-label {
  width: 55px;
  height: 7px;
  margin-bottom: 9px;
  border-radius: 4px;
  background: #cbd5e1;
}

.pf-mini-value {
  width: 65px;
  height: 13px;
  border-radius: 4px;
  background: var(--pf-primary);
}

.pf-chart {
  height: 150px;
  display: flex;
  align-items: flex-end;
  gap: 10px;
  padding: 20px;
  border: 1px solid var(--pf-border);
  border-radius: 10px;
}

.pf-bar {
  flex: 1;
  border-radius: 5px 5px 0 0;
  background: #99f6e4;
}

.pf-bar:nth-child(1) {
  height: 42%;
}

.pf-bar:nth-child(2) {
  height: 68%;
}

.pf-bar:nth-child(3) {
  height: 50%;
}

.pf-bar:nth-child(4) {
  height: 82%;
}

.pf-bar:nth-child(5) {
  height: 62%;
}

.pf-bar:nth-child(6) {
  height: 94%;
}

/* =========================================================
   PUBLIC TRUST
   ========================================================= */

.pf-trust {
  padding: 25px 0;
  border-top: 1px solid var(--pf-border);
  border-bottom: 1px solid var(--pf-border);
  background: white;
}

.pf-trust-content {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 30px;
  color: var(--pf-text-muted);
  font-size: 13px;
  font-weight: 600;
}

/* =========================================================
   PUBLIC SECTIONS
   ========================================================= */

.pf-section {
  padding: 90px 0;
  background: white;
}

.pf-section-muted {
  background: var(--pf-background);
}

.pf-section-header {
  max-width: 720px;
  margin: 0 auto 48px;
  text-align: center;
}

.pf-eyebrow {
  margin-bottom: 10px;
  color: var(--pf-primary);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 1.3px;
  text-transform: uppercase;
}

.pf-section h2 {
  margin: 0;
  color: var(--pf-text);
  font-size: clamp(30px, 4vw, 43px);
  line-height: 1.15;
  letter-spacing: -1.6px;
}

.pf-section-description {
  max-width: 620px;
  margin: 16px auto 0;
  color: var(--pf-text-muted);
  font-size: 16px;
  line-height: 1.7;
}

/* =========================================================
   FEATURE CARDS
   ========================================================= */

.pf-features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}

.pf-feature-card {
  padding: 28px;
  border: 1px solid var(--pf-border);
  border-radius: var(--pf-radius-lg);
  background: white;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    border-color 0.2s ease;
}

.pf-feature-card:hover {
  transform: translateY(-4px);
  border-color: #99f6e4;
  box-shadow: var(--pf-shadow-md);
}

.pf-feature-icon {
  width: 48px;
  height: 48px;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: var(--pf-primary-light);
  color: var(--pf-primary);
}

.pf-feature-icon svg {
  width: 23px;
  height: 23px;
}

.pf-feature-card h3 {
  margin: 0 0 9px;
  color: var(--pf-text);
  font-size: 18px;
}

.pf-feature-card p {
  margin: 0;
  color: var(--pf-text-muted);
  font-size: 14px;
  line-height: 1.7;
}

/* =========================================================
   STEPS
   ========================================================= */

.pf-steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}

.pf-step {
  padding: 30px;
  border: 1px solid var(--pf-border);
  border-radius: var(--pf-radius-lg);
  background: white;
}

.pf-step-number {
  width: 38px;
  height: 38px;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--pf-primary);
  color: white;
  font-size: 13px;
  font-weight: 800;
}

.pf-step h3 {
  margin: 0 0 9px;
  font-size: 18px;
}

.pf-step p {
  margin: 0;
  color: var(--pf-text-muted);
  font-size: 14px;
  line-height: 1.7;
}

/* =========================================================
   SECURITY
   ========================================================= */

.pf-security {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  align-items: center;
  gap: 60px;
}

.pf-security-box {
  padding: 35px;
  border-radius: var(--pf-radius-xl);
  background: #0f172a;
  color: white;
  box-shadow: var(--pf-shadow-lg);
}

.pf-security-icon {
  width: 55px;
  height: 55px;
  margin-bottom: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  background: rgba(20, 184, 166, 0.18);
  color: #5eead4;
}

.pf-security-icon svg {
  width: 27px;
  height: 27px;
}

.pf-security-box h3 {
  margin: 0 0 12px;
  font-size: 24px;
}

.pf-security-box p {
  margin: 0;
  color: #cbd5e1;
  font-size: 14px;
  line-height: 1.7;
}

.pf-security-list {
  display: grid;
  gap: 20px;
}

.pf-security-item {
  display: flex;
  gap: 15px;
}

.pf-check {
  width: 26px;
  height: 26px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--pf-primary-light);
  color: var(--pf-primary);
  font-weight: 900;
}

.pf-security-item h4 {
  margin: 0 0 5px;
  font-size: 16px;
}

.pf-security-item p {
  margin: 0;
  color: var(--pf-text-muted);
  font-size: 14px;
  line-height: 1.6;
}

/* =========================================================
   CTA
   ========================================================= */

.pf-cta {
  padding: 90px 0;
  background: var(--pf-primary);
  color: white;
}

.pf-cta-box {
  text-align: center;
}

.pf-cta h2 {
  max-width: 720px;
  margin: 0 auto;
  color: white;
  font-size: clamp(32px, 4vw, 48px);
  line-height: 1.12;
  letter-spacing: -1.7px;
}

.pf-cta p {
  max-width: 600px;
  margin: 17px auto 27px;
  color: #ccfbf1;
  line-height: 1.7;
}

.pf-cta .pf-btn-primary {
  background: white;
  color: var(--pf-primary);
  box-shadow: none;
}

.pf-cta .pf-btn-primary:hover {
  background: #f0fdfa;
}

/* =========================================================
   FOOTER
   ========================================================= */

.pf-footer {
  padding: 55px 0 25px;
  background: #0f172a;
  color: white;
}

.pf-footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 40px;
  padding-bottom: 45px;
}

.pf-footer .pf-logo {
  color: white;
}

.pf-footer-description {
  max-width: 330px;
  margin-top: 17px;
  color: #94a3b8;
  font-size: 14px;
  line-height: 1.7;
}

.pf-footer-column h4 {
  margin: 0 0 17px;
  color: white;
  font-size: 14px;
}

.pf-footer-column a {
  display: block;
  margin-bottom: 11px;
  color: #94a3b8;
  font-size: 13px;
  transition: color 0.2s ease;
}

.pf-footer-column a:hover {
  color: white;
}

.pf-footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
  border-top: 1px solid #1e293b;
  color: #64748b;
  font-size: 12px;
}

/* =========================================================
   =========================================================
   PHARMAFLOW APPLICATION
   =========================================================
   ========================================================= */

/* =========================================================
   APP LAYOUT
   ========================================================= */

.pf-app {
  min-height: 100vh;
  background: var(--pf-background);
}

.pf-app-layout {
  min-height: 100vh;
  display: flex;
}

/* =========================================================
   SIDEBAR
   ========================================================= */

.pf-sidebar {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 200;
  width: var(--pf-sidebar-width);
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: #ffffff;
  border-right: 1px solid var(--pf-border);
}

.pf-sidebar-brand {
  height: var(--pf-header-height);
  display: flex;
  align-items: center;
  padding: 0 20px;
  border-bottom: 1px solid var(--pf-border);
}

.pf-sidebar-nav {
  flex: 1;
  overflow-y: auto;
  padding: 18px 12px;
}

.pf-sidebar-section-title {
  padding: 10px 12px 7px;
  color: var(--pf-text-light);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
  text-transform: uppercase;
}

.pf-sidebar-link {
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 4px;
  padding: 0 12px;
  border-radius: 10px;
  color: var(--pf-text-secondary);
  font-size: 14px;
  font-weight: 600;
  transition:
    background 0.18s ease,
    color 0.18s ease;
}

.pf-sidebar-link:hover {
  background: var(--pf-primary-soft);
  color: var(--pf-primary);
}

.pf-sidebar-link.active {
  background: var(--pf-primary-light);
  color: var(--pf-primary-dark);
}

.pf-sidebar-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pf-sidebar-icon svg {
  width: 19px;
  height: 19px;
}

.pf-sidebar-footer {
  padding: 12px;
  border-top: 1px solid var(--pf-border);
}

/* =========================================================
   APP MAIN
   ========================================================= */

.pf-app-main {
  width: calc(100% - var(--pf-sidebar-width));
  min-height: 100vh;
  margin-left: var(--pf-sidebar-width);
}

/* =========================================================
   APP HEADER
   ========================================================= */

.pf-app-header {
  position: sticky;
  top: 0;
  z-index: 80;
  height: var(--pf-header-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 0 28px;
  background: rgba(255, 255, 255, 0.95);
  border-bottom: 1px solid var(--pf-border);
  backdrop-filter: blur(12px);
}

.pf-app-header-left {
  display: flex;
  align-items: center;
  gap: 15px;
}

.pf-app-header-title {
  margin: 0;
  color: var(--pf-text);
  font-size: 18px;
  font-weight: 800;
}

.pf-app-header-subtitle {
  margin: 3px 0 0;
  color: var(--pf-text-muted);
  font-size: 12px;
}

.pf-app-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* =========================================================
   USER MENU
   ========================================================= */

.pf-user-menu {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pf-user-avatar {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--pf-primary-light);
  color: var(--pf-primary-dark);
  font-size: 13px;
  font-weight: 800;
}

.pf-user-info {
  min-width: 0;
}

.pf-user-name {
  margin: 0;
  color: var(--pf-text);
  font-size: 13px;
  font-weight: 700;
}

.pf-user-role {
  margin: 2px 0 0;
  color: var(--pf-text-muted);
  font-size: 11px;
}

/* =========================================================
   MOBILE MENU BUTTON
   ========================================================= */

.pf-mobile-menu {
  width: 40px;
  height: 40px;
  display: none;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--pf-border);
  border-radius: 9px;
  background: white;
  color: var(--pf-text);
}

/* =========================================================
   PAGE CONTENT
   ========================================================= */

.pf-page {
  padding: 28px;
}

.pf-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 25px;
}

.pf-page-title {
  margin: 0;
  color: var(--pf-text);
  font-size: 26px;
  line-height: 1.2;
  letter-spacing: -0.6px;
  font-weight: 800;
}

.pf-page-description {
  margin: 7px 0 0;
  color: var(--pf-text-muted);
  font-size: 13px;
  line-height: 1.6;
}

.pf-page-actions {
  display: flex;
  align-items: center;
  gap: 9px;
}

/* =========================================================
   STAT CARDS
   ========================================================= */

.pf-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 22px;
}

.pf-stat-card {
  padding: 20px;
  border: 1px solid var(--pf-border);
  border-radius: var(--pf-radius-md);
  background: white;
  box-shadow: var(--pf-shadow-sm);
}

.pf-stat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.pf-stat-label {
  color: var(--pf-text-muted);
  font-size: 12px;
  font-weight: 600;
}

.pf-stat-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: var(--pf-primary-light);
  color: var(--pf-primary);
}

.pf-stat-icon svg {
  width: 18px;
  height: 18px;
}

.pf-stat-value {
  margin-top: 12px;
  color: var(--pf-text);
  font-size: 25px;
  line-height: 1;
  font-weight: 800;
}

.pf-stat-change {
  margin-top: 9px;
  font-size: 11px;
  font-weight: 700;
}

.pf-stat-change.positive {
  color: var(--pf-success);
}

.pf-stat-change.negative {
  color: var(--pf-danger);
}

.pf-stat-change.neutral {
  color: var(--pf-text-muted);
}

/* =========================================================
   CARDS
   ========================================================= */

.pf-card {
  border: 1px solid var(--pf-border);
  border-radius: var(--pf-radius-md);
  background: white;
  box-shadow: var(--pf-shadow-sm);
}

.pf-card-header {
  min-height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 0 20px;
  border-bottom: 1px solid var(--pf-border);
}

.pf-card-title {
  margin: 0;
  color: var(--pf-text);
  font-size: 15px;
  font-weight: 800;
}

.pf-card-description {
  margin: 4px 0 0;
  color: var(--pf-text-muted);
  font-size: 11px;
}

.pf-card-body {
  padding: 20px;
}

/* =========================================================
   GRID
   ========================================================= */

.pf-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
}

.pf-grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}

.pf-grid-main {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 18px;
}

/* =========================================================
   TABLE
   ========================================================= */

.pf-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.pf-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 650px;
}

.pf-table th {
  padding: 12px 15px;
  border-bottom: 1px solid var(--pf-border);
  background: #f8fafc;
  color: var(--pf-text-muted);
  font-size: 11px;
  font-weight: 800;
  text-align: left;
  white-space: nowrap;
}

.pf-table td {
  padding: 14px 15px;
  border-bottom: 1px solid var(--pf-border-light);
  color: var(--pf-text-secondary);
  font-size: 12px;
  vertical-align: middle;
}

.pf-table tbody tr:hover {
  background: #fafafa;
}

.pf-table tbody tr:last-child td {
  border-bottom: 0;
}

/* =========================================================
   BADGES
   ========================================================= */

.pf-status {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 9px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
}

.pf-status-success {
  background: var(--pf-success-bg);
  color: var(--pf-success);
}

.pf-status-warning {
  background: var(--pf-warning-bg);
  color: var(--pf-warning);
}

.pf-status-danger {
  background: var(--pf-danger-bg);
  color: var(--pf-danger);
}

.pf-status-info {
  background: var(--pf-info-bg);
  color: var(--pf-info);
}

.pf-status-neutral {
  background: #f1f5f9;
  color: var(--pf-text-secondary);
}

/* =========================================================
   FORMS
   ========================================================= */

.pf-form {
  display: grid;
  gap: 18px;
}

.pf-form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.pf-form-grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.pf-field {
  display: grid;
  gap: 7px;
}

.pf-field-full {
  grid-column: 1 / -1;
}

.pf-label {
  color: var(--pf-text-secondary);
  font-size: 12px;
  font-weight: 700;
}

.pf-input,
.pf-select,
.pf-textarea {
  width: 100%;
  min-height: 44px;
  padding: 0 13px;
  border: 1px solid #cbd5e1;
  border-radius: 9px;
  outline: none;
  background: white;
  color: var(--pf-text);
  font-size: 13px;
  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}

.pf-textarea {
  min-height: 100px;
  padding-top: 11px;
  padding-bottom: 11px;
  resize: vertical;
}

.pf-input::placeholder,
.pf-textarea::placeholder {
  color: #94a3b8;
}

.pf-input:focus,
.pf-select:focus,
.pf-textarea:focus {
  border-color: var(--pf-primary);
  box-shadow:
    0 0 0 3px rgba(15, 118, 110, 0.1);
}

.pf-input:disabled,
.pf-select:disabled,
.pf-textarea:disabled {
  background: #f8fafc;
  color: var(--pf-text-muted);
  cursor: not-allowed;
}

.pf-form-help {
  color: var(--pf-text-muted);
  font-size: 11px;
  line-height: 1.5;
}

.pf-form-error {
  color: var(--pf-danger);
  font-size: 11px;
  font-weight: 600;
}

/* =========================================================
   SEARCH
   ========================================================= */

.pf-search {
  position: relative;
}

.pf-search input {
  padding-left: 40px;
}

.pf-search-icon {
  position: absolute;
  top: 50%;
  left: 13px;
  width: 17px;
  height: 17px;
  transform: translateY(-50%);
  color: var(--pf-text-light);
}

/* =========================================================
   EMPTY STATE
   ========================================================= */

.pf-empty {
  padding: 55px 25px;
  text-align: center;
}

.pf-empty-icon {
  width: 55px;
  height: 55px;
  margin: 0 auto 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 15px;
  background: var(--pf-primary-light);
  color: var(--pf-primary);
}

.pf-empty-icon svg {
  width: 25px;
  height: 25px;
}

.pf-empty h3 {
  margin: 0 0 7px;
  color: var(--pf-text);
  font-size: 16px;
}

.pf-empty p {
  max-width: 400px;
  margin: 0 auto;
  color: var(--pf-text-muted);
  font-size: 12px;
  line-height: 1.6;
}

/* =========================================================
   ALERTS
   ========================================================= */

.pf-alert {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: 13px 15px;
  border: 1px solid;
  border-radius: 10px;
  font-size: 12px;
  line-height: 1.5;
}

.pf-alert-success {
  border-color: #bbf7d0;
  background: var(--pf-success-bg);
  color: #166534;
}

.pf-alert-warning {
  border-color: #fde68a;
  background: var(--pf-warning-bg);
  color: #92400e;
}

.pf-alert-danger {
  border-color: #fecaca;
  background: var(--pf-danger-bg);
  color: #991b1b;
}

.pf-alert-info {
  border-color: #bfdbfe;
  background: var(--pf-info-bg);
  color: #1e40af;
}

/* =========================================================
   MODAL
   ========================================================= */

.pf-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(15, 23, 42, 0.5);
  backdrop-filter: blur(4px);
}

.pf-modal {
  width: min(560px, 100%);
  max-height: calc(100vh - 40px);
  overflow-y: auto;
  border-radius: var(--pf-radius-lg);
  background: white;
  box-shadow: var(--pf-shadow-lg);
}

.pf-modal-header {
  min-height: 65px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  border-bottom: 1px solid var(--pf-border);
}

.pf-modal-title {
  margin: 0;
  color: var(--pf-text);
  font-size: 17px;
  font-weight: 800;
}

.pf-modal-close {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--pf-text-muted);
}

.pf-modal-close:hover {
  background: var(--pf-surface-soft);
  color: var(--pf-text);
}

.pf-modal-body {
  padding: 20px;
}

.pf-modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding: 15px 20px;
  border-top: 1px solid var(--pf-border);
}

/* =========================================================
   LOADING
   ========================================================= */

.pf-spinner {
  width: 19px;
  height: 19px;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: white;
  border-radius: 50%;
  animation: pf-spin 0.7s linear infinite;
}

.pf-spinner-dark {
  border-color: rgba(15, 118, 110, 0.2);
  border-top-color: var(--pf-primary);
}

@keyframes pf-spin {
  to {
    transform: rotate(360deg);
  }
}

.pf-loading {
  min-height: 250px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* =========================================================
   AUTHENTICATION PAGES
   ========================================================= */

.pf-auth-page {
  min-height: 100vh;
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: var(--pf-background);
}

.pf-auth-brand {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 50px;
  background:
    radial-gradient(
      circle at 70% 20%,
      rgba(45, 212, 191, 0.18),
      transparent 30%
    ),
    #0f766e;
  color: white;
}

.pf-auth-brand-content {
  width: min(500px, 100%);
}

.pf-auth-brand .pf-logo {
  color: white;
  margin-bottom: 60px;
}

.pf-auth-brand .pf-logo span {
  color: #99f6e4;
}

.pf-auth-brand h1 {
  margin: 0;
  color: white;
  font-size: clamp(36px, 4vw, 55px);
  line-height: 1.08;
  letter-spacing: -2px;
}

.pf-auth-brand-description {
  max-width: 480px;
  margin: 20px 0 30px;
  color: #ccfbf1;
  font-size: 16px;
  line-height: 1.7;
}

.pf-auth-benefits {
  display: grid;
  gap: 14px;
}

.pf-auth-benefit {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #ecfdf5;
  font-size: 13px;
  font-weight: 600;
}

.pf-auth-benefit-check {
  width: 23px;
  height: 23px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.15);
}

.pf-auth-form-side {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  background: white;
}

.pf-auth-form-container {
  width: min(460px, 100%);
}

.pf-auth-mobile-logo {
  display: none;
}

.pf-auth-header {
  margin-bottom: 28px;
}

.pf-auth-title {
  margin: 0;
  color: var(--pf-text);
  font-size: 30px;
  line-height: 1.2;
  letter-spacing: -0.8px;
  font-weight: 800;
}

.pf-auth-description {
  margin: 9px 0 0;
  color: var(--pf-text-muted);
  font-size: 13px;
  line-height: 1.6;
}

.pf-auth-form {
  display: grid;
  gap: 16px;
}

.pf-auth-footer {
  margin-top: 22px;
  color: var(--pf-text-muted);
  font-size: 12px;
  text-align: center;
}

.pf-auth-footer a {
  color: var(--pf-primary);
  font-weight: 700;
}

.pf-auth-footer a:hover {
  text-decoration: underline;
}

/* =========================================================
   SUPPORT
   ========================================================= */

.pf-support-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}

.pf-support-card {
  padding: 26px;
  border: 1px solid var(--pf-border);
  border-radius: var(--pf-radius-lg);
  background: white;
}

.pf-support-card h3 {
  margin: 0 0 8px;
  font-size: 17px;
}

.pf-support-card p {
  margin: 0;
  color: var(--pf-text-muted);
  font-size: 13px;
  line-height: 1.6;
}

.pf-support-contact {
  display: inline-flex;
  margin-top: 17px;
  color: var(--pf-primary);
  font-size: 13px;
  font-weight: 700;
}

/* =========================================================
   RESPONSIVE — TABLET
   ========================================================= */

@media (max-width: 1050px) {
  .pf-nav-links {
    gap: 18px;
  }

  .pf-hero-grid {
    gap: 35px;
  }

  .pf-stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pf-grid-main {
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   RESPONSIVE — MOBILE
   ========================================================= */

@media (max-width: 900px) {
  .pf-nav-links {
    display: none;
  }

  .pf-hero-grid {
    grid-template-columns: 1fr;
  }

  .pf-preview {
    max-width: 650px;
    margin: 0 auto;
  }

  .pf-features,
  .pf-steps,
  .pf-support-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pf-security {
    grid-template-columns: 1fr;
  }

  .pf-footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pf-auth-page {
    grid-template-columns: 1fr;
  }

  .pf-auth-brand {
    display: none;
  }

  .pf-auth-mobile-logo {
    display: inline-flex;
    margin-bottom: 30px;
  }

  .pf-auth-form-side {
    min-height: 100vh;
  }

  .pf-sidebar {
    transform: translateX(-100%);
    transition: transform 0.25s ease;
  }

  .pf-sidebar.open {
    transform: translateX(0);
  }

  .pf-app-main {
    width: 100%;
    margin-left: 0;
  }

  .pf-mobile-menu {
    display: flex;
  }
}

/* =========================================================
   RESPONSIVE — SMALL MOBILE
   ========================================================= */

@media (max-width: 620px) {
  .pf-container {
    width: min(100% - 28px, 1180px);
  }

  .pf-nav {
    min-height: 66px;
  }

  .pf-logo {
    font-size: 20px;
  }

  .pf-logo-icon {
    width: 37px;
    height: 37px;
  }

  .pf-nav-actions .pf-btn-secondary {
    display: none;
  }

  .pf-hero {
    padding: 55px 0 50px;
  }

  .pf-hero h1 {
    font-size: 42px;
    letter-spacing: -2px;
  }

  .pf-hero-description {
    font-size: 16px;
  }

  .pf-hero-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .pf-hero-actions .pf-btn {
    width: 100%;
  }

  .pf-preview-body {
    grid-template-columns: 70px 1fr;
  }

  .pf-preview-content {
    padding: 13px;
  }

  .pf-preview-cards {
    gap: 6px;
  }

  .pf-mini-card {
    padding: 8px;
  }

  .pf-features,
  .pf-steps,
  .pf-support-grid,
  .pf-stats-grid,
  .pf-grid-2,
  .pf-grid-3,
  .pf-form-grid,
  .pf-form-grid-3 {
    grid-template-columns: 1fr;
  }

  .pf-section {
    padding: 65px 0;
  }

  .pf-security {
    gap: 35px;
  }

  .pf-footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 30px 20px;
  }

  .pf-footer-bottom {
    flex-direction: column;
  }

  .pf-page {
    padding: 20px 14px;
  }

  .pf-page-header {
    flex-direction: column;
  }

  .pf-page-title {
    font-size: 23px;
  }

  .pf-page-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .pf-page-actions .pf-btn {
    flex: 1;
  }

  .pf-app-header {
    padding: 0 14px;
  }

  .pf-user-info {
    display: none;
  }

  .pf-auth-form-side {
    padding: 25px 18px;
  }

  .pf-auth-title {
    font-size: 27px;
  }
}
/* =========================================================
   PHARMAFLOW — REGISTER PREMIUM
========================================================= */

.pf-register-page {
  min-height: 100vh;
  width: 100%;
  display: grid;
  grid-template-columns: minmax(540px, 1fr) minmax(500px, 0.92fr);
  background: #ffffff;
}


/* =========================================================
   SHOWCASE
========================================================= */

.pf-register-showcase {
  position: relative;
  min-height: 100vh;
  overflow: hidden;
  background:
    radial-gradient(
      circle at 12% 12%,
      rgba(255,255,255,.13),
      transparent 25%
    ),
    radial-gradient(
      circle at 88% 78%,
      rgba(255,255,255,.10),
      transparent 30%
    ),
    linear-gradient(
      140deg,
      #075c57 0%,
      #087970 48%,
      #0c9185 100%
    );
}

.pf-register-showcase::before {
  content: "";
  position: absolute;
  width: 650px;
  height: 650px;
  top: -330px;
  right: -300px;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 50%;
}

.pf-register-showcase::after {
  content: "";
  position: absolute;
  width: 500px;
  height: 500px;
  bottom: -340px;
  left: -300px;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 50%;
}

.pf-register-decoration {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

.pf-register-decoration-one {
  width: 9px;
  height: 9px;
  top: 23%;
  right: 16%;
  background: rgba(255,255,255,.27);
  box-shadow:
    0 0 0 7px rgba(255,255,255,.04),
    0 0 0 14px rgba(255,255,255,.025);
}

.pf-register-decoration-two {
  width: 6px;
  height: 6px;
  bottom: 29%;
  left: 13%;
  background: rgba(255,255,255,.22);
}

.pf-register-showcase-inner {
  position: relative;
  z-index: 2;
  width: min(100%, 760px);
  min-height: 100vh;
  margin: 0 auto;
  padding: 42px 58px 28px;
  display: flex;
  flex-direction: column;
}


/* =========================================================
   LOGO
========================================================= */

.pf-register-logo,
.pf-register-mobile-logo {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  width: fit-content;
  text-decoration: none;
}

.pf-register-logo-mark {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pf-register-logo-mark svg {
  width: 40px;
  height: 40px;
}

.pf-register-logo-text {
  color: white;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -.8px;
}

.pf-register-logo-text span {
  font-weight: 500;
  opacity: .9;
}


/* =========================================================
   SHOWCASE CONTENT
========================================================= */

.pf-register-showcase-content {
  margin-top: auto;
  margin-bottom: auto;
  padding: 50px 0 40px;
}

.pf-register-eyebrow {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 999px;
  background: rgba(255,255,255,.07);
  color: rgba(255,255,255,.88);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .8px;
}

.pf-register-eyebrow span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #b9f5da;
  box-shadow: 0 0 0 4px rgba(185,245,218,.09);
}

.pf-register-showcase h1 {
  max-width: 590px;
  margin: 23px 0 17px;
  color: #ffffff;
  font-size: clamp(40px, 4vw, 57px);
  line-height: 1.02;
  letter-spacing: -2.7px;
  font-weight: 450;
}

.pf-register-showcase h1 strong {
  font-weight: 800;
}

.pf-register-showcase-content > p {
  max-width: 500px;
  margin: 0;
  color: rgba(255,255,255,.69);
  font-size: 13px;
  line-height: 1.7;
}


/* =========================================================
   TRIAL CARD
========================================================= */

.pf-register-trial-card {
  max-width: 475px;
  margin-top: 29px;
  padding: 14px;
  display: flex;
  align-items: center;
  gap: 11px;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 14px;
  background: rgba(255,255,255,.085);
  backdrop-filter: blur(12px);
}

.pf-register-trial-icon {
  width: 35px;
  height: 35px;
  flex: 0 0 35px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: rgba(255,255,255,.10);
  font-size: 16px;
}

.pf-register-trial-card > div:nth-child(2) {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1;
}

.pf-register-trial-card strong {
  color: white;
  font-size: 10px;
  font-weight: 800;
}

.pf-register-trial-card span {
  color: rgba(255,255,255,.55);
  font-size: 7px;
}

.pf-register-trial-badge {
  padding: 5px 7px;
  border-radius: 6px;
  background: rgba(183,246,218,.12);
  color: #b9f5da;
  font-size: 6px;
  font-weight: 850;
  letter-spacing: .5px;
}


/* =========================================================
   FEATURES
========================================================= */

.pf-register-features {
  margin-top: 30px;
  display: grid;
  gap: 13px;
}

.pf-register-feature {
  display: flex;
  align-items: center;
  gap: 11px;
}

.pf-register-feature-icon {
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,.10);
  border-radius: 9px;
  background: rgba(255,255,255,.09);
  color: white;
  font-size: 10px;
  font-weight: 800;
}

.pf-register-feature div:last-child {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.pf-register-feature strong {
  color: white;
  font-size: 8px;
  font-weight: 750;
}

.pf-register-feature span {
  color: rgba(255,255,255,.49);
  font-size: 6.5px;
}


/* =========================================================
   SHOWCASE FOOTER
========================================================= */

.pf-register-showcase-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 7px;
  color: rgba(255,255,255,.38);
  font-size: 7px;
}


/* =========================================================
   FORM SIDE
========================================================= */

.pf-register-form-section {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  background: #ffffff;
  overflow-y: auto;
}

.pf-register-form-wrapper {
  width: min(100%, 570px);
  padding: 35px 42px 45px;
}


/* =========================================================
   TOP LINK
========================================================= */

.pf-register-top-link {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 28px;
}

.pf-register-top-link a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #849290;
  font-size: 8px;
  font-weight: 700;
  text-decoration: none;
}

.pf-register-top-link a:hover {
  color: #087970;
}

.pf-register-top-link a span {
  font-size: 13px;
}


/* =========================================================
   HEADER
========================================================= */

.pf-register-header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.pf-register-header-icon {
  width: 43px;
  height: 43px;
  flex: 0 0 43px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dff0ec;
  border-radius: 13px;
  background: #edf8f5;
  font-size: 18px;
}

.pf-register-kicker {
  margin-bottom: 4px;
  color: #09897d;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: 1px;
}

.pf-register-header h2 {
  margin: 0;
  color: #142f2e;
  font-size: 27px;
  line-height: 1.1;
  letter-spacing: -1px;
  font-weight: 800;
}

.pf-register-header p {
  margin: 5px 0 0;
  color: #8b9896;
  font-size: 9px;
}


/* =========================================================
   PROGRESS
========================================================= */

.pf-register-progress {
  margin-top: 20px;
}

.pf-register-progress-line {
  height: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: #edf2f0;
}

.pf-register-progress-line span {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    #087970,
    #40b6a7
  );
}

.pf-register-progress-text {
  margin-top: 7px;
  display: flex;
  justify-content: space-between;
  gap: 10px;
  color: #8b9896;
  font-size: 7px;
}

.pf-register-progress-text strong {
  color: #087970;
  font-weight: 800;
}


/* =========================================================
   MESSAGES
========================================================= */

.pf-register-message {
  margin-top: 17px;
  padding: 10px 11px;
  display: flex;
  align-items: flex-start;
  gap: 9px;
  border-radius: 10px;
}

.pf-register-message-icon {
  width: 22px;
  height: 22px;
  flex: 0 0 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  font-size: 9px;
  font-weight: 850;
}

.pf-register-message > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.pf-register-message strong {
  font-size: 9px;
}

.pf-register-message span {
  font-size: 8px;
  line-height: 1.45;
}

.pf-register-message-error {
  border: 1px solid #f2d6d3;
  background: #fff7f6;
  color: #a24a44;
}

.pf-register-message-error .pf-register-message-icon {
  background: #f8ddda;
}

.pf-register-message-success {
  border: 1px solid #d2eee4;
  background: #f1fbf7;
  color: #247b62;
}

.pf-register-message-success .pf-register-message-icon {
  background: #d5eee5;
}


/* =========================================================
   FORM
========================================================= */

.pf-register-form {
  margin-top: 22px;
  display: flex;
  flex-direction: column;
  gap: 13px;
}


/* =========================================================
   SECTION TITLES
========================================================= */

.pf-register-section-title {
  margin-top: 8px;
  padding-top: 7px;
  display: flex;
  align-items: center;
  gap: 9px;
  border-top: 1px solid #edf2f0;
}

.pf-register-section-number {
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: #eaf6f3;
  color: #087970;
  font-size: 7px;
  font-weight: 850;
}

.pf-register-section-title > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.pf-register-section-title strong {
  color: #405654;
  font-size: 9px;
  font-weight: 800;
}

.pf-register-section-title span:last-child {
  color: #9aa5a3;
  font-size: 6.5px;
}


/* =========================================================
   FIELDS
========================================================= */

.pf-register-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.pf-register-field label {
  color: #405553;
  font-size: 8px;
  font-weight: 750;
}

.pf-register-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}


/* =========================================================
   INPUTS
========================================================= */

.pf-register-input-wrapper {
  position: relative;
}

.pf-register-input-icon {
  position: absolute;
  left: 11px;
  top: 50%;
  width: 15px;
  height: 15px;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #9aa7a5;
  font-size: 10px;
  pointer-events: none;
}

.pf-register-input-wrapper input {
  width: 100%;
  height: 43px;
  padding: 0 38px 0 35px;
  border: 1px solid #dfe8e6;
  border-radius: 10px;
  outline: none;
  background: #fbfdfc;
  color: #173432;
  font-family: inherit;
  font-size: 9px;
  transition:
    border-color .2s ease,
    box-shadow .2s ease,
    background .2s ease;
}

.pf-register-field > input,
.pf-register-field > textarea,
.pf-register-select {
  width: 100%;
  border: 1px solid #dfe8e6;
  outline: none;
  border-radius: 10px;
  background: #fbfdfc;
  color: #173432;
  font-family: inherit;
  font-size: 9px;
  transition:
    border-color .2s ease,
    box-shadow .2s ease,
    background .2s ease;
}

.pf-register-field > input {
  height: 43px;
  padding: 0 11px;
}

.pf-register-field > textarea {
  min-height: 58px;
  padding: 9px 11px;
  resize: vertical;
  line-height: 1.5;
}

.pf-register-select {
  height: 43px;
  padding: 0 10px;
  cursor: pointer;
}

.pf-register-input-wrapper input::placeholder,
.pf-register-field > input::placeholder,
.pf-register-field > textarea::placeholder {
  color: #aeb9b7;
}

.pf-register-input-wrapper input:hover,
.pf-register-field > input:hover,
.pf-register-field > textarea:hover,
.pf-register-select:hover {
  border-color: #cad9d6;
}

.pf-register-input-wrapper input:focus,
.pf-register-field > input:focus,
.pf-register-field > textarea:focus,
.pf-register-select:focus {
  border-color: #0b978b;
  background: #ffffff;
  box-shadow: 0 0 0 4px rgba(11,151,139,.07);
}

.pf-register-input-wrapper input:disabled,
.pf-register-field > input:disabled,
.pf-register-field > textarea:disabled,
.pf-register-select:disabled {
  opacity: .65;
  cursor: not-allowed;
}


/* =========================================================
   CURRENCY
========================================================= */

.pf-register-currency {
  min-height: 43px;
  padding: 7px 10px;
  display: flex;
  align-items: center;
  gap: 9px;
  border: 1px solid #e1ebe8;
  border-radius: 10px;
  background: #f7fbfa;
}

.pf-register-currency-icon {
  width: 27px;
  height: 27px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: #e4f4f0;
  color: #087970;
  font-size: 10px;
  font-weight: 850;
}

.pf-register-currency > div:nth-child(2) {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.pf-register-currency span {
  color: #8d9a98;
  font-size: 6.5px;
}

.pf-register-currency strong {
  color: #304b48;
  font-size: 9px;
}

.pf-register-currency small {
  color: #087970;
  font-size: 6px;
  font-weight: 800;
}


/* =========================================================
   PASSWORD TOGGLE
========================================================= */

.pf-register-password-toggle {
  position: absolute;
  top: 50%;
  right: 7px;
  width: 28px;
  height: 28px;
  transform: translateY(-50%);
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: #8d9b99;
  cursor: pointer;
  font-size: 11px;
}

.pf-register-password-toggle:hover {
  background: #edf6f3;
  color: #087970;
}


/* =========================================================
   PASSWORD STRENGTH
========================================================= */

.pf-register-password-strength {
  margin-top: 4px;
  display: flex;
  align-items: center;
  gap: 7px;
}

.pf-register-strength-bars {
  width: 80px;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 3px;
}

.pf-register-strength-bars span {
  height: 3px;
  border-radius: 999px;
  background: #e3e9e7;
}

.pf-register-strength-bars span.active {
  background: #3eaa94;
}

.pf-register-password-strength > span {
  color: #7e8d8a;
  font-size: 6.5px;
}


/* =========================================================
   PASSWORD MATCH
========================================================= */

.pf-register-match {
  margin-top: 3px;
  font-size: 7px;
  font-weight: 700;
}

.pf-register-match.success {
  color: #2a8a6c;
}

.pf-register-match.error {
  color: #b5534b;
}


/* =========================================================
   TERMS
========================================================= */

.pf-register-terms {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 3px;
  color: #82908e;
  font-size: 7px;
  line-height: 1.5;
  cursor: pointer;
}

.pf-register-terms input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.pf-register-checkbox {
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #d3dfdc;
  border-radius: 5px;
  background: white;
  color: transparent;
  font-size: 8px;
  font-weight: 900;
}

.pf-register-terms input:checked + .pf-register-checkbox {
  border-color: #087970;
  background: #087970;
  color: white;
}


/* =========================================================
   SUBMIT
========================================================= */

.pf-register-submit {
  width: 100%;
  height: 47px;
  margin-top: 2px;
  padding: 0 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 0;
  border-radius: 10px;
  background: linear-gradient(
    135deg,
    #087970,
    #0a9a8d
  );
  color: white;
  font-family: inherit;
  font-size: 9px;
  font-weight: 800;
  cursor: pointer;
  box-shadow:
    0 8px 20px rgba(8,121,112,.18);
  transition:
    transform .18s ease,
    box-shadow .18s ease,
    opacity .18s ease;
}

.pf-register-submit:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow:
    0 12px 25px rgba(8,121,112,.23);
}

.pf-register-submit:active:not(:disabled) {
  transform: translateY(0);
}

.pf-register-submit:disabled {
  opacity: .68;
  cursor: not-allowed;
}

.pf-register-submit-arrow {
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  background: rgba(255,255,255,.14);
  font-size: 12px;
}


/* =========================================================
   SPINNER
========================================================= */

.pf-register-spinner {
  width: 14px;
  height: 14px;
  border: 2px solid rgba(255,255,255,.30);
  border-top-color: white;
  border-radius: 50%;
  animation: pf-register-spin .7s linear infinite;
}

@keyframes pf-register-spin {
  to {
    transform: rotate(360deg);
  }
}


/* =========================================================
   FREE NOTE
========================================================= */

.pf-register-free-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  color: #98a4a2;
  font-size: 6.5px;
}

.pf-register-free-note span:first-child {
  color: #159179;
  font-weight: 900;
}

.pf-register-free-note strong {
  color: #087970;
  font-weight: 800;
}


/* =========================================================
   LOGIN LINK
========================================================= */

.pf-register-login {
  margin-top: 18px;
  padding-top: 17px;
  border-top: 1px solid #edf1f0;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  color: #899593;
  font-size: 7px;
}

.pf-register-login a {
  color: #087970;
  font-weight: 800;
  text-decoration: none;
}

.pf-register-login a:hover {
  text-decoration: underline;
}


/* =========================================================
   SECURITY
========================================================= */

.pf-register-security {
  margin-top: 13px;
  padding: 9px 10px;
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid #edf2f0;
  border-radius: 9px;
  background: #f8faf9;
}

.pf-register-security-icon {
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  background: #e6f5f1;
  color: #087970;
  font-size: 9px;
  font-weight: 900;
}

.pf-register-security div:last-child {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.pf-register-security strong {
  color: #4a5b59;
  font-size: 7px;
}

.pf-register-security span {
  color: #929e9c;
  font-size: 6px;
  line-height: 1.4;
}


/* =========================================================
   MOBILE LOGO
========================================================= */

.pf-register-mobile-logo {
  display: none;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1200px) {

  .pf-register-page {
    grid-template-columns:
      minmax(470px, 1fr)
      minmax(470px, 1fr);
  }

  .pf-register-showcase-inner {
    padding-left: 38px;
    padding-right: 38px;
  }

  .pf-register-showcase h1 {
    font-size: 44px;
  }

  .pf-register-form-wrapper {
    padding-left: 32px;
    padding-right: 32px;
  }
}


@media (max-width: 900px) {

  .pf-register-page {
    display: block;
  }

  .pf-register-showcase {
    display: none;
  }

  .pf-register-form-section {
    min-height: 100vh;
    padding: 20px;
  }

  .pf-register-form-wrapper {
    width: min(100%, 570px);
    padding: 20px 10px 40px;
  }

  .pf-register-mobile-logo {
    display: inline-flex;
    margin-bottom: 25px;
  }

  .pf-register-mobile-logo .pf-register-logo-mark {
    color: #087970;
  }

  .pf-register-mobile-logo .pf-register-logo-text {
    color: #173432;
  }

  .pf-register-mobile-logo .pf-register-logo-text span {
    color: #087970;
  }
}


@media (max-width: 520px) {

  .pf-register-form-section {
    padding: 10px;
  }

  .pf-register-form-wrapper {
    padding: 15px 5px 30px;
  }

  .pf-register-grid {
    grid-template-columns: 1fr;
  }

  .pf-register-header h2 {
    font-size: 24px;
  }

  .pf-register-header p {
    font-size: 8px;
  }

  .pf-register-top-link {
    margin-bottom: 23px;
  }

  .pf-register-input-wrapper input,
  .pf-register-field > input,
  .pf-register-select {
    height: 44px;
  }

  .pf-register-submit {
    height: 48px;
  }
}
/* ============================================================
   PHARMAFLOW — ULTRA PROFESSIONAL DASHBOARD
   Version 2 — Large / Premium / Readable
============================================================ */

.pf-app-shell {
  min-height: 100vh;
  display: flex;
  background: #f4f7f7;
  color: #17252d;
  font-family: inherit;
}

/* ============================================================
   LOADING
============================================================ */

.pf-dashboard-loading {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f4f7f7;
}

.pf-loading-card {
  width: min(460px, calc(100% - 40px));
  padding: 52px 40px;
  text-align: center;
  background: #ffffff;
  border: 1px solid #e0e8e9;
  border-radius: 28px;
  box-shadow: 0 25px 80px rgba(21, 54, 63, 0.10);
}

.pf-loading-logo {
  width: 72px;
  height: 72px;
  margin: 0 auto 24px;
  border-radius: 21px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #0f766e;
  color: #ffffff;
  font-size: 32px;
  font-weight: 800;
  box-shadow: 0 12px 28px rgba(15, 118, 110, 0.22);
}

.pf-loading-card h2 {
  margin: 24px 0 8px;
  color: #17262e;
  font-size: 22px;
  font-weight: 800;
}

.pf-loading-card p {
  margin: 0;
  color: #728189;
  font-size: 15px;
}

.pf-spinner {
  width: 38px;
  height: 38px;
  margin: 0 auto;
  border: 3px solid #dce9e7;
  border-top-color: #0f766e;
  border-radius: 50%;
  animation: pf-spin 0.8s linear infinite;
}

@keyframes pf-spin {
  to {
    transform: rotate(360deg);
  }
}

/* ============================================================
   SIDEBAR
============================================================ */

.pf-sidebar {
  width: 290px;
  min-height: 100vh;
  flex: 0 0 290px;
  display: flex;
  flex-direction: column;
  background: #ffffff;
  border-right: 1px solid #dfe7e9;
  position: sticky;
  top: 0;
  height: 100vh;
  z-index: 50;
}

/* BRAND */

.pf-sidebar-brand {
  min-height: 94px;
  padding: 20px 23px;
  display: flex;
  align-items: center;
  border-bottom: 1px solid #edf1f2;
}

.pf-brand-button {
  border: 0;
  background: transparent;
  display: flex;
  align-items: center;
  gap: 14px;
  cursor: pointer;
  text-align: left;
  padding: 0;
}

.pf-brand-mark {
  width: 50px;
  height: 50px;
  border-radius: 15px;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 25px;
  font-weight: 800;
  box-shadow: 0 10px 24px rgba(15, 118, 110, 0.20);
}

.pf-brand-button strong {
  display: block;
  color: #18262d;
  font-size: 24px;
  line-height: 1;
  font-weight: 850;
  letter-spacing: -0.8px;
}

.pf-brand-button strong span {
  color: #0f766e;
}

.pf-brand-button small {
  display: block;
  margin-top: 6px;
  color: #89979d;
  font-size: 11px;
  font-weight: 500;
}

/* ============================================================
   PHARMACY CARD
============================================================ */

.pf-sidebar-pharmacy {
  margin: 20px 18px 15px;
  padding: 15px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 1px solid #d8ebe8;
  background: linear-gradient(
    135deg,
    #f0faf8,
    #f8fcfb
  );
  border-radius: 17px;
  position: relative;
}

.pf-pharmacy-icon {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  border-radius: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #d8f1ed;
  color: #0f766e;
  font-size: 19px;
  font-weight: 800;
}

.pf-pharmacy-mini-info {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-pharmacy-mini-info span {
  color: #78908e;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.7px;
}

.pf-pharmacy-mini-info strong {
  margin-top: 4px;
  overflow: hidden;
  color: #26363d;
  font-size: 14px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-pharmacy-mini-info small {
  margin-top: 3px;
  color: #77878d;
  font-size: 11px;
}

.pf-online-dot {
  width: 9px;
  height: 9px;
  margin-left: auto;
  align-self: flex-start;
  border-radius: 50%;
  background: #16a675;
  box-shadow: 0 0 0 5px #dcf5eb;
}

/* ============================================================
   NAVIGATION
============================================================ */

.pf-sidebar-nav {
  flex: 1;
  padding: 10px 15px;
  overflow-y: auto;
}

.pf-nav-title {
  margin: 16px 13px 10px;
  color: #9aa7ac;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.2px;
}

.pf-nav-item {
  width: 100%;
  height: 52px;
  margin-bottom: 5px;
  border: 0;
  border-radius: 14px;
  background: transparent;
  color: #64747b;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 0 15px;
  font-size: 14px;
  font-weight: 650;
  cursor: pointer;
  text-align: left;
  transition: all 0.2s ease;
  position: relative;
}

.pf-nav-item:hover {
  background: #f2f8f7;
  color: #0f766e;
}

.pf-nav-item-active {
  background: #e4f5f2;
  color: #0f766e;
  font-weight: 750;
}

.pf-nav-icon {
  width: 25px;
  text-align: center;
  font-size: 20px;
}

.pf-nav-active-dot {
  width: 5px;
  height: 25px;
  position: absolute;
  right: 0;
  border-radius: 5px 0 0 5px;
  background: #0f766e;
}

/* ============================================================
   SUPPORT
============================================================ */

.pf-sidebar-support {
  margin: 13px 18px;
  padding: 15px;
  display: flex;
  gap: 12px;
  border-radius: 16px;
  background: #f6f8f9;
  border: 1px solid #edf1f2;
}

.pf-support-icon {
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  border-radius: 11px;
  background: #e4eaec;
  color: #53636a;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  font-weight: 800;
}

.pf-sidebar-support strong {
  display: block;
  color: #34454c;
  font-size: 12px;
  font-weight: 750;
}

.pf-sidebar-support span {
  display: block;
  margin-top: 4px;
  color: #89969c;
  font-size: 10px;
  line-height: 1.4;
}

/* ============================================================
   USER SIDEBAR
============================================================ */

.pf-sidebar-user {
  padding: 18px;
  border-top: 1px solid #e9edef;
  display: flex;
  align-items: center;
  gap: 12px;
}

.pf-avatar {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  border-radius: 13px;
  background: #dff3ef;
  color: #0f766e;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 850;
}

.pf-avatar-small {
  width: 42px;
  height: 42px;
}

.pf-user-details,
.pf-header-profile > div:last-child {
  min-width: 0;
  flex: 1;
}

.pf-user-details strong,
.pf-header-profile strong {
  display: block;
  overflow: hidden;
  color: #26363d;
  font-size: 12px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-user-details span,
.pf-header-profile span {
  display: block;
  margin-top: 4px;
  color: #87959b;
  font-size: 10px;
}

.pf-logout-icon {
  width: 35px;
  height: 35px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #9aa6ab;
  font-size: 20px;
  cursor: pointer;
}

.pf-logout-icon:hover {
  color: #d34d4d;
  background: #fff0f0;
}

/* ============================================================
   MAIN
============================================================ */

.pf-app-main {
  min-width: 0;
  flex: 1;
}

/* ============================================================
   HEADER
============================================================ */

.pf-app-header {
  min-height: 94px;
  padding: 0 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(255,255,255,0.97);
  border-bottom: 1px solid #dfe7e9;
  position: sticky;
  top: 0;
  z-index: 30;
  backdrop-filter: blur(15px);
}

.pf-header-left {
  display: flex;
  align-items: center;
  gap: 18px;
}

.pf-header-label {
  display: block;
  color: #94a1a6;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.4px;
}

.pf-header-left h1 {
  margin: 5px 0 0;
  color: #17262e;
  font-size: 25px;
  font-weight: 800;
  letter-spacing: -0.6px;
}

.pf-header-left h1 span {
  font-size: 22px;
}

.pf-header-actions {
  display: flex;
  align-items: center;
  gap: 11px;
}

.pf-header-icon-button {
  width: 43px;
  height: 43px;
  border: 1px solid #dfe7e9;
  border-radius: 12px;
  background: #ffffff;
  color: #68777e;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  transition: 0.2s ease;
}

.pf-header-icon-button:hover {
  border-color: #b8d9d5;
  color: #0f766e;
  background: #f6fbfa;
}

.pf-notification-button {
  position: relative;
}

.pf-notification-button > span {
  width: 7px;
  height: 7px;
  position: absolute;
  top: 7px;
  right: 7px;
  border-radius: 50%;
  background: #e35c5c;
}

.pf-header-divider {
  width: 1px;
  height: 40px;
  margin: 0 8px;
  background: #e3e9eb;
}

.pf-header-profile {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pf-refresh-spin {
  display: inline-block;
  animation: pf-spin 0.7s linear infinite;
}

.pf-mobile-menu-button {
  display: none;
}

/* ============================================================
   CONTENT
============================================================ */

.pf-dashboard-content {
  width: 100%;
  max-width: 1650px;
  margin: 0 auto;
  padding: 38px 42px 30px;
}

/* ============================================================
   ERROR
============================================================ */

.pf-dashboard-alert {
  margin-bottom: 24px;
  padding: 17px 20px;
  display: flex;
  align-items: center;
  gap: 14px;
  border: 1px solid #f0caca;
  border-radius: 15px;
  background: #fff7f7;
}

.pf-alert-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  border-radius: 12px;
  background: #fde5e5;
  color: #c44747;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  font-weight: 850;
}

.pf-dashboard-alert strong {
  color: #9f3535;
  font-size: 13px;
}

.pf-dashboard-alert p {
  margin: 4px 0 0;
  color: #ad5a5a;
  font-size: 12px;
}

.pf-dashboard-alert button {
  margin-left: auto;
  padding: 9px 14px;
  border: 0;
  border-radius: 9px;
  background: #fff;
  color: #a53e3e;
  font-size: 11px;
  font-weight: 750;
  cursor: pointer;
}

/* ============================================================
   INTRO
============================================================ */

.pf-dashboard-intro {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 25px;
  margin-bottom: 25px;
}

.pf-date-label {
  margin: 0 0 7px;
  color: #8a989e;
  font-size: 12px;
  font-weight: 550;
  text-transform: capitalize;
}

.pf-dashboard-intro h2 {
  margin: 0;
  color: #17262e;
  font-size: 34px;
  line-height: 1.1;
  font-weight: 850;
  letter-spacing: -1px;
}

.pf-dashboard-intro p:last-child {
  margin: 7px 0 0;
  color: #78878d;
  font-size: 13px;
}

.pf-dashboard-intro p strong {
  color: #35464d;
}

.pf-intro-actions {
  display: flex;
  gap: 11px;
}

.pf-primary-button,
.pf-secondary-button {
  height: 46px;
  padding: 0 19px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.2s ease;
}

.pf-primary-button {
  border: 1px solid #0f766e;
  background: #0f766e;
  color: #ffffff;
  box-shadow: 0 9px 22px rgba(15, 118, 110, 0.18);
}

.pf-primary-button:hover {
  background: #0c655f;
  transform: translateY(-1px);
}

.pf-secondary-button {
  border: 1px solid #d9e2e4;
  background: #ffffff;
  color: #405158;
}

.pf-secondary-button:hover {
  border-color: #b4d5d1;
  color: #0f766e;
}

/* ============================================================
   PHARMACY BANNER
============================================================ */

.pf-pharmacy-banner {
  min-height: 116px;
  margin-bottom: 19px;
  padding: 21px 24px;
  border: 1px solid #d4e9e5;
  border-radius: 19px;
  background: linear-gradient(
    110deg,
    #eaf8f5 0%,
    #f7fcfb 100%
  );
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
}

.pf-banner-main {
  display: flex;
  align-items: center;
  gap: 16px;
}

.pf-banner-logo {
  width: 58px;
  height: 58px;
  border-radius: 17px;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 25px;
  font-weight: 850;
  box-shadow: 0 10px 22px rgba(15, 118, 110, 0.18);
}

.pf-banner-main > div:last-child > span,
.pf-banner-status > div > span {
  display: block;
  color: #6d8985;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.pf-banner-main h3 {
  margin: 5px 0 3px;
  color: #203239;
  font-size: 19px;
  font-weight: 800;
}

.pf-banner-main p {
  margin: 0;
  color: #708187;
  font-size: 11px;
}

.pf-banner-status {
  min-width: 205px;
  padding: 13px 17px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-radius: 13px;
  background: #ffffff;
  border: 1px solid #dce9e7;
}

.pf-status-dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #17a476;
  box-shadow: 0 0 0 5px #def4eb;
}

.pf-banner-status strong {
  display: block;
  margin-top: 4px;
  color: #168361;
  font-size: 12px;
}

/* ============================================================
   KPI
============================================================ */

.pf-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

.pf-kpi-card {
  min-width: 0;
  padding: 21px;
  border: 1px solid #dfe7e9;
  border-radius: 18px;
  background: #ffffff;
  text-align: left;
  cursor: pointer;
  box-shadow: 0 6px 22px rgba(28, 53, 61, 0.035);
  transition: all 0.22s ease;
}

.pf-kpi-card:hover {
  transform: translateY(-3px);
  border-color: #c5dcda;
  box-shadow: 0 15px 32px rgba(28, 53, 61, 0.08);
}

.pf-kpi-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.pf-kpi-icon {
  width: 47px;
  height: 47px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 850;
}

.pf-kpi-teal {
  background: #e2f5f2;
  color: #0f766e;
}

.pf-kpi-blue {
  background: #e9f1fa;
  color: #3d719f;
}

.pf-kpi-orange {
  background: #fff1de;
  color: #cc8127;
}

.pf-kpi-green {
  background: #e3f6ed;
  color: #178260;
}

.pf-kpi-arrow {
  color: #b1bdc1;
  font-size: 18px;
}

.pf-kpi-label {
  margin-top: 18px;
  color: #718087;
  font-size: 12px;
  font-weight: 600;
}

.pf-kpi-value {
  margin-top: 5px;
  color: #16262e;
  font-size: 29px;
  line-height: 1.1;
  font-weight: 850;
  letter-spacing: -0.8px;
}

.pf-kpi-description {
  margin-top: 7px;
  color: #909da2;
  font-size: 10px;
}

/* ============================================================
   MAIN GRID
============================================================ */

.pf-main-dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(390px, 0.85fr);
  gap: 19px;
}

.pf-panel {
  min-width: 0;
  border: 1px solid #dfe7e9;
  border-radius: 19px;
  background: #ffffff;
  overflow: hidden;
  box-shadow: 0 6px 22px rgba(28, 53, 61, 0.035);
}

.pf-panel-header {
  padding: 22px 23px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid #edf1f2;
}

.pf-panel-eyebrow {
  color: #0f766e;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 1.2px;
}

.pf-panel-header h3 {
  margin: 5px 0 4px;
  color: #26363d;
  font-size: 19px;
  font-weight: 800;
}

.pf-panel-header p {
  margin: 0;
  color: #89969c;
  font-size: 11px;
}

.pf-link-button {
  flex-shrink: 0;
  border: 0;
  background: transparent;
  color: #0f766e;
  font-size: 11px;
  font-weight: 750;
  cursor: pointer;
}

.pf-link-button span {
  margin-left: 6px;
  font-size: 15px;
}

/* ============================================================
   TABLE
============================================================ */

.pf-table-wrapper {
  overflow-x: auto;
}

.pf-dashboard-table {
  width: 100%;
  border-collapse: collapse;
}

.pf-dashboard-table th {
  padding: 13px 23px;
  background: #fafcfc;
  color: #96a2a7;
  font-size: 9px;
  font-weight: 800;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.pf-dashboard-table td {
  padding: 17px 23px;
  border-top: 1px solid #edf1f2;
  color: #65747b;
  font-size: 11px;
  white-space: nowrap;
}

.pf-dashboard-table tbody tr {
  transition: background 0.15s ease;
}

.pf-dashboard-table tbody tr:hover {
  background: #fbfdfd;
}

.pf-sale-number {
  display: flex;
  align-items: center;
  gap: 7px;
}

.pf-sale-number span {
  color: #a1adb1;
  font-size: 10px;
}

.pf-sale-number strong {
  color: #34444b;
  font-size: 12px;
  font-weight: 750;
}

.pf-date-value {
  color: #89969c;
  font-size: 11px;
}

.pf-sale-total {
  color: #26373e;
  font-size: 12px;
  font-weight: 800;
}

.pf-status-badge {
  padding: 7px 10px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 9px;
  font-weight: 750;
}

.pf-status-badge > span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

.pf-status-success {
  background: #e7f7ef;
  color: #19815e;
}

.pf-status-success > span {
  background: #1a9a70;
}

.pf-status-warning {
  background: #fff4df;
  color: #bd7925;
}

.pf-status-warning > span {
  background: #d78d29;
}

.pf-status-danger {
  background: #fdeaea;
  color: #bd4848;
}

.pf-status-danger > span {
  background: #d85c5c;
}

.pf-empty-cell {
  padding: 0 !important;
}

.pf-empty-state {
  min-height: 230px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.pf-empty-state > div {
  width: 52px;
  height: 52px;
  margin-bottom: 13px;
  border-radius: 15px;
  background: #eef3f4;
  color: #8c9ba0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 21px;
}

.pf-empty-state strong {
  color: #5b6a71;
  font-size: 13px;
}

.pf-empty-state span {
  margin-top: 5px;
  color: #99a5aa;
  font-size: 10px;
}

/* ============================================================
   STOCK
============================================================ */

.pf-stock-summary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  padding: 17px 20px 5px;
}

.pf-stock-summary-card {
  padding: 13px;
  border-radius: 12px;
  text-align: center;
}

.pf-stock-summary-card span {
  display: block;
  font-size: 9px;
  font-weight: 600;
}

.pf-stock-summary-card strong {
  display: block;
  margin-top: 4px;
  font-size: 21px;
  font-weight: 850;
}

.pf-stock-good {
  background: #edf8f3;
  color: #208160;
}

.pf-stock-warning {
  background: #fff6e8;
  color: #bb7929;
}

.pf-stock-danger {
  background: #fff0f0;
  color: #bd4c4c;
}

.pf-stock-list {
  padding: 10px 20px 20px;
}

.pf-stock-item {
  min-width: 0;
  padding: 14px 0;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid #edf1f2;
}

.pf-stock-item:last-child {
  border-bottom: 0;
}

.pf-stock-product-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  border-radius: 11px;
  background: #fff1df;
  color: #c98228;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 850;
  font-size: 15px;
}

.pf-stock-product {
  min-width: 0;
  flex: 1;
}

.pf-stock-product strong {
  display: block;
  overflow: hidden;
  color: #37474e;
  font-size: 12px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-stock-product span {
  display: block;
  margin-top: 4px;
  color: #9aa5aa;
  font-size: 9px;
}

.pf-stock-quantity {
  min-width: 55px;
  text-align: right;
}

.pf-stock-quantity strong {
  display: block;
  font-size: 16px;
  font-weight: 850;
}

.pf-stock-quantity span {
  display: block;
  margin-top: 2px;
  font-size: 8px;
}

.pf-stock-quantity.warning {
  color: #c47b22;
}

.pf-stock-quantity.danger {
  color: #bd4c4c;
}

.pf-stock-empty {
  min-height: 175px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.pf-stock-empty > div {
  width: 47px;
  height: 47px;
  margin-bottom: 11px;
  border-radius: 50%;
  background: #e7f7ef;
  color: #19815e;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 850;
}

.pf-stock-empty strong {
  color: #4b5c63;
  font-size: 13px;
}

.pf-stock-empty span {
  margin-top: 5px;
  color: #9aa5aa;
  font-size: 10px;
}

/* ============================================================
   QUICK ACTIONS
============================================================ */

.pf-quick-section {
  margin-top: 27px;
}

.pf-section-heading {
  margin-bottom: 13px;
}

.pf-section-heading span {
  color: #0f766e;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 1.2px;
}

.pf-section-heading h3 {
  margin: 4px 0 0;
  color: #26363d;
  font-size: 20px;
  font-weight: 800;
}

.pf-quick-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.pf-quick-card {
  min-width: 0;
  min-height: 125px;
  padding: 18px;
  border: 1px solid #dfe7e9;
  border-radius: 17px;
  background: #ffffff;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  text-align: left;
  cursor: pointer;
  transition: all 0.22s ease;
}

.pf-quick-card:hover {
  border-color: #b9d9d5;
  transform: translateY(-3px);
  box-shadow: 0 13px 28px rgba(28, 53, 61, 0.07);
}

.pf-quick-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  border-radius: 12px;
  background: #e9f7f5;
  color: #0f766e;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 850;
}

.pf-quick-content {
  min-width: 0;
  flex: 1;
}

.pf-quick-content strong {
  display: block;
  color: #34444b;
  font-size: 12px;
  font-weight: 750;
}

.pf-quick-content span {
  display: block;
  margin-top: 6px;
  color: #8c999e;
  font-size: 10px;
  line-height: 1.5;
}

.pf-quick-arrow {
  color: #a2aeb2;
  font-size: 16px;
}

.pf-quick-card-primary {
  border-color: #c9e3df;
  background: linear-gradient(
    145deg,
    #f2fbf9,
    #ffffff
  );
}

.pf-quick-card-primary .pf-quick-icon {
  background: #0f766e;
  color: #ffffff;
}

/* ============================================================
   FOOTER
============================================================ */

.pf-dashboard-footer {
  margin-top: 30px;
  padding: 19px 2px 5px;
  border-top: 1px solid #dfe7e9;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #98a4a9;
  font-size: 10px;
}

.pf-dashboard-footer > div {
  display: flex;
  align-items: center;
  gap: 8px;
}

.pf-footer-mark {
  color: #0f766e;
  font-size: 14px;
}

.pf-dashboard-footer strong {
  color: #4a5960;
  font-size: 12px;
  font-weight: 750;
}

.pf-dashboard-footer strong span {
  color: #0f766e;
}

.pf-dashboard-footer > div > span:last-child {
  padding-left: 7px;
  border-left: 1px solid #dce2e4;
}

/* ============================================================
   MOBILE
============================================================ */

.pf-mobile-overlay {
  display: none;
}

@media (max-width: 1250px) {

  .pf-sidebar {
    width: 260px;
    flex-basis: 260px;
  }

  .pf-kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pf-main-dashboard-grid {
    grid-template-columns: 1fr;
  }

  .pf-quick-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pf-dashboard-content {
    padding-left: 28px;
    padding-right: 28px;
  }
}

@media (max-width: 900px) {

  .pf-sidebar {
    position: fixed;
    left: -300px;
    top: 0;
    bottom: 0;
    width: 290px;
    flex-basis: 290px;
    transition: left 0.25s ease;
    box-shadow: 20px 0 60px rgba(15, 42, 52, 0.15);
  }

  .pf-sidebar-mobile-open {
    left: 0;
  }

  .pf-sidebar-close {
    display: block;
    margin-left: auto;
    border: 0;
    background: transparent;
    color: #89969b;
    font-size: 28px;
    cursor: pointer;
  }

  .pf-mobile-overlay {
    display: block;
    position: fixed;
    inset: 0;
    border: 0;
    background: rgba(20, 35, 42, 0.38);
    z-index: 40;
  }

  .pf-mobile-menu-button {
    width: 43px;
    height: 43px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #dfe7e9;
    border-radius: 12px;
    background: #ffffff;
    color: #51616a;
    cursor: pointer;
    font-size: 20px;
  }

  .pf-app-header {
    padding: 0 22px;
  }

  .pf-dashboard-content {
    padding: 27px 22px;
  }
}

@media (max-width: 680px) {

  .pf-header-actions .pf-header-profile,
  .pf-header-divider {
    display: none;
  }

  .pf-header-actions {
    gap: 7px;
  }

  .pf-dashboard-intro {
    align-items: flex-start;
    flex-direction: column;
  }

  .pf-dashboard-intro h2 {
    font-size: 29px;
  }

  .pf-intro-actions {
    width: 100%;
  }

  .pf-primary-button,
  .pf-secondary-button {
    flex: 1;
  }

  .pf-pharmacy-banner {
    align-items: flex-start;
    flex-direction: column;
  }

  .pf-banner-status {
    width: 100%;
  }

  .pf-kpi-grid {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  .pf-kpi-card {
    padding: 16px;
  }

  .pf-kpi-value {
    font-size: 22px;
  }

  .pf-quick-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 470px) {

  .pf-dashboard-content {
    padding: 20px 14px;
  }

  .pf-app-header {
    min-height: 75px;
    padding: 0 14px;
  }

  .pf-header-left {
    gap: 10px;
  }

  .pf-header-left h1 {
    font-size: 19px;
  }

  .pf-header-label {
    font-size: 8px;
  }

  .pf-header-icon-button {
    width: 38px;
    height: 38px;
  }

  .pf-kpi-grid {
    grid-template-columns: 1fr;
  }

  .pf-intro-actions {
    flex-direction: column;
  }

  .pf-primary-button,
  .pf-secondary-button {
    width: 100%;
  }

  .pf-pharmacy-banner {
    padding: 17px;
  }

  .pf-banner-main {
    gap: 11px;
  }

  .pf-banner-logo {
    width: 48px;
    height: 48px;
    flex-basis: 48px;
  }

  .pf-panel-header {
    padding: 18px;
  }

  .pf-panel-header h3 {
    font-size: 17px;
  }

  .pf-dashboard-table {
    min-width: 650px;
  }

  .pf-stock-summary {
    grid-template-columns: 1fr;
  }

  .pf-stock-summary-card {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .pf-stock-summary-card strong {
    margin: 0;
  }

  .pf-dashboard-footer {
    align-items: flex-start;
    flex-direction: column;
    gap: 9px;
  }
}
/* =========================================================
   PHARMAFLOW — PREMIUM PRODUCTS UI
   ========================================================= */

.pf-products-page {
  width: 100%;
  min-height: calc(100vh - var(--pf-topbar-height));
  background: #f5f8f8;
  padding: 28px 32px 40px;
}

.pf-products-container {
  width: 100%;
  max-width: 1600px;
  margin: 0 auto;
}

/* HEADER PRODUITS */
.pf-products-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
}

.pf-products-title {
  display: flex;
  align-items: center;
  gap: 16px;
}

.pf-products-icon {
  width: 54px;
  height: 54px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 16px;
  background: linear-gradient(135deg, #0f766e, #0d9488);
  color: white;
  font-size: 24px;
  box-shadow: 0 8px 20px rgba(15, 118, 110, 0.20);
}

.pf-products-title h1 {
  margin: 0;
  font-size: 28px;
  line-height: 1.2;
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -0.5px;
}

.pf-products-title p {
  margin: 6px 0 0;
  font-size: 14px;
  color: #64748b;
}

/* BOUTON AJOUTER */
.pf-products-add {
  border: 0;
  border-radius: 12px;
  padding: 13px 20px;
  background: #0f766e;
  color: white;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  box-shadow: 0 7px 18px rgba(15, 118, 110, 0.18);
  transition: all 0.2s ease;
}

.pf-products-add:hover {
  background: #115e59;
  transform: translateY(-1px);
  box-shadow: 0 10px 24px rgba(15, 118, 110, 0.25);
}

/* =========================================================
   STATISTIQUES
   ========================================================= */

.pf-products-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
  margin-bottom: 24px;
}

.pf-product-stat {
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 15px;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.035);
  transition: all 0.2s ease;
}

.pf-product-stat:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.07);
}

.pf-product-stat-icon {
  width: 46px;
  height: 46px;
  flex-shrink: 0;
  border-radius: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #e6f5f2;
  color: #0f766e;
  font-size: 20px;
}

.pf-product-stat-label {
  font-size: 12px;
  font-weight: 600;
  color: #64748b;
  margin-bottom: 4px;
}

.pf-product-stat-value {
  font-size: 24px;
  line-height: 1;
  font-weight: 800;
  color: #0f172a;
}

/* =========================================================
   BARRE DE RECHERCHE / FILTRES
   ========================================================= */

.pf-products-toolbar {
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  padding: 17px;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.035);
}

.pf-products-search {
  flex: 1;
  min-width: 260px;
  height: 44px;
  border: 1px solid #dbe3ea;
  border-radius: 11px;
  padding: 0 15px;
  outline: none;
  background: #f8fafc;
  color: #0f172a;
  font-size: 14px;
  transition: all 0.2s ease;
}

.pf-products-search:focus {
  background: white;
  border-color: #0f766e;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.10);
}

.pf-products-filter {
  height: 44px;
  min-width: 170px;
  border: 1px solid #dbe3ea;
  border-radius: 11px;
  padding: 0 13px;
  background: white;
  color: #334155;
  font-size: 14px;
  font-weight: 500;
  outline: none;
}

.pf-products-filter:focus {
  border-color: #0f766e;
}

/* =========================================================
   TABLEAU
   ========================================================= */

.pf-products-table-card {
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 3px 12px rgba(15, 23, 42, 0.045);
}

.pf-products-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.pf-products-table {
  width: 100%;
  min-width: 1050px;
  border-collapse: collapse;
}

.pf-products-table thead {
  background: #f8fafc;
}

.pf-products-table th {
  padding: 15px 18px;
  text-align: left;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 800;
  color: #64748b;
  border-bottom: 1px solid #e2e8f0;
  white-space: nowrap;
}

.pf-products-table td {
  padding: 17px 18px;
  border-bottom: 1px solid #edf1f4;
  font-size: 14px;
  color: #334155;
  vertical-align: middle;
}

.pf-products-table tbody tr {
  transition: background 0.15s ease;
}

.pf-products-table tbody tr:hover {
  background: #f8fbfb;
}

.pf-products-table tbody tr:last-child td {
  border-bottom: 0;
}

/* NOM PRODUIT */
.pf-product-name {
  display: flex;
  align-items: center;
  gap: 12px;
}

.pf-product-avatar {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #e6f5f2;
  color: #0f766e;
  font-weight: 800;
  font-size: 15px;
}

.pf-product-name-main {
  font-weight: 700;
  color: #0f172a;
}

.pf-product-name-sub {
  margin-top: 3px;
  font-size: 12px;
  color: #94a3b8;
}

/* PRIX */
.pf-product-price {
  font-weight: 700;
  color: #0f172a;
  white-space: nowrap;
}

/* STOCK */
.pf-stock-good {
  color: #047857;
  font-weight: 800;
}

.pf-stock-warning {
  color: #d97706;
  font-weight: 800;
}

.pf-stock-danger {
  color: #dc2626;
  font-weight: 800;
}

/* BADGES */
.pf-product-badge {
  display: inline-flex;
  align-items: center;
  padding: 5px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.pf-product-badge-active {
  background: #dcfce7;
  color: #15803d;
}

.pf-product-badge-inactive {
  background: #f1f5f9;
  color: #64748b;
}

.pf-product-badge-expired {
  background: #fee2e2;
  color: #b91c1c;
}

.pf-product-badge-warning {
  background: #fef3c7;
  color: #b45309;
}

/* =========================================================
   ACTIONS
   ========================================================= */

.pf-product-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.pf-product-action {
  width: 34px;
  height: 34px;
  border: 1px solid #e2e8f0;
  border-radius: 9px;
  background: white;
  color: #64748b;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.18s ease;
}

.pf-product-action:hover {
  border-color: #0f766e;
  color: #0f766e;
  background: #e6f5f2;
}

.pf-product-action-danger:hover {
  border-color: #fecaca;
  color: #dc2626;
  background: #fef2f2;
}

/* =========================================================
   MODAL PRODUIT
   ========================================================= */

.pf-product-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  background: rgba(15, 23, 42, 0.48);
  backdrop-filter: blur(5px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.pf-product-modal {
  width: min(760px, 100%);
  max-height: calc(100vh - 48px);
  overflow-y: auto;
  background: white;
  border-radius: 20px;
  box-shadow: 0 25px 70px rgba(15, 23, 42, 0.20);
}

.pf-product-modal-header {
  padding: 22px 24px;
  border-bottom: 1px solid #e2e8f0;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pf-product-modal-title {
  font-size: 20px;
  font-weight: 800;
  color: #0f172a;
}

.pf-product-modal-close {
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 9px;
  background: #f1f5f9;
  color: #64748b;
  cursor: pointer;
  font-size: 18px;
}

.pf-product-modal-close:hover {
  background: #fee2e2;
  color: #dc2626;
}

.pf-product-modal-body {
  padding: 24px;
}

.pf-product-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.pf-product-form-full {
  grid-column: 1 / -1;
}

.pf-product-form-label {
  display: block;
  margin-bottom: 7px;
  font-size: 13px;
  font-weight: 700;
  color: #334155;
}

.pf-product-form-input {
  width: 100%;
  height: 44px;
  padding: 0 13px;
  border: 1px solid #dbe3ea;
  border-radius: 10px;
  background: white;
  color: #0f172a;
  outline: none;
  font-size: 14px;
  transition: all 0.2s ease;
}

.pf-product-form-input:focus {
  border-color: #0f766e;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.10);
}

.pf-product-modal-footer {
  padding: 18px 24px;
  border-top: 1px solid #e2e8f0;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

/* =========================================================
   EMPTY STATE
   ========================================================= */

.pf-products-empty {
  padding: 70px 30px;
  text-align: center;
}

.pf-products-empty-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 16px;
  border-radius: 18px;
  background: #e6f5f2;
  color: #0f766e;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 27px;
}

.pf-products-empty h3 {
  margin: 0;
  font-size: 18px;
  font-weight: 800;
  color: #0f172a;
}

.pf-products-empty p {
  margin: 7px 0 0;
  font-size: 14px;
  color: #64748b;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {
  .pf-products-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .pf-products-page {
    padding: 20px 15px 30px;
  }

  .pf-products-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .pf-products-add {
    width: 100%;
    justify-content: center;
  }

  .pf-products-stats {
    grid-template-columns: 1fr;
  }

  .pf-products-toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .pf-products-search {
    min-width: 0;
    width: 100%;
  }

  .pf-products-filter {
    width: 100%;
  }

  .pf-product-form-grid {
    grid-template-columns: 1fr;
  }

  .pf-product-form-full {
    grid-column: auto;
  }

  .pf-product-modal-overlay {
    padding: 12px;
  }

  .pf-product-modal {
    max-height: calc(100vh - 24px);
  }
}
/* =========================================================
   PHARMAFLOW — CORRECTION POSITION PAGE PRODUITS
   ========================================================= */

.pf-app {
  width: 100%;
  min-height: 100vh;
  display: flex;
  align-items: stretch;
}

/* SIDEBAR */
.pf-sidebar {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: var(--pf-sidebar-width);
  height: 100vh;
  z-index: 100;
  overflow-y: auto;
}

/* ZONE PRINCIPALE */
.pf-main {
  width: calc(100% - var(--pf-sidebar-width));
  min-width: 0;
  min-height: 100vh;
  margin-left: var(--pf-sidebar-width);
  display: flex;
  flex-direction: column;
}

/* TOPBAR */
.pf-topbar {
  width: 100%;
  min-height: var(--pf-topbar-height);
  flex-shrink: 0;
}

/* CONTENU */
.pf-content {
  width: 100%;
  flex: 1;
  min-width: 0;
  padding: 0;
  margin: 0;
  display: block;
}

/* PAGE PRODUITS */
.pf-products-page {
  width: 100%;
  min-height: auto;
  padding: 26px 30px 40px;
  margin: 0;
  background: #f5f8f8;
}

/* CONTENEUR PRODUITS */
.pf-products-container {
  width: 100%;
  max-width: none;
  margin: 0;
}

/* HEADER */
.pf-products-header {
  width: 100%;
  margin: 0 0 22px;
}

/* STATISTIQUES */
.pf-products-stats {
  width: 100%;
  margin-bottom: 20px;
}

/* BARRE RECHERCHE */
.pf-products-toolbar {
  width: 100%;
  margin-bottom: 18px;
}

/* TABLEAU */
.pf-products-table-card {
  width: 100%;
  margin: 0;
}

/* =========================================================
   TOPBAR PRODUITS — ALIGNEMENT
   ========================================================= */

.pf-topbar-left,
.pf-topbar-right {
  display: flex;
  align-items: center;
}

.pf-topbar-left {
  gap: 12px;
}

.pf-topbar-right {
  margin-left: auto;
}

/* =========================================================
   TABLEAU — MEILLEURE UTILISATION DE L'ESPACE
   ========================================================= */

.pf-products-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.pf-products-table {
  width: 100%;
  min-width: 1000px;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {
  .pf-sidebar {
    transform: translateX(-100%);
    transition: transform 0.25s ease;
  }

  .pf-sidebar.pf-sidebar-open {
    transform: translateX(0);
  }

  .pf-main {
    width: 100%;
    margin-left: 0;
  }

  .pf-products-page {
    padding: 22px 18px 35px;
  }
}

@media (max-width: 600px) {
  .pf-products-page {
    padding: 18px 14px 30px;
  }
}
/* =========================================================
   SIDEBAR — ASPECT PLUS PRO
   ========================================================= */

.pf-sidebar {
  background: #ffffff;
  border-right: 1px solid #e2e8f0;
  box-shadow: 4px 0 18px rgba(15, 23, 42, 0.035);
}

.pf-sidebar-brand {
  min-height: 76px;
  padding: 18px 20px;
}

.pf-pharmacy-card {
  margin: 10px 14px 18px;
}

.pf-sidebar-nav {
  padding: 4px 12px;
}

.pf-nav-section-title {
  margin: 18px 10px 8px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #94a3b8;
}

.pf-nav-item {
  min-height: 44px;
  margin-bottom: 4px;
  padding: 0 12px;
  border-radius: 10px;
}

.pf-sidebar-bottom {
  padding: 16px 14px 18px;
}
/* =========================================================
   PHARMAFLOW — PAGE VENTES / CAISSE
   Correspond exactement à ventes/page.tsx
   ========================================================= */

.pf-sales-page {
  min-height: 100vh;
  background: #f5f8f8;
  color: #0f172a;
}

.pf-sales-container {
  width: min(1680px, calc(100% - 48px));
  margin: 0 auto;
  padding: 28px 0 40px;
}

/* =========================================================
   HEADER
   ========================================================= */

.pf-sales-header {
  background: #ffffff;
  border-bottom: 1px solid #e2e8f0;
  position: sticky;
  top: 0;
  z-index: 30;
}

.pf-sales-header-inner {
  width: min(1680px, calc(100% - 48px));
  min-height: 82px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.pf-sales-title-area {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.pf-sales-back {
  width: 40px;
  height: 40px;
  border: 1px solid #e2e8f0;
  border-radius: 11px;
  background: #ffffff;
  color: #475569;
  font-size: 21px;
  cursor: pointer;
  transition: 0.2s ease;
}

.pf-sales-back:hover {
  border-color: #0f766e;
  color: #0f766e;
  background: #f0fdfa;
}

.pf-sales-title-icon {
  width: 50px;
  height: 50px;
  flex: 0 0 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  background: #e6f5f2;
  font-size: 25px;
}

.pf-sales-title-area h1 {
  margin: 0;
  font-size: 25px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: -0.5px;
  color: #0f172a;
}

.pf-sales-title-area p {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 14px;
}

.pf-sales-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* =========================================================
   BOUTONS
   ========================================================= */

.pf-sales-btn {
  min-height: 42px;
  border-radius: 10px;
  padding: 0 16px;
  border: 1px solid transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
}

.pf-sales-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.pf-sales-btn-primary {
  background: #0f766e;
  color: #ffffff;
  border-color: #0f766e;
}

.pf-sales-btn-primary:hover:not(:disabled) {
  background: #115e59;
  border-color: #115e59;
}

.pf-sales-btn-secondary {
  background: #ffffff;
  color: #334155;
  border-color: #dbe3e8;
}

.pf-sales-btn-secondary:hover:not(:disabled) {
  border-color: #0f766e;
  color: #0f766e;
  background: #f0fdfa;
}

/* =========================================================
   ALERTES
   ========================================================= */

.pf-sales-alert {
  min-height: 48px;
  margin-bottom: 20px;
  padding: 12px 16px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  gap: 11px;
  font-size: 14px;
  font-weight: 600;
}

.pf-sales-alert-success {
  color: #166534;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
}

.pf-sales-alert-error {
  color: #b91c1c;
  background: #fef2f2;
  border: 1px solid #fecaca;
}

.pf-sales-alert-error button {
  margin-left: auto;
  border: 0;
  background: transparent;
  color: inherit;
  font-size: 20px;
  cursor: pointer;
}

/* =========================================================
   STATISTIQUES
   ========================================================= */

.pf-sales-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}

.pf-sales-stat {
  border: 1px solid #e2e8f0;
  background: #ffffff;
  border-radius: 14px;
  padding: 17px;
  display: flex;
  align-items: center;
  gap: 14px;
  text-align: left;
  cursor: pointer;
  transition: all 0.2s ease;
}

.pf-sales-stat:hover {
  transform: translateY(-1px);
  border-color: #cbd5e1;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.06);
}

.pf-sales-stat-active {
  border-color: #0f766e;
  box-shadow: 0 0 0 2px rgba(15, 118, 110, 0.08);
}

.pf-sales-stat-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
  flex: 0 0 44px;
}

.pf-sales-stat-icon-blue {
  background: #eff6ff;
}

.pf-sales-stat-icon-green {
  background: #f0fdf4;
}

.pf-sales-stat-icon-orange {
  background: #fff7ed;
}

.pf-sales-stat-icon-red {
  background: #fef2f2;
}

.pf-sales-stat div:last-child {
  min-width: 0;
}

.pf-sales-stat span {
  display: block;
  color: #64748b;
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 3px;
}

.pf-sales-stat strong {
  display: block;
  color: #0f172a;
  font-size: 21px;
  font-weight: 800;
}

/* =========================================================
   LAYOUT PRODUITS + PANIER
   ========================================================= */

.pf-sales-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 430px;
  gap: 20px;
  align-items: start;
}

.pf-sales-products-panel,
.pf-sales-cart-panel,
.pf-sales-recent {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  box-shadow: 0 4px 18px rgba(15, 23, 42, 0.035);
}

.pf-sales-products-panel {
  min-width: 0;
  padding: 22px;
}

.pf-sales-panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 18px;
}

.pf-sales-panel-header h2,
.pf-sales-cart-header h2,
.pf-sales-recent-header h2 {
  margin: 0;
  color: #0f172a;
  font-size: 18px;
  font-weight: 800;
}

.pf-sales-panel-header p,
.pf-sales-recent-header p {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 13px;
}

.pf-sales-result-count {
  flex-shrink: 0;
  padding: 7px 10px;
  border-radius: 8px;
  background: #f1f5f9;
  color: #475569;
  font-size: 12px;
  font-weight: 700;
}

/* =========================================================
   RECHERCHE / FILTRES
   ========================================================= */

.pf-sales-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 220px;
  gap: 10px;
  margin-bottom: 11px;
}

.pf-sales-search {
  height: 46px;
  border: 1px solid #dbe3e8;
  border-radius: 10px;
  background: #ffffff;
  display: flex;
  align-items: center;
  padding: 0 13px;
  transition: 0.2s ease;
}

.pf-sales-search:focus-within {
  border-color: #0f766e;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.08);
}

.pf-sales-search > span {
  color: #94a3b8;
  font-size: 23px;
  margin-right: 8px;
}

.pf-sales-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: #0f172a;
  font-size: 14px;
}

.pf-sales-search input::placeholder {
  color: #94a3b8;
}

.pf-sales-search button {
  border: 0;
  background: transparent;
  color: #94a3b8;
  font-size: 20px;
  cursor: pointer;
}

.pf-sales-select {
  height: 46px;
  padding: 0 12px;
  border: 1px solid #dbe3e8;
  border-radius: 10px;
  background: #ffffff;
  color: #334155;
  outline: 0;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.pf-sales-select:focus {
  border-color: #0f766e;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.08);
}

.pf-sales-filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 19px;
}

.pf-sales-filter-row button {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  background: #ffffff;
  color: #64748b;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: 0.2s ease;
}

.pf-sales-filter-row button:hover {
  border-color: #99f6e4;
  color: #0f766e;
}

.pf-sales-filter-row button.pf-sales-filter-active {
  color: #0f766e;
  background: #e6f5f2;
  border-color: #99f6e4;
}

/* =========================================================
   GRILLE PRODUITS
   ========================================================= */

.pf-sales-product-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
}

.pf-sales-product-card {
  min-width: 0;
  padding: 15px;
  border: 1px solid #e2e8f0;
  border-radius: 13px;
  background: #ffffff;
  transition: all 0.2s ease;
  display: flex;
  flex-direction: column;
}

.pf-sales-product-card:hover {
  border-color: #a7dcd6;
  box-shadow: 0 10px 25px rgba(15, 118, 110, 0.08);
  transform: translateY(-1px);
}

.pf-sales-product-disabled {
  opacity: 0.7;
}

.pf-sales-product-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 13px;
}

.pf-sales-product-avatar {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: #e6f5f2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
}

.pf-sales-stock-badge {
  padding: 5px 8px;
  border-radius: 7px;
  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
}

.pf-sales-stock-good {
  background: #f0fdf4;
  color: #15803d;
}

.pf-sales-stock-low {
  background: #fff7ed;
  color: #c2410c;
}

.pf-sales-stock-out {
  background: #fef2f2;
  color: #dc2626;
}

.pf-sales-product-info {
  min-height: 82px;
}

.pf-sales-product-info h3 {
  margin: 0;
  color: #0f172a;
  font-size: 14px;
  font-weight: 800;
  line-height: 1.35;
}

.pf-sales-generic {
  margin: 4px 0 0;
  color: #64748b;
  font-size: 11px;
  line-height: 1.35;
}

.pf-sales-product-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 8px;
}

.pf-sales-product-meta span {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 4px 6px;
  border-radius: 5px;
  background: #f8fafc;
  color: #64748b;
  font-size: 9px;
  font-weight: 600;
}

.pf-sales-product-bottom {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 10px;
  margin-top: 11px;
  padding-top: 11px;
  border-top: 1px solid #f1f5f9;
}

.pf-sales-product-bottom strong {
  color: #0f766e;
  font-size: 14px;
  font-weight: 800;
}

.pf-sales-product-bottom span {
  color: #94a3b8;
  font-size: 10px;
}

.pf-sales-stock-number {
  color: #64748b;
  font-size: 10px;
}

.pf-sales-stock-number strong {
  color: #334155;
  font-size: 11px;
}

.pf-sales-in-cart {
  margin-top: 8px;
  padding: 6px 8px;
  border-radius: 7px;
  background: #f0fdfa;
  color: #0f766e;
  font-size: 10px;
  font-weight: 700;
}

.pf-sales-add-product {
  width: 100%;
  height: 37px;
  margin-top: 11px;
  border: 0;
  border-radius: 8px;
  background: #0f766e;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: 0.2s ease;
}

.pf-sales-add-product:hover:not(:disabled) {
  background: #115e59;
}

.pf-sales-add-product:disabled {
  background: #e2e8f0;
  color: #94a3b8;
  cursor: not-allowed;
}

/* =========================================================
   PANIER
   ========================================================= */

.pf-sales-cart-panel {
  position: sticky;
  top: 102px;
  overflow: hidden;
}

.pf-sales-cart-header {
  padding: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid #e2e8f0;
}

.pf-sales-cart-header p {
  margin: 4px 0 0;
  color: #94a3b8;
  font-size: 11px;
}

.pf-sales-clear {
  border: 0;
  background: transparent;
  color: #dc2626;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.pf-sales-clear:hover {
  text-decoration: underline;
}

.pf-sales-cart-empty {
  padding: 55px 25px;
  text-align: center;
}

.pf-sales-cart-empty-icon {
  width: 65px;
  height: 65px;
  margin: 0 auto 15px;
  border-radius: 18px;
  background: #f1f5f9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
}

.pf-sales-cart-empty h3 {
  margin: 0;
  color: #334155;
  font-size: 15px;
}

.pf-sales-cart-empty p {
  max-width: 260px;
  margin: 7px auto 0;
  color: #94a3b8;
  font-size: 12px;
  line-height: 1.5;
}

.pf-sales-cart-items {
  max-height: 420px;
  overflow-y: auto;
  padding: 5px 20px;
}

.pf-sales-cart-item {
  padding: 14px 0;
  border-bottom: 1px solid #f1f5f9;
}

.pf-sales-cart-item-main {
  display: flex;
  align-items: center;
  gap: 9px;
}

.pf-sales-cart-item-icon {
  width: 33px;
  height: 33px;
  flex: 0 0 33px;
  border-radius: 8px;
  background: #e6f5f2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
}

.pf-sales-cart-item-info {
  min-width: 0;
  flex: 1;
}

.pf-sales-cart-item-info strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #334155;
  font-size: 12px;
}

.pf-sales-cart-item-info span {
  display: block;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 9px;
}

.pf-sales-remove {
  width: 25px;
  height: 25px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #94a3b8;
  font-size: 18px;
  cursor: pointer;
}

.pf-sales-remove:hover {
  background: #fef2f2;
  color: #dc2626;
}

.pf-sales-cart-item-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
}

.pf-sales-cart-item-controls > strong {
  color: #0f766e;
  font-size: 12px;
}

.pf-sales-quantity {
  display: inline-flex;
  align-items: center;
  border: 1px solid #e2e8f0;
  border-radius: 7px;
  overflow: hidden;
}

.pf-sales-quantity button {
  width: 29px;
  height: 28px;
  border: 0;
  background: #f8fafc;
  color: #334155;
  cursor: pointer;
  font-size: 15px;
}

.pf-sales-quantity button:hover {
  background: #e6f5f2;
  color: #0f766e;
}

.pf-sales-quantity strong {
  min-width: 29px;
  text-align: center;
  color: #334155;
  font-size: 11px;
}

.pf-sales-item-discount {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
}

.pf-sales-item-discount label {
  flex: 1;
  color: #94a3b8;
  font-size: 9px;
}

.pf-sales-item-discount input {
  width: 75px;
  height: 27px;
  padding: 0 7px;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  outline: 0;
  color: #334155;
  font-size: 10px;
}

.pf-sales-item-discount input:focus {
  border-color: #0f766e;
}

.pf-sales-item-discount span {
  color: #94a3b8;
  font-size: 9px;
}

/* =========================================================
   CLIENT
   ========================================================= */

.pf-sales-customer {
  padding: 17px 20px;
  border-top: 1px solid #e2e8f0;
}

.pf-sales-section-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 9px;
  color: #334155;
  font-size: 11px;
  font-weight: 800;
}

.pf-sales-section-label span {
  color: #94a3b8;
  font-size: 9px;
  font-weight: 600;
}

.pf-sales-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin-bottom: 7px;
}

.pf-sales-customer input,
.pf-sales-customer textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid #e2e8f0;
  border-radius: 7px;
  outline: 0;
  background: #ffffff;
  color: #334155;
  font-family: inherit;
  font-size: 10px;
}

.pf-sales-customer input {
  height: 34px;
  padding: 0 9px;
}

.pf-sales-customer textarea {
  min-height: 52px;
  padding: 8px 9px;
  resize: vertical;
}

.pf-sales-customer input:focus,
.pf-sales-customer textarea:focus {
  border-color: #0f766e;
  box-shadow: 0 0 0 2px rgba(15, 118, 110, 0.07);
}

.pf-sales-customer input::placeholder,
.pf-sales-customer textarea::placeholder {
  color: #a1acb9;
}

/* =========================================================
   RÉSUMÉ
   ========================================================= */

.pf-sales-summary {
  padding: 16px 20px;
  background: #f8fafc;
  border-top: 1px solid #e2e8f0;
  border-bottom: 1px solid #e2e8f0;
}

.pf-sales-summary > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 9px;
}

.pf-sales-summary > div > span {
  color: #64748b;
  font-size: 11px;
}

.pf-sales-summary > div > strong {
  color: #334155;
  font-size: 11px;
}

.pf-sales-discount-line strong {
  color: #dc2626 !important;
}

.pf-sales-discount-input {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.pf-sales-discount-input label {
  color: #64748b;
  font-size: 11px;
}

.pf-sales-discount-input > div {
  display: flex;
  align-items: center;
  gap: 5px;
}

.pf-sales-discount-input input {
  width: 80px;
  height: 29px;
  padding: 0 7px;
  border: 1px solid #dbe3e8;
  border-radius: 6px;
  outline: 0;
  font-size: 10px;
  text-align: right;
}

.pf-sales-discount-input input:focus {
  border-color: #0f766e;
}

.pf-sales-discount-input span {
  color: #94a3b8;
  font-size: 9px;
}

.pf-sales-total {
  margin: 13px -4px 0 !important;
  padding-top: 13px;
  border-top: 1px dashed #cbd5e1;
}

.pf-sales-total span {
  color: #0f172a !important;
  font-size: 13px !important;
  font-weight: 800;
}

.pf-sales-total strong {
  color: #0f766e !important;
  font-size: 20px !important;
  font-weight: 900 !important;
}

/* =========================================================
   BOUTON ENCAISSER
   ========================================================= */

.pf-sales-checkout-btn {
  width: calc(100% - 40px);
  margin: 16px 20px 20px;
  min-height: 58px;
  padding: 9px 13px;
  border: 0;
  border-radius: 11px;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  text-align: left;
  transition: 0.2s ease;
}

.pf-sales-checkout-btn:hover {
  background: #115e59;
  transform: translateY(-1px);
  box-shadow: 0 8px 20px rgba(15, 118, 110, 0.18);
}

.pf-sales-checkout-btn > span:first-child {
  font-size: 22px;
}

.pf-sales-checkout-btn > span:last-child {
  margin-left: auto;
  font-size: 20px;
}

.pf-sales-checkout-btn div {
  flex: 1;
}

.pf-sales-checkout-btn strong {
  display: block;
  font-size: 13px;
}

.pf-sales-checkout-btn small {
  display: block;
  margin-top: 2px;
  opacity: 0.8;
  font-size: 10px;
}

/* =========================================================
   EMPTY
   ========================================================= */

.pf-sales-empty {
  padding: 70px 25px;
  text-align: center;
  border: 1px dashed #dbe3e8;
  border-radius: 12px;
  background: #fafcfc;
}

.pf-sales-empty-icon {
  width: 58px;
  height: 58px;
  margin: 0 auto 14px;
  border-radius: 16px;
  background: #f1f5f9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 25px;
}

.pf-sales-empty h3 {
  margin: 0;
  color: #334155;
  font-size: 15px;
}

.pf-sales-empty p {
  margin: 6px 0 16px;
  color: #94a3b8;
  font-size: 12px;
}

/* =========================================================
   VENTES RÉCENTES
   ========================================================= */

.pf-sales-recent {
  margin-top: 20px;
  overflow: hidden;
}

.pf-sales-recent-header {
  min-height: 76px;
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-bottom: 1px solid #e2e8f0;
}

.pf-sales-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.pf-sales-table {
  width: 100%;
  border-collapse: collapse;
}

.pf-sales-table th {
  padding: 12px 20px;
  background: #f8fafc;
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
  text-align: left;
  white-space: nowrap;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.pf-sales-table td {
  padding: 14px 20px;
  border-top: 1px solid #f1f5f9;
  color: #64748b;
  font-size: 12px;
  white-space: nowrap;
}

.pf-sales-table tbody tr:hover {
  background: #fafdfd;
}

.pf-sales-table td strong {
  color: #334155;
}

.pf-sales-table-total {
  color: #0f766e !important;
}

.pf-sales-client strong {
  display: block;
  font-size: 12px;
}

.pf-sales-client span {
  display: block;
  margin-top: 2px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-sales-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 8px;
  border-radius: 6px;
  background: #f0fdf4;
  color: #15803d;
  font-size: 10px;
  font-weight: 800;
}

.pf-sales-recent-empty {
  padding: 45px 20px;
  text-align: center;
  color: #94a3b8;
  font-size: 13px;
}

/* =========================================================
   MODAL ENCAISSEMENT
   ========================================================= */

.pf-sales-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  padding: 20px;
  background: rgba(15, 23, 42, 0.45);
  backdrop-filter: blur(5px);
  display: flex;
  align-items: center;
  justify-content: center;
}

.pf-sales-modal {
  width: min(560px, 100%);
  max-height: calc(100vh - 40px);
  overflow-y: auto;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 25px 80px rgba(15, 23, 42, 0.25);
}

.pf-sales-modal-header {
  min-height: 78px;
  padding: 0 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid #e2e8f0;
}

.pf-sales-modal-header > div {
  display: flex;
  align-items: center;
  gap: 12px;
}

.pf-sales-modal-icon {
  width: 43px;
  height: 43px;
  border-radius: 12px;
  background: #e6f5f2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}

.pf-sales-modal-header h2 {
  margin: 0;
  color: #0f172a;
  font-size: 17px;
  font-weight: 800;
}

.pf-sales-modal-header p {
  margin: 3px 0 0;
  color: #94a3b8;
  font-size: 11px;
}

.pf-sales-modal-close {
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 8px;
  background: #f8fafc;
  color: #64748b;
  font-size: 21px;
  cursor: pointer;
}

.pf-sales-modal-close:hover {
  background: #fef2f2;
  color: #dc2626;
}

.pf-sales-modal-body {
  padding: 22px;
}

.pf-sales-payment-total {
  padding: 18px;
  border-radius: 12px;
  background: #f0fdfa;
  border: 1px solid #ccfbf1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.pf-sales-payment-total span {
  color: #64748b;
  font-size: 12px;
  font-weight: 600;
}

.pf-sales-payment-total strong {
  color: #0f766e;
  font-size: 25px;
  font-weight: 900;
}

.pf-sales-payment-section {
  margin-top: 20px;
}

.pf-sales-payment-section > label,
.pf-sales-paid-section > label {
  display: block;
  margin-bottom: 9px;
  color: #334155;
  font-size: 12px;
  font-weight: 800;
}

.pf-sales-payment-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 7px;
}

.pf-sales-payment-grid button {
  min-height: 72px;
  padding: 8px 5px;
  border: 1px solid #e2e8f0;
  border-radius: 9px;
  background: #ffffff;
  color: #64748b;
  cursor: pointer;
  transition: 0.2s ease;
}

.pf-sales-payment-grid button:hover {
  border-color: #99f6e4;
  color: #0f766e;
}

.pf-sales-payment-grid button.pf-sales-payment-active {
  border-color: #0f766e;
  background: #e6f5f2;
  color: #0f766e;
  box-shadow: 0 0 0 2px rgba(15, 118, 110, 0.07);
}

.pf-sales-payment-grid button span {
  display: block;
  font-size: 19px;
  margin-bottom: 5px;
}

.pf-sales-payment-grid button strong {
  display: block;
  font-size: 9px;
}

.pf-sales-paid-section {
  margin-top: 20px;
}

.pf-sales-paid-input {
  height: 54px;
  display: flex;
  align-items: center;
  border: 1px solid #dbe3e8;
  border-radius: 10px;
  padding: 0 13px;
  transition: 0.2s ease;
}

.pf-sales-paid-input:focus-within {
  border-color: #0f766e;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.08);
}

.pf-sales-paid-input input {
  width: 100%;
  border: 0;
  outline: 0;
  color: #0f172a;
  font-size: 20px;
  font-weight: 800;
  background: transparent;
}

.pf-sales-paid-input span {
  color: #64748b;
  font-size: 12px;
  font-weight: 700;
}

.pf-sales-quick-amounts {
  display: flex;
  gap: 7px;
  margin-top: 8px;
}

.pf-sales-quick-amounts button {
  min-height: 31px;
  padding: 0 10px;
  border: 1px solid #e2e8f0;
  border-radius: 7px;
  background: #ffffff;
  color: #64748b;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
}

.pf-sales-quick-amounts button:hover {
  border-color: #99f6e4;
  color: #0f766e;
  background: #f0fdfa;
}

.pf-sales-change {
  margin-top: 18px;
  padding: 14px 16px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pf-sales-change-positive {
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
}

.pf-sales-change-negative {
  background: #fef2f2;
  border: 1px solid #fecaca;
}

.pf-sales-change span {
  font-size: 11px;
  font-weight: 700;
}

.pf-sales-change-positive span {
  color: #15803d;
}

.pf-sales-change-negative span {
  color: #dc2626;
}

.pf-sales-change strong {
  font-size: 17px;
  font-weight: 900;
}

.pf-sales-change-positive strong {
  color: #15803d;
}

.pf-sales-change-negative strong {
  color: #dc2626;
}

.pf-sales-payment-client {
  margin-top: 13px;
  padding: 10px 12px;
  border-radius: 8px;
  background: #f8fafc;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pf-sales-payment-client span {
  color: #94a3b8;
  font-size: 10px;
}

.pf-sales-payment-client strong {
  color: #334155;
  font-size: 11px;
}

.pf-sales-modal-footer {
  padding: 15px 22px;
  border-top: 1px solid #e2e8f0;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.pf-sales-confirm-btn {
  min-height: 42px;
  padding: 0 18px;
  border: 0;
  border-radius: 9px;
  background: #0f766e;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.pf-sales-confirm-btn:hover:not(:disabled) {
  background: #115e59;
}

.pf-sales-confirm-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* =========================================================
   LOADING
   ========================================================= */

.pf-sales-loading {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #f5f8f8;
  text-align: center;
}

.pf-sales-loading h2 {
  margin: 16px 0 5px;
  color: #334155;
  font-size: 17px;
}

.pf-sales-loading p {
  margin: 0;
  color: #94a3b8;
  font-size: 12px;
}

.pf-sales-spinner,
.pf-sales-small-spinner {
  border-radius: 50%;
  border: 3px solid #d1fae5;
  border-top-color: #0f766e;
  animation: pf-sales-spin 0.8s linear infinite;
}

.pf-sales-spinner {
  width: 38px;
  height: 38px;
}

.pf-sales-small-spinner {
  width: 15px;
  height: 15px;
  border-width: 2px;
}

@keyframes pf-sales-spin {
  to {
    transform: rotate(360deg);
  }
}

/* =========================================================
   FOOTER
   ========================================================= */

.pf-sales-footer {
  padding: 22px 3px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  color: #94a3b8;
  font-size: 10px;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1250px) {
  .pf-sales-layout {
    grid-template-columns: minmax(0, 1fr) 390px;
  }

  .pf-sales-product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1050px) {
  .pf-sales-layout {
    grid-template-columns: 1fr;
  }

  .pf-sales-cart-panel {
    position: static;
  }

  .pf-sales-stats {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 760px) {
  .pf-sales-container,
  .pf-sales-header-inner {
    width: min(100% - 24px, 1680px);
  }

  .pf-sales-header-inner {
    min-height: 70px;
  }

  .pf-sales-title-area p {
    display: none;
  }

  .pf-sales-title-area h1 {
    font-size: 19px;
  }

  .pf-sales-title-icon {
    width: 42px;
    height: 42px;
    flex-basis: 42px;
    font-size: 20px;
  }

  .pf-sales-back {
    width: 35px;
    height: 35px;
  }

  .pf-sales-header-actions .pf-sales-btn-secondary {
    display: none;
  }

  .pf-sales-container {
    padding-top: 16px;
  }

  .pf-sales-stats {
    gap: 8px;
  }

  .pf-sales-stat {
    padding: 12px;
  }

  .pf-sales-stat-icon {
    width: 36px;
    height: 36px;
    flex-basis: 36px;
  }

  .pf-sales-stat strong {
    font-size: 17px;
  }

  .pf-sales-products-panel {
    padding: 15px;
  }

  .pf-sales-toolbar {
    grid-template-columns: 1fr;
  }

  .pf-sales-product-grid {
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }

  .pf-sales-product-card {
    padding: 11px;
  }

  .pf-sales-product-info {
    min-height: 76px;
  }

  .pf-sales-product-bottom {
    display: block;
  }

  .pf-sales-stock-number {
    margin-top: 5px;
  }

  .pf-sales-panel-header {
    display: block;
  }

  .pf-sales-result-count {
    display: inline-block;
    margin-top: 9px;
  }

  .pf-sales-payment-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .pf-sales-footer {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .pf-sales-title-icon {
    display: none;
  }

  .pf-sales-header-actions .pf-sales-btn-primary {
    padding: 0 11px;
    font-size: 11px;
  }

  .pf-sales-stats {
    grid-template-columns: 1fr 1fr;
  }

  .pf-sales-product-grid {
    grid-template-columns: 1fr;
  }

  .pf-sales-product-info {
    min-height: auto;
  }

  .pf-sales-form-row {
    grid-template-columns: 1fr;
  }

  .pf-sales-payment-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pf-sales-payment-total strong {
    font-size: 20px;
  }

  .pf-sales-modal-overlay {
    padding: 8px;
  }

  .pf-sales-modal {
    max-height: calc(100vh - 16px);
    border-radius: 14px;
  }

  .pf-sales-modal-body {
    padding: 15px;
  }

  .pf-sales-modal-footer {
    padding: 12px 15px;
  }
}

/* =========================================================
   IMPRESSION
   ========================================================= */

@media print {
  .pf-sales-header,
  .pf-sales-stats,
  .pf-sales-toolbar,
  .pf-sales-filter-row,
  .pf-sales-products-panel,
  .pf-sales-recent,
  .pf-sales-footer,
  .pf-sales-modal-overlay {
    display: none !important;
  }

  .pf-sales-page {
    background: #ffffff;
  }
}
/* =========================================================
   PHARMAFLOW — MODULE REÇU & IMPRESSION
   ========================================================= */

.pf-sales-receipt-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  padding: 24px;
  background: rgba(15, 23, 42, 0.58);
  backdrop-filter: blur(8px);

  display: flex;
  align-items: center;
  justify-content: center;

  overflow-y: auto;
}

/* =========================================================
   FENÊTRE DU REÇU
   ========================================================= */

.pf-sales-receipt-modal {
  width: min(780px, 100%);
  max-height: calc(100vh - 48px);

  display: flex;
  flex-direction: column;

  overflow: hidden;

  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 20px;

  box-shadow:
    0 30px 80px rgba(15, 23, 42, 0.28);
}

/* =========================================================
   EN-TÊTE
   ========================================================= */

.pf-sales-receipt-header {
  min-height: 84px;
  padding: 18px 24px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  background: #ffffff;
  border-bottom: 1px solid #e2e8f0;
}

.pf-sales-receipt-header > div {
  display: flex;
  align-items: center;
  gap: 14px;
}

.pf-sales-receipt-success-icon {
  width: 48px;
  height: 48px;

  flex: 0 0 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #dcfce7;
  color: #15803d;

  font-size: 22px;
  font-weight: 900;
}

.pf-sales-receipt-header h2 {
  margin: 0;

  color: #0f172a;

  font-size: 19px;
  line-height: 1.2;
  font-weight: 800;
}

.pf-sales-receipt-header p {
  margin: 5px 0 0;

  color: #64748b;

  font-size: 12px;
  line-height: 1.4;
}

.pf-sales-receipt-close {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 0;
  border-radius: 10px;

  background: #f8fafc;
  color: #64748b;

  font-size: 23px;
  line-height: 1;

  cursor: pointer;

  transition:
    background 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease;
}

.pf-sales-receipt-close:hover {
  background: #fef2f2;
  color: #dc2626;
  transform: scale(1.04);
}

/* =========================================================
   ZONE APERÇU
   ========================================================= */

.pf-sales-receipt-preview {
  flex: 1;

  min-height: 0;

  overflow-y: auto;

  padding: 30px;

  background:
    linear-gradient(
      135deg,
      #f8fafc 0%,
      #f1f5f9 100%
    );
}

.pf-sales-receipt-preview::-webkit-scrollbar {
  width: 8px;
}

.pf-sales-receipt-preview::-webkit-scrollbar-track {
  background: transparent;
}

.pf-sales-receipt-preview::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 20px;
}

/* =========================================================
   PAPIER DU REÇU
   ========================================================= */

.pf-sales-receipt-paper {
  width: min(430px, 100%);

  margin: 0 auto;
  padding: 30px;

  background: #ffffff;

  border: 1px solid #e2e8f0;

  border-radius: 4px;

  box-shadow:
    0 12px 35px rgba(15, 23, 42, 0.10);
}

/* =========================================================
   IDENTITÉ PHARMACIE
   ========================================================= */

.pf-sales-receipt-brand {
  text-align: center;
}

.pf-sales-receipt-logo {
  width: 52px;
  height: 52px;

  margin: 0 auto 10px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;

  background: #e6f5f2;
  color: #0f766e;

  font-size: 24px;
}

.pf-sales-receipt-brand h3 {
  margin: 0;

  color: #0f172a;

  font-size: 19px;
  line-height: 1.25;
  font-weight: 900;

  text-transform: uppercase;
  letter-spacing: 0.2px;
}

.pf-sales-receipt-brand p {
  margin: 6px 0 0;

  color: #64748b;

  font-size: 10px;
  line-height: 1.5;
}

/* =========================================================
   TITRE REÇU
   ========================================================= */

.pf-sales-receipt-title {
  margin-top: 18px;

  padding: 9px 12px;

  border-radius: 8px;

  background: #f0fdfa;

  color: #0f766e;

  font-size: 12px;
  font-weight: 900;

  text-align: center;
  letter-spacing: 1.5px;
}

/* =========================================================
   INFORMATIONS DE VENTE
   ========================================================= */

.pf-sales-receipt-meta {
  margin-top: 17px;
  padding: 13px 0;

  border-top: 1px dashed #cbd5e1;
  border-bottom: 1px dashed #cbd5e1;
}

.pf-sales-receipt-meta > div {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 18px;

  margin: 6px 0;
}

.pf-sales-receipt-meta span {
  color: #64748b;

  font-size: 10px;
}

.pf-sales-receipt-meta strong {
  color: #334155;

  font-size: 10px;
  font-weight: 700;

  text-align: right;
}

/* =========================================================
   SÉPARATEUR
   ========================================================= */

.pf-sales-receipt-divider {
  margin: 14px 0;

  border-top: 1px dashed #cbd5e1;
}

/* =========================================================
   ARTICLES
   ========================================================= */

.pf-sales-receipt-items {
  width: 100%;
}

.pf-sales-receipt-item {
  padding: 10px 0;

  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 15px;

  border-bottom: 1px solid #f1f5f9;
}

.pf-sales-receipt-item-main {
  min-width: 0;
}

.pf-sales-receipt-item-main strong {
  display: block;

  color: #334155;

  font-size: 11px;
  line-height: 1.4;
  font-weight: 800;
}

.pf-sales-receipt-item-main span {
  display: block;

  margin-top: 3px;

  color: #94a3b8;

  font-size: 9px;
}

.pf-sales-receipt-item > strong {
  flex-shrink: 0;

  color: #0f766e;

  font-size: 10px;
  font-weight: 800;

  text-align: right;
}

/* =========================================================
   TOTAUX
   ========================================================= */

.pf-sales-receipt-totals {
  margin-top: 4px;
}

.pf-sales-receipt-totals > div {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 15px;

  margin: 7px 0;
}

.pf-sales-receipt-totals span {
  color: #64748b;

  font-size: 10px;
}

.pf-sales-receipt-totals strong {
  color: #334155;

  font-size: 10px;
  font-weight: 700;

  text-align: right;
}

.pf-sales-receipt-discount span {
  color: #dc2626;
}

.pf-sales-receipt-discount strong {
  color: #dc2626 !important;
}

/* =========================================================
   TOTAL FINAL
   ========================================================= */

.pf-sales-receipt-total {
  margin-top: 13px !important;
  padding-top: 13px;

  border-top: 2px solid #0f172a;
}

.pf-sales-receipt-total span {
  color: #0f172a !important;

  font-size: 13px !important;
  font-weight: 900 !important;
}

.pf-sales-receipt-total strong {
  color: #0f766e !important;

  font-size: 18px !important;
  font-weight: 900 !important;
}

/* =========================================================
   PAIEMENT
   ========================================================= */

.pf-sales-receipt-payment {
  margin-top: 17px;
  padding: 13px;

  border: 1px solid #e2e8f0;
  border-radius: 10px;

  background: #f8fafc;
}

.pf-sales-receipt-payment > div {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 15px;

  margin: 7px 0;
}

.pf-sales-receipt-payment span {
  color: #64748b;

  font-size: 10px;
}

.pf-sales-receipt-payment strong {
  color: #334155;

  font-size: 10px;
  font-weight: 800;

  text-align: right;
}

/* =========================================================
   NOTES
   ========================================================= */

.pf-sales-receipt-notes {
  margin-top: 15px;
  padding-top: 12px;

  border-top: 1px dashed #cbd5e1;
}

.pf-sales-receipt-notes strong {
  color: #334155;

  font-size: 10px;
  font-weight: 800;
}

.pf-sales-receipt-notes p {
  margin: 5px 0 0;

  color: #64748b;

  font-size: 10px;
  line-height: 1.5;
}

/* =========================================================
   REMERCIEMENT
   ========================================================= */

.pf-sales-receipt-thanks {
  margin-top: 20px;
  padding-top: 14px;

  border-top: 1px dashed #cbd5e1;

  text-align: center;
}

.pf-sales-receipt-thanks strong {
  display: block;

  color: #334155;

  font-size: 10px;
  font-weight: 900;

  letter-spacing: 0.6px;
}

.pf-sales-receipt-thanks span {
  display: block;

  margin-top: 5px;

  color: #94a3b8;

  font-size: 8px;
}

/* =========================================================
   BARRE DES ACTIONS
   ========================================================= */

.pf-sales-receipt-actions {
  min-height: 76px;

  padding: 15px 24px;

  display: flex;
  align-items: center;
  justify-content: flex-end;

  gap: 10px;

  background: #ffffff;

  border-top: 1px solid #e2e8f0;
}

/* =========================================================
   BOUTON IMPRIMER
   ========================================================= */

.pf-sales-print-btn {
  min-height: 44px;

  padding: 0 20px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 8px;

  border: 0;
  border-radius: 10px;

  background: #0f766e;
  color: #ffffff;

  font-size: 12px;
  font-weight: 800;

  cursor: pointer;

  box-shadow:
    0 5px 14px rgba(15, 118, 110, 0.18);

  transition:
    background 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.pf-sales-print-btn:hover {
  background: #115e59;

  transform: translateY(-1px);

  box-shadow:
    0 8px 20px rgba(15, 118, 110, 0.25);
}

.pf-sales-print-btn:active {
  transform: translateY(0);
}

.pf-sales-print-btn:focus-visible {
  outline: 3px solid rgba(15, 118, 110, 0.22);
  outline-offset: 2px;
}

/* =========================================================
   BOUTON FERMER
   ========================================================= */

.pf-sales-receipt-actions
.pf-sales-btn-secondary {
  min-height: 44px;

  padding: 0 17px;

  border: 1px solid #e2e8f0;
  border-radius: 10px;

  background: #ffffff;
  color: #334155;

  font-size: 12px;
  font-weight: 700;

  cursor: pointer;

  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease;
}

.pf-sales-receipt-actions
.pf-sales-btn-secondary:hover {
  background: #f8fafc;
  border-color: #cbd5e1;
  color: #0f172a;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 700px) {

  .pf-sales-receipt-overlay {
    padding: 10px;

    align-items: flex-start;
  }

  .pf-sales-receipt-modal {
    width: 100%;

    max-height: calc(100vh - 20px);

    border-radius: 15px;
  }

  .pf-sales-receipt-header {
    min-height: 72px;

    padding: 14px 16px;
  }

  .pf-sales-receipt-success-icon {
    width: 40px;
    height: 40px;

    flex-basis: 40px;

    font-size: 18px;
  }

  .pf-sales-receipt-header h2 {
    font-size: 16px;
  }

  .pf-sales-receipt-header p {
    font-size: 11px;
  }

  .pf-sales-receipt-preview {
    padding: 15px;
  }

  .pf-sales-receipt-paper {
    padding: 22px 18px;
  }

  .pf-sales-receipt-actions {
    min-height: auto;

    padding: 12px;

    flex-direction: column-reverse;
  }

  .pf-sales-receipt-actions
  .pf-sales-btn-secondary,
  .pf-sales-print-btn {
    width: 100%;
  }
}

/* =========================================================
   IMPRESSION DE L'APERÇU PHARMAFLOW
   ========================================================= */

@media print {

  body {
    background: #ffffff !important;
  }

  .pf-sales-receipt-overlay {
    position: static !important;

    padding: 0 !important;

    background: #ffffff !important;

    display: block !important;
  }

  .pf-sales-receipt-modal {
    width: 100% !important;
    max-height: none !important;

    border: 0 !important;
    border-radius: 0 !important;

    box-shadow: none !important;
  }

  .pf-sales-receipt-header,
  .pf-sales-receipt-actions {
    display: none !important;
  }

  .pf-sales-receipt-preview {
    padding: 0 !important;

    overflow: visible !important;

    background: #ffffff !important;
  }

  .pf-sales-receipt-paper {
    width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    border: 0 !important;
    border-radius: 0 !important;

    box-shadow: none !important;
  }
}
/* =========================================================
   PHARMAFLOW — STOCK & IMPRESSION
   ========================================================= */

/* ---------------------------------------------------------
   AMÉLIORATION GÉNÉRALE STOCK
   --------------------------------------------------------- */

.pf-stock-print-area {
  background: #ffffff;
  color: #0f172a;
}

.pf-stock-print-only {
  display: none;
}

/* ---------------------------------------------------------
   IMPRESSION
   --------------------------------------------------------- */

@media print {
  /* Page blanche et propre */
  html,
  body {
    background: #ffffff !important;
    color: #000000 !important;
    margin: 0 !important;
    padding: 0 !important;
  }

  /* Cacher les éléments inutiles à l'impression */
  header,
  nav,
  button,
  input,
  select,
  textarea,
  .no-print,
  .pf-no-print {
    display: none !important;
  }

  /* Éviter les arrière-plans gris */
  main,
  section,
  div {
    box-shadow: none !important;
  }

  /* Tables propres */
  table {
    width: 100% !important;
    border-collapse: collapse !important;
  }

  th,
  td {
    border: 1px solid #d1d5db !important;
    padding: 8px !important;
    color: #000000 !important;
    background: #ffffff !important;
  }

  th {
    font-weight: 700 !important;
  }

  /* Cacher les cartes statistiques lors de l'impression */
  .pf-stock-stat {
    display: none !important;
  }

  /* Afficher les éléments réservés à l'impression */
  .pf-stock-print-only {
    display: block !important;
  }

  /* Éviter les coupures disgracieuses */
  tr,
  .pf-card,
  section {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
  }

  /* Titres */
  h1,
  h2,
  h3 {
    color: #000000 !important;
  }

  /* Format papier */
  @page {
    size: A4;
    margin: 12mm;
  }
}

/* ---------------------------------------------------------
   IMPRESSION THERMIQUE
   --------------------------------------------------------- */

@media print and (max-width: 600px) {
  @page {
    size: 80mm auto;
    margin: 4mm;
  }

  html,
  body {
    width: 80mm !important;
    min-width: 80mm !important;
    background: #ffffff !important;
  }

  body {
    font-size: 11px !important;
  }

  table {
    width: 100% !important;
    font-size: 10px !important;
  }

  th,
  td {
    padding: 4px 2px !important;
  }
}

