/* =========================================================
   PHARMAFLOW — STOCK MANAGEMENT
   PREMIUM LIGHT UI
   ========================================================= */

.pf-stock-page {
  min-height: 100vh;
  background:
    radial-gradient(
      circle at 0% 0%,
      rgba(15, 118, 110, 0.045),
      transparent 32%
    ),
    #f5f8f8;
  color: #0f172a;
  padding-bottom: 60px;
}

/* =========================================================
   LOADING
   ========================================================= */

.pf-stock-loading {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #f5f8f8;
  text-align: center;
  padding: 30px;
}

.pf-stock-loading h2 {
  margin: 20px 0 6px;
  font-size: 20px;
  font-weight: 800;
  color: #0f172a;
}

.pf-stock-loading p {
  margin: 0;
  color: #64748b;
  font-size: 14px;
}

.pf-stock-spinner {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 4px solid #dcefed;
  border-top-color: #0f766e;
  animation: pf-stock-spin 0.8s linear infinite;
}

@keyframes pf-stock-spin {
  to {
    transform: rotate(360deg);
  }
}

/* =========================================================
   HEADER
   ========================================================= */

.pf-stock-header {
  background: rgba(255, 255, 255, 0.94);
  border-bottom: 1px solid #e2e8f0;
  position: sticky;
  top: 0;
  z-index: 30;
  backdrop-filter: blur(16px);
}

.pf-stock-header-inner {
  width: min(1500px, calc(100% - 48px));
  min-height: 104px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.pf-stock-header-left {
  min-width: 0;
}

.pf-stock-back {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 0;
  background: transparent;
  color: #64748b;
  padding: 0;
  margin-bottom: 12px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: color 0.2s ease;
}

.pf-stock-back:hover {
  color: #0f766e;
}

.pf-stock-back span:first-child {
  font-size: 17px;
}

.pf-stock-title-row {
  display: flex;
  align-items: center;
  gap: 14px;
}

.pf-stock-title-icon {
  width: 48px;
  height: 48px;
  border-radius: 14px;
  background: #e6f5f2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  flex: 0 0 auto;
}

.pf-stock-title-row h1 {
  margin: 0;
  font-size: clamp(25px, 2.2vw, 32px);
  line-height: 1.1;
  font-weight: 850;
  letter-spacing: -0.025em;
  color: #0f172a;
}

.pf-stock-title-row p {
  margin: 7px 0 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.5;
}

.pf-stock-refresh {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 42px;
  padding: 0 17px;
  border: 1px solid #dbe4e7;
  border-radius: 11px;
  background: #ffffff;
  color: #334155;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 2px 7px rgba(15, 23, 42, 0.04);
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease;
}

.pf-stock-refresh:hover {
  border-color: #b9dcd7;
  color: #0f766e;
  background: #f8fdfc;
  transform: translateY(-1px);
}

.pf-stock-refresh:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* =========================================================
   CONTAINER
   ========================================================= */

.pf-stock-container {
  width: min(1500px, calc(100% - 48px));
  margin: 0 auto;
  padding-top: 28px;
}

/* =========================================================
   ALERTS
   ========================================================= */

.pf-stock-alert {
  min-height: 68px;
  border-radius: 14px;
  margin-bottom: 20px;
  padding: 13px 16px;
  display: flex;
  align-items: center;
  gap: 13px;
  border: 1px solid;
  box-shadow: 0 5px 18px rgba(15, 23, 42, 0.035);
}

.pf-stock-alert-success {
  background: #f0fdf9;
  border-color: #b8e6d9;
  color: #0f766e;
}

.pf-stock-alert-error {
  background: #fff7f7;
  border-color: #f2c7c7;
  color: #b42318;
}

.pf-stock-alert-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  font-weight: 900;
}

.pf-stock-alert-success .pf-stock-alert-icon {
  background: #d9f4ec;
  color: #087568;
}

.pf-stock-alert-error .pf-stock-alert-icon {
  background: #fde5e5;
  color: #b42318;
}

.pf-stock-alert-content {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1;
  min-width: 0;
}

.pf-stock-alert-content strong {
  font-size: 13px;
  font-weight: 800;
}

.pf-stock-alert-content span {
  font-size: 13px;
  line-height: 1.45;
}

.pf-stock-alert-close {
  width: 32px;
  height: 32px;
  border: 0;
  background: transparent;
  border-radius: 8px;
  color: currentColor;
  font-size: 22px;
  cursor: pointer;
  opacity: 0.65;
}

.pf-stock-alert-close:hover {
  opacity: 1;
  background: rgba(15, 23, 42, 0.05);
}

/* =========================================================
   STATISTICS
   ========================================================= */

.pf-stock-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

.pf-stock-stat-card {
  min-height: 128px;
  padding: 20px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  display: flex;
  align-items: center;
  gap: 15px;
  box-shadow:
    0 2px 8px rgba(15, 23, 42, 0.025),
    0 12px 30px rgba(15, 23, 42, 0.025);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.pf-stock-stat-card:hover {
  transform: translateY(-2px);
  box-shadow:
    0 5px 12px rgba(15, 23, 42, 0.04),
    0 18px 36px rgba(15, 23, 42, 0.045);
}

.pf-stock-stat-icon {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 23px;
  flex: 0 0 auto;
}

.pf-stock-stat-icon-teal {
  background: #e6f5f2;
}

.pf-stock-stat-icon-blue {
  background: #edf5ff;
}

.pf-stock-stat-icon-orange {
  background: #fff6e8;
}

.pf-stock-stat-icon-red {
  background: #fff0f0;
  color: #dc2626;
  font-size: 27px;
  font-weight: 800;
}

.pf-stock-stat-content {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-stock-stat-content span {
  font-size: 12px;
  color: #64748b;
  font-weight: 650;
}

.pf-stock-stat-content strong {
  margin-top: 4px;
  color: #0f172a;
  font-size: 27px;
  line-height: 1.1;
  font-weight: 850;
  letter-spacing: -0.02em;
}

.pf-stock-stat-content small {
  margin-top: 5px;
  color: #94a3b8;
  font-size: 11px;
}

/* =========================================================
   CARDS
   ========================================================= */

.pf-stock-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  margin-bottom: 22px;
  overflow: hidden;
  box-shadow:
    0 2px 8px rgba(15, 23, 42, 0.025),
    0 15px 35px rgba(15, 23, 42, 0.025);
