/* =========================================================
   MOVEMENT FORM
   ========================================================= */

.pf-stock-movement-form {
  padding: 25px 26px 27px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.pf-stock-field {
