  margin-top: 6px;
  color: #94a3b8;
  font-size: 11px;
}

.pf-stock-selected-info {
  min-height: 38px;
  margin-top: 8px;
  padding: 7px 11px;
  border-radius: 9px;
  background: #f3faf8;
  border: 1px solid #d7eee9;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.pf-stock-selected-info span {
  color: #64748b;
  font-size: 11px;
}

.pf-stock-selected-info strong {
  color: #0f766e;
  font-size: 12px;
}

/* =========================================================
   TYPE SELECTOR
   ========================================================= */

.pf-stock-type-selector {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.pf-stock-type-option {
  min-height: 76px;
  border: 1px solid #dfe7e9;
  background: #ffffff;
  border-radius: 13px;
  padding: 12px 15px;
  display: flex;
  align-items: center;
  gap: 12px;
  text-align: left;
  cursor: pointer;
  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.2s ease;
}

.pf-stock-type-option:hover {
  transform: translateY(-1px);
  border-color: #b7d4d0;
}

.pf-stock-type-option > span:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.pf-stock-type-option strong {
  color: #334155;
  font-size: 13px;
  font-weight: 800;
}

.pf-stock-type-option small {
  color: #94a3b8;
  font-size: 11px;
}

.pf-stock-type-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 23px;
  font-weight: 500;
  flex: 0 0 auto;
}

.pf-stock-type-option:first-child
  .pf-stock-type-icon {
  background: #eaf8f4;
  color: #0f766e;
}

.pf-stock-type-option:last-child
  .pf-stock-type-icon {
  background: #fff0f0;
  color: #dc2626;
}

.pf-stock-type-option.active-entry {
  border-color: #56b9aa;
  background: #f3fbf9;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.06);
}

.pf-stock-type-option.active-exit {
  border-color: #efaaa8;
  background: #fff8f8;
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.05);
}

/* =========================================================
   FORM BUTTON
   ========================================================= */

.pf-stock-form-action {
  display: flex;
  align-items: flex-end;
}

.pf-stock-submit {
  width: 100%;
  height: 47px;
  border: 0;
  border-radius: 11px;
  color: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    opacity 0.2s ease;
}

.pf-stock-submit:hover:not(:disabled) {
  transform: translateY(-1px);
}

.pf-stock-submit:active:not(:disabled) {
  transform: translateY(0);
}

.pf-stock-submit:disabled {
  opacity: 0.62;
  cursor: not-allowed;
}

.pf-stock-submit-entry {
  background: #0f766e;
  box-shadow: 0 7px 16px rgba(15, 118, 110, 0.16);
}

.pf-stock-submit-entry:hover:not(:disabled) {
  background: #0d6b64;
  box-shadow: 0 9px 20px rgba(15, 118, 110, 0.22);
}

.pf-stock-submit-exit {
  background: #c2413e;
  box-shadow: 0 7px 16px rgba(194, 65, 62, 0.14);
}

.pf-stock-submit-exit:hover:not(:disabled) {
  background: #b33a37;
  box-shadow: 0 9px 20px rgba(194, 65, 62, 0.19);
}

.pf-stock-submit > span:first-child {
  font-size: 19px;
  line-height: 1;
}

.pf-stock-button-spinner {
  width: 16px;
  height: 16px;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: #ffffff;
  border-radius: 50%;
  animation: pf-stock-spin 0.7s linear infinite;
}

/* =========================================================
   SEARCH
   ========================================================= */

.pf-stock-current-header {
  align-items: flex-end;
}

.pf-stock-search-wrapper {
  position: relative;
  width: min(350px, 100%);
}

.pf-stock-search-icon {
  position: absolute;
  left: 13px;
  top: 50%;
  transform: translateY(-50%);
  color: #94a3b8;
  font-size: 20px;
  pointer-events: none;
}

.pf-stock-search {
  width: 100%;
  height: 43px;
  border: 1px solid #dce5e7;
  border-radius: 10px;
  background: #ffffff;
  color: #0f172a;
  padding: 0 13px 0 39px;
  outline: none;
  font-size: 13px;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.pf-stock-search::placeholder {
  color: #9aa6b2;
}

.pf-stock-search:focus {
  border-color: #0f9b8e;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.08);
}

/* =========================================================
   TABLE
   ========================================================= */

.pf-stock-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.pf-stock-table {
  width: 100%;
  min-width: 850px;
  border-collapse: collapse;
}

.pf-stock-table thead {
  background: #f8fafb;
}

.pf-stock-table th {
  height: 47px;
  padding: 0 24px;
  border-bottom: 1px solid #e8eef0;
  color: #64748b;
  text-align: left;
  white-space: nowrap;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.pf-stock-table td {
  padding: 16px 24px;
  border-bottom: 1px solid #eef2f3;
  color: #334155;
  font-size: 13px;
  vertical-align: middle;
}

.pf-stock-table tbody tr {
  transition: background 0.18s ease;
}

.pf-stock-table tbody tr:hover {
  background: #fbfdfd;
}

.pf-stock-table tbody tr:last-child td {
  border-bottom: 0;
}

/* =========================================================
   PRODUCT
   ========================================================= */

.pf-stock-product {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 220px;
}

.pf-stock-product-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: #eef8f6;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  flex: 0 0 auto;
}

.pf-stock-product > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-stock-product strong {
  color: #172033;
  font-size: 13px;
  font-weight: 800;
}

.pf-stock-product span {
  margin-top: 2px;
  color: #64748b;
  font-size: 11px;
}

.pf-stock-product small {
  margin-top: 3px;
  color: #a0aab5;
  font-size: 10px;
}

.pf-stock-category {
  display: inline-block;
  padding: 5px 9px;
  border-radius: 7px;
  background: #f5f7f8;
  color: #64748b;
  font-size: 11px;
  font-weight: 650;
}

.pf-stock-quantity {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
}

.pf-stock-quantity strong {
  font-size: 17px;
  font-weight: 850;
}

.pf-stock-quantity span {
  font-size: 11px;
  color: #64748b;
}

.pf-stock-quantity-normal strong {
  color: #0f766e;
}

.pf-stock-quantity-low strong {
  color: #d97706;
}

.pf-stock-quantity-out strong {
  color: #dc2626;
}

.pf-stock-minimum {
  color: #64748b;
  font-size: 12px;
}

.pf-stock-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
}

.pf-stock-badge i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  display: block;
}

.pf-stock-badge-normal {
  background: #eaf8f3;
  color: #087568;
}

.pf-stock-badge-normal i {
  background: #19a67e;
}

.pf-stock-badge-low {
  background: #fff5e5;
  color: #b45309;
}

.pf-stock-badge-low i {
  background: #f59e0b;
}

.pf-stock-badge-out {
  background: #fff0f0;
  color: #c2413e;
}

.pf-stock-badge-out i {
  background: #ef4444;
}

/* =========================================================
   TABLE FOOTER
   ========================================================= */

.pf-stock-table-footer {
  min-height: 50px;
  padding: 0 24px;
  border-top: 1px solid #eef2f3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #94a3b8;
  font-size: 11px;
}

/* =========================================================
   EMPTY
   ========================================================= */

.pf-stock-empty-cell {
  height: 260px;
}

.pf-stock-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 30px;
}

.pf-stock-empty-icon {
  width: 50px;
  height: 50px;
  border-radius: 14px;
  background: #f4f7f8;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
  font-size: 20px;
}

.pf-stock-empty strong {
  color: #334155;
  font-size: 14px;
  font-weight: 800;
}

.pf-stock-empty span {
  margin-top: 5px;
  color: #94a3b8;
  font-size: 12px;
}

/* =========================================================
   HISTORY
   ========================================================= */

.pf-stock-history-table {
  min-width: 1000px;
}

.pf-stock-date {
  color: #64748b;
  font-size: 11px;
  white-space: nowrap;
}

.pf-stock-history-product {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.pf-stock-history-product strong {
  color: #172033;
  font-size: 12px;
  font-weight: 800;
}

.pf-stock-history-product span {
  color: #94a3b8;
  font-size: 10px;
}

.pf-stock-movement-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
}

.pf-stock-movement-badge > span {
  width: 17px;
  height: 17px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
}

.pf-stock-movement-entry {
  background: #eaf8f3;
  color: #087568;
}

.pf-stock-movement-entry > span {
  background: #d2f1e6;
}

.pf-stock-movement-exit {
  background: #fff0f0;
  color: #c2413e;
}

.pf-stock-movement-exit > span {
  background: #f9dddd;
}

.pf-stock-history-quantity {
  font-size: 14px;
  font-weight: 850;
}

.pf-stock-history-quantity-entry {
  color: #0f766e;
}

.pf-stock-history-quantity-exit {
  color: #c2413e;
}

.pf-stock-history-text {
  color: #64748b;
  font-size: 12px;
}

.pf-stock-reference {
  display: inline-block;
  padding: 5px 8px;
  border-radius: 6px;
  background: #f6f8f9;
  color: #64748b;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 10px;
}

.pf-stock-history-footer {
  min-height: 50px;
  padding: 0 24px;
  border-top: 1px solid #eef2f3;
  display: flex;
  align-items: center;
  color: #94a3b8;
  font-size: 11px;
}

/* =========================================================
   SECURITY NOTE
   ========================================================= */

.pf-stock-security-note {
  margin-top: 2px;
  padding: 15px 18px;
  border: 1px solid #dceeea;
  border-radius: 13px;
  background: #f7fcfb;
  display: flex;
  align-items: center;
  gap: 12px;
}

.pf-stock-security-icon {
  width: 33px;
  height: 33px;
  border-radius: 9px;
  background: #e2f4ef;
  color: #0f766e;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  flex: 0 0 auto;
}

.pf-stock-security-note > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.pf-stock-security-note strong {
  color: #334155;
  font-size: 11px;
  font-weight: 800;
}

.pf-stock-security-note span {
  color: #7b8794;
  font-size: 10px;
  line-height: 1.5;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1200px) {
  .pf-stock-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pf-stock-header-inner,
  .pf-stock-container {
    width: min(100% - 36px, 1500px);
  }
}

@media (max-width: 800px) {
  .pf-stock-header {
    position: static;
  }

  .pf-stock-header-inner {
    min-height: auto;
    padding: 20px 0;
    align-items: flex-start;
  }

  .pf-stock-refresh {
    flex: 0 0 auto;
  }

  .pf-stock-title-row h1 {
    font-size: 24px;
  }

  .pf-stock-title-row p {
    max-width: 500px;
  }

  .pf-stock-movement-form {
    grid-template-columns: 1fr;
  }

  .pf-stock-field-full {
    grid-column: auto;
  }

  .pf-stock-form-action {
    grid-column: auto;
  }

  .pf-stock-current-header {
    align-items: stretch;
    flex-direction: column;
  }

  .pf-stock-search-wrapper {
    width: 100%;
  }
}

@media (max-width: 600px) {
  .pf-stock-header-inner,
  .pf-stock-container {
    width: calc(100% - 24px);
  }

  .pf-stock-header-inner {
    flex-direction: column;
    gap: 15px;
  }

  .pf-stock-refresh {
    width: 100%;
  }

  .pf-stock-title-icon {
    width: 42px;
    height: 42px;
    border-radius: 12px;
    font-size: 20px;
  }

  .pf-stock-title-row {
    align-items: flex-start;
  }

  .pf-stock-title-row h1 {
    font-size: 22px;
  }

  .pf-stock-title-row p {
    font-size: 12px;
  }

  .pf-stock-container {
    padding-top: 18px;
  }

  .pf-stock-stats {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .pf-stock-stat-card {
    min-height: 100px;
    padding: 16px;
  }

  .pf-stock-stat-icon {
    width: 45px;
    height: 45px;
  }

  .pf-stock-card-header {
    padding: 19px;
  }

  .pf-stock-movement-form {
    padding: 19px;
  }

  .pf-stock-type-selector {
    grid-template-columns: 1fr;
  }

  .pf-stock-alert {
    align-items: flex-start;
  }

  .pf-stock-table th,
  .pf-stock-table td {
    padding-left: 15px;
    padding-right: 15px;
  }

  .pf-stock-table-footer {
    padding: 0 15px;
  }

  .pf-stock-security-note {
    align-items: flex-start;
  }
}

/* =========================================================
   ACCESSIBILITY
   ========================================================= */

.pf-stock-page button:focus-visible,
.pf-stock-page input:focus-visible,
.pf-stock-page select:focus-visible {
  outline: 3px solid rgba(15, 118, 110, 0.18);
  outline-offset: 2px;
}

/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {
  .pf-stock-page *,
  .pf-stock-page *::before,
  .pf-stock-page *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}
/* =========================================================
   PHARMAFLOW — USERS / TEAM MANAGEMENT
   Premium administration interface
   ========================================================= */

.pf-users-page {
  min-height: 100vh;
  background:
    radial-gradient(
      circle at top right,
      rgba(15, 118, 110, 0.06),
      transparent 32%
    ),
    #f5f8f8;
  color: #0f172a;
}

.pf-users-shell {
  width: 100%;
  max-width: 1540px;
  margin: 0 auto;
  padding: 32px 40px 64px;
}

/* =========================================================
   LOADING
   ========================================================= */

.pf-users-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.pf-users-loading-card {
  width: min(420px, calc(100% - 32px));
  padding: 42px;
  text-align: center;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 24px;
  box-shadow:
    0 20px 60px rgba(15, 23, 42, 0.08);
}

.pf-users-loading-card h2 {
  margin: 20px 0 8px;
  font-size: 20px;
  font-weight: 800;
}

.pf-users-loading-card p {
  margin: 0;
  color: #64748b;
  font-size: 14px;
}

.pf-users-spinner {
  width: 42px;
  height: 42px;
  margin: 0 auto;
  border: 4px solid #dcefed;
  border-top-color: #0f766e;
  border-radius: 50%;
  animation: pfUsersSpin 0.8s linear infinite;
}

@keyframes pfUsersSpin {
  to {
    transform: rotate(360deg);
  }
}

/* =========================================================
   HEADER
   ========================================================= */

.pf-users-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: 28px;
}

.pf-users-header-left {
  min-width: 0;
}

.pf-users-back {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 18px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #64748b;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: color 0.2s ease;
}

.pf-users-back:hover {
  color: #0f766e;
}

.pf-users-back span {
  font-size: 18px;
}

.pf-users-heading {
  display: flex;
  align-items: center;
  gap: 18px;
}

.pf-users-heading-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  flex: 0 0 58px;
  border-radius: 18px;
  background: #e6f5f2;
  font-size: 27px;
  box-shadow:
    inset 0 0 0 1px rgba(15, 118, 110, 0.08);
}

.pf-users-heading h1 {
  margin: 0;
  color: #0f172a;
  font-size: clamp(28px, 3vw, 38px);
  line-height: 1.1;
  font-weight: 850;
  letter-spacing: -0.035em;
}

.pf-users-heading p {
  margin: 8px 0 0;
  color: #64748b;
  font-size: 15px;
}

.pf-users-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pf-users-refresh,
.pf-users-primary-button {
  min-height: 46px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 0 17px;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 750;
  cursor: pointer;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.pf-users-refresh {
  border: 1px solid #dbe3e8;
  background: #ffffff;
  color: #334155;
}

.pf-users-refresh:hover:not(:disabled) {
  background: #f8fafc;
  border-color: #cbd5e1;
}

.pf-users-primary-button {
  border: 1px solid #0f766e;
  background: #0f766e;
  color: #ffffff;
  box-shadow:
    0 8px 20px rgba(15, 118, 110, 0.16);
}

.pf-users-primary-button:hover {
  background: #115e59;
  transform: translateY(-1px);
  box-shadow:
    0 12px 26px rgba(15, 118, 110, 0.22);
}

.pf-users-refresh span,
.pf-users-primary-button span {
  font-size: 18px;
}

/* =========================================================
   ALERTS
   ========================================================= */

.pf-users-alert {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 15px 18px;
  margin-bottom: 20px;
  border-radius: 14px;
  border: 1px solid;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
}

.pf-users-alert-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  border-radius: 10px;
  font-weight: 900;
}

.pf-users-alert strong {
  display: block;
  margin-bottom: 3px;
  font-size: 14px;
}

.pf-users-alert p {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
}

.pf-users-alert > button:last-child {
  margin-left: auto;
  border: 0;
  background: transparent;
  font-size: 22px;
  color: inherit;
  opacity: 0.6;
  cursor: pointer;
}

.pf-users-alert-success {
  background: #f0fdf9;
  border-color: #b7e7dd;
  color: #0f766e;
}

.pf-users-alert-success .pf-users-alert-icon {
  background: #d8f4ed;
}

.pf-users-alert-error {
  background: #fff7f7;
  border-color: #fecaca;
  color: #b91c1c;
}

.pf-users-alert-error .pf-users-alert-icon {
  background: #fee2e2;
}

/* =========================================================
   STATISTICS
   ========================================================= */

.pf-users-stats {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

.pf-users-stat-card {
  display: flex;
  align-items: center;
  gap: 15px;
  min-height: 112px;
  padding: 20px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  box-shadow:
    0 7px 22px rgba(15, 23, 42, 0.035);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.pf-users-stat-card:hover {
  transform: translateY(-2px);
  box-shadow:
    0 12px 30px rgba(15, 23, 42, 0.07);
}

.pf-users-stat-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  border-radius: 15px;
  font-size: 22px;
}

.pf-users-stat-blue {
  background: #eff6ff;
}

.pf-users-stat-green {
  background: #ecfdf5;
}

.pf-users-stat-purple {
  background: #f5f3ff;
}

.pf-users-stat-orange {
  background: #fff7ed;
}

.pf-users-stat-card span {
  display: block;
  margin-bottom: 4px;
  color: #64748b;
  font-size: 12px;
  font-weight: 700;
}

.pf-users-stat-card strong {
  display: inline-block;
  margin-right: 7px;
  color: #0f172a;
  font-size: 28px;
  line-height: 1;
  font-weight: 850;
}

.pf-users-stat-card small {
  color: #94a3b8;
  font-size: 11px;
}

/* =========================================================
   TOOLBAR
   ========================================================= */

.pf-users-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px;
  margin-bottom: 18px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  box-shadow:
    0 5px 18px rgba(15, 23, 42, 0.025);
}

.pf-users-search-box {
  position: relative;
  display: flex;
  align-items: center;
  width: min(580px, 100%);
}

.pf-users-search-box > span {
  position: absolute;
  left: 15px;
  color: #94a3b8;
  font-size: 22px;
  pointer-events: none;
}

.pf-users-search-box input {
  width: 100%;
  height: 46px;
  padding: 0 42px 0 45px;
  border: 1px solid #e2e8f0;
  border-radius: 11px;
  outline: none;
  background: #f8fafc;
  color: #0f172a;
  font-size: 14px;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.pf-users-search-box input::placeholder {
  color: #94a3b8;
}

.pf-users-search-box input:focus {
  background: #ffffff;
  border-color: #0f766e;
  box-shadow:
    0 0 0 4px rgba(15, 118, 110, 0.08);
}

.pf-users-search-box > button {
  position: absolute;
  right: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 27px;
  height: 27px;
  border: 0;
  border-radius: 7px;
  background: #e2e8f0;
  color: #475569;
  cursor: pointer;
}

.pf-users-filter-group {
  display: flex;
  gap: 10px;
}

.pf-users-filter-group select {
  min-width: 170px;
  height: 46px;
  padding: 0 38px 0 13px;
  border: 1px solid #e2e8f0;
  border-radius: 11px;
  background: #ffffff;
  color: #334155;
  outline: none;
  font-size: 13px;
  cursor: pointer;
}

.pf-users-filter-group select:focus {
  border-color: #0f766e;
  box-shadow:
    0 0 0 4px rgba(15, 118, 110, 0.08);
}

/* =========================================================
   TABLE
   ========================================================= */

.pf-users-table-card {
  overflow: hidden;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  box-shadow:
    0 8px 28px rgba(15, 23, 42, 0.04);
}

.pf-users-table-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 23px 24px;
  border-bottom: 1px solid #edf1f4;
}

.pf-users-table-header h2 {
  margin: 0;
  color: #0f172a;
  font-size: 18px;
  font-weight: 800;
}

.pf-users-table-header p {
  margin: 5px 0 0;
  color: #94a3b8;
  font-size: 13px;
}

.pf-users-secure-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 11px;
  border-radius: 9px;
  background: #f0fdf9;
  color: #0f766e;
  font-size: 12px;
  font-weight: 700;
}

.pf-users-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.pf-users-table {
  width: 100%;
  min-width: 1050px;
  border-collapse: collapse;
}

.pf-users-table th {
  padding: 13px 20px;
  background: #f8fafc;
  color: #64748b;
  text-align: left;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.pf-users-table td {
  padding: 17px 20px;
  border-top: 1px solid #edf1f4;
  vertical-align: middle;
  color: #334155;
  font-size: 13px;
}

.pf-users-table tbody tr {
  transition:
    background 0.2s ease;
}

.pf-users-table tbody tr:hover {
  background: #f9fbfb;
}

.pf-users-row-inactive {
  opacity: 0.65;
  background: #fafafa;
}

.pf-users-th-actions {
  width: 110px;
  text-align: right !important;
}

/* =========================================================
   PERSON
   ========================================================= */

.pf-users-person {
  display: flex;
  align-items: center;
  gap: 12px;
}

.pf-users-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  border-radius: 13px;
  background:
    linear-gradient(
      135deg,
      #e6f5f2,
      #d7eee9
    );
  color: #0f766e;
  font-size: 13px;
  font-weight: 850;
}

.pf-users-person-info {
  min-width: 190px;
}

.pf-users-person-info strong {
  display: block;
  color: #0f172a;
  font-size: 13px;
  font-weight: 800;
}

.pf-users-person-info span {
  display: block;
  max-width: 270px;
  margin-top: 3px;
  overflow: hidden;
  color: #64748b;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-users-person-info small {
  display: inline-block;
  margin-top: 4px;
  color: #0f766e;
  font-size: 10px;
  font-weight: 800;
}

.pf-users-contact span {
  display: block;
  color: #475569;
}

.pf-users-warning-text {
  display: block;
  margin-top: 5px;
  color: #b45309;
  font-size: 10px;
  font-weight: 700;
}

.pf-users-last-login {
  color: #64748b;
  white-space: nowrap;
  font-size: 12px;
}

/* =========================================================
   ROLES
   ========================================================= */

.pf-users-role,
.pf-users-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 29px;
  padding: 0 9px;
  border-radius: 999px;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 800;
}

.pf-users-role-owner {
  background: #f5f3ff;
  color: #7c3aed;
}

.pf-users-role-admin {
  background: #eff6ff;
  color: #2563eb;
}

.pf-users-role-pharmacist {
  background: #ecfdf5;
  color: #047857;
}

.pf-users-role-cashier {
  background: #fff7ed;
  color: #c2410c;
}

.pf-users-role-employee {
  background: #f1f5f9;
  color: #475569;
}

/* =========================================================
   STATUS
   ========================================================= */

.pf-users-status-active {
  background: #ecfdf5;
  color: #047857;
}

.pf-users-status-inactive {
  background: #fef2f2;
  color: #b91c1c;
}

.pf-users-status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

/* =========================================================
   ACTIONS
   ========================================================= */

.pf-users-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
}

.pf-users-action {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: 1px solid #e2e8f0;
  border-radius: 9px;
  background: #ffffff;
  color: #64748b;
  font-size: 14px;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease;
}

.pf-users-action:hover:not(:disabled) {
  transform: translateY(-1px);
}

.pf-users-action-edit:hover {
  border-color: #b7e7dd;
  background: #f0fdf9;
  color: #0f766e;
}

.pf-users-action-disable:hover {
  border-color: #fed7aa;
  background: #fff7ed;
  color: #c2410c;
}

.pf-users-action-enable:hover {
  border-color: #bbf7d0;
  background: #f0fdf4;
  color: #15803d;
}

.pf-users-action:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* =========================================================
   EMPTY STATE
   ========================================================= */

.pf-users-empty {
  padding: 65px 24px;
  text-align: center;
}

.pf-users-empty-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 66px;
  height: 66px;
  margin: 0 auto 15px;
  border-radius: 20px;
  background: #f1f5f9;
  font-size: 28px;
}

.pf-users-empty h3 {
  margin: 0;
  color: #334155;
  font-size: 16px;
  font-weight: 800;
}

.pf-users-empty p {
  max-width: 430px;
  margin: 7px auto 16px;
  color: #94a3b8;
  font-size: 13px;
}

.pf-users-empty button {
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid #dbe3e8;
  border-radius: 9px;
  background: #ffffff;
  color: #0f766e;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

/* =========================================================
   ROLES SECTION
   ========================================================= */

.pf-users-roles-section {
  margin-top: 26px;
}

.pf-users-section-heading {
  margin-bottom: 14px;
}

.pf-users-section-kicker {
  color: #0f766e;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.13em;
}

.pf-users-section-heading h2 {
  margin: 5px 0 0;
  color: #0f172a;
  font-size: 20px;
  font-weight: 850;
}

.pf-users-section-heading p {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 13px;
}

.pf-users-roles-grid {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.pf-users-role-card {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  min-height: 130px;
  padding: 18px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.pf-users-role-card:hover {
  transform: translateY(-2px);
  box-shadow:
    0 12px 26px rgba(15, 23, 42, 0.06);
}

.pf-users-role-card-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  border-radius: 12px;
  background: #f0fdf9;
  font-size: 19px;
}

.pf-users-role-card h3 {
  margin: 1px 0 5px;
  color: #0f172a;
  font-size: 14px;
  font-weight: 800;
}

.pf-users-role-card p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.55;
}

/* =========================================================
   SECURITY
   ========================================================= */

.pf-users-security-card {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-top: 20px;
  padding: 18px 20px;
  border: 1px solid #cfe9e4;
  border-radius: 16px;
  background:
    linear-gradient(
      135deg,
      #f0fdf9,
      #ffffff
    );
}

.pf-users-security-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 45px;
  height: 45px;
  flex: 0 0 45px;
  border-radius: 13px;
  background: #dff4ef;
  font-size: 20px;
}

.pf-users-security-card h3 {
  margin: 0 0 4px;
  color: #0f172a;
  font-size: 14px;
  font-weight: 800;
}

.pf-users-security-card p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.55;
}

/* =========================================================
   MODALE
   ========================================================= */

.pf-users-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  overflow-y: auto;
  background: rgba(15, 23, 42, 0.48);
  backdrop-filter: blur(6px);
  animation: pfUsersFadeIn 0.18s ease;
}

@keyframes pfUsersFadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.pf-users-modal {
  width: min(720px, 100%);
  max-height: calc(100vh - 48px);
  overflow-y: auto;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 24px;
  box-shadow:
    0 30px 90px rgba(15, 23, 42, 0.22);
  animation: pfUsersModalIn 0.2s ease;
}

@keyframes pfUsersModalIn {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.985);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.pf-users-modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 25px 26px 21px;
  border-bottom: 1px solid #edf1f4;
}

.pf-users-modal-kicker {
  color: #0f766e;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.pf-users-modal-header h2 {
  margin: 5px 0 5px;
  color: #0f172a;
  font-size: 22px;
  font-weight: 850;
  letter-spacing: -0.025em;
}

.pf-users-modal-header p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
}

.pf-users-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #ffffff;
  color: #64748b;
  font-size: 22px;
  cursor: pointer;
}

.pf-users-modal-close:hover {
  background: #f8fafc;
  color: #0f172a;
}

/* =========================================================
   FORM
   ========================================================= */

.pf-users-form {
  padding: 25px 26px 26px;
}

.pf-users-form-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 17px;
}

.pf-users-form-full {
  grid-column: 1 / -1;
}

.pf-users-form-group label {
  display: block;
  margin-bottom: 7px;
  color: #334155;
  font-size: 12px;
  font-weight: 800;
}

.pf-users-form-group input,
.pf-users-form-group select {
  width: 100%;
  min-height: 46px;
  padding: 0 13px;
  border: 1px solid #dbe3e8;
  border-radius: 11px;
  outline: none;
  background: #ffffff;
  color: #0f172a;
  font-size: 13px;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.pf-users-form-group input::placeholder {
  color: #a1acb8;
}

.pf-users-form-group input:focus,
.pf-users-form-group select:focus {
  border-color: #0f766e;
  box-shadow:
    0 0 0 4px rgba(15, 118, 110, 0.08);
}

.pf-users-form-group small {
  display: block;
  margin-top: 6px;
  color: #94a3b8;
  font-size: 10px;
  line-height: 1.45;
}

.pf-users-password-field {
  display: flex;
  gap: 8px;
}

.pf-users-password-field input {
  flex: 1;
}

.pf-users-password-field button {
  min-width: 92px;
  padding: 0 12px;
  border: 1px solid #dbe3e8;
  border-radius: 11px;
  background: #f8fafc;
  color: #475569;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

.pf-users-password-field button:hover {
  background: #f1f5f9;
}

/* =========================================================
   PERMISSION PREVIEW
   ========================================================= */

.pf-users-permission-preview {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 20px;
  padding: 14px;
  border: 1px solid #d9ece8;
  border-radius: 13px;
  background: #f4fcfa;
}

.pf-users-permission-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  border-radius: 12px;
  background: #dff4ef;
  font-size: 20px;
}

.pf-users-permission-preview strong {
  display: block;
  color: #0f172a;
  font-size: 13px;
}

.pf-users-permission-preview p {
  margin: 3px 0 0;
  color: #64748b;
  font-size: 11px;
}

/* =========================================================
   SECURE NOTE
   ========================================================= */

.pf-users-secure-note {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin-top: 15px;
  padding: 13px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #f8fafc;
}

.pf-users-secure-note > span {
  font-size: 17px;
}

.pf-users-secure-note strong {
  display: block;
  margin-bottom: 3px;
  color: #334155;
  font-size: 11px;
}

.pf-users-secure-note p {
  margin: 0;
  color: #64748b;
  font-size: 10px;
  line-height: 1.5;
}

/* =========================================================
   MODAL FOOTER
   ========================================================= */

.pf-users-modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 23px;
  padding-top: 19px;
  border-top: 1px solid #edf1f4;
}

.pf-users-secondary-button,
.pf-users-submit-button {
  min-height: 45px;
  padding: 0 18px;
  border-radius: 11px;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}

.pf-users-secondary-button {
  border: 1px solid #dbe3e8;
  background: #ffffff;
  color: #475569;
}

.pf-users-secondary-button:hover:not(:disabled) {
  background: #f8fafc;
}

.pf-users-submit-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 180px;
  border: 1px solid #0f766e;
  background: #0f766e;
  color: #ffffff;
  box-shadow:
    0 8px 18px rgba(15, 118, 110, 0.15);
}

.pf-users-submit-button:hover:not(:disabled) {
  background: #115e59;
  transform: translateY(-1px);
}

.pf-users-secondary-button:disabled,
.pf-users-submit-button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.pf-users-button-spinner {
  width: 15px;
  height: 15px;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: #ffffff;
  border-radius: 50%;
  animation: pfUsersSpin 0.7s linear infinite;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1180px) {
  .pf-users-shell {
    padding-left: 24px;
    padding-right: 24px;
  }

  .pf-users-stats {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-users-roles-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 850px) {
  .pf-users-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .pf-users-header-actions {
    width: 100%;
  }

  .pf-users-refresh,
  .pf-users-primary-button {
    flex: 1;
  }

  .pf-users-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .pf-users-search-box {
    width: 100%;
  }

  .pf-users-filter-group {
    display: grid;
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-users-filter-group select {
    width: 100%;
  }
}

@media (max-width: 640px) {
  .pf-users-shell {
    padding: 20px 15px 45px;
  }

  .pf-users-heading {
    align-items: flex-start;
  }

  .pf-users-heading-icon {
    width: 48px;
    height: 48px;
    flex-basis: 48px;
    border-radius: 14px;
    font-size: 22px;
  }

  .pf-users-heading h1 {
    font-size: 27px;
  }

  .pf-users-heading p {
    font-size: 13px;
  }

  .pf-users-header-actions {
    flex-direction: column;
  }

  .pf-users-refresh,
  .pf-users-primary-button {
    width: 100%;
  }

  .pf-users-stats {
    grid-template-columns:
      1fr;
  }

  .pf-users-roles-grid {
    grid-template-columns:
      1fr;
  }

  .pf-users-table-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .pf-users-secure-badge {
    align-self: flex-start;
  }

  .pf-users-filter-group {
    grid-template-columns:
      1fr;
  }

  .pf-users-modal-backdrop {
    align-items: flex-start;
    padding: 10px;
  }

  .pf-users-modal {
    max-height: calc(100vh - 20px);
    border-radius: 18px;
  }

  .pf-users-modal-header {
    padding: 20px;
  }

  .pf-users-form {
    padding: 20px;
  }

  .pf-users-form-grid {
    grid-template-columns:
      1fr;
  }

  .pf-users-form-full {
    grid-column: auto;
  }

  .pf-users-modal-footer {
    flex-direction: column-reverse;
  }

  .pf-users-secondary-button,
  .pf-users-submit-button {
    width: 100%;
  }

  .pf-users-security-card {
    align-items: flex-start;
  }
}

/* =========================================================
   ACCESSIBILITY
   ========================================================= */

.pf-users-page button:focus-visible,
.pf-users-page input:focus-visible,
.pf-users-page select:focus-visible {
  outline: 3px solid rgba(15, 118, 110, 0.18);
  outline-offset: 2px;
}

/* =========================================================
   PRINT
   ========================================================= */

@media print {
  .pf-users-page {
    background: #ffffff;
  }

  .pf-users-header-actions,
  .pf-users-toolbar,
  .pf-users-actions,
  .pf-users-roles-section,
  .pf-users-security-card {
    display: none !important;
  }

  .pf-users-shell {
    max-width: none;
    padding: 0;
  }

  .pf-users-table-card,
  .pf-users-stat-card {
    box-shadow: none;
  }
}
/* ============================================================
   PHARMAFLOW — CAISSE / POS PREMIUM
   ============================================================ */

.pf-caisse-page {
  min-height: 100vh;
  background: #f5f8f8;
  color: #0f172a;
  display: flex;
  overflow: hidden;
}


/* ============================================================
   SIDEBAR
============================================================ */

.pf-caisse-sidebar {
  width: 270px;
  min-width: 270px;
  height: 100vh;
  background: #ffffff;
  border-right: 1px solid #e2e8f0;
  display: flex;
  flex-direction: column;
  position: sticky;
  top: 0;
  z-index: 100;
}

.pf-caisse-brand {
  min-height: 78px;
  padding: 18px 18px;
  border-bottom: 1px solid #eef2f4;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pf-caisse-brand-button {
  border: 0;
  background: transparent;
  padding: 0;
  display: flex;
  align-items: center;
  gap: 11px;
  cursor: pointer;
  text-align: left;
}

.pf-caisse-brand-mark {
  width: 42px;
  height: 42px;
  border-radius: 13px;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  font-weight: 800;
  box-shadow: 0 7px 18px rgba(15, 118, 110, 0.20);
}

.pf-caisse-brand-button strong {
  display: block;
  color: #0f172a;
  font-size: 19px;
  line-height: 1.1;
  letter-spacing: -0.4px;
}

.pf-caisse-brand-button strong span {
  color: #0f766e;
}

.pf-caisse-brand-button small {
  display: block;
  margin-top: 4px;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 600;
}

.pf-caisse-close {
  display: none;
}


/* ============================================================
   PHARMACIE
============================================================ */

.pf-caisse-pharmacy {
  margin: 16px;
  padding: 13px;
  border: 1px solid #e2e8f0;
  background: #f8fbfb;
  border-radius: 14px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.pf-caisse-pharmacy-icon {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: 11px;
  background: #e6f5f2;
  color: #0f766e;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 800;
}

.pf-caisse-pharmacy > div:last-child {
  min-width: 0;
}

.pf-caisse-pharmacy span {
  display: block;
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.7px;
}

.pf-caisse-pharmacy strong {
  display: block;
  margin-top: 3px;
  color: #0f172a;
  font-size: 12px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pf-caisse-pharmacy small {
  display: block;
  margin-top: 2px;
  color: #64748b;
  font-size: 10px;
}


/* ============================================================
   NAVIGATION
============================================================ */

.pf-caisse-nav {
  flex: 1;
  padding: 3px 13px 15px;
  overflow-y: auto;
}

.pf-caisse-nav > p {
  margin: 13px 10px 8px;
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1px;
}

.pf-caisse-nav-separator {
  margin-top: 22px !important;
}

.pf-caisse-nav-item {
  width: 100%;
  min-height: 43px;
  border: 0;
  border-radius: 11px;
  background: transparent;
  color: #64748b;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
  margin-bottom: 4px;
  font-size: 12px;
  font-weight: 650;
  cursor: pointer;
  text-align: left;
  transition:
    background 0.18s ease,
    color 0.18s ease,
    transform 0.18s ease;
}

.pf-caisse-nav-item:hover {
  background: #f1f7f6;
  color: #0f766e;
}

.pf-caisse-nav-item.active {
  background: #e6f5f2;
  color: #0f766e;
  font-weight: 800;
}

.pf-caisse-nav-item > span {
  width: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
}


/* ============================================================
   STOCK STATUS
============================================================ */

.pf-caisse-stock-status {
  margin: 0 15px 13px;
  padding: 12px;
  border: 1px solid #dcefe9;
  background: #f5fbf9;
  border-radius: 13px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.pf-caisse-status-icon {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  background: #dcfce7;
  color: #15803d;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}

.pf-caisse-stock-status strong {
  display: block;
  color: #166534;
  font-size: 10px;
}

.pf-caisse-stock-status span {
  display: block;
  margin-top: 2px;
  color: #64748b;
  font-size: 9px;
}


/* ============================================================
   UTILISATEUR
============================================================ */

.pf-caisse-user {
  min-height: 74px;
  border-top: 1px solid #eef2f4;
  padding: 12px 15px;
  display: flex;
  align-items: center;
  gap: 9px;
}

.pf-caisse-avatar {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: 11px;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 800;
}

.pf-caisse-avatar.small {
  width: 34px;
  height: 34px;
  border-radius: 10px;
}

.pf-caisse-user-info {
  min-width: 0;
  flex: 1;
}

.pf-caisse-user-info strong {
  display: block;
  color: #0f172a;
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pf-caisse-user-info span {
  display: block;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 9px;
}

.pf-caisse-logout {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #94a3b8;
  font-size: 18px;
  cursor: pointer;
}

.pf-caisse-logout:hover {
  background: #fef2f2;
  color: #dc2626;
}


/* ============================================================
   MAIN
============================================================ */

.pf-caisse-main {
  min-width: 0;
  flex: 1;
  height: 100vh;
  overflow-y: auto;
}

.pf-caisse-header {
  height: 76px;
  padding: 0 30px;
  background: #ffffff;
  border-bottom: 1px solid #e2e8f0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 50;
}

.pf-caisse-header-left {
  display: flex;
  align-items: center;
  gap: 15px;
}

.pf-caisse-header-label {
  color: #0f766e;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.2px;
}

.pf-caisse-header h1 {
  margin: 4px 0 0;
  color: #0f172a;
  font-size: 21px;
  line-height: 1.1;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.pf-caisse-header-right {
  display: flex;
  align-items: center;
  gap: 18px;
}

.pf-caisse-live {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #15803d;
  font-size: 10px;
  font-weight: 750;
}

.pf-caisse-live > span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 0 4px #dcfce7;
}

.pf-caisse-header-divider {
  width: 1px;
  height: 30px;
  background: #e2e8f0;
}

.pf-caisse-header-user {
  display: flex;
  align-items: center;
  gap: 9px;
}

.pf-caisse-header-user strong {
  display: block;
  color: #0f172a;
  font-size: 11px;
}

.pf-caisse-header-user span {
  display: block;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 9px;
}

.pf-caisse-mobile-menu {
  display: none;
}


/* ============================================================
   CONTENT
============================================================ */

.pf-caisse-content {
  width: 100%;
  max-width: 1700px;
  margin: 0 auto;
  padding: 25px 30px 40px;
}


/* ============================================================
   ALERTES
============================================================ */

.pf-caisse-alert {
  min-height: 62px;
  padding: 12px 15px;
  margin-bottom: 17px;
  border-radius: 13px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.pf-caisse-alert > span {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}

.pf-caisse-alert strong {
  display: block;
  font-size: 11px;
}

.pf-caisse-alert p {
  margin: 3px 0 0;
  font-size: 10px;
}

.pf-caisse-alert button {
  margin-left: auto;
  border: 0;
  background: transparent;
  font-size: 19px;
  cursor: pointer;
}

.pf-caisse-alert.danger {
  background: #fff7f7;
  border: 1px solid #fecaca;
  color: #991b1b;
}

.pf-caisse-alert.danger > span {
  background: #fee2e2;
  color: #dc2626;
}

.pf-caisse-alert.success {
  background: #f3fbf7;
  border: 1px solid #bbf7d0;
  color: #166534;
}

.pf-caisse-alert.success > span {
  background: #dcfce7;
  color: #16a34a;
}


/* ============================================================
   RECHERCHE
============================================================ */

.pf-caisse-search-card {
  min-height: 66px;
  padding: 10px 15px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 15px;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: 0 3px 14px rgba(15, 23, 42, 0.025);
}

.pf-caisse-search-icon {
  width: 39px;
  height: 39px;
  border-radius: 11px;
  background: #e6f5f2;
  color: #0f766e;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

.pf-caisse-search-input-wrap {
  min-width: 0;
  flex: 1;
  position: relative;
}

.pf-caisse-search-input-wrap input {
  width: 100%;
  height: 42px;
  border: 0;
  outline: 0;
  background: transparent;
  color: #0f172a;
  font-size: 13px;
  font-weight: 550;
}

.pf-caisse-search-input-wrap input::placeholder {
  color: #94a3b8;
}

.pf-caisse-search-clear {
  position: absolute;
  right: 3px;
  top: 50%;
  transform: translateY(-50%);
  width: 29px;
  height: 29px;
  border: 0;
  border-radius: 8px;
  background: #f1f5f9;
  color: #64748b;
  cursor: pointer;
}

.pf-caisse-search-hint {
  padding-left: 13px;
  border-left: 1px solid #e2e8f0;
  color: #94a3b8;
  font-size: 10px;
  white-space: nowrap;
}

.pf-caisse-search-hint span {
  color: #0f766e;
  font-weight: 800;
  margin-right: 4px;
}


/* ============================================================
   MINI STATS
============================================================ */

.pf-caisse-mini-stats {
  margin-top: 15px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 13px;
}

.pf-caisse-mini-stat {
  padding: 13px 15px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  display: flex;
  align-items: center;
  gap: 11px;
}

.pf-caisse-mini-icon {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}

.pf-caisse-mini-icon.teal {
  background: #e6f5f2;
  color: #0f766e;
}

.pf-caisse-mini-icon.orange {
  background: #fff7ed;
  color: #ea580c;
}

.pf-caisse-mini-icon.red {
  background: #fef2f2;
  color: #dc2626;
}

.pf-caisse-mini-icon.blue {
  background: #eff6ff;
  color: #2563eb;
}

.pf-caisse-mini-stat span {
  display: block;
  color: #64748b;
  font-size: 9px;
  font-weight: 650;
}

.pf-caisse-mini-stat strong {
  display: block;
  margin-top: 3px;
  color: #0f172a;
  font-size: 17px;
  font-weight: 800;
}


/* ============================================================
   WORKSPACE
============================================================ */

.pf-caisse-workspace {
  margin-top: 15px;
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(390px, 0.75fr);
  gap: 15px;
  align-items: start;
}


/* ============================================================
   PANELS
============================================================ */

.pf-caisse-products-panel,
.pf-caisse-cart-panel {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 17px;
  overflow: hidden;
  box-shadow: 0 4px 18px rgba(15, 23, 42, 0.025);
}

.pf-caisse-panel-header,
.pf-caisse-cart-header {
  min-height: 76px;
  padding: 16px 19px;
  border-bottom: 1px solid #eef2f4;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pf-caisse-panel-header > div > span,
.pf-caisse-cart-header > div > span {
  color: #0f766e;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: 1px;
}

.pf-caisse-panel-header h2,
.pf-caisse-cart-header h2 {
  margin: 4px 0 0;
  color: #0f172a;
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -0.25px;
}

.pf-caisse-product-count {
  color: #64748b;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  padding: 6px 10px;
  font-size: 9px;
  font-weight: 700;
}


/* ============================================================
   PRODUITS
============================================================ */

.pf-caisse-products {
  padding: 15px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
  max-height: 650px;
  overflow-y: auto;
}

.pf-caisse-product {
  min-width: 0;
  min-height: 174px;
  padding: 13px;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  background: #ffffff;
  text-align: left;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}

.pf-caisse-product:hover:not(:disabled) {
  transform: translateY(-2px);
  border-color: #99d8d1;
  box-shadow: 0 8px 22px rgba(15, 118, 110, 0.09);
}

.pf-caisse-product.disabled {
  opacity: 0.56;
  cursor: not-allowed;
}

.pf-caisse-product-top {
  position: relative;
  display: flex;
  justify-content: space-between;
}

.pf-caisse-product-icon {
  width: 39px;
  height: 39px;
  border-radius: 11px;
  background: #e6f5f2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
}

.pf-caisse-cart-badge {
  min-width: 23px;
  height: 23px;
  padding: 0 6px;
  border-radius: 20px;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9px;
  font-weight: 800;
}

.pf-caisse-product-info {
  min-width: 0;
  margin-top: 13px;
}

.pf-caisse-product-info strong {
  display: block;
  color: #0f172a;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pf-caisse-product-info span {
  display: block;
  margin-top: 4px;
  color: #64748b;
  font-size: 9px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pf-caisse-product-info small {
  display: block;
  margin-top: 4px;
  color: #94a3b8;
  font-size: 8px;
}

.pf-caisse-product-bottom {
  margin-top: auto;
  padding-top: 12px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
}

.pf-caisse-product-bottom > strong {
  color: #0f766e;
  font-size: 11px;
  font-weight: 850;
}

.pf-caisse-product-bottom > span {
  font-size: 8px;
  font-weight: 800;
  white-space: nowrap;
}

.pf-caisse-product-bottom .stock-ok {
  color: #15803d;
}

.pf-caisse-product-bottom .stock-low {
  color: #ea580c;
}

.pf-caisse-product-bottom .stock-out {
  color: #dc2626;
}


/* ============================================================
   PANIER
============================================================ */

.pf-caisse-cart-panel {
  position: sticky;
  top: 91px;
}

.pf-caisse-cart-header {
  min-height: 76px;
}

.pf-caisse-cart-header h2 {
  display: flex;
  align-items: center;
  gap: 7px;
}

.pf-caisse-cart-header h2 em {
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 20px;
  background: #e6f5f2;
  color: #0f766e;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-style: normal;
  font-size: 8px;
}

.pf-caisse-clear-cart {
  border: 0;
  background: transparent;
  color: #dc2626;
  font-size: 9px;
  font-weight: 750;
  cursor: pointer;
}

.pf-caisse-cart-items {
  max-height: 245px;
  overflow-y: auto;
}

.pf-caisse-cart-empty {
  min-height: 190px;
  padding: 25px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.pf-caisse-cart-empty-icon {
  width: 52px;
  height: 52px;
  margin-bottom: 12px;
  border-radius: 16px;
  background: #f1f5f9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 23px;
}

.pf-caisse-cart-empty strong {
  color: #334155;
  font-size: 12px;
}

.pf-caisse-cart-empty span {
  max-width: 230px;
  margin-top: 5px;
  color: #94a3b8;
  font-size: 9px;
  line-height: 1.5;
}


/* ============================================================
   CART ITEM
============================================================ */

.pf-caisse-cart-item {
  padding: 11px 15px;
  border-bottom: 1px solid #f1f5f9;
  display: grid;
  grid-template-columns: 35px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 9px;
}

.pf-caisse-cart-item-icon {
  width: 35px;
  height: 35px;
  border-radius: 9px;
  background: #f1f8f7;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
}

.pf-caisse-cart-item-info {
  min-width: 0;
}

.pf-caisse-cart-item-info strong {
  display: block;
  color: #0f172a;
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pf-caisse-cart-item-info span {
  display: block;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 8px;
}

.pf-caisse-quantity {
  display: flex;
  align-items: center;
  gap: 5px;
}

.pf-caisse-quantity button {
  width: 25px;
  height: 25px;
  border: 1px solid #e2e8f0;
  border-radius: 7px;
  background: #ffffff;
  color: #334155;
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
}

.pf-caisse-quantity button:hover {
  background: #e6f5f2;
  color: #0f766e;
  border-color: #b6ddd7;
}

.pf-caisse-quantity strong {
  min-width: 18px;
  text-align: center;
  color: #0f172a;
  font-size: 10px;
}

.pf-caisse-cart-item-total {
  text-align: right;
}

.pf-caisse-cart-item-total strong {
  display: block;
  color: #0f766e;
  font-size: 10px;
  white-space: nowrap;
}

.pf-caisse-cart-item-total button {
  margin-top: 3px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #cbd5e1;
  cursor: pointer;
  font-size: 13px;
}

.pf-caisse-cart-item-total button:hover {
  color: #dc2626;
}


/* ============================================================
   CLIENT
============================================================ */

.pf-caisse-customer {
  padding: 14px 16px;
  border-top: 1px solid #eef2f4;
}

.pf-caisse-subheading {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #334155;
  font-size: 10px;
  font-weight: 800;
}

.pf-caisse-subheading > span {
  font-size: 13px;
}

.pf-caisse-subheading small {
  margin-left: auto;
  color: #94a3b8;
  font-size: 8px;
  font-weight: 600;
}

.pf-caisse-customer-grid {
  margin-top: 9px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.pf-caisse-customer-grid input,
.pf-caisse-discount-row input,
.pf-caisse-paid input {
  width: 100%;
  height: 36px;
  padding: 0 10px;
  border: 1px solid #dfe6eb;
  border-radius: 9px;
  outline: none;
  background: #fbfdfd;
  color: #0f172a;
  font-size: 10px;
}

.pf-caisse-customer-grid input:focus,
.pf-caisse-discount-row input:focus,
.pf-caisse-paid input:focus {
  border-color: #76bdb5;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.07);
}


/* ============================================================
   TOTALS
============================================================ */

.pf-caisse-totals {
  padding: 13px 16px;
  background: #f8fafc;
  border-top: 1px solid #eef2f4;
}

.pf-caisse-totals > div {
  min-height: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.pf-caisse-totals span {
  color: #64748b;
  font-size: 9px;
}

.pf-caisse-totals strong {
  color: #334155;
  font-size: 10px;
}

.pf-caisse-discount-row > div {
  position: relative;
  width: 110px;
}

.pf-caisse-discount-row input {
  padding-right: 36px;
  text-align: right;
}

.pf-caisse-discount-row > div > span {
  position: absolute;
  right: 9px;
  top: 50%;
  transform: translateY(-50%);
  color: #94a3b8;
  font-size: 7px;
  font-weight: 750;
}

.pf-caisse-total-final {
  margin-top: 8px;
  padding-top: 11px;
  border-top: 1px dashed #dbe3e8;
}

.pf-caisse-total-final span {
  color: #0f172a;
  font-size: 9px;
  font-weight: 850;
}

.pf-caisse-total-final strong {
  color: #0f766e;
  font-size: 20px;
  font-weight: 900;
  letter-spacing: -0.5px;
}


/* ============================================================
   PAIEMENT
============================================================ */

.pf-caisse-payment {
  padding: 14px 16px;
  border-top: 1px solid #eef2f4;
}

.pf-caisse-payment-methods {
  margin-top: 10px;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 6px;
}

.pf-caisse-payment-methods button {
  min-width: 0;
  min-height: 52px;
  padding: 6px 3px;
  border: 1px solid #e2e8f0;
  border-radius: 9px;
  background: #ffffff;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

.pf-caisse-payment-methods button:hover {
  border-color: #9ed4ce;
}

.pf-caisse-payment-methods button.active {
  background: #e6f5f2;
  border-color: #62b5ab;
  box-shadow: 0 0 0 2px rgba(15, 118, 110, 0.05);
}

.pf-caisse-payment-methods button > span {
  font-size: 14px;
}

.pf-caisse-payment-methods button small {
  color: #64748b;
  font-size: 7px;
  font-weight: 750;
  text-align: center;
}

.pf-caisse-payment-methods button.active small {
  color: #0f766e;
}

.pf-caisse-paid {
  margin-top: 13px;
}

.pf-caisse-paid label {
  display: block;
  margin-bottom: 6px;
  color: #334155;
  font-size: 9px;
  font-weight: 800;
}

.pf-caisse-paid > div {
  position: relative;
}

.pf-caisse-paid input {
  height: 42px;
  padding-right: 52px;
  font-size: 13px;
  font-weight: 750;
  text-align: right;
}

.pf-caisse-paid > div > span {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: #94a3b8;
  font-size: 8px;
  font-weight: 750;
}

.pf-caisse-change {
  margin-top: 9px;
  padding: 10px 12px;
  border-radius: 9px;
  background: #fff7ed;
  border: 1px solid #fed7aa;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pf-caisse-change span {
  color: #9a3412;
  font-size: 9px;
  font-weight: 700;
}

.pf-caisse-change strong {
  color: #c2410c;
  font-size: 13px;
}

.pf-caisse-change.positive {
  background: #f0fdf4;
  border-color: #bbf7d0;
}

.pf-caisse-change.positive span {
  color: #166534;
}

.pf-caisse-change.positive strong {
  color: #15803d;
}


/* ============================================================
   BOUTON ENCAISSER
============================================================ */

.pf-caisse-submit {
  width: calc(100% - 32px);
  min-height: 49px;
  margin: 2px 16px 0;
  border: 0;
  border-radius: 11px;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 850;
  cursor: pointer;
  box-shadow: 0 7px 18px rgba(15, 118, 110, 0.18);
  transition:
    transform 0.18s ease,
    background 0.18s ease;
}

.pf-caisse-submit:hover:not(:disabled) {
  background: #115e59;
  transform: translateY(-1px);
}

.pf-caisse-submit:disabled {
  background: #cbd5e1;
  box-shadow: none;
  cursor: not-allowed;
}

.pf-caisse-submit > span:not(.pf-spinner) {
  font-size: 15px;
}

.pf-caisse-secure-note {
  margin: 8px 16px 15px;
  color: #94a3b8;
  font-size: 8px;
  text-align: center;
}


/* ============================================================
   BAS DE PAGE
============================================================ */

.pf-caisse-bottom {
  margin-top: 15px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 13px;
}

.pf-caisse-bottom-card {
  padding: 15px 17px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  column-gap: 15px;
}

.pf-caisse-bottom-card > span {
  color: #64748b;
  font-size: 9px;
  font-weight: 650;
}

.pf-caisse-bottom-card > strong {
  grid-row: span 2;
  color: #0f172a;
  font-size: 22px;
  font-weight: 850;
}

.pf-caisse-bottom-card > strong.danger {
  color: #dc2626;
}

.pf-caisse-bottom-card button {
  width: fit-content;
  margin-top: 5px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #0f766e;
  font-size: 8px;
  font-weight: 800;
  cursor: pointer;
}


/* ============================================================
   MODAL HISTORIQUE
============================================================ */

.pf-caisse-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 500;
  padding: 25px;
  background: rgba(15, 23, 42, 0.42);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
}

.pf-caisse-modal {
  width: min(680px, 100%);
  max-height: 85vh;
  background: #ffffff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 25px 70px rgba(15, 23, 42, 0.20);
  display: flex;
  flex-direction: column;
}

.pf-caisse-modal-header {
  min-height: 78px;
  padding: 16px 20px;
  border-bottom: 1px solid #e2e8f0;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pf-caisse-modal-header span {
  color: #0f766e;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: 1px;
}

.pf-caisse-modal-header h2 {
  margin: 4px 0 0;
  color: #0f172a;
  font-size: 17px;
  font-weight: 850;
}

.pf-caisse-modal-header button {
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 9px;
  background: #f1f5f9;
  color: #64748b;
  font-size: 20px;
  cursor: pointer;
}

.pf-caisse-modal-body {
  min-height: 180px;
  overflow-y: auto;
}

.pf-caisse-modal-empty {
  min-height: 220px;
  padding: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 8px;
  color: #94a3b8;
  text-align: center;
}

.pf-caisse-modal-empty > div:first-child {
  font-size: 27px;
}

.pf-caisse-modal-empty strong {
  color: #334155;
  font-size: 12px;
}

.pf-caisse-modal-empty span {
  font-size: 9px;
}

.pf-caisse-sales-list {
  padding: 5px 18px;
}

.pf-caisse-sale-row {
  min-height: 68px;
  padding: 10px 3px;
  border-bottom: 1px solid #f1f5f9;
  display: grid;
  grid-template-columns: 39px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}

.pf-caisse-sale-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: #e6f5f2;
  color: #0f766e;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pf-caisse-sale-info {
  min-width: 0;
}

.pf-caisse-sale-info strong {
  display: block;
  color: #0f172a;
  font-size: 10px;
}

.pf-caisse-sale-info span,
.pf-caisse-sale-info small {
  display: block;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 8px;
}

.pf-caisse-sale-amount {
  text-align: right;
}

.pf-caisse-sale-amount strong {
  display: block;
  color: #0f766e;
  font-size: 10px;
}

.pf-caisse-sale-amount span {
  display: block;
  margin-top: 3px;
  color: #15803d;
  font-size: 8px;
  font-weight: 750;
}

.pf-caisse-modal-footer {
  padding: 13px 18px;
  border-top: 1px solid #e2e8f0;
  display: flex;
  justify-content: flex-end;
}

.pf-caisse-modal-footer button {
  min-height: 36px;
  padding: 0 15px;
  border: 1px solid #e2e8f0;
  border-radius: 9px;
  background: #ffffff;
  color: #334155;
  font-size: 10px;
  font-weight: 750;
  cursor: pointer;
}


/* ============================================================
   OVERLAY MOBILE
============================================================ */

.pf-caisse-overlay {
  display: none;
}


/* ============================================================
   SCROLLBAR
============================================================ */

.pf-caisse-products::-webkit-scrollbar,
.pf-caisse-cart-items::-webkit-scrollbar,
.pf-caisse-main::-webkit-scrollbar,
.pf-caisse-nav::-webkit-scrollbar,
.pf-caisse-modal-body::-webkit-scrollbar {
  width: 5px;
}

.pf-caisse-products::-webkit-scrollbar-thumb,
.pf-caisse-cart-items::-webkit-scrollbar-thumb,
.pf-caisse-main::-webkit-scrollbar-thumb,
.pf-caisse-nav::-webkit-scrollbar-thumb,
.pf-caisse-modal-body::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 20px;
}


/* ============================================================
   RESPONSIVE — TABLETTE
============================================================ */

@media (max-width: 1250px) {

  .pf-caisse-content {
    padding-left: 20px;
    padding-right: 20px;
  }

  .pf-caisse-products {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pf-caisse-workspace {
    grid-template-columns:
      minmax(0, 1.15fr)
      minmax(360px, 0.85fr);
  }

}


/* ============================================================
   RESPONSIVE — PETIT ÉCRAN
============================================================ */

@media (max-width: 950px) {

  .pf-caisse-sidebar {
    position: fixed;
    left: 0;
    top: 0;
    transform: translateX(-105%);
    transition: transform 0.25s ease;
    box-shadow: 15px 0 45px rgba(15, 23, 42, 0.12);
  }

  .pf-caisse-sidebar-open {
    transform: translateX(0);
  }

  .pf-caisse-overlay {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 90;
    border: 0;
    background: rgba(15, 23, 42, 0.38);
    backdrop-filter: blur(2px);
  }

  .pf-caisse-close {
    display: block;
    width: 32px;
    height: 32px;
    border: 0;
    border-radius: 8px;
    background: #f1f5f9;
    color: #64748b;
    font-size: 20px;
    cursor: pointer;
  }

  .pf-caisse-mobile-menu {
    width: 38px;
    height: 38px;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    background: #ffffff;
    color: #334155;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 18px;
  }

  .pf-caisse-header {
    padding: 0 20px;
  }

  .pf-caisse-workspace {
    grid-template-columns: 1fr;
  }

  .pf-caisse-cart-panel {
    position: static;
  }

  .pf-caisse-products {
    max-height: 500px;
  }

}


/* ============================================================
   RESPONSIVE — MOBILE
============================================================ */

@media (max-width: 650px) {

  .pf-caisse-header {
    height: 68px;
    padding: 0 13px;
  }

  .pf-caisse-header h1 {
    font-size: 17px;
  }

  .pf-caisse-header-label {
    font-size: 7px;
  }

  .pf-caisse-header-right {
    gap: 0;
  }

  .pf-caisse-live,
  .pf-caisse-header-divider,
  .pf-caisse-header-user > div {
    display: none;
  }

  .pf-caisse-content {
    padding: 13px 10px 30px;
  }

  .pf-caisse-search-card {
    padding: 8px 10px;
  }

  .pf-caisse-search-icon {
    width: 34px;
    height: 34px;
  }

  .pf-caisse-search-input-wrap input {
    font-size: 11px;
  }

  .pf-caisse-search-hint {
    display: none;
  }

  .pf-caisse-mini-stats {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .pf-caisse-mini-stat {
    padding: 10px;
  }

  .pf-caisse-mini-icon {
    width: 32px;
    height: 32px;
  }

  .pf-caisse-mini-stat strong {
    font-size: 15px;
  }

  .pf-caisse-products {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 9px;
    gap: 7px;
  }

  .pf-caisse-product {
    min-height: 155px;
    padding: 10px;
  }

  .pf-caisse-product-icon {
    width: 34px;
    height: 34px;
  }

  .pf-caisse-product-info strong {
    font-size: 10px;
  }

  .pf-caisse-product-bottom > strong {
    font-size: 9px;
  }

  .pf-caisse-cart-item {
    grid-template-columns: 32px minmax(0, 1fr);
  }

  .pf-caisse-quantity {
    grid-column: 2;
  }

  .pf-caisse-cart-item-total {
    grid-column: 2;
    grid-row: 2;
    justify-self: end;
    margin-top: -28px;
  }

  .pf-caisse-customer-grid {
    grid-template-columns: 1fr;
  }

  .pf-caisse-payment-methods {
    grid-template-columns: repeat(3, 1fr);
  }

  .pf-caisse-bottom {
    grid-template-columns: 1fr;
  }

  .pf-caisse-modal-overlay {
    padding: 10px;
  }

  .pf-caisse-modal {
    max-height: 92vh;
    border-radius: 15px;
  }

}


/* ============================================================
   TRÈS PETIT MOBILE
============================================================ */

@media (max-width: 390px) {

  .pf-caisse-products {
    grid-template-columns: 1fr;
  }

  .pf-caisse-product {
    min-height: 135px;
  }

  .pf-caisse-payment-methods {
    grid-template-columns: repeat(2, 1fr);
  }

}
/* =========================================================
   PHARMAFLOW — ESPACE PHARMACIEN
   Design professionnel / clair / responsive
   ========================================================= */


/* =========================================================
   VARIABLES
   ========================================================= */

:root {
  --pf-pharmacien-primary: #0f766e;
  --pf-pharmacien-primary-dark: #115e59;
  --pf-pharmacien-primary-light: #e8f6f3;

  --pf-pharmacien-bg: #f5f8f8;
  --pf-pharmacien-white: #ffffff;

  --pf-pharmacien-text: #0f172a;
  --pf-pharmacien-secondary: #334155;
  --pf-pharmacien-soft: #64748b;
  --pf-pharmacien-muted: #94a3b8;

  --pf-pharmacien-border: #e2e8f0;

  --pf-pharmacien-success: #15803d;
  --pf-pharmacien-success-bg: #ecfdf3;

  --pf-pharmacien-warning: #b45309;
  --pf-pharmacien-warning-bg: #fff7ed;

  --pf-pharmacien-danger: #dc2626;
  --pf-pharmacien-danger-bg: #fef2f2;

  --pf-pharmacien-shadow:
    0 1px 2px rgba(15, 23, 42, 0.04),
    0 8px 24px rgba(15, 23, 42, 0.04);

  --pf-pharmacien-shadow-hover:
    0 10px 30px rgba(15, 23, 42, 0.08);
}


/* =========================================================
   PAGE PRINCIPALE
   ========================================================= */

.pf-app {
  min-height: 100vh;
  background: var(--pf-pharmacien-bg);
}

.pf-main {
  min-width: 0;
}

.pf-content {
  padding: 0 28px 40px;
}

.pf-container {
  width: 100%;
  max-width: 1680px;
  margin: 0 auto;
}


/* =========================================================
   TOPBAR
   ========================================================= */

.pf-topbar {
  min-height: 76px;
  padding: 18px 28px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  background: rgba(255, 255, 255, 0.96);
  border-bottom: 1px solid var(--pf-pharmacien-border);

  position: sticky;
  top: 0;
  z-index: 30;

  backdrop-filter: blur(12px);
}

.pf-topbar-left {
  min-width: 0;

  display: flex;
  align-items: center;
  gap: 14px;
}

.pf-page-title {
  margin: 0;

  color: var(--pf-pharmacien-text);

  font-size: 25px;
  line-height: 1.2;
  font-weight: 750;

  letter-spacing: -0.025em;
}

.pf-page-subtitle {
  margin: 5px 0 0;

  color: var(--pf-pharmacien-soft);

  font-size: 14px;
  line-height: 1.5;
}

.pf-topbar-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}


/* =========================================================
   ROLE PILL
   ========================================================= */

.pf-role-pill {
  min-height: 38px;
  padding: 0 13px;

  display: inline-flex;
  align-items: center;
  gap: 8px;

  border: 1px solid #bfe7e1;
  border-radius: 999px;

  background: var(--pf-pharmacien-primary-light);
  color: var(--pf-pharmacien-primary-dark);

  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.pf-role-dot {
  width: 8px;
  height: 8px;

  border-radius: 50%;
  background: var(--pf-pharmacien-primary);

  box-shadow: 0 0 0 4px rgba(15, 118, 110, 0.10);
}


/* =========================================================
   BOUTONS
   ========================================================= */

.pf-btn {
  min-height: 42px;
  padding: 0 16px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  border-radius: 9px;
  border: 1px solid transparent;

  font-size: 13px;
  font-weight: 700;

  cursor: pointer;

  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease;
}

.pf-btn:hover {
  transform: translateY(-1px);
}

.pf-btn-primary {
  background: var(--pf-pharmacien-primary);
  color: #ffffff;

  box-shadow:
    0 4px 10px rgba(15, 118, 110, 0.16);
}

.pf-btn-primary:hover {
  background: var(--pf-pharmacien-primary-dark);

  box-shadow:
    0 7px 16px rgba(15, 118, 110, 0.20);
}

.pf-btn-secondary {
  background: #ffffff;
  color: var(--pf-pharmacien-secondary);

  border-color: var(--pf-pharmacien-border);
}

.pf-btn-secondary:hover {
  background: #f8fafc;
}

.pf-btn-white {
  background: #ffffff;
  color: var(--pf-pharmacien-primary-dark);

  border-color: rgba(255, 255, 255, 0.9);

  box-shadow:
    0 5px 15px rgba(15, 23, 42, 0.08);
}


/* =========================================================
   WELCOME CARD
   ========================================================= */

.pf-welcome-card {
  position: relative;
  overflow: hidden;

  margin-top: 26px;
  margin-bottom: 22px;

  min-height: 190px;
  padding: 30px 34px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;

  border-radius: 18px;

  background:
    linear-gradient(
      135deg,
      #0f766e 0%,
      #0d8278 55%,
      #115e59 100%
    );

  box-shadow:
    0 10px 30px rgba(15, 118, 110, 0.16);
}

.pf-welcome-card::before {
  content: "";

  position: absolute;

  width: 280px;
  height: 280px;

  right: 100px;
  top: -180px;

  border-radius: 50%;

  border: 1px solid rgba(255, 255, 255, 0.12);
}

.pf-welcome-card::after {
  content: "";

  position: absolute;

  width: 220px;
  height: 220px;

  right: -70px;
  bottom: -120px;

  border-radius: 50%;

  border: 1px solid rgba(255, 255, 255, 0.12);
}

.pf-welcome-card > div {
  position: relative;
  z-index: 2;
}

.pf-welcome-eyebrow {
  margin-bottom: 9px;

  color: rgba(255, 255, 255, 0.72);

  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.pf-welcome-card h2 {
  margin: 0;

  color: #ffffff;

  font-size: 27px;
  line-height: 1.2;
  font-weight: 750;

  letter-spacing: -0.025em;
}

.pf-welcome-card p {
  max-width: 690px;

  margin: 10px 0 0;

  color: rgba(255, 255, 255, 0.82);

  font-size: 14px;
  line-height: 1.65;
}

.pf-welcome-action {
  flex-shrink: 0;
}


/* =========================================================
   STATISTIQUES
   ========================================================= */

.pf-stats-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 16px;

  margin-bottom: 24px;
}

.pf-stat-card {
  min-width: 0;

  padding: 20px;

  background: var(--pf-pharmacien-white);

  border: 1px solid var(--pf-pharmacien-border);
  border-radius: 14px;

  box-shadow: var(--pf-pharmacien-shadow);

  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease;
}

.pf-stat-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--pf-pharmacien-shadow-hover);
}

.pf-stat-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.pf-stat-icon {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  background: var(--pf-pharmacien-primary-light);
  color: var(--pf-pharmacien-primary);

  font-size: 18px;
}

.pf-stat-label {
  color: var(--pf-pharmacien-muted);

  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.pf-stat-value {
  margin-top: 17px;

  color: var(--pf-pharmacien-text);

  font-size: 27px;
  line-height: 1.15;
  font-weight: 800;

  letter-spacing: -0.03em;
}

.pf-stat-description {
  margin-top: 5px;

  color: var(--pf-pharmacien-soft);

  font-size: 12px;
}


/* =========================================================
   SECTIONS
   ========================================================= */

.pf-section {
  margin-bottom: 24px;
}

.pf-section-header {
  margin-bottom: 13px;

  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}

.pf-section-title {
  margin: 0;

  color: var(--pf-pharmacien-text);

  font-size: 18px;
  font-weight: 750;
}

.pf-section-subtitle {
  margin: 4px 0 0;

  color: var(--pf-pharmacien-soft);

  font-size: 13px;
}


/* =========================================================
   ACTIONS RAPIDES
   ========================================================= */

.pf-quick-actions {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 14px;
}

.pf-quick-action {
  min-width: 0;

  padding: 17px;

  display: flex;
  align-items: center;
  gap: 12px;

  text-align: left;
  text-decoration: none;

  background: #ffffff;

  border: 1px solid var(--pf-pharmacien-border);
  border-radius: 13px;

  color: inherit;

  cursor: pointer;

  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.03);

  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}

.pf-quick-action:hover {
  transform: translateY(-2px);

  border-color: #b7deda;

  box-shadow:
    0 10px 22px rgba(15, 23, 42, 0.06);
}

.pf-quick-action-primary {
  border-color: #a9dcd5;

  background:
    linear-gradient(
      180deg,
      #f0faf8 0%,
      #ffffff 100%
    );
}

.pf-quick-icon {
  width: 43px;
  height: 43px;

  flex: 0 0 43px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  background: var(--pf-pharmacien-primary-light);
  color: var(--pf-pharmacien-primary);

  font-size: 19px;
}

.pf-quick-action > span:nth-child(2) {
  min-width: 0;

  flex: 1;
}

.pf-quick-action strong {
  display: block;

  color: var(--pf-pharmacien-text);

  font-size: 13px;
  line-height: 1.3;
  font-weight: 750;
}

.pf-quick-action small {
  display: block;

  margin-top: 4px;

  color: var(--pf-pharmacien-soft);

  font-size: 11px;
  line-height: 1.4;
}

.pf-quick-arrow {
  color: var(--pf-pharmacien-muted);

  font-size: 18px;

  transition:
    transform 0.18s ease,
    color 0.18s ease;
}

.pf-quick-action:hover .pf-quick-arrow {
  color: var(--pf-pharmacien-primary);
  transform: translateX(3px);
}


/* =========================================================
   DASHBOARD GRID
   ========================================================= */

.pf-dashboard-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1.45fr)
    minmax(320px, 0.85fr);

  gap: 20px;

  margin-bottom: 20px;
}

.pf-dashboard-side {
  display: flex;
  flex-direction: column;
  gap: 20px;
}


/* =========================================================
   CARTES
   ========================================================= */

.pf-card {
  min-width: 0;

  background: #ffffff;

  border: 1px solid var(--pf-pharmacien-border);
  border-radius: 15px;

  box-shadow: var(--pf-pharmacien-shadow);
}

.pf-card-header {
  min-height: 72px;

  padding: 18px 20px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;

  border-bottom: 1px solid #edf1f4;
}

.pf-card-title {
  margin: 0;

  color: var(--pf-pharmacien-text);

  font-size: 15px;
  font-weight: 750;
}

.pf-card-subtitle {
  margin: 4px 0 0;

  color: var(--pf-pharmacien-soft);

  font-size: 12px;
  line-height: 1.45;
}

.pf-card-link {
  color: var(--pf-pharmacien-primary);

  font-size: 12px;
  font-weight: 750;

  text-decoration: none;

  white-space: nowrap;
}

.pf-card-link:hover {
  color: var(--pf-pharmacien-primary-dark);
  text-decoration: underline;
}


/* =========================================================
   TABLES
   ========================================================= */

.pf-table-wrapper {
  width: 100%;

  overflow-x: auto;
  overflow-y: hidden;
}

.pf-table {
  width: 100%;

  border-collapse: collapse;

  font-size: 12px;
}

.pf-table th {
  padding: 12px 18px;

  background: #f8fafb;

  color: var(--pf-pharmacien-muted);

  border-bottom: 1px solid var(--pf-pharmacien-border);

  text-align: left;

  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;

  white-space: nowrap;
}

.pf-table td {
  padding: 14px 18px;

  color: var(--pf-pharmacien-secondary);

  border-bottom: 1px solid #f0f2f4;

  vertical-align: middle;
}

.pf-table tbody tr:last-child td {
  border-bottom: none;
}

.pf-table tbody tr {
  transition: background 0.15s ease;
}

.pf-table tbody tr:hover {
  background: #fbfdfd;
}

.pf-table td strong {
  color: var(--pf-pharmacien-text);

  font-weight: 700;
}


/* =========================================================
   BADGES
   ========================================================= */

.pf-badge {
  min-height: 25px;
  padding: 0 9px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  border-radius: 999px;

  font-size: 10px;
  font-weight: 800;

  white-space: nowrap;
}

.pf-badge-success {
  background: var(--pf-pharmacien-success-bg);
  color: var(--pf-pharmacien-success);
}

.pf-badge-warning {
  background: var(--pf-pharmacien-warning-bg);
  color: var(--pf-pharmacien-warning);
}

.pf-badge-danger {
  background: var(--pf-pharmacien-danger-bg);
  color: var(--pf-pharmacien-danger);
}


/* =========================================================
   PERFORMANCE
   ========================================================= */

.pf-performance-list {
  padding: 4px 20px 12px;
}

.pf-performance-row {
  min-height: 70px;

  padding: 14px 0;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;

  border-bottom: 1px solid #eef1f3;
}

.pf-performance-row:last-child {
  border-bottom: none;
}

.pf-performance-row > div {
  min-width: 0;
}

.pf-performance-row span {
  display: block;

  color: var(--pf-pharmacien-soft);

  font-size: 11px;
}

.pf-performance-row strong {
  display: block;

  margin-top: 4px;

  color: var(--pf-pharmacien-text);

  font-size: 13px;
}

.pf-performance-row b {
  color: var(--pf-pharmacien-primary-dark);

  font-size: 13px;
  font-weight: 800;

  white-space: nowrap;
}


/* =========================================================
   STOCK SUMMARY
   ========================================================= */

.pf-stock-summary {
  padding: 18px 20px;

  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 10px;
}

.pf-stock-summary-item {
  padding: 14px 10px;

  text-align: center;

  border-radius: 10px;

  background: #f8fafc;
}

.pf-stock-summary-item.warning {
  background: var(--pf-pharmacien-warning-bg);
}

.pf-stock-summary-item.danger {
  background: var(--pf-pharmacien-danger-bg);
}

.pf-stock-number {
  color: var(--pf-pharmacien-text);

  font-size: 21px;
  font-weight: 800;
}

.pf-stock-summary-item span {
  display: block;

  margin-top: 3px;

  color: var(--pf-pharmacien-soft);

  font-size: 10px;
  font-weight: 650;
}

.pf-stock-summary-item.warning .pf-stock-number {
  color: var(--pf-pharmacien-warning);
}

.pf-stock-summary-item.danger .pf-stock-number {
  color: var(--pf-pharmacien-danger);
}


/* =========================================================
   LISTE ALERTES PRODUITS
   ========================================================= */

.pf-product-alert-list {
  padding: 5px 20px 15px;
}

.pf-product-alert-row {
  min-height: 58px;

  padding: 10px 0;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;

  border-bottom: 1px solid #eef1f3;
}

.pf-product-alert-row:last-child {
  border-bottom: none;
}

.pf-product-alert-row > div {
  min-width: 0;
}

.pf-product-alert-row strong {
  display: block;

  overflow: hidden;

  color: var(--pf-pharmacien-text);

  font-size: 12px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-product-alert-row span:not(.pf-badge) {
  display: block;

  margin-top: 4px;

  color: var(--pf-pharmacien-soft);

  font-size: 10px;
}


/* =========================================================
   EXPIRATION
   ========================================================= */

.pf-info-badge {
  padding: 6px 9px;

  border-radius: 7px;

  background: var(--pf-pharmacien-primary-light);
  color: var(--pf-pharmacien-primary-dark);

  font-size: 10px;
  font-weight: 800;
}

.pf-alert {
  margin: 14px 20px;

  padding: 13px 14px;

  display: flex;
  align-items: flex-start;
  gap: 11px;

  border-radius: 10px;
}

.pf-alert-danger {
  background: var(--pf-pharmacien-danger-bg);
  border: 1px solid #fecaca;
}

.pf-alert-warning {
  background: var(--pf-pharmacien-warning-bg);
  border: 1px solid #fed7aa;
}

.pf-alert-icon {
  width: 25px;
  height: 25px;

  flex: 0 0 25px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  font-size: 11px;
  font-weight: 900;
}

.pf-alert-danger .pf-alert-icon {
  background: #fee2e2;
  color: var(--pf-pharmacien-danger);
}

.pf-alert-warning .pf-alert-icon {
  background: #ffedd5;
  color: var(--pf-pharmacien-warning);
}

.pf-alert strong {
  display: block;

  color: var(--pf-pharmacien-text);

  font-size: 12px;
}

.pf-alert p {
  margin: 3px 0 0;

  color: var(--pf-pharmacien-soft);

  font-size: 11px;
  line-height: 1.5;
}

.pf-alert-action {
  margin-left: auto;

  color: var(--pf-pharmacien-primary);

  font-size: 11px;
  font-weight: 750;

  white-space: nowrap;
}


/* =========================================================
   MOUVEMENTS DE STOCK
   ========================================================= */

.pf-movement-list {
  padding: 4px 20px 12px;
}

.pf-movement-row {
  min-height: 62px;

  padding: 10px 0;

  display: flex;
  align-items: center;
  gap: 11px;

  border-bottom: 1px solid #eef1f3;
}

.pf-movement-row:last-child {
  border-bottom: none;
}

.pf-movement-icon {
  width: 33px;
  height: 33px;

  flex: 0 0 33px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  font-size: 16px;
  font-weight: 800;
}

.pf-movement-icon.success {
  background: var(--pf-pharmacien-success-bg);
  color: var(--pf-pharmacien-success);
}

.pf-movement-icon.danger {
  background: var(--pf-pharmacien-danger-bg);
  color: var(--pf-pharmacien-danger);
}

.pf-movement-info {
  min-width: 0;
  flex: 1;
}

.pf-movement-info strong {
  display: block;

  overflow: hidden;

  color: var(--pf-pharmacien-text);

  font-size: 11px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-movement-info span {
  display: block;

  margin-top: 3px;

  overflow: hidden;

  color: var(--pf-pharmacien-soft);

  font-size: 10px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-movement-quantity {
  text-align: right;
}

.pf-movement-quantity strong {
  display: block;

  font-size: 12px;
}

.pf-movement-quantity span {
  display: block;

  margin-top: 3px;

  color: var(--pf-pharmacien-muted);

  font-size: 9px;

  white-space: nowrap;
}

.text-success {
  color: var(--pf-pharmacien-success) !important;
}

.text-danger {
  color: var(--pf-pharmacien-danger) !important;
}

.text-right {
  text-align: right !important;
}


/* =========================================================
   SECURITY CARD
   ========================================================= */

.pf-security-card {
  margin-top: 20px;

  padding: 17px 20px;

  display: flex;
  align-items: flex-start;
  gap: 13px;

  border: 1px solid #cce8e4;
  border-radius: 13px;

  background:
    linear-gradient(
      180deg,
      #f0faf8 0%,
      #f8fcfb 100%
    );
}

.pf-security-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  background: #d9f2ee;
  color: var(--pf-pharmacien-primary);

  font-size: 17px;
}

.pf-security-card strong {
  display: block;

  color: var(--pf-pharmacien-primary-dark);

  font-size: 12px;
  font-weight: 800;
}

.pf-security-card p {
  margin: 4px 0 0;

  color: var(--pf-pharmacien-soft);

  font-size: 11px;
  line-height: 1.55;
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.pf-empty-state {
  padding: 32px 20px;

  text-align: center;
}

.pf-empty-icon {
  width: 48px;
  height: 48px;

  margin: 0 auto 11px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;

  background: #f1f5f9;

  font-size: 20px;
}

.pf-empty-state h3 {
  margin: 0;

  color: var(--pf-pharmacien-text);

  font-size: 13px;
  font-weight: 750;
}

.pf-empty-state p {
  max-width: 420px;

  margin: 5px auto 14px;

  color: var(--pf-pharmacien-soft);

  font-size: 11px;
  line-height: 1.55;
}


/* =========================================================
   LOADING
   ========================================================= */

.pf-loading {
  padding: 45px 20px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  color: var(--pf-pharmacien-soft);

  text-align: center;
}

.pf-loading p {
  margin: 12px 0 0;

  font-size: 12px;
}

.pf-spinner {
  width: 30px;
  height: 30px;

  border: 3px solid #d9eeee;
  border-top-color: var(--pf-pharmacien-primary);

  border-radius: 50%;

  animation: pf-pharmacien-spin 0.8s linear infinite;
}

@keyframes pf-pharmacien-spin {
  to {
    transform: rotate(360deg);
  }
}


/* =========================================================
   SKELETON
   ========================================================= */

.pf-skeleton-grid {
  padding: 35px 28px;

  display: grid;
  grid-template-columns: repeat(4, 1fr);

  gap: 16px;
}

.pf-skeleton-card {
  height: 145px;

  border-radius: 14px;

  background:
    linear-gradient(
      90deg,
      #edf2f3 25%,
      #f7f9f9 50%,
      #edf2f3 75%
    );

  background-size: 200% 100%;

  animation: pf-pharmacien-skeleton 1.4s infinite;
}

@keyframes pf-pharmacien-skeleton {
  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.pf-sidebar {
  background: #ffffff;

  border-right: 1px solid var(--pf-pharmacien-border);
}

.pf-sidebar-brand {
  min-height: 76px;

  padding: 17px 18px;

  display: flex;
  align-items: center;
  gap: 11px;

  border-bottom: 1px solid #edf1f3;
}

.pf-logo-mark {
  width: 39px;
  height: 39px;

  flex: 0 0 39px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  background: var(--pf-pharmacien-primary);
  color: #ffffff;

  font-size: 18px;
  font-weight: 850;

  box-shadow:
    0 5px 12px rgba(15, 118, 110, 0.18);
}

.pf-brand-name {
  color: var(--pf-pharmacien-text);

  font-size: 15px;
  font-weight: 800;
}

.pf-brand-subtitle {
  margin-top: 2px;

  color: var(--pf-pharmacien-soft);

  font-size: 10px;
}


/* =========================================================
   PHARMACY CARD SIDEBAR
   ========================================================= */

.pf-pharmacy-card {
  margin: 15px;

  padding: 12px;

  display: flex;
  align-items: center;
  gap: 10px;

  background: #f6faf9;

  border: 1px solid #dcefeb;
  border-radius: 11px;
}

.pf-pharmacy-icon {
  width: 34px;
  height: 34px;

  flex: 0 0 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  background: #e2f5f1;

  font-size: 16px;
}

.pf-pharmacy-info {
  min-width: 0;
}

.pf-pharmacy-info strong {
  display: block;

  overflow: hidden;

  color: var(--pf-pharmacien-text);

  font-size: 11px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-pharmacy-info span {
  display: block;

  margin-top: 3px;

  color: var(--pf-pharmacien-soft);

  font-size: 9px;
}


/* =========================================================
   NAVIGATION SIDEBAR
   ========================================================= */

.pf-sidebar-nav {
  padding: 6px 10px 15px;
}

.pf-nav-section-title {
  margin: 17px 9px 7px;

  color: #a0aab6;

  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.pf-nav-item {
  min-height: 39px;

  padding: 0 10px;

  display: flex;
  align-items: center;
  gap: 10px;

  color: #475569;

  border-radius: 8px;

  text-decoration: none;

  font-size: 11px;
  font-weight: 600;

  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.pf-nav-item:hover {
  background: #f1f8f7;
  color: var(--pf-pharmacien-primary-dark);
}

.pf-nav-item.active {
  background: var(--pf-pharmacien-primary-light);
  color: var(--pf-pharmacien-primary-dark);

  font-weight: 750;
}

.pf-nav-icon {
  width: 20px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  font-size: 14px;
}

.pf-nav-readonly {
  margin-left: auto;

  padding: 3px 6px;

  border-radius: 5px;

  background: #f1f5f9;

  color: #94a3b8;

  font-size: 7px;
  font-weight: 750;
}


/* =========================================================
   UTILISATEUR SIDEBAR
   ========================================================= */

.pf-sidebar-user {
  padding: 13px 15px;

  display: flex;
  align-items: center;
  gap: 9px;

  border-top: 1px solid #edf1f3;
}

.pf-user-avatar {
  width: 34px;
  height: 34px;

  flex: 0 0 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: var(--pf-pharmacien-primary-light);
  color: var(--pf-pharmacien-primary-dark);

  font-size: 10px;
  font-weight: 800;
}

.pf-user-info {
  min-width: 0;
  flex: 1;
}

.pf-user-info strong {
  display: block;

  overflow: hidden;

  color: var(--pf-pharmacien-text);

  font-size: 10px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-user-info span {
  display: block;

  margin-top: 2px;

  color: var(--pf-pharmacien-soft);

  font-size: 9px;
}

.pf-logout-button {
  width: 30px;
  height: 30px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid var(--pf-pharmacien-border);
  border-radius: 7px;

  background: #ffffff;

  color: #64748b;

  cursor: pointer;
}

.pf-logout-button:hover {
  background: #fef2f2;
  color: #dc2626;
  border-color: #fecaca;
}


/* =========================================================
   MOBILE
   ========================================================= */

.pf-mobile-menu,
.pf-mobile-close {
  display: none;
}

.pf-mobile-overlay {
  display: none;
}


/* =========================================================
   RESPONSIVE 1300 PX
   ========================================================= */

@media (max-width: 1300px) {
  .pf-stats-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-quick-actions {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-dashboard-grid {
    grid-template-columns:
      minmax(0, 1fr);
  }

  .pf-dashboard-side {
    display: grid;

    grid-template-columns:
      repeat(2, minmax(0, 1fr));

    gap: 20px;
  }
}


/* =========================================================
   RESPONSIVE 900 PX
   ========================================================= */

@media (max-width: 900px) {
  .pf-content {
    padding: 0 18px 30px;
  }

  .pf-topbar {
    padding: 15px 18px;
  }

  .pf-welcome-card {
    padding: 25px;
  }

  .pf-dashboard-side {
    grid-template-columns: 1fr;
  }
}


/* =========================================================
   RESPONSIVE 760 PX
   ========================================================= */

@media (max-width: 760px) {
  .pf-sidebar {
    position: fixed;

    top: 0;
    left: 0;
    bottom: 0;

    width: 275px;

    z-index: 100;

    transform: translateX(-105%);

    transition:
      transform 0.25s ease;

    box-shadow:
      10px 0 35px rgba(15, 23, 42, 0.10);
  }

  .pf-sidebar.pf-sidebar-open {
    transform: translateX(0);
  }

  .pf-mobile-overlay {
    position: fixed;

    inset: 0;

    z-index: 90;

    display: block;

    background: rgba(15, 23, 42, 0.38);

    backdrop-filter: blur(2px);
  }

  .pf-mobile-menu {
    width: 38px;
    height: 38px;

    display: flex;
    align-items: center;
    justify-content: center;

    flex: 0 0 38px;

    border: 1px solid var(--pf-pharmacien-border);
    border-radius: 9px;

    background: #ffffff;

    color: var(--pf-pharmacien-text);

    font-size: 17px;

    cursor: pointer;
  }

  .pf-mobile-close {
    width: 30px;
    height: 30px;

    margin-left: auto;

    display: flex;
    align-items: center;
    justify-content: center;

    border: none;
    border-radius: 7px;

    background: #f1f5f9;

    color: #64748b;

    font-size: 19px;

    cursor: pointer;
  }

  .pf-topbar {
    min-height: 68px;
  }

  .pf-page-title {
    font-size: 19px;
  }

  .pf-page-subtitle {
    display: none;
  }

  .pf-role-pill {
    display: none;
  }

  .pf-topbar-actions .pf-btn {
    min-height: 38px;
    padding: 0 11px;

    font-size: 11px;
  }

  .pf-welcome-card {
    min-height: auto;

    margin-top: 18px;

    padding: 23px;

    flex-direction: column;
    align-items: flex-start;
  }

  .pf-welcome-card h2 {
    font-size: 22px;
  }

  .pf-welcome-card p {
    font-size: 12px;
  }

  .pf-welcome-action {
    width: 100%;
  }

  .pf-welcome-action .pf-btn {
    width: 100%;
  }

  .pf-stats-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));

    gap: 10px;
  }

  .pf-stat-card {
    padding: 15px;
  }

  .pf-stat-value {
    font-size: 22px;
  }

  .pf-stat-description {
    font-size: 10px;
  }

  .pf-quick-actions {
    grid-template-columns: 1fr;
  }

  .pf-dashboard-grid {
    grid-template-columns: 1fr;

    gap: 15px;
  }

  .pf-dashboard-side {
    display: flex;
    flex-direction: column;

    gap: 15px;
  }

  .pf-card-header {
    padding: 15px;
  }

  .pf-performance-list,
  .pf-movement-list,
  .pf-product-alert-list {
    padding-left: 15px;
    padding-right: 15px;
  }

  .pf-stock-summary {
    padding-left: 15px;
    padding-right: 15px;
  }

  .pf-security-card {
    padding: 14px;
  }
}


/* =========================================================
   RESPONSIVE 520 PX
   ========================================================= */

@media (max-width: 520px) {
  .pf-content {
    padding: 0 12px 24px;
  }

  .pf-topbar {
    padding: 12px;
  }

  .pf-topbar-actions .pf-btn {
    font-size: 0;
    width: 38px;
    padding: 0;
  }

  .pf-topbar-actions .pf-btn::first-letter {
    font-size: 17px;
  }

  .pf-page-title {
    font-size: 17px;
  }

  .pf-stats-grid {
    grid-template-columns: 1fr 1fr;
  }

  .pf-stat-card {
    padding: 13px;
  }

  .pf-stat-icon {
    width: 32px;
    height: 32px;

    font-size: 14px;
  }

  .pf-stat-label {
    font-size: 8px;
  }

  .pf-stat-value {
    margin-top: 12px;

    font-size: 20px;
  }

  .pf-welcome-card {
    padding: 19px;
  }

  .pf-welcome-card h2 {
    font-size: 20px;
  }

  .pf-section-title {
    font-size: 16px;
  }

  .pf-quick-action {
    padding: 14px;
  }

  .pf-quick-icon {
    width: 38px;
    height: 38px;
    flex-basis: 38px;
  }

  .pf-table {
    min-width: 620px;
  }

  .pf-security-card {
    align-items: flex-start;
  }
}


/* =========================================================
   ACCESSIBILITÉ
   ========================================================= */

.pf-btn:focus-visible,
.pf-nav-item:focus-visible,
.pf-card-link:focus-visible,
.pf-quick-action:focus-visible,
.pf-mobile-menu:focus-visible,
.pf-mobile-close:focus-visible,
.pf-logout-button:focus-visible {
  outline: 3px solid rgba(15, 118, 110, 0.22);
  outline-offset: 2px;
}


/* =========================================================
   IMPRESSION
   ========================================================= */

@media print {
  .pf-sidebar,
  .pf-topbar-actions,
  .pf-mobile-menu,
  .pf-mobile-close {
    display: none !important;
  }

  .pf-content {
    padding: 0;
  }

  .pf-welcome-card,
  .pf-card,
  .pf-security-card {
    box-shadow: none;
  }

  .pf-main {
    margin-left: 0 !important;
  }
}
