/* =========================================================
   PHARMAFLOW — ESPACE MON PROFIL
   Design Premium / Responsive / Mobile First
   ========================================================= */

:root {
  --pf-profile-primary: #0f766e;
  --pf-profile-primary-dark: #115e59;
  --pf-profile-primary-light: #e6f5f2;

  --pf-profile-bg: #f4f8f8;
  --pf-profile-surface: #ffffff;

  --pf-profile-text: #0f172a;
  --pf-profile-text-secondary: #334155;
  --pf-profile-text-soft: #64748b;
  --pf-profile-text-muted: #94a3b8;

  --pf-profile-border: #e2e8f0;
  --pf-profile-border-light: #edf2f7;

  --pf-profile-success: #15803d;
  --pf-profile-success-bg: #f0fdf4;

  --pf-profile-danger: #dc2626;
  --pf-profile-danger-bg: #fef2f2;

  --pf-profile-warning: #d97706;
  --pf-profile-warning-bg: #fffbeb;

  --pf-profile-info: #2563eb;
  --pf-profile-info-bg: #eff6ff;

  --pf-profile-sidebar: 270px;
  --pf-profile-topbar: 78px;
}

/* =========================================================
   PAGE PRINCIPALE
   ========================================================= */

.pf-app {
  min-height: 100vh;
  background:
    radial-gradient(
      circle at top right,
      rgba(15, 118, 110, 0.035),
      transparent 28%
    ),
    var(--pf-profile-bg);
  color: var(--pf-profile-text);
}

/* =========================================================
   SIDEBAR
   ========================================================= */

.pf-sidebar {
  position: fixed;
  z-index: 100;
  top: 0;
  left: 0;

  width: var(--pf-profile-sidebar);
  height: 100vh;

  display: flex;
  flex-direction: column;

  background: rgba(255, 255, 255, 0.97);
  border-right: 1px solid var(--pf-profile-border);

  box-shadow:
    8px 0 30px rgba(15, 23, 42, 0.035);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);

  transition:
    transform 0.28s ease,
    box-shadow 0.28s ease;
}

/* =========================================================
   BRAND
   ========================================================= */

.pf-sidebar-brand {
  min-height: 78px;
  padding: 18px 18px;

  display: flex;
  align-items: center;
  gap: 12px;

  border-bottom: 1px solid var(--pf-profile-border-light);
}

.pf-logo-mark {
  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;

  background:
    linear-gradient(
      135deg,
      var(--pf-profile-primary),
      var(--pf-profile-primary-dark)
    );

  color: #ffffff;

  font-size: 19px;
  font-weight: 900;

  box-shadow:
    0 8px 18px rgba(15, 118, 110, 0.22);
}

.pf-brand-name {
  color: var(--pf-profile-text);
  font-size: 17px;
  line-height: 1.2;
  font-weight: 850;
  letter-spacing: -0.02em;
}

.pf-brand-subtitle {
  margin-top: 3px;

  color: var(--pf-profile-text-muted);

  font-size: 11px;
  line-height: 1.2;
  font-weight: 600;
}

/* =========================================================
   CARTE PHARMACIE
   ========================================================= */

.pf-pharmacy-card {
  margin: 18px 14px 10px;
  padding: 13px;

  display: flex;
  align-items: center;
  gap: 11px;

  border: 1px solid #dcefeb;
  border-radius: 15px;

  background:
    linear-gradient(
      135deg,
      #f4fbfa,
      #ffffff
    );

  box-shadow:
    0 4px 14px rgba(15, 118, 110, 0.045);
}

.pf-pharmacy-icon {
  width: 40px;
  height: 40px;

  flex: 0 0 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  background: var(--pf-profile-primary-light);

  font-size: 19px;
}

.pf-pharmacy-info {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 3px;
}

.pf-pharmacy-info strong {
  overflow: hidden;

  color: var(--pf-profile-text);

  font-size: 13px;
  font-weight: 800;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.pf-pharmacy-info span {
  overflow: hidden;

  color: var(--pf-profile-text-soft);

  font-size: 11px;
  font-weight: 500;

  white-space: nowrap;
  text-overflow: ellipsis;
}

/* =========================================================
   NAVIGATION
   ========================================================= */

.pf-sidebar-nav {
  flex: 1;

  padding: 12px 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.pf-nav-section-title {
  margin: 18px 10px 8px;

  color: #9aa8b8;

  font-size: 9px;
  line-height: 1.2;

  font-weight: 850;
  letter-spacing: 0.12em;
}

.pf-nav-item {
  width: 100%;

  min-height: 44px;

  margin-bottom: 4px;
  padding: 10px 12px;

  display: flex;
  align-items: center;
  gap: 11px;

  border: 1px solid transparent;
  border-radius: 11px;

  background: transparent;

  color: var(--pf-profile-text-secondary);

  font-family: inherit;
  font-size: 12px;
  font-weight: 650;

  text-decoration: none;

  cursor: pointer;

  transition:
    background 0.18s ease,
    color 0.18s ease,
    border-color 0.18s ease,
    transform 0.18s ease;
}

.pf-nav-item:hover {
  background: #f5faf9;
  border-color: #e1efed;

  color: var(--pf-profile-primary);

  transform: translateX(2px);
}

.pf-nav-item.active {
  background:
    linear-gradient(
      90deg,
      #e8f6f3,
      #f3faf9
    );

  border-color: #d5ebe7;

  color: var(--pf-profile-primary-dark);

  font-weight: 800;

  box-shadow:
    inset 3px 0 0 var(--pf-profile-primary);
}

.pf-nav-icon {
  width: 22px;
  height: 22px;

  flex: 0 0 22px;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 15px;
}

/* =========================================================
   UTILISATEUR SIDEBAR
   ========================================================= */

.pf-sidebar-user {
  margin: 10px 12px 14px;
  padding: 12px;

  display: flex;
  align-items: center;
  gap: 10px;

  border: 1px solid var(--pf-profile-border);
  border-radius: 15px;

  background: #ffffff;

  box-shadow:
    0 4px 15px rgba(15, 23, 42, 0.035);
}

.pf-user-avatar {
  width: 39px;
  height: 39px;

  flex: 0 0 39px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  background:
    linear-gradient(
      135deg,
      #dff5f1,
      #c9ebe5
    );

  color: var(--pf-profile-primary-dark);

  font-size: 12px;
  font-weight: 900;
}

.pf-user-info {
  min-width: 0;
  flex: 1;

  display: flex;
  flex-direction: column;
  gap: 3px;
}

.pf-user-info strong {
  overflow: hidden;

  color: var(--pf-profile-text);

  font-size: 11px;
  font-weight: 800;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.pf-user-info span {
  color: var(--pf-profile-text-soft);

  font-size: 10px;
  font-weight: 600;
}

.pf-logout-button {
  width: 31px;
  height: 31px;

  flex: 0 0 31px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #fee2e2;
  border-radius: 9px;

  background: #fff7f7;

  color: var(--pf-profile-danger);

  font-size: 14px;

  cursor: pointer;

  transition:
    background 0.18s ease,
    transform 0.18s ease;
}

.pf-logout-button:hover {
  background: var(--pf-profile-danger-bg);

  transform: scale(1.05);
}

/* =========================================================
   MAIN
   ========================================================= */

.pf-main {
  min-height: 100vh;

  margin-left: var(--pf-profile-sidebar);

  background: transparent;
}

/* =========================================================
   TOPBAR
   ========================================================= */

.pf-topbar {
  position: sticky;
  z-index: 50;
  top: 0;

  min-height: var(--pf-profile-topbar);

  padding: 14px 30px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 20px;

  background: rgba(255, 255, 255, 0.94);

  border-bottom: 1px solid rgba(226, 232, 240, 0.85);

  box-shadow:
    0 4px 20px rgba(15, 23, 42, 0.025);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.pf-topbar-left {
  min-width: 0;

  display: flex;
  align-items: center;
  gap: 14px;
}

.pf-page-title {
  margin: 0;

  color: var(--pf-profile-text);

  font-size: 23px;
  line-height: 1.2;

  font-weight: 850;

  letter-spacing: -0.035em;
}

.pf-page-subtitle {
  margin: 5px 0 0;

  color: var(--pf-profile-text-soft);

  font-size: 12px;
  line-height: 1.45;

  font-weight: 500;
}

.pf-topbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pf-role-pill {
  min-height: 35px;

  padding: 7px 11px;

  display: inline-flex;
  align-items: center;
  gap: 7px;

  border: 1px solid #dcefeb;
  border-radius: 999px;

  background: #f5fbfa;

  color: var(--pf-profile-primary-dark);

  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.06em;
}

.pf-role-dot {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #16a34a;

  box-shadow:
    0 0 0 3px rgba(22, 163, 74, 0.10);
}

/* =========================================================
   CONTENT
   ========================================================= */

.pf-content {
  padding: 30px;
}

.pf-container {
  width: 100%;
  max-width: 1320px;

  margin: 0 auto;
}

/* =========================================================
   CARTES
   ========================================================= */

.pf-card {
  position: relative;

  overflow: hidden;

  padding: 25px;

  border: 1px solid var(--pf-profile-border);
  border-radius: 19px;

  background: rgba(255, 255, 255, 0.98);

  box-shadow:
    0 8px 25px rgba(15, 23, 42, 0.035);

  transition:
    box-shadow 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}

.pf-card:hover {
  border-color: #d9e7e5;

  box-shadow:
    0 14px 35px rgba(15, 23, 42, 0.055);
}

.pf-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 20px;
}

.pf-card-title {
  margin: 0;

  color: var(--pf-profile-text);

  font-size: 16px;
  line-height: 1.3;

  font-weight: 850;

  letter-spacing: -0.025em;
}

.pf-card-subtitle {
  margin: 6px 0 0;

  color: var(--pf-profile-text-soft);

  font-size: 12px;
  line-height: 1.5;

  font-weight: 500;
}

/* =========================================================
   FORMULAIRES
   ========================================================= */

.pf-form-grid {
  display: grid;

  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );

  gap: 18px;
}

.pf-form-group {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 7px;
}

.pf-form-label {
  color: var(--pf-profile-text-secondary);

  font-size: 11px;
  line-height: 1.3;

  font-weight: 800;
}

.form-input {
  width: 100%;
  min-height: 46px;

  padding: 11px 13px;

  border: 1px solid #dce3ea;
  border-radius: 11px;

  outline: none;

  background: #ffffff;

  color: var(--pf-profile-text);

  font-family: inherit;
  font-size: 13px;
  font-weight: 500;

  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    background 0.18s ease;
}

.form-input:hover {
  border-color: #cbd5e1;
}

.form-input:focus {
  border-color: var(--pf-profile-primary);

  background: #ffffff;

  box-shadow:
    0 0 0 4px
    rgba(15, 118, 110, 0.10);
}

.form-input::placeholder {
  color: #a8b3c0;
}

.form-input:disabled {
  cursor: not-allowed;

  background: #f8fafc;

  color: #94a3b8;
}

/* =========================================================
   INFO CARDS
   ========================================================= */

.pf-info-card {
  min-width: 0;

  padding: 16px 17px;

  border: 1px solid var(--pf-profile-border-light);
  border-radius: 14px;

  background:
    linear-gradient(
      135deg,
      #fbfdfd,
      #f8fafc
    );

  transition:
    border-color 0.18s ease,
    transform 0.18s ease,
    box-shadow 0.18s ease;
}

.pf-info-card:hover {
  border-color: #dce8e7;

  transform: translateY(-1px);

  box-shadow:
    0 7px 20px rgba(15, 23, 42, 0.035);
}

.pf-info-card span {
  display: block;

  margin-bottom: 7px;

  color: var(--pf-profile-text-muted);

  font-size: 10px;
  line-height: 1.3;

  font-weight: 750;

  text-transform: uppercase;
  letter-spacing: 0.045em;
}

.pf-info-card strong {
  display: block;

  color: var(--pf-profile-text);

  font-size: 13px;
  line-height: 1.45;

  font-weight: 750;

  word-break: break-word;
}

/* =========================================================
   BOUTONS
   ========================================================= */

.pf-btn {
  min-height: 42px;

  padding: 10px 16px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;

  border: 1px solid transparent;
  border-radius: 11px;

  font-family: inherit;

  font-size: 12px;
  line-height: 1;

  font-weight: 800;

  cursor: pointer;

  white-space: nowrap;

  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease;
}

.pf-btn:hover:not(:disabled) {
  transform: translateY(-1px);
}

.pf-btn:active:not(:disabled) {
  transform: translateY(0);
}

.pf-btn:disabled {
  opacity: 0.6;

  cursor: not-allowed;
}

.pf-btn-primary {
  border-color: var(--pf-profile-primary);

  background:
    linear-gradient(
      135deg,
      var(--pf-profile-primary),
      var(--pf-profile-primary-dark)
    );

  color: #ffffff;

  box-shadow:
    0 7px 16px
    rgba(15, 118, 110, 0.17);
}

.pf-btn-primary:hover:not(:disabled) {
  box-shadow:
    0 10px 22px
    rgba(15, 118, 110, 0.23);
}

.pf-btn-secondary {
  border-color: var(--pf-profile-border);

  background: #ffffff;

  color: var(--pf-profile-text-secondary);
}

.pf-btn-secondary:hover:not(:disabled) {
  border-color: #cbd5e1;

  background: #f8fafc;
}

.pf-btn-danger {
  border-color: #fecaca;

  background: #fff7f7;

  color: var(--pf-profile-danger);
}

.pf-btn-danger:hover:not(:disabled) {
  background: var(--pf-profile-danger-bg);

  border-color: #fca5a5;
}

/* =========================================================
   ALERTES
   ========================================================= */

.pf-alert {
  padding: 14px 16px;

  display: flex;
  align-items: flex-start;
  gap: 12px;

  border-radius: 14px;

  font-size: 12px;
}

.pf-alert-icon {
  width: 27px;
  height: 27px;

  flex: 0 0 27px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  font-size: 12px;
  font-weight: 900;
}

.pf-alert strong {
  display: block;

  margin-bottom: 3px;

  font-size: 12px;
  font-weight: 850;
}

.pf-alert p {
  margin: 0;

  font-size: 11px;
  line-height: 1.5;
}

.pf-alert-success {
  border: 1px solid #bbf7d0;

  background: var(--pf-profile-success-bg);

  color: #166534;
}

.pf-alert-success .pf-alert-icon {
  background: #dcfce7;

  color: #15803d;
}

.pf-alert-danger {
  border: 1px solid #fecaca;

  background: var(--pf-profile-danger-bg);

  color: #991b1b;
}

.pf-alert-danger .pf-alert-icon {
  background: #fee2e2;

  color: #dc2626;
}

/* =========================================================
   SECURITY CARD
   ========================================================= */

.pf-security-card {
  padding: 20px;

  display: flex;
  align-items: flex-start;
  gap: 15px;

  border: 1px solid #dbeafe;
  border-radius: 17px;

  background:
    linear-gradient(
      135deg,
      #f8fbff,
      #ffffff
    );

  box-shadow:
    0 7px 22px rgba(37, 99, 235, 0.035);
}

.pf-security-icon {
  width: 45px;
  height: 45px;

  flex: 0 0 45px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;

  background: var(--pf-profile-info-bg);

  font-size: 19px;
}

.pf-security-card strong {
  display: block;

  margin-bottom: 5px;

  color: #1e3a8a;

  font-size: 13px;
  font-weight: 850;
}

.pf-security-card p {
  margin: 0;

  color: #64748b;

  font-size: 11px;
  line-height: 1.6;
}
/* =========================================================
   LOADING
   ========================================================= */

.pf-loading {
  min-height: 300px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 14px;

  color: var(--pf-profile-text-soft);

  text-align: center;
}

.pf-loading p {
  margin: 0;

  font-size: 12px;
  font-weight: 600;
}

.pf-spinner {
  width: 36px;
  height: 36px;

  border: 3px solid #dcefeb;
  border-top-color: var(--pf-profile-primary);

  border-radius: 50%;

  animation:
    pfProfileSpin 0.75s linear infinite;
}

@keyframes pfProfileSpin {
  to {
    transform: rotate(360deg);
  }
}

/* =========================================================
   MOBILE MENU
   ========================================================= */

.pf-mobile-menu,
.pf-mobile-close {
  display: none;
}

.pf-mobile-overlay {
  display: none;
}

/* =========================================================
   FOCUS ACCESSIBLE
   ========================================================= */

.pf-btn:focus-visible,
.pf-nav-item:focus-visible,
.pf-logout-button:focus-visible,
.pf-mobile-menu:focus-visible,
.pf-mobile-close:focus-visible {
  outline: 3px solid
    rgba(15, 118, 110, 0.18);

  outline-offset: 2px;
}

/* =========================================================
   ANIMATION D'APPARITION
   ========================================================= */

.pf-card {
  animation:
    pfProfileCardIn 0.35s ease both;
}

@keyframes pfProfileCardIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* =========================================================
   TABLETTE
   ========================================================= */

@media (max-width: 1100px) {
  .pf-sidebar {
    width: 245px;
  }

  .pf-main {
    margin-left: 245px;
  }

  .pf-topbar {
    padding-left: 22px;
    padding-right: 22px;
  }

  .pf-content {
    padding: 22px;
  }

  .pf-form-grid {
    gap: 14px;
  }

  .pf-card {
    padding: 21px;
  }

  .pf-topbar-actions
  .pf-btn-primary {
    padding-left: 13px;
    padding-right: 13px;
  }
}

/* =========================================================
   TABLETTE / PETIT ÉCRAN
   ========================================================= */

@media (max-width: 850px) {
  .pf-sidebar {
    transform: translateX(-105%);

    box-shadow:
      15px 0 45px
      rgba(15, 23, 42, 0.15);
  }

  .pf-sidebar.pf-sidebar-open {
    transform: translateX(0);
  }

  .pf-main {
    margin-left: 0;
  }

  .pf-mobile-menu {
    width: 39px;
    height: 39px;

    flex: 0 0 39px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid var(--pf-profile-border);
    border-radius: 11px;

    background: #ffffff;

    color: var(--pf-profile-text);

    font-size: 18px;

    cursor: pointer;

    box-shadow:
      0 3px 10px rgba(15, 23, 42, 0.035);
  }

  .pf-mobile-close {
    width: 30px;
    height: 30px;

    margin-left: auto;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid var(--pf-profile-border);
    border-radius: 9px;

    background: #ffffff;

    color: var(--pf-profile-text-soft);

    font-size: 19px;
    line-height: 1;

    cursor: pointer;
  }

  .pf-mobile-overlay {
    position: fixed;
    z-index: 90;

    inset: 0;

    display: block;

    background:
      rgba(15, 23, 42, 0.38);

    backdrop-filter: blur(2px);
    -webkit-backdrop-filter: blur(2px);
  }

  .pf-topbar {
    min-height: 70px;

    padding: 12px 18px;
  }

  .pf-content {
    padding: 20px 18px;
  }

  .pf-page-title {
    font-size: 20px;
  }

  .pf-page-subtitle {
    font-size: 11px;
  }

  .pf-role-pill {
    display: none;
  }
}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 640px) {
  .pf-topbar {
    padding: 11px 13px;

    gap: 10px;
  }

  .pf-topbar-left {
    gap: 10px;
  }

  .pf-page-title {
    font-size: 18px;
  }

  .pf-page-subtitle {
    display: none;
  }

  .pf-topbar-actions
  .pf-btn-primary {
    min-height: 38px;

    padding: 8px 11px;

    font-size: 10px;
  }

  .pf-content {
    padding: 14px 12px 24px;
  }

  .pf-card {
    padding: 17px 15px;

    border-radius: 16px;
  }

  .pf-card-header {
    align-items: flex-start;

    gap: 12px;
  }

  .pf-card-title {
    font-size: 14px;
  }

  .pf-card-subtitle {
    font-size: 11px;
  }

  .pf-form-grid {
    grid-template-columns: 1fr;

    gap: 13px;
  }

  .pf-form-label {
    font-size: 10px;
  }

  .form-input {
    min-height: 45px;

    padding: 10px 12px;

    font-size: 12px;
  }

  .pf-btn {
    min-height: 42px;

    padding: 10px 13px;

    font-size: 11px;
  }

  .pf-info-card {
    padding: 13px 14px;
  }

  .pf-info-card span {
    font-size: 9px;
  }

  .pf-info-card strong {
    font-size: 12px;
  }

  .pf-security-card {
    padding: 16px;

    gap: 11px;
  }

  .pf-security-icon {
    width: 39px;
    height: 39px;

    flex-basis: 39px;

    border-radius: 11px;

    font-size: 16px;
  }

  .pf-security-card strong {
    font-size: 12px;
  }

  .pf-security-card p {
    font-size: 10px;
    line-height: 1.55;
  }

  .pf-alert {
    padding: 12px;

    gap: 9px;
  }

  .pf-alert-icon {
    width: 24px;
    height: 24px;

    flex-basis: 24px;

    border-radius: 7px;
  }

  .pf-alert strong {
    font-size: 11px;
  }

  .pf-alert p {
    font-size: 10px;
  }

  .pf-container
  > section:last-child {
    align-items: stretch !important;
  }
}

/* =========================================================
   PETIT MOBILE
   ========================================================= */

@media (max-width: 430px) {
  .pf-topbar-actions
  .pf-btn-primary {
    padding-left: 9px;
    padding-right: 9px;

    font-size: 9px;
  }

  .pf-mobile-menu {
    width: 36px;
    height: 36px;

    flex-basis: 36px;
  }

  .pf-page-title {
    font-size: 17px;
  }

  .pf-content {
    padding-left: 9px;
    padding-right: 9px;
  }

  .pf-card {
    padding: 15px 13px;
  }

  .pf-card-header
  > div:last-child {
    width: 44px !important;
    height: 44px !important;

    flex: 0 0 44px;
  }

  .pf-btn {
    width: 100%;
  }

  .pf-form-group {
    width: 100%;
  }

  .pf-info-card {
    width: 100%;
  }
}

/* =========================================================
   ACCESSIBILITÉ — RÉDUCTION DES ANIMATIONS
   ========================================================= */

@media (prefers-reduced-motion: reduce) {
  .pf-card,
  .pf-btn,
  .pf-nav-item,
  .pf-info-card,
  .pf-logout-button,
  .pf-sidebar,
  .pf-spinner {
    animation: none !important;
    transition: none !important;
  }
}

/* =========================================================
   IMPRESSION
   ========================================================= */

@media print {
  body {
    background: #ffffff !important;
  }

  .pf-sidebar,
  .pf-topbar,
  .pf-mobile-menu,
  .pf-mobile-overlay,
  .pf-btn,
  .pf-logout-button {
    display: none !important;
  }

  .pf-main {
    margin-left: 0 !important;
  }

  .pf-content {
    padding: 0 !important;
  }

  .pf-card {
    border: 1px solid #d1d5db !important;

    box-shadow: none !important;

    break-inside: avoid;
  }

  .pf-security-card {
    box-shadow: none !important;
  }
}
/* =========================================================
   PHARMAFLOW — PHARMACIEN DASHBOARD
   PREMIUM RESPONSIVE DESIGN
   ========================================================= */

.pf-pharmacien-app {
  --pharma-primary: #0f766e;
  --pharma-primary-dark: #115e59;
  --pharma-primary-soft: #e7f7f4;
  --pharma-primary-softer: #f2fbfa;

  --pharma-text: #0f172a;
  --pharma-text-secondary: #334155;
  --pharma-text-muted: #64748b;

  --pharma-border: #e2e8f0;
  --pharma-background: #f5f8f9;
  --pharma-white: #ffffff;

  --pharma-success: #15803d;
  --pharma-success-soft: #ecfdf3;

  --pharma-warning: #b45309;
  --pharma-warning-soft: #fff7ed;

  --pharma-danger: #dc2626;
  --pharma-danger-soft: #fef2f2;

  --pharma-info: #2563eb;
  --pharma-info-soft: #eff6ff;
}

/* ---------------------------------------------------------
   SIDEBAR
   --------------------------------------------------------- */

.pf-pharmacien-sidebar {
  background:
    linear-gradient(
      180deg,
      #ffffff 0%,
      #fbfefe 100%
    );

  border-right:
    1px solid
    var(--pharma-border);

  box-shadow:
    4px 0 24px
    rgba(15, 23, 42, 0.035);

  z-index: 100;
}

.pf-pharmacien-sidebar .pf-sidebar-brand {
  padding:
    22px 20px;

  border-bottom:
    1px solid
    #edf2f3;
}

.pf-pharmacien-sidebar
  .pf-logo-mark {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;

  background:
    linear-gradient(
      135deg,
      #0f766e,
      #14b8a6
    );

  color: #ffffff;

  font-size: 18px;
  font-weight: 900;

  box-shadow:
    0 8px 20px
    rgba(15, 118, 110, 0.22);
}

.pf-pharmacien-sidebar
  .pf-brand-name {
  font-size: 17px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.pf-pharmacien-sidebar
  .pf-brand-subtitle {
  margin-top: 3px;

  color:
    var(--pharma-text-muted);

  font-size: 11px;
  font-weight: 600;
}

/* ---------------------------------------------------------
   PHARMACY CARD
   --------------------------------------------------------- */

.pf-pharmacien-pharmacy-card {
  position: relative;

  margin:
    18px 16px 12px;

  padding: 14px;

  display: flex;
  align-items: center;

  gap: 11px;

  border:
    1px solid
    #dcefeb;

  border-radius: 15px;

  background:
    linear-gradient(
      135deg,
      #f2fbfa,
      #ffffff
    );

  overflow: hidden;
}

.pf-pharmacien-pharmacy-card::before {
  content: "";

  position: absolute;

  left: 0;
  top: 0;
  bottom: 0;

  width: 3px;

  background:
    linear-gradient(
      180deg,
      #0f766e,
      #14b8a6
    );
}

.pf-pharmacien-pharmacy-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  background: #ffffff;

  border:
    1px solid
    #d8ece9;

  font-size: 18px;
}

.pf-pharmacien-pharmacy-card > div:nth-child(2) {
  min-width: 0;

  display: flex;
  flex-direction: column;
}

.pf-pharmacien-pharmacy-card span:not(.pf-online-dot) {
  color:
    var(--pharma-text-muted);

  font-size: 10px;
  font-weight: 700;

  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.pf-pharmacien-pharmacy-card strong {
  margin-top: 2px;

  overflow: hidden;

  color:
    var(--pharma-text);

  font-size: 13px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.pf-pharmacien-pharmacy-card small {
  margin-top: 2px;

  color:
    var(--pharma-text-muted);

  font-size: 11px;
}

.pf-online-dot {
  width: 8px;
  height: 8px;

  margin-left: auto;

  flex: 0 0 8px;

  border-radius: 999px;

  background: #22c55e;

  box-shadow:
    0 0 0 4px
    rgba(34, 197, 94, 0.10);
}

/* ---------------------------------------------------------
   NAVIGATION
   --------------------------------------------------------- */

.pf-pharmacien-sidebar
  .pf-sidebar-nav {
  padding:
    10px 12px;
}

.pf-pharmacien-sidebar
  .pf-nav-section-title {
  margin:
    18px 10px 7px;

  color:
    #94a3b8;

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 0.10em;
}

.pf-pharmacien-sidebar
  .pf-nav-item {
  width: 100%;

  min-height: 44px;

  margin-bottom: 3px;

  padding:
    0 12px;

  display: flex;
  align-items: center;

  gap: 11px;

  border: 0;
  border-radius: 11px;

  background: transparent;

  color:
    #475569;

  font-family: inherit;

  font-size: 13px;
  font-weight: 600;

  text-align: left;

  cursor: pointer;

  transition:
    background 0.18s ease,
    color 0.18s ease,
    transform 0.18s ease;
}

.pf-pharmacien-sidebar
  .pf-nav-item:hover {
  background:
    #f0f8f7;

  color:
    var(--pharma-primary);

  transform:
    translateX(2px);
}

.pf-pharmacien-sidebar
  .pf-nav-item-active {
  background:
    linear-gradient(
      90deg,
      #e5f6f3,
      #f3fbfa
    );

  color:
    var(--pharma-primary);

  font-weight: 750;

  box-shadow:
    inset 3px 0 0
    var(--pharma-primary);
}

.pf-pharmacien-sidebar
  .pf-nav-icon {
  width: 23px;

  display: inline-flex;
  justify-content: center;

  font-size: 17px;
}

/* ---------------------------------------------------------
   SIDEBAR USER
   --------------------------------------------------------- */

.pf-pharmacien-sidebar-user {
  margin-top: auto;

  padding:
    14px 15px;

  display: flex;
  align-items: center;

  gap: 10px;

  border-top:
    1px solid
    #edf2f3;
}

.pf-pharmacien-sidebar-user
  .pf-user-avatar {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  background:
    linear-gradient(
      135deg,
      #0f766e,
      #14b8a6
    );

  color: #ffffff;

  font-size: 13px;
  font-weight: 800;
}

.pf-pharmacien-sidebar-user
  .pf-user-info {
  min-width: 0;

  flex: 1;

  display: flex;
  flex-direction: column;
}

.pf-pharmacien-sidebar-user
  .pf-user-info strong {
  overflow: hidden;

  color:
    var(--pharma-text);

  font-size: 12px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.pf-pharmacien-sidebar-user
  .pf-user-info span {
  margin-top: 2px;

  color:
    var(--pharma-text-muted);

  font-size: 10px;
}

/* ---------------------------------------------------------
   TOPBAR
   --------------------------------------------------------- */

.pf-pharmacien-topbar {
  min-height: 76px;

  border-bottom:
    1px solid
    var(--pharma-border);

  background:
    rgba(255, 255, 255, 0.94);

  backdrop-filter:
    blur(16px);

  box-shadow:
    0 2px 15px
    rgba(15, 23, 42, 0.025);
}

.pf-topbar-page-title {
  color:
    var(--pharma-text);

  font-size: 17px;
  font-weight: 800;

  letter-spacing: -0.02em;
}

.pf-topbar-page-subtitle {
  margin-top: 3px;

  color:
    var(--pharma-text-muted);

  font-size: 12px;
}

.pf-topbar-right {
  display: flex;
  align-items: center;

  gap: 15px;
}

.pf-pharmacien-live {
  display: flex;
  align-items: center;

  gap: 7px;

  padding:
    7px 10px;

  border:
    1px solid
    #d9f2e2;

  border-radius: 999px;

  background:
    #f2fcf5;

  color:
    #15803d;

  font-size: 10px;
  font-weight: 750;
}

.pf-pharmacien-live span {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #22c55e;

  box-shadow:
    0 0 0 3px
    rgba(34, 197, 94, 0.12);
}

.pf-topbar-date {
  color:
    var(--pharma-text-muted);

  font-size: 12px;

  text-transform: capitalize;
}

.pf-topbar-profile {
  padding: 4px 7px;

  display: flex;
  align-items: center;

  gap: 9px;

  border: 0;

  border-radius: 12px;

  background: transparent;

  cursor: pointer;

  text-align: left;
}

.pf-topbar-profile:hover {
  background: #f8fafc;
}

.pf-topbar-avatar {
  width: 37px;
  height: 37px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  background:
    linear-gradient(
      135deg,
      #0f766e,
      #14b8a6
    );

  color: #ffffff;

  font-size: 12px;
  font-weight: 800;
}

.pf-topbar-profile div:last-child {
  display: flex;
  flex-direction: column;
}

.pf-topbar-profile strong {
  color:
    var(--pharma-text);

  font-size: 12px;
}

.pf-topbar-profile span {
  margin-top: 2px;

  color:
    var(--pharma-text-muted);

  font-size: 10px;
}
/* ---------------------------------------------------------
   HERO
   --------------------------------------------------------- */

.pf-pharmacien-hero {
  position: relative;

  margin-bottom: 20px;

  padding:
    28px 30px;

  display: flex;
  justify-content: space-between;
  align-items: center;

  gap: 25px;

  overflow: hidden;

  border-radius: 20px;

  background:
    linear-gradient(
      135deg,
      #0f766e 0%,
      #0d8178 48%,
      #115e59 100%
    );

  box-shadow:
    0 18px 45px
    rgba(15, 118, 110, 0.16);
}

.pf-pharmacien-hero::before {
  content: "";

  position: absolute;

  width: 330px;
  height: 330px;

  right: -110px;
  top: -170px;

  border-radius: 50%;

  background:
    rgba(255, 255, 255, 0.08);
}

.pf-pharmacien-hero::after {
  content: "";

  position: absolute;

  width: 190px;
  height: 190px;

  right: 160px;
  bottom: -130px;

  border-radius: 50%;

  background:
    rgba(255, 255, 255, 0.055);
}

.pf-pharmacien-hero-main {
  position: relative;
  z-index: 2;

  max-width: 700px;
}

.pf-pharmacien-eyebrow {
  margin-bottom: 8px;

  color:
    rgba(255, 255, 255, 0.72);

  font-size: 10px;
  font-weight: 800;

  letter-spacing: 0.13em;
}

.pf-pharmacien-hero h1 {
  margin: 0;

  color: #ffffff;

  font-size:
    clamp(25px, 3vw, 34px);

  line-height: 1.12;

  letter-spacing:
    -0.035em;
}

.pf-pharmacien-hero p {
  margin:
    11px 0 0;

  color:
    rgba(255, 255, 255, 0.82);

  font-size: 13px;
  line-height: 1.65;
}

.pf-pharmacien-hero p strong {
  color: #ffffff;
}

.pf-pharmacien-hero-meta {
  margin-top: 17px;

  display: flex;
  align-items: center;

  gap: 8px;

  flex-wrap: wrap;
}

.pf-pharmacien-hero-meta span {
  padding:
    7px 10px;

  border:
    1px solid
    rgba(255, 255, 255, 0.16);

  border-radius: 999px;

  background:
    rgba(255, 255, 255, 0.08);

  color:
    rgba(255, 255, 255, 0.9);

  font-size: 10px;
  font-weight: 650;
}

.pf-pharmacien-hero-actions {
  position: relative;
  z-index: 2;

  display: flex;
  flex-direction: column;

  align-items: stretch;

  gap: 8px;

  min-width: 185px;
}

.pf-btn-white {
  background: #ffffff !important;
  color:
    var(--pharma-primary) !important;

  border-color:
    #ffffff !important;

  box-shadow:
    0 8px 20px
    rgba(0, 0, 0, 0.10);
}

.pf-btn-white:hover {
  transform:
    translateY(-1px);

  box-shadow:
    0 12px 25px
    rgba(0, 0, 0, 0.13);
}

.pf-btn-ghost-white {
  background:
    rgba(255, 255, 255, 0.10) !important;

  color: #ffffff !important;

  border:
    1px solid
    rgba(255, 255, 255, 0.20) !important;
}

.pf-btn-ghost-white:hover {
  background:
    rgba(255, 255, 255, 0.16) !important;
}

.pf-pharmacien-refresh {
  padding: 8px 10px;

  border: 0;

  background: transparent;

  color:
    rgba(255, 255, 255, 0.70);

  font-size: 10px;
  font-weight: 650;

  cursor: pointer;
}

.pf-pharmacien-refresh:hover {
  color: #ffffff;
}

/* ---------------------------------------------------------
   KPI
   --------------------------------------------------------- */

.pf-pharmacien-kpi-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 15px;

  margin-bottom: 16px;
}

.pf-pharmacien-kpi {
  position: relative;

  min-width: 0;

  padding: 18px;

  border:
    1px solid
    var(--pharma-border);

  border-radius: 17px;

  background:
    #ffffff;

  box-shadow:
    0 5px 20px
    rgba(15, 23, 42, 0.035);

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    border-color 0.2s ease;
}

.pf-pharmacien-kpi:hover {
  transform:
    translateY(-2px);

  border-color:
    #cfe4e1;

  box-shadow:
    0 12px 30px
    rgba(15, 23, 42, 0.07);
}

.pf-pharmacien-kpi-head {
  display: flex;
  align-items: center;

  gap: 10px;
}

.pf-pharmacien-kpi-icon {
  width: 39px;
  height: 39px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  font-size: 17px;
}

.pf-pharmacien-kpi-icon.primary {
  background:
    #e7f7f4;
}

.pf-pharmacien-kpi-icon.info {
  background:
    #eff6ff;
}

.pf-pharmacien-kpi-icon.success {
  background:
    #ecfdf3;
}

.pf-pharmacien-kpi-icon.warning {
  background:
    #fff7ed;
}

.pf-pharmacien-kpi-head > span {
  color:
    var(--pharma-text-muted);

  font-size: 9px;
  font-weight: 800;

  letter-spacing:
    0.065em;
}

.pf-pharmacien-kpi > strong {
  display: block;

  margin-top: 17px;

  color:
    var(--pharma-text);

  font-size:
    clamp(20px, 2vw, 27px);

  font-weight: 850;

  letter-spacing:
    -0.035em;

  line-height: 1.1;

  overflow-wrap: anywhere;
}

.pf-pharmacien-kpi-footer {
  margin-top: 12px;

  display: flex;
  justify-content: space-between;

  gap: 8px;

  color:
    var(--pharma-text-muted);

  font-size: 10px;
}

.pf-pharmacien-kpi-footer b {
  color:
    var(--pharma-text-secondary);

  font-weight: 700;
}

/* ---------------------------------------------------------
   ALERT CARDS
   --------------------------------------------------------- */

.pf-pharmacien-alert-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 12px;

  margin-bottom: 26px;
}

.pf-pharmacien-alert-card {
  position: relative;

  min-width: 0;

  padding: 15px;

  display: flex;
  align-items: center;

  gap: 11px;

  border-radius: 15px;

  border:
    1px solid
    var(--pharma-border);

  background: #ffffff;

  text-align: left;

  cursor: pointer;

  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease;
}

.pf-pharmacien-alert-card:hover {
  transform:
    translateY(-2px);

  box-shadow:
    0 10px 25px
    rgba(15, 23, 42, 0.06);
}

.pf-pharmacien-alert-card.neutral {
  cursor: default;
}

.pf-pharmacien-alert-card-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  font-weight: 900;
}

.pf-pharmacien-alert-card.warning {
  background:
    #fffdf7;

  border-color:
    #f4e7c5;
}

.pf-pharmacien-alert-card.warning
  .pf-pharmacien-alert-card-icon {
  background:
    #fff3cd;

  color:
    #b45309;
}

.pf-pharmacien-alert-card.danger {
  background:
    #fffafa;

  border-color:
    #f5d6d6;
}

.pf-pharmacien-alert-card.danger
  .pf-pharmacien-alert-card-icon {
  background:
    #fee2e2;

  color:
    #dc2626;
}

.pf-pharmacien-alert-card.orange {
  background:
    #fffaf6;

  border-color:
    #f6dfcc;
}

.pf-pharmacien-alert-card.orange
  .pf-pharmacien-alert-card-icon {
  background:
    #ffedd5;

  color:
    #c2410c;
}

.pf-pharmacien-alert-card.neutral
  .pf-pharmacien-alert-card-icon {
  background:
    #e7f7f4;

  color:
    var(--pharma-primary);
}

.pf-pharmacien-alert-card > div:nth-child(2) {
  min-width: 0;

  display: flex;
  flex-direction: column;
}

.pf-pharmacien-alert-card
  div:nth-child(2)
  > span {
  color:
    var(--pharma-text-muted);

  font-size: 9px;
  font-weight: 800;

  letter-spacing:
    0.06em;
}

.pf-pharmacien-alert-card
  div:nth-child(2)
  > strong {
  margin-top: 2px;

  color:
    var(--pharma-text);

  font-size: 19px;
  font-weight: 850;
}

.pf-pharmacien-alert-card
  div:nth-child(2)
  > small {
  margin-top: 1px;

  color:
    var(--pharma-text-muted);

  font-size: 10px;
}

.pf-alert-arrow {
  margin-left: auto;

  color:
    #94a3b8;

  font-size: 15px;
}

/* ---------------------------------------------------------
   SECTIONS
   --------------------------------------------------------- */

.pf-pharmacien-section {
  margin-bottom: 25px;
}

.pf-pharmacien-section-heading {
  margin-bottom: 12px;

  display: flex;
  justify-content: space-between;
  align-items: flex-end;
}

.pf-pharmacien-section-heading
  > div
  > span {
  color:
    var(--pharma-primary);

  font-size: 9px;
  font-weight: 850;

  letter-spacing:
    0.12em;
}

.pf-pharmacien-section-heading h2 {
  margin:
    4px 0 0;

  color:
    var(--pharma-text);

  font-size: 19px;
  font-weight: 800;

  letter-spacing:
    -0.025em;
}

/* ---------------------------------------------------------
   QUICK ACTIONS
   --------------------------------------------------------- */

.pf-pharmacien-actions-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 12px;
}

.pf-pharmacien-action {
  min-height: 92px;

  padding: 15px;

  display: flex;
  align-items: center;

  gap: 12px;

  border:
    1px solid
    var(--pharma-border);

  border-radius: 15px;

  background:
    #ffffff;

  text-align: left;

  cursor: pointer;

  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    border-color 0.18s ease;
}

.pf-pharmacien-action:hover {
  transform:
    translateY(-2px);

  border-color:
    #bcded9;

  box-shadow:
    0 10px 26px
    rgba(15, 23, 42, 0.06);
}

.pf-pharmacien-action.primary {
  border-color:
    #b8ddd8;

  background:
    linear-gradient(
      135deg,
      #f0fbf9,
      #ffffff
    );
}

.pf-pharmacien-action-icon {
  width: 43px;
  height: 43px;

  flex: 0 0 43px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  background:
    #e8f7f4;

  font-size: 19px;
}

.pf-pharmacien-action > div:nth-child(2) {
  min-width: 0;

  flex: 1;

  display: flex;
  flex-direction: column;
}

.pf-pharmacien-action strong {
  color:
    var(--pharma-text);

  font-size: 12px;
}

.pf-pharmacien-action span {
  margin-top: 3px;

  color:
    var(--pharma-text-muted);

  font-size: 10px;
  line-height: 1.35;
}

.pf-pharmacien-action > b {
  color:
    #94a3b8;

  font-size: 15px;
}
/* ---------------------------------------------------------
   MAIN GRID
   --------------------------------------------------------- */

.pf-pharmacien-main-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1.55fr)
    minmax(330px, 0.8fr);

  gap: 16px;

  margin-bottom: 16px;
}

.pf-pharmacien-main-grid > .pf-card {
  min-width: 0;
}

.pf-pharmacien-card-header {
  padding:
    20px 20px 15px;

  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 15px;
}

.pf-pharmacien-card-header > div {
  min-width: 0;
}

.pf-section-kicker {
  display: block;

  color:
    var(--pharma-primary);

  font-size: 9px;
  font-weight: 850;

  letter-spacing:
    0.11em;
}

.pf-pharmacien-card-header h2 {
  margin:
    5px 0 0;

  color:
    var(--pharma-text);

  font-size: 17px;
  font-weight: 800;

  letter-spacing:
    -0.025em;
}

.pf-pharmacien-card-header p {
  margin:
    5px 0 0;

  color:
    var(--pharma-text-muted);

  font-size: 11px;
  line-height: 1.5;
}

.pf-pharmacien-text-button,
.pf-link-button {
  flex-shrink: 0;

  padding:
    7px 0;

  border: 0;

  background: transparent;

  color:
    var(--pharma-primary);

  font-family: inherit;

  font-size: 10px;
  font-weight: 750;

  cursor: pointer;
}

.pf-pharmacien-text-button:hover {
  color:
    var(--pharma-primary-dark);
}

.pf-pharmacien-text-button span {
  margin-left: 5px;
}

/* ---------------------------------------------------------
   TABLE
   --------------------------------------------------------- */

.pf-pharmacien-table-scroll {
  width: 100%;

  overflow-x: auto;

  -webkit-overflow-scrolling: touch;
}

.pf-pharmacien-table {
  width: 100%;

  min-width: 680px;

  border-collapse:
    collapse;
}

.pf-pharmacien-table th {
  padding:
    10px 20px;

  border-top:
    1px solid
    #eef2f3;

  border-bottom:
    1px solid
    #eef2f3;

  background:
    #fafcfc;

  color:
    #94a3b8;

  font-size: 9px;
  font-weight: 800;

  text-transform: uppercase;
  letter-spacing:
    0.06em;

  text-align: left;
}

.pf-pharmacien-table td {
  padding:
    13px 20px;

  border-bottom:
    1px solid
    #f0f3f4;

  color:
    var(--pharma-text-secondary);

  font-size: 11px;

  vertical-align: middle;
}

.pf-pharmacien-table tbody tr {
  transition:
    background 0.15s ease;
}

.pf-pharmacien-table tbody tr:hover {
  background:
    #fbfefe;
}

.pf-align-right {
  text-align: right !important;
}

.pf-sale-reference {
  display: flex;
  align-items: center;

  gap: 7px;
}

.pf-sale-reference-icon {
  width: 25px;
  height: 25px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 8px;

  background:
    #e7f7f4;

  color:
    var(--pharma-primary);

  font-size: 10px;
  font-weight: 850;
}

.pf-sale-reference strong {
  font-size: 11px;
}

.pf-table-primary {
  display: block;

  color:
    var(--pharma-text);

  font-weight: 650;
}

.pf-table-secondary {
  display: block;

  color:
    var(--pharma-text-muted);

  font-size: 10px;
}

.pf-table-primary + .pf-table-secondary {
  margin-top: 2px;
}

.pf-sale-total {
  color:
    var(--pharma-primary);

  white-space: nowrap;
}

/* ---------------------------------------------------------
   STATUS BADGES
   --------------------------------------------------------- */

.pf-status-badge {
  display: inline-flex;
  align-items: center;

  gap: 5px;

  padding:
    5px 8px;

  border-radius: 999px;

  font-size: 9px;
  font-weight: 750;

  white-space: nowrap;
}

.pf-status-badge > span {
  width: 5px;
  height: 5px;

  border-radius: 50%;
}

.pf-status-badge.success {
  background:
    #ecfdf3;

  color:
    #15803d;
}

.pf-status-badge.success > span {
  background:
    #22c55e;
}

.pf-status-badge.warning {
  background:
    #fff7ed;

  color:
    #b45309;
}

.pf-status-badge.warning > span {
  background:
    #f59e0b;
}

.pf-status-badge.danger {
  background:
    #fef2f2;

  color:
    #dc2626;
}

.pf-status-badge.danger > span {
  background:
    #ef4444;
}

.pf-status-badge.orange {
  background:
    #fff7ed;

  color:
    #c2410c;
}

/* ---------------------------------------------------------
   PERFORMANCE
   --------------------------------------------------------- */

.pf-pharmacien-performance-card {
  overflow: hidden;
}

.pf-performance-round-icon {
  width: 36px;
  height: 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  background:
    #e7f7f4;
}

.pf-performance-big {
  margin:
    3px 20px 20px;

  padding:
    17px;

  border:
    1px solid
    #dcefeb;

  border-radius: 14px;

  background:
    linear-gradient(
      135deg,
      #f2fbfa,
      #ffffff
    );
}

.pf-performance-big span {
  display: block;

  color:
    var(--pharma-text-muted);

  font-size: 10px;
  font-weight: 650;
}

.pf-performance-big strong {
  display: block;

  margin-top: 7px;

  color:
    var(--pharma-primary-dark);

  font-size: 25px;
  font-weight: 850;

  letter-spacing:
    -0.04em;
}

.pf-performance-big small {
  display: block;

  margin-top: 4px;

  color:
    var(--pharma-text-muted);

  font-size: 10px;
}

.pf-performance-bars {
  padding:
    0 20px 15px;
}

.pf-performance-bar-item {
  margin-bottom: 15px;
}

.pf-performance-bar-item:last-child {
  margin-bottom: 0;
}

.pf-performance-bar-item > div:first-child {
  margin-bottom: 6px;

  display: flex;
  justify-content: space-between;

  gap: 10px;
}

.pf-performance-bar-item span {
  color:
    var(--pharma-text-muted);

  font-size: 10px;
}

.pf-performance-bar-item strong {
  color:
    var(--pharma-text-secondary);

  font-size: 10px;
}

.pf-performance-track {
  width: 100%;
  height: 6px;

  overflow: hidden;

  border-radius: 999px;

  background:
    #eef2f3;
}

.pf-performance-fill {
  height: 100%;

  border-radius: inherit;

  background:
    var(--pharma-primary);

  transition:
    width 0.5s ease;
}

.pf-performance-fill.info {
  background:
    #3b82f6;
}

.pf-performance-fill.success {
  background:
    #22c55e;
}

.pf-performance-report-button {
  width: calc(100% - 40px);

  margin:
    5px 20px 20px;

  padding:
    11px 12px;

  display: flex;
  justify-content: space-between;
  align-items: center;

  border:
    1px solid
    #d8ece9;

  border-radius: 10px;

  background:
    #f7fcfb;

  color:
    var(--pharma-primary);

  font-family: inherit;

  font-size: 10px;
  font-weight: 750;

  cursor: pointer;

  transition:
    background 0.18s ease;
}

.pf-performance-report-button:hover {
  background:
    #eaf8f5;
}

/* ---------------------------------------------------------
   STOCK / EXPIRATION LIST
   --------------------------------------------------------- */

.pf-pharmacien-alert-list {
  padding:
    0 20px 15px;
}

.pf-pharmacien-alert-row {
  width: 100%;

  padding:
    11px 0;

  display: flex;
  align-items: center;

  gap: 10px;

  border: 0;
  border-bottom:
    1px solid
    #f0f3f4;

  background: transparent;

  font-family: inherit;

  text-align: left;

  cursor: pointer;
}

.pf-pharmacien-alert-row:last-child {
  border-bottom: 0;
}

.pf-pharmacien-alert-row:hover
  .pf-pharmacien-alert-details
  strong {
  color:
    var(--pharma-primary);
}

.pf-pharmacien-alert-symbol {
  width: 31px;
  height: 31px;

  flex: 0 0 31px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  font-size: 12px;
  font-weight: 900;
}

.pf-pharmacien-alert-symbol.warning {
  background:
    #fff7ed;

  color:
    #b45309;
}

.pf-pharmacien-alert-symbol.danger {
  background:
    #fef2f2;

  color:
    #dc2626;
}

.pf-pharmacien-alert-symbol.orange {
  background:
    #fff7ed;

  color:
    #c2410c;
}

.pf-pharmacien-alert-details {
  min-width: 0;

  flex: 1;

  display: flex;
  flex-direction: column;
}

.pf-pharmacien-alert-details strong {
  overflow: hidden;

  color:
    var(--pharma-text);

  font-size: 11px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.pf-pharmacien-alert-details span {
  margin-top: 2px;

  overflow: hidden;

  color:
    var(--pharma-text-muted);

  font-size: 9px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.pf-pharmacien-row-arrow {
  color:
    #cbd5e1;

  font-size: 14px;
}

/* ---------------------------------------------------------
   EMPTY / SUCCESS
   --------------------------------------------------------- */

.pf-pharmacien-empty {
  padding:
    40px 20px;

  text-align: center;
}

.pf-pharmacien-empty-icon {
  width: 48px;
  height: 48px;

  margin:
    0 auto 12px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;

  background:
    #f1f5f9;

  font-size: 21px;
}

.pf-pharmacien-empty h3 {
  margin: 0;

  color:
    var(--pharma-text);

  font-size: 14px;
  font-weight: 750;
}

.pf-pharmacien-empty p {
  max-width: 360px;

  margin:
    6px auto 15px;

  color:
    var(--pharma-text-muted);

  font-size: 11px;
  line-height: 1.5;
}

.pf-pharmacien-success-state {
  margin:
    5px 20px 20px;

  padding: 17px;

  display: flex;
  align-items: center;

  gap: 11px;

  border:
    1px solid
    #d9f0df;

  border-radius: 13px;

  background:
    #f5fcf7;
}

.pf-pharmacien-success-icon {
  width: 34px;
  height: 34px;

  flex: 0 0 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  background:
    #dcfce7;

  color:
    #15803d;

  font-weight: 900;
}

.pf-pharmacien-success-state div:last-child {
  display: flex;
  flex-direction: column;
}

.pf-pharmacien-success-state strong {
  color:
    #166534;

  font-size: 11px;
}

.pf-pharmacien-success-state span {
  margin-top: 2px;

  color:
    #64748b;

  font-size: 9px;
}

/* ---------------------------------------------------------
   MOVEMENTS
   --------------------------------------------------------- */

.pf-pharmacien-movements-card {
  margin-bottom: 20px;
}

.pf-product-table-cell {
  display: flex;
  align-items: center;

  gap: 8px;
}

.pf-product-mini-icon {
  width: 29px;
  height: 29px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 8px;

  background:
    #f0f7f6;

  font-size: 13px;
}

.pf-reference-pill {
  display: inline-block;

  max-width: 130px;

  padding:
    4px 7px;

  overflow: hidden;

  border-radius: 6px;

  background:
    #f8fafc;

  color:
    #64748b;

  font-size: 9px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

/* ---------------------------------------------------------
   SUMMARY
   --------------------------------------------------------- */

.pf-pharmacien-summary-section {
  margin-bottom: 18px;
}

.pf-pharmacien-summary-heading {
  margin-bottom: 12px;

  display: flex;
  justify-content: space-between;
  align-items: flex-end;

  gap: 15px;
}

.pf-pharmacien-summary-heading > div > span {
  color:
    var(--pharma-primary);

  font-size: 9px;
  font-weight: 850;

  letter-spacing:
    0.11em;
}

.pf-pharmacien-summary-heading h2 {
  margin:
    4px 0 0;

  color:
    var(--pharma-text);

  font-size: 18px;
  font-weight: 800;
}

.pf-pharmacien-secure-label {
  padding:
    6px 9px;

  border-radius: 999px;

  background:
    #f0fdf4;

  color:
    #15803d;

  font-size: 9px;
  font-weight: 700;
}

.pf-pharmacien-summary-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 12px;
}

.pf-pharmacien-summary-card {
  padding: 17px;

  border:
    1px solid
    var(--pharma-border);

  border-radius: 14px;

  background:
    #ffffff;
}

.pf-pharmacien-summary-card span {
  display: block;

  color:
    var(--pharma-text-muted);

  font-size: 10px;
}

.pf-pharmacien-summary-card strong {
  display: block;

  margin-top: 7px;

  color:
    var(--pharma-text);

  font-size: 20px;
  font-weight: 850;

  letter-spacing:
    -0.035em;

  overflow-wrap: anywhere;
}

.pf-pharmacien-summary-card small {
  display: block;

  margin-top: 3px;

  color:
    #94a3b8;

  font-size: 9px;
}

/* ---------------------------------------------------------
   SECURITY
   --------------------------------------------------------- */

.pf-pharmacien-security {
  margin-bottom: 25px;

  padding:
    15px 18px;

  display: flex;
  align-items: center;

  gap: 12px;

  border:
    1px solid
    #dcefeb;

  border-radius: 14px;

  background:
    linear-gradient(
      135deg,
      #f4fbfa,
      #ffffff
    );
}

.pf-pharmacien-security-icon {
  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  background:
    #e5f6f3;

  font-size: 18px;
}

.pf-pharmacien-security > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.pf-pharmacien-security strong {
  color:
    var(--pharma-text);

  font-size: 11px;
}

.pf-pharmacien-security p {
  margin:
    3px 0 0;

  color:
    var(--pharma-text-muted);

  font-size: 9px;
  line-height: 1.5;
}

.pf-pharmacien-security-status {
  padding:
    6px 9px;

  display: flex;
  align-items: center;

  gap: 6px;

  border-radius: 999px;

  background:
    #f0fdf4;

  color:
    #15803d;

  font-size: 9px;
  font-weight: 700;

  white-space: nowrap;
}

.pf-pharmacien-security-status span {
  width: 5px;
  height: 5px;

  border-radius: 50%;

  background:
    #22c55e;
}

/* ---------------------------------------------------------
   LOADING
   --------------------------------------------------------- */

.pf-pharmacien-loading {
  min-height: 260px;

  display: flex;
  flex-direction: column;

  align-items: center;
  justify-content: center;

  padding: 25px;

  text-align: center;
}

.pf-pharmacien-loading strong {
  margin-top: 15px;

  color:
    var(--pharma-text);

  font-size: 14px;
}

.pf-pharmacien-loading span {
  margin-top: 5px;

  color:
    var(--pharma-text-muted);

  font-size: 10px;
}

.pf-pharmacien-skeleton {
  display: flex;
  flex-direction: column;

  gap: 15px;
}

.pf-skeleton-wide {
  height: 190px !important;
}

.pf-skeleton-large {
  height: 430px !important;
}

/* ---------------------------------------------------------
   ERROR
   --------------------------------------------------------- */

.pf-pharmacien-error {
  padding: 25px;

  display: flex;
  align-items: flex-start;

  gap: 15px;

  border:
    1px solid
    #fecaca;

  border-radius: 16px;

  background:
    #fffafa;
}

.pf-pharmacien-error-icon {
  width: 40px;
  height: 40px;

  flex: 0 0 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  background:
    #fee2e2;

  color:
    #dc2626;

  font-size: 18px;
  font-weight: 900;
}

.pf-pharmacien-error h1 {
  margin:
    4px 0 7px;

  color:
    #991b1b;

  font-size: 18px;
}

.pf-pharmacien-error p {
  margin: 0;

  color:
    #7f1d1d;

  font-size: 11px;
  line-height: 1.55;

  word-break: break-word;
}

.pf-pharmacien-error-actions {
  margin-top: 15px;

  display: flex;

  gap: 10px;

  flex-wrap: wrap;
}

/* ---------------------------------------------------------
   SIDEBAR MOBILE CLOSE
   --------------------------------------------------------- */

.pf-pharmacien-sidebar-close {
  display: none;

  margin-left: auto;

  width: 34px;
  height: 34px;

  border: 0;
  border-radius: 9px;

  background:
    #f1f5f9;

  color:
    #475569;

  font-size: 20px;

  cursor: pointer;
}

/* ---------------------------------------------------------
   MOBILE
   --------------------------------------------------------- */

@media (max-width: 1200px) {

  .pf-pharmacien-kpi-grid,
  .pf-pharmacien-alert-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-pharmacien-actions-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-pharmacien-summary-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-pharmacien-main-grid {
    grid-template-columns:
      minmax(0, 1fr);
  }
}

@media (max-width: 900px) {

  .pf-pharmacien-sidebar {
    transform:
      translateX(-100%);

    transition:
      transform 0.25s ease;

    box-shadow:
      15px 0 40px
      rgba(15, 23, 42, 0.15);
  }

  .pf-pharmacien-sidebar.pf-sidebar-open {
    transform:
      translateX(0);
  }

  .pf-pharmacien-sidebar-close {
    display: flex;

    align-items: center;
    justify-content: center;
  }

  .pf-pharmacien-app
    .pf-main {
    margin-left: 0;
  }

  .pf-pharmacien-topbar {
    padding:
      0 15px;
  }

  .pf-mobile-menu-button {
    display: flex !important;
  }

  .pf-pharmacien-hero {
    padding:
      23px;

    align-items: flex-start;

    flex-direction: column;
  }

  .pf-pharmacien-hero-actions {
    width: 100%;

    display: grid;

    grid-template-columns:
      repeat(2, minmax(0, 1fr));

    min-width: 0;
  }

  .pf-pharmacien-refresh {
    grid-column:
      1 / -1;
  }

  .pf-topbar-date {
    display: none;
  }
}

@media (max-width: 680px) {

  .pf-pharmacien-kpi-grid,
  .pf-pharmacien-alert-grid,
  .pf-pharmacien-actions-grid,
  .pf-pharmacien-summary-grid {
    grid-template-columns: 1fr;
  }

  .pf-content {
    padding:
      14px !important;
  }

  .pf-container {
    padding:
      0 !important;
  }

  .pf-pharmacien-hero {
    padding:
      21px 18px;

    border-radius: 17px;
  }

  .pf-pharmacien-hero h1 {
    font-size: 25px;
  }

  .pf-pharmacien-hero p {
    font-size: 11px;
  }

  .pf-pharmacien-hero-actions {
    grid-template-columns: 1fr;
  }

  .pf-pharmacien-refresh {
    grid-column: auto;
  }

  .pf-pharmacien-kpi {
    padding: 16px;
  }

  .pf-pharmacien-kpi > strong {
    font-size: 23px;
  }

  .pf-pharmacien-alert-card {
    padding: 14px;
  }

  .pf-pharmacien-card-header {
    padding:
      17px 15px 13px;

    flex-direction: column;
  }

  .pf-pharmacien-text-button {
    padding: 0;
  }

  .pf-pharmacien-table {
    min-width: 690px;
  }

  .pf-pharmacien-security {
    align-items: flex-start;

    flex-wrap: wrap;
  }

  .pf-pharmacien-security-status {
    margin-left: 50px;
  }

  .pf-performance-big {
    margin-left: 15px;
    margin-right: 15px;
  }

  .pf-performance-bars {
    padding-left: 15px;
    padding-right: 15px;
  }

  .pf-performance-report-button {
    width: calc(100% - 30px);

    margin-left: 15px;
    margin-right: 15px;
  }
}

@media (max-width: 420px) {

  .pf-topbar-page-title {
    font-size: 14px;
  }

  .pf-topbar-page-subtitle {
    font-size: 10px;
  }

  .pf-topbar-profile
    div:last-child {
    display: none;
  }

  .pf-pharmacien-hero-meta {
    gap: 5px;
  }

  .pf-pharmacien-hero-meta span {
    font-size: 9px;
  }

  .pf-pharmacien-kpi-head
    > span {
    font-size: 8px;
  }

  .pf-pharmacien-summary-card strong {
    font-size: 19px;
  }
}

/* ---------------------------------------------------------
   ACCESSIBILITÉ / TOUCH
   --------------------------------------------------------- */

.pf-pharmacien-app
  button:focus-visible {
  outline:
    3px solid
    rgba(15, 118, 110, 0.22);

  outline-offset: 2px;
}

.pf-pharmacien-app
  button:disabled {
  opacity: 0.6;

  cursor: not-allowed;
}

/* ---------------------------------------------------------
   PRINT
   --------------------------------------------------------- */

@media print {

  .pf-pharmacien-sidebar,
  .pf-pharmacien-topbar,
  .pf-pharmacien-hero-actions,
  .pf-mobile-menu-button,
  .pf-pharmacien-text-button,
  .pf-link-button,
  .pf-performance-report-button {
    display: none !important;
  }

  .pf-pharmacien-app
    .pf-main {
    margin-left: 0 !important;

    width: 100% !important;
  }

  .pf-pharmacien-hero {
    background:
      #ffffff !important;

    color:
      #000000 !important;

    box-shadow: none !important;

    border:
      1px solid
      #dddddd !important;
  }

  .pf-pharmacien-hero h1,
  .pf-pharmacien-hero p,
  .pf-pharmacien-hero-meta span {
    color:
      #000000 !important;
  }

  .pf-pharmacien-kpi,
  .pf-card,
  .pf-pharmacien-summary-card {
    box-shadow: none !important;

    break-inside: avoid;
  }

  .pf-pharmacien-main-grid {
    grid-template-columns:
      1fr 1fr;
  }

  .pf-pharmacien-kpi-grid {
    grid-template-columns:
      repeat(4, 1fr);
  }

  .pf-pharmacien-alert-grid {
    grid-template-columns:
      repeat(4, 1fr);
  }
}
/* =========================================================
   PHARMAFLOW — RAPPORTS PHARMACIEN
   ========================================================= */

.pf-report-app {
  min-height: 100vh;
  display: flex;
  background: #f5f8f8;
  color: #0f172a;
}

/* SIDEBAR */

.pf-report-sidebar {
  width: 270px;
  min-height: 100vh;
  position: fixed;
  left: 0;
  top: 0;
  bottom: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  background: #ffffff;
  border-right: 1px solid #e2e8f0;
}

.pf-report-brand {
  height: 76px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 22px;
  border-bottom: 1px solid #e2e8f0;
}

.pf-report-brand-mark {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #0f766e;
  color: #ffffff;
  font-size: 26px;
  font-weight: 800;
}

.pf-report-brand strong {
  display: block;
  color: #0f172a;
  font-size: 18px;
  line-height: 1.2;
}

.pf-report-brand span {
  display: block;
  margin-top: 3px;
  color: #64748b;
  font-size: 11px;
}

/* PHARMACY CARD */

.pf-report-pharmacy {
  margin: 18px 16px 10px;
  padding: 13px;
  display: flex;
  align-items: center;
  gap: 11px;
  border: 1px solid #dcebe8;
  border-radius: 13px;
  background: #f3faf8;
}

.pf-report-pharmacy-icon {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: #ffffff;
  font-size: 18px;
}

.pf-report-pharmacy small {
  display: block;
  margin-bottom: 3px;
  color: #64748b;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pf-report-pharmacy strong {
  display: block;
  max-width: 165px;
  overflow: hidden;
  color: #0f172a;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* NAVIGATION */

.pf-report-nav {
  flex: 1;
  padding: 10px 12px;
  overflow-y: auto;
}

.pf-report-nav-title {
  margin: 18px 10px 8px;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.09em;
}

.pf-report-nav-title:first-child {
  margin-top: 8px;
}

.pf-report-nav-item {
  width: 100%;
  min-height: 44px;
  margin-bottom: 3px;
  padding: 0 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #475569;
  cursor: pointer;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  transition:
    background 0.18s ease,
    color 0.18s ease,
    transform 0.18s ease;
}

.pf-report-nav-item span {
  width: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
  font-size: 17px;
}

.pf-report-nav-item:hover {
  background: #f0f8f6;
  color: #0f766e;
}

.pf-report-nav-item:hover span {
  color: #0f766e;
}

.pf-report-nav-item.active {
  background: #e6f5f2;
  color: #0f766e;
}

.pf-report-nav-item.active span {
  color: #0f766e;
}

/* SIDEBAR USER */

.pf-report-sidebar-bottom {
  padding: 14px;
  border-top: 1px solid #e2e8f0;
}

.pf-report-user {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px;
}

.pf-report-avatar {
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #0f766e;
  color: #ffffff;
  font-size: 14px;
  font-weight: 800;
}

.pf-report-user strong {
  display: block;
  max-width: 160px;
  overflow: hidden;
  color: #0f172a;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-report-user span {
  display: block;
  margin-top: 2px;
  color: #64748b;
  font-size: 11px;
}

.pf-report-logout {
  width: 100%;
  margin-top: 8px;
  padding: 9px 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #64748b;
  cursor: pointer;
  font-family: inherit;
  font-size: 12px;
  font-weight: 600;
  text-align: left;
}

.pf-report-logout:hover {
  background: #fff1f2;
  color: #be123c;
}

/* MAIN */

.pf-report-main {
  width: calc(100% - 270px);
  min-height: 100vh;
  margin-left: 270px;
}

/* HEADER */

.pf-report-header {
  min-height: 76px;
  padding: 18px 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  background: #ffffff;
  border-bottom: 1px solid #e2e8f0;
}

.pf-report-breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 5px;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 600;
}

.pf-report-breadcrumb span {
  color: #cbd5e1;
}

.pf-report-header h1 {
  margin: 0;
  color: #0f172a;
  font-size: 25px;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.pf-report-header p {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 13px;
}

.pf-report-header-actions {
  display: flex;
  align-items: center;
  gap: 9px;
}

/* BUTTONS */

.pf-report-btn {
  min-height: 40px;
  padding: 0 15px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border-radius: 9px;
  cursor: pointer;
  font-family: inherit;
  font-size: 12px;
  font-weight: 700;
  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.18s ease;
}

.pf-report-btn:hover {
  transform: translateY(-1px);
}

.pf-report-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.pf-report-btn-primary {
  border: 1px solid #0f766e;
  background: #0f766e;
  color: #ffffff;
}

.pf-report-btn-primary:hover {
  background: #115e59;
}

.pf-report-btn-secondary {
  border: 1px solid #dbe3e8;
  background: #ffffff;
  color: #334155;
}

.pf-report-btn-secondary:hover {
  border-color: #b8d7d2;
  background: #f8fbfb;
  color: #0f766e;
}

/* CONTENT */

.pf-report-content {
  max-width: 1500px;
  margin: 0 auto;
  padding: 28px 34px 40px;
}

/* PERIOD CARD */

.pf-report-period-card {
  margin-bottom: 20px;
  padding: 21px 23px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border: 1px solid #dfe8e7;
  border-radius: 15px;
  background: #ffffff;
  box-shadow: 0 3px 12px rgba(15, 23, 42, 0.025);
}

.pf-report-section-label {
  display: block;
  color: #0f766e;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.pf-report-period-card h2 {
  margin: 5px 0 0;
  color: #0f172a;
  font-size: 19px;
  font-weight: 800;
}

.pf-report-period-card p {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 12px;
}

.pf-report-period-tabs {
  padding: 4px;
  display: flex;
  align-items: center;
  gap: 3px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #f8fafc;
}

.pf-report-period-tabs button {
  min-height: 35px;
  padding: 0 13px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: #64748b;
  cursor: pointer;
  font-family: inherit;
  font-size: 11px;
  font-weight: 700;
}

.pf-report-period-tabs button:hover {
  color: #0f766e;
}

.pf-report-period-tabs button.active {
  background: #ffffff;
  color: #0f766e;
  box-shadow: 0 1px 4px rgba(15, 23, 42, 0.08);
}

/* STATS */

.pf-report-stats-grid {
  margin-bottom: 20px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.pf-report-stat-card {
  min-height: 112px;
  padding: 17px;
  display: flex;
  align-items: center;
  gap: 13px;
  border: 1px solid #e1e8eb;
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 3px 12px rgba(15, 23, 42, 0.025);
}

.pf-report-stat-icon {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  font-size: 19px;
  font-weight: 800;
}

.pf-report-stat-icon.revenue {
  background: #e6f5f2;
  color: #0f766e;
}

.pf-report-stat-icon.sales {
  background: #eff6ff;
  color: #2563eb;
}

.pf-report-stat-icon.products {
  background: #f5f3ff;
  color: #7c3aed;
}

.pf-report-stat-icon.average {
  background: #fff7ed;
  color: #ea580c;
}

.pf-report-stat-card span {
  display: block;
  color: #64748b;
  font-size: 11px;
}

.pf-report-stat-card strong {
  display: block;
  margin-top: 4px;
  color: #0f172a;
  font-size: 20px;
  font-weight: 800;
  line-height: 1.15;
}

.pf-report-stat-card small {
  display: block;
  margin-top: 5px;
  color: #94a3b8;
  font-size: 10px;
}

/* TWO COLUMNS */

.pf-report-grid-two {
  margin-bottom: 20px;
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
  gap: 20px;
}

/* PANEL */

.pf-report-panel {
  min-width: 0;
  border: 1px solid #e1e8eb;
  border-radius: 15px;
  background: #ffffff;
  box-shadow: 0 3px 12px rgba(15, 23, 42, 0.025);
  overflow: hidden;
}

.pf-report-full-panel {
  margin-bottom: 20px;
}

.pf-report-panel-header {
  min-height: 68px;
  padding: 16px 19px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-bottom: 1px solid #edf1f3;
}

.pf-report-panel-header h2 {
  margin: 4px 0 0;
  color: #0f172a;
  font-size: 15px;
  font-weight: 800;
}

.pf-report-panel-count {
  padding: 5px 9px;
  border-radius: 7px;
  background: #f1f5f9;
  color: #64748b;
  font-size: 10px;
  font-weight: 700;
}

/* PRODUCT LIST */

.pf-report-product-list {
  padding: 5px 18px;
}

.pf-report-product-row {
  min-height: 64px;
  display: flex;
  align-items: center;
  gap: 11px;
  border-bottom: 1px solid #f0f3f5;
}

.pf-report-product-row:last-child {
  border-bottom: 0;
}

.pf-report-rank {
  width: 27px;
  height: 27px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: #f1f5f9;
  color: #475569;
  font-size: 11px;
  font-weight: 800;
}

.pf-report-product-info {
  min-width: 0;
  flex: 1;
}

.pf-report-product-info strong {
  display: block;
  overflow: hidden;
  color: #0f172a;
  font-size: 12px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-report-product-info span {
  display: block;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-report-product-revenue {
  color: #0f766e;
  font-size: 12px;
  white-space: nowrap;
}

/* STOCK SUMMARY */

.pf-report-stock-summary {
  padding: 19px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.pf-report-stock-summary > div {
  min-height: 90px;
  padding: 13px;
  border: 1px solid #edf1f3;
  border-radius: 11px;
  background: #fafcfc;
}

.pf-report-stock-summary span {
  display: block;
  margin-bottom: 7px;
  font-size: 12px;
}

.pf-report-stock-summary span.success {
  color: #16a34a;
}

.pf-report-stock-summary span.warning {
  color: #d97706;
}

.pf-report-stock-summary span.danger {
  color: #dc2626;
}

.pf-report-stock-summary span.info {
  color: #2563eb;
}

.pf-report-stock-summary strong {
  display: block;
  color: #0f172a;
  font-size: 22px;
  font-weight: 800;
}

.pf-report-stock-summary small {
  display: block;
  margin-top: 3px;
  color: #64748b;
  font-size: 10px;
}

/* TABLE */

.pf-report-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.pf-report-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 700px;
}

.pf-report-table th {
  padding: 12px 18px;
  border-bottom: 1px solid #e8edef;
  background: #fafcfc;
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.pf-report-table td {
  padding: 14px 18px;
  border-bottom: 1px solid #f0f3f5;
  color: #475569;
  font-size: 12px;
}

.pf-report-table tbody tr:last-child td {
  border-bottom: 0;
}

.pf-report-table tbody tr:hover {
  background: #fbfdfd;
}

.pf-report-table td strong {
  color: #0f172a;
  font-weight: 700;
}

.text-right {
  text-align: right !important;
}

/* STATUS */

.pf-report-status {
  padding: 4px 8px;
  display: inline-flex;
  align-items: center;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 700;
}

.pf-report-status.success {
  background: #ecfdf3;
  color: #15803d;
}

/* EMPTY */

.pf-report-empty {
  min-height: 170px;
  padding: 28px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.pf-report-empty > div {
  width: 43px;
  height: 43px;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: #f1f5f9;
  color: #64748b;
  font-size: 18px;
}

.pf-report-empty strong {
  color: #334155;
  font-size: 13px;
}

.pf-report-empty span {
  max-width: 300px;
  margin-top: 5px;
  color: #94a3b8;
  font-size: 11px;
  line-height: 1.5;
}

/* ALERTS */

.pf-report-alert-list {
  padding: 5px 18px;
}

.pf-report-alert-row {
  min-height: 61px;
  padding: 9px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid #f0f3f5;
}

.pf-report-alert-row:last-child {
  border-bottom: 0;
}

.pf-report-alert-row > div {
  min-width: 0;
}

.pf-report-alert-row strong {
  display: block;
  overflow: hidden;
  color: #334155;
  font-size: 12px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-report-alert-row span {
  display: block;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-report-alert-row > strong {
  flex-shrink: 0;
  font-size: 11px;
}

.danger-text {
  color: #dc2626 !important;
}

.warning-text {
  color: #d97706 !important;
}

.pf-report-alert-row.expired {
  background: #fffafa;
}

/* GOOD STATE */

.pf-report-good-state {
  min-height: 150px;
  padding: 24px;
  display: flex;
  align-items: center;
  gap: 13px;
}

.pf-report-good-state > span {
  width: 39px;
  height: 39px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #ecfdf3;
  color: #16a34a;
  font-size: 18px;
  font-weight: 800;
}

.pf-report-good-state strong {
  display: block;
  color: #334155;
  font-size: 13px;
}

.pf-report-good-state p {
  margin: 4px 0 0;
  color: #94a3b8;
  font-size: 11px;
  line-height: 1.5;
}

/* FINANCIAL SUMMARY */

.pf-report-summary-card {
  margin-bottom: 20px;
  padding: 22px;
  border: 1px solid #cfe4e0;
  border-radius: 15px;
  background: linear-gradient(
    135deg,
    #f2fbf9 0%,
    #ffffff 100%
  );
}

.pf-report-summary-card h2 {
  margin: 4px 0 0;
  color: #0f172a;
  font-size: 17px;
  font-weight: 800;
}

.pf-report-summary-values {
  margin-top: 19px;
  padding-top: 17px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 15px;
  border-top: 1px solid #dcebe8;
}

.pf-report-summary-values > div {
  min-width: 0;
}

.pf-report-summary-values span {
  display: block;
  color: #64748b;
  font-size: 10px;
}

.pf-report-summary-values strong {
  display: block;
  margin-top: 5px;
  color: #0f172a;
  font-size: 16px;
  font-weight: 800;
}

/* FOOTER */

.pf-report-footer {
  padding: 17px 2px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-report-footer strong {
  display: block;
  color: #475569;
  font-size: 11px;
}

.pf-report-footer span {
  display: block;
  margin-top: 2px;
}

/* LOADING */

.pf-report-loading {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #f5f8f8;
  text-align: center;
}

.pf-report-spinner {
  width: 42px;
  height: 42px;
  margin-bottom: 17px;
  border: 3px solid #dcebe8;
  border-top-color: #0f766e;
  border-radius: 50%;
  animation: pf-report-spin 0.8s linear infinite;
}

@keyframes pf-report-spin {
  to {
    transform: rotate(360deg);
  }
}

.pf-report-loading h2 {
  margin: 0;
  color: #334155;
  font-size: 16px;
}

.pf-report-loading p {
  margin: 6px 0 0;
  color: #94a3b8;
  font-size: 12px;
}

/* ERROR */

.pf-report-error-page {
  min-height: 100vh;
  padding: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f5f8f8;
}

.pf-report-error-card {
  width: min(100%, 500px);
  padding: 30px;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 8px 30px rgba(15, 23, 42, 0.07);
  text-align: center;
}

.pf-report-error-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #fff1f2;
  color: #dc2626;
  font-size: 22px;
  font-weight: 800;
}

.pf-report-error-card h1 {
  margin: 0;
  color: #0f172a;
  font-size: 19px;
  font-weight: 800;
}

.pf-report-error-card p {
  margin: 9px 0 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.6;
}

.pf-report-error-actions {
  margin-top: 21px;
  display: flex;
  justify-content: center;
  gap: 9px;
}

/* RESPONSIVE */

@media (max-width: 1200px) {
  .pf-report-stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pf-report-grid-two {
    grid-template-columns: 1fr;
  }

  .pf-report-summary-values {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .pf-report-sidebar {
    width: 225px;
  }

  .pf-report-main {
    width: calc(100% - 225px);
    margin-left: 225px;
  }

  .pf-report-header {
    padding: 18px 22px;
  }

  .pf-report-content {
    padding: 22px;
  }

  .pf-report-header-actions {
    flex-shrink: 0;
  }
}

@media (max-width: 720px) {
  .pf-report-sidebar {
    width: 100%;
    height: auto;
    min-height: 0;
    position: relative;
    border-right: 0;
    border-bottom: 1px solid #e2e8f0;
  }

  .pf-report-app {
    display: block;
  }

  .pf-report-brand {
    height: 68px;
  }

  .pf-report-nav {
    max-height: none;
  }

  .pf-report-sidebar-bottom {
    display: none;
  }

  .pf-report-main {
    width: 100%;
    margin-left: 0;
  }

  .pf-report-header {
    padding: 20px 16px;
    flex-direction: column;
    align-items: flex-start;
  }

  .pf-report-header-actions {
    width: 100%;
  }

  .pf-report-header-actions .pf-report-btn {
    flex: 1;
  }

  .pf-report-content {
    padding: 16px;
  }

  .pf-report-period-card {
    align-items: flex-start;
    flex-direction: column;
    padding: 17px;
  }

  .pf-report-period-tabs {
    width: 100%;
    overflow-x: auto;
  }

  .pf-report-period-tabs button {
    flex: 1;
    white-space: nowrap;
  }

  .pf-report-stats-grid {
    grid-template-columns: 1fr;
  }

  .pf-report-summary-values {
    grid-template-columns: 1fr 1fr;
  }

  .pf-report-footer {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 480px) {
  .pf-report-header h1 {
    font-size: 21px;
  }

  .pf-report-header p {
    font-size: 11px;
  }

  .pf-report-header-actions {
    flex-direction: column;
  }

  .pf-report-header-actions .pf-report-btn {
    width: 100%;
  }

  .pf-report-period-tabs button {
    padding: 0 10px;
    font-size: 10px;
  }

  .pf-report-stock-summary {
    grid-template-columns: 1fr 1fr;
    padding: 14px;
  }

  .pf-report-summary-values {
    grid-template-columns: 1fr;
  }

  .pf-report-error-actions {
    flex-direction: column;
  }

  .pf-report-error-actions .pf-report-btn {
    width: 100%;
  }
}

/* IMPRESSION */

@media print {
  .pf-report-sidebar,
  .pf-report-header-actions,
  .pf-report-period-tabs {
    display: none !important;
  }

  .pf-report-app {
    display: block;
    min-height: auto;
    background: #ffffff;
  }

  .pf-report-main {
    width: 100%;
    margin: 0;
  }

  .pf-report-header {
    padding: 15px 0;
    border-bottom: 1px solid #cbd5e1;
  }

  .pf-report-content {
    max-width: none;
    padding: 15px 0;
  }

  .pf-report-panel,
  .pf-report-period-card,
  .pf-report-stat-card,
  .pf-report-summary-card {
    box-shadow: none;
    break-inside: avoid;
  }

  .pf-report-grid-two {
    break-inside: avoid;
  }

  .pf-report-footer {
    border-top: 1px solid #cbd5e1;
  }
}
/* =========================================================
   PHARMAFLOW — ESPACE PHARMACIEN — PAIEMENTS
   ========================================================= */

.pf-payment-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
}

.pf-payment-page-header h1 {
  margin: 6px 0 8px;
  font-size: 32px;
  line-height: 1.15;
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -0.03em;
}

.pf-payment-page-header p {
  margin: 0;
  max-width: 720px;
  color: #64748b;
  font-size: 15px;
  line-height: 1.7;
}

.pf-payment-header-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.pf-payment-pharmacy-banner {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 22px;
  margin-bottom: 20px;
  border: 1px solid #dce8e6;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 5px 20px rgba(15, 118, 110, 0.05);
}

.pf-payment-pharmacy-icon {
  width: 52px;
  height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 15px;
  background: #e6f5f2;
  font-size: 25px;
  flex: 0 0 auto;
}

.pf-payment-pharmacy-banner > div:nth-child(2) {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.pf-payment-pharmacy-banner > div:nth-child(2) span {
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.pf-payment-pharmacy-banner > div:nth-child(2) strong {
  color: #0f172a;
  font-size: 17px;
  font-weight: 800;
}

.pf-payment-pharmacy-banner > div:nth-child(2) small {
  color: #64748b;
  font-size: 12px;
}

.pf-payment-security {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 13px;
  border-radius: 999px;
  background: #f0fdf4;
  color: #15803d;
  font-size: 12px;
  font-weight: 700;
}

.pf-payment-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 20px;
}

.pf-payment-kpi {
  display: flex;
  align-items: center;
  gap: 15px;
  min-height: 125px;
  padding: 20px;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 5px 20px rgba(15, 23, 42, 0.035);
}

.pf-payment-kpi-icon {
  width: 50px;
  height: 50px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 15px;
  font-size: 23px;
}

.pf-payment-kpi-icon.primary {
  background: #e6f5f2;
}

.pf-payment-kpi-icon.info {
  background: #eff6ff;
}

.pf-payment-kpi-icon.success {
  background: #f0fdf4;
}

.pf-payment-kpi-icon.warning {
  background: #fffbeb;
}

.pf-payment-kpi > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-payment-kpi > div:last-child > span {
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.pf-payment-kpi > div:last-child > strong {
  margin-top: 4px;
  color: #0f172a;
  font-size: 22px;
  line-height: 1.2;
  font-weight: 800;
}

.pf-payment-kpi > div:last-child > small {
  margin-top: 5px;
  color: #94a3b8;
  font-size: 11px;
}

.pf-payment-performance-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 20px;
  margin-bottom: 20px;
}

.pf-payment-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 24px 24px 0;
}

.pf-payment-card-header h2 {
  margin: 6px 0 5px;
  color: #0f172a;
  font-size: 21px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.pf-payment-card-header p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.6;
}

.pf-payment-performance-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 28px 24px 20px;
}

.pf-payment-performance-main > div:first-child {
  display: flex;
  flex-direction: column;
}

.pf-payment-performance-main span {
  color: #64748b;
  font-size: 12px;
  font-weight: 600;
}

.pf-payment-performance-main strong {
  margin-top: 5px;
  color: #0f766e;
  font-size: 31px;
  line-height: 1.1;
  font-weight: 850;
}

.pf-payment-performance-icon {
  width: 58px;
  height: 58px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 17px;
  background: #e6f5f2;
  font-size: 27px;
}

.pf-payment-performance-line {
  height: 8px;
  margin: 0 24px;
  overflow: hidden;
  border-radius: 999px;
  background: #eef2f2;
}

.pf-payment-performance-line > div {
  height: 100%;
  border-radius: inherit;
  background: #0f766e;
}

.pf-payment-performance-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 17px 24px 23px;
}

.pf-payment-performance-footer span {
  color: #64748b;
  font-size: 12px;
}

.pf-payment-performance-footer strong {
  color: #334155;
  font-size: 13px;
}

.pf-payment-method-list {
  padding: 18px 24px 24px;
}

.pf-payment-method-row {
  display: flex;
  gap: 12px;
  padding: 12px 0;
}

.pf-payment-method-row + .pf-payment-method-row {
  border-top: 1px solid #f1f5f9;
}

.pf-payment-method-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  border-radius: 11px;
  background: #f8fafc;
  font-size: 18px;
}

.pf-payment-method-content {
  min-width: 0;
  flex: 1;
}

.pf-payment-method-content > div:first-child {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.pf-payment-method-content > div:first-child strong {
  color: #334155;
  font-size: 13px;
}

.pf-payment-method-content > div:first-child span {
  color: #94a3b8;
  font-size: 11px;
}

.pf-payment-method-amount {
  display: flex;
  justify-content: space-between;
  margin-top: 3px;
}

.pf-payment-method-amount strong {
  color: #0f172a;
  font-size: 12px;
}

.pf-payment-method-amount span {
  color: #0f766e;
  font-size: 11px;
  font-weight: 800;
}

.pf-payment-method-bar {
  height: 5px;
  margin-top: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: #f1f5f9;
}

.pf-payment-method-bar > div {
  height: 100%;
  min-width: 2px;
  border-radius: inherit;
  background: #0f766e;
}

.pf-payment-empty-small {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 205px;
  padding: 24px;
  text-align: center;
}

.pf-payment-empty-small > span {
  font-size: 30px;
}

.pf-payment-empty-small strong {
  margin-top: 8px;
  color: #334155;
  font-size: 14px;
}

.pf-payment-empty-small small {
  max-width: 310px;
  margin-top: 5px;
  color: #94a3b8;
  font-size: 11px;
  line-height: 1.6;
}

.pf-payment-filters-card {
  margin-bottom: 20px;
}

.pf-payment-filters-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 22px 24px 16px;
}

.pf-payment-filters-header h2 {
  margin: 6px 0 0;
  color: #0f172a;
  font-size: 19px;
  font-weight: 800;
}

.pf-payment-clear-button {
  border: 0;
  background: transparent;
  color: #0f766e;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

.pf-payment-filter-grid {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) 210px 210px;
  gap: 12px;
  padding: 0 24px 17px;
}

.pf-payment-search-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.pf-payment-search-wrapper > span {
  position: absolute;
  left: 14px;
  font-size: 15px;
  pointer-events: none;
}

.pf-payment-search-input,
.pf-payment-select {
  width: 100%;
  height: 46px;
  border: 1px solid #dbe4e3;
  border-radius: 12px;
  outline: none;
  background: #ffffff;
  color: #334155;
  font-size: 13px;
  transition: 0.2s ease;
}

.pf-payment-search-input {
  padding: 0 14px 0 42px;
}

.pf-payment-select {
  padding: 0 12px;
  cursor: pointer;
}

.pf-payment-search-input:focus,
.pf-payment-select:focus {
  border-color: #0f766e;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.1);
}

.pf-payment-filter-result {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 13px 24px;
  border-top: 1px solid #f1f5f9;
  background: #fbfdfd;
  border-radius: 0 0 18px 18px;
}

.pf-payment-filter-result span {
  color: #64748b;
  font-size: 12px;
}

.pf-payment-filter-result strong {
  color: #0f766e;
  font-size: 14px;
}

.pf-payment-table-card {
  overflow: hidden;
  margin-bottom: 20px;
}

.pf-payment-table-count {
  min-width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 10px;
  border-radius: 11px;
  background: #e6f5f2;
  color: #0f766e;
  font-size: 13px;
  font-weight: 800;
}

.pf-payment-table-scroll {
  width: 100%;
  overflow-x: auto;
  margin-top: 18px;
}

.pf-payment-table {
  width: 100%;
  min-width: 930px;
  border-collapse: collapse;
}

.pf-payment-table th {
  padding: 13px 24px;
  border-top: 1px solid #f1f5f9;
  border-bottom: 1px solid #e2e8f0;
  background: #f8fafc;
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  white-space: nowrap;
}

.pf-payment-table td {
  padding: 15px 24px;
  border-bottom: 1px solid #f1f5f9;
  color: #334155;
  font-size: 13px;
  vertical-align: middle;
}

.pf-payment-table tbody tr {
  transition: background 0.15s ease;
}

.pf-payment-table tbody tr:hover {
  background: #fbfdfd;
}

.pf-payment-reference {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pf-payment-reference-icon {
  width: 37px;
  height: 37px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: #e6f5f2;
  font-size: 16px;
}

.pf-payment-reference > div:last-child,
.pf-payment-sale,
.pf-payment-client,
.pf-payment-date {
  display: flex;
  flex-direction: column;
}

.pf-payment-reference strong,
.pf-payment-sale strong,
.pf-payment-client strong,
.pf-payment-date strong {
  color: #334155;
  font-size: 12px;
  font-weight: 800;
}

.pf-payment-reference small,
.pf-payment-sale small,
.pf-payment-client small,
.pf-payment-date small {
  margin-top: 2px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-payment-sale strong {
  color: #0f766e;
}

.pf-payment-method-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: max-content;
  padding: 6px 9px;
  border-radius: 9px;
  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
}

.pf-payment-method-badge.cash {
  background: #f0fdf4;
  color: #15803d;
}

.pf-payment-method-badge.mobile {
  background: #eff6ff;
  color: #2563eb;
}

.pf-payment-method-badge.card {
  background: #f5f3ff;
  color: #7c3aed;
}

.pf-payment-method-badge.bank {
  background: #fff7ed;
  color: #c2410c;
}

.pf-payment-method-badge.other {
  background: #f8fafc;
  color: #475569;
}

.pf-payment-amount {
  color: #0f766e;
  font-size: 14px;
  font-weight: 850;
}

.pf-payment-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 340px;
  padding: 40px 20px;
  text-align: center;
}

.pf-payment-empty-icon {
  width: 70px;
  height: 70px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 20px;
  background: #e6f5f2;
  font-size: 31px;
}

.pf-payment-empty h3 {
  margin: 15px 0 5px;
  color: #334155;
  font-size: 18px;
  font-weight: 800;
}

.pf-payment-empty p {
  max-width: 430px;
  margin: 0 0 18px;
  color: #94a3b8;
  font-size: 13px;
  line-height: 1.6;
}

.pf-payment-info-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

.pf-payment-info-card {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-height: 100px;
  padding: 18px;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #ffffff;
}

.pf-payment-info-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: #e6f5f2;
  font-size: 19px;
}

.pf-payment-info-card > div:nth-child(2) {
  display: flex;
  flex-direction: column;
}

.pf-payment-info-card strong {
  color: #334155;
  font-size: 13px;
  font-weight: 800;
}

.pf-payment-info-card span {
  margin-top: 4px;
  color: #64748b;
  font-size: 11px;
  line-height: 1.55;
}

.pf-payment-info-card button {
  align-self: center;
  margin-left: auto;
  padding: 0;
  border: 0;
  background: transparent;
  color: #0f766e;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
}

.pf-payment-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 18px 4px 30px;
  color: #94a3b8;
  font-size: 11px;
}

.pf-payment-footer > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.pf-payment-footer > div:first-child {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.pf-payment-footer strong {
  color: #334155;
  font-size: 13px;
}

.pf-payment-footer span {
  color: #94a3b8;
}

/* Rapport destiné à l'impression */
.pf-payment-print-report {
  display: none;
}

/* Responsive */
@media (max-width: 1200px) {
  .pf-payment-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pf-payment-filter-grid {
    grid-template-columns: minmax(0, 1fr) 1fr 1fr;
  }

  .pf-payment-info-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 900px) {
  .pf-payment-page-header {
    flex-direction: column;
  }

  .pf-payment-header-actions {
    justify-content: flex-start;
  }

  .pf-payment-performance-grid {
    grid-template-columns: 1fr;
  }

  .pf-payment-filter-grid {
    grid-template-columns: 1fr;
  }

  .pf-payment-pharmacy-banner {
    align-items: flex-start;
  }

  .pf-payment-security {
    margin-left: auto;
  }
}

@media (max-width: 650px) {
  .pf-payment-kpi-grid {
    grid-template-columns: 1fr;
  }

  .pf-payment-page-header h1 {
    font-size: 26px;
  }

  .pf-payment-header-actions {
    width: 100%;
  }

  .pf-payment-header-actions .pf-btn {
    flex: 1;
  }

  .pf-payment-pharmacy-banner {
    flex-wrap: wrap;
  }

  .pf-payment-security {
    width: 100%;
    margin-left: 0;
    justify-content: center;
  }

  .pf-payment-performance-main strong {
    font-size: 25px;
  }

  .pf-payment-filters-header,
  .pf-payment-card-header {
    padding-left: 18px;
    padding-right: 18px;
  }

  .pf-payment-filter-grid {
    padding-left: 18px;
    padding-right: 18px;
  }

  .pf-payment-filter-result {
    padding-left: 18px;
    padding-right: 18px;
  }

  .pf-payment-footer {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* Impression */
@media print {
  body {
    background: #ffffff !important;
  }

  .pf-app {
    display: none !important;
  }

  .pf-payment-print-report {
    display: block !important;
    padding: 25px;
    color: #111827;
    background: #ffffff;
  }

  .pf-payment-print-header {
    margin-bottom: 25px;
    text-align: center;
  }

  .pf-payment-print-header h1 {
    margin: 0;
    font-size: 25px;
  }

  .pf-payment-print-header h2 {
    margin: 8px 0 5px;
    font-size: 19px;
  }

  .pf-payment-print-header p {
    margin: 3px 0;
    color: #64748b;
    font-size: 11px;
  }

  .pf-payment-print-summary {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin-bottom: 25px;
  }

  .pf-payment-print-summary > div {
    padding: 14px;
    border: 1px solid #d1d5db;
  }

  .pf-payment-print-summary span {
    display: block;
    color: #64748b;
    font-size: 10px;
  }

  .pf-payment-print-summary strong {
    display: block;
    margin-top: 5px;
    font-size: 16px;
  }

  .pf-payment-print-report table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
  }

  .pf-payment-print-report th,
  .pf-payment-print-report td {
    padding: 8px;
    border: 1px solid #d1d5db;
    text-align: left;
  }

  .pf-payment-print-report th {
    background: #f1f5f9;
    font-weight: 800;
  }
}
