  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  background: #e6f5f2;
}

.pf-report-stat-card span {
  display: block;
  font-size: 11px;
  color: #64748b;
}

.pf-report-stat-card strong {
  display: block;
  margin-top: 4px;
  font-size: 19px;
  color: #0f172a;
}

.pf-report-stat-card small {
  display: block;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-report-content-grid {
  max-width: 1400px;
  margin: 0 auto 20px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.pf-report-panel {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  overflow: hidden;
}

.pf-report-panel-header {
  padding: 19px 20px;
  border-bottom: 1px solid #e2e8f0;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.pf-report-panel-header h2 {
  margin: 5px 0 0;
  font-size: 17px;
}

.pf-report-finance-list {
  padding: 7px 20px 16px;
}

.pf-report-finance-list > div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 13px 0;
  border-bottom: 1px solid #f1f5f9;
  font-size: 12px;
}

.pf-report-finance-list span {
  color: #64748b;
}

.pf-report-finance-list strong {
  color: #0f172a;
}

.pf-report-finance-list strong.negative {
  color: #dc2626;
}

.pf-report-finance-list .total {
  border-bottom: 0;
  padding-top: 17px;
}

.pf-report-finance-list .total span {
  color: #0f172a;
  font-weight: 800;
}

.pf-report-finance-list .total strong {
  color: #0f766e;
  font-size: 17px;
}

.pf-report-stock-grid {
  padding: 16px 20px 20px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.pf-report-stock-grid > div {
  border: 1px solid #eef2f7;
  border-radius: 10px;
  padding: 13px;
  background: #fafcfc;
}

.pf-report-stock-grid span {
  display: block;
  font-size: 10px;
  color: #64748b;
}

.pf-report-stock-grid strong {
  display: block;
  margin-top: 5px;
  font-size: 18px;
  color: #0f172a;
}

.pf-report-stock-grid strong.warning {
  color: #d97706;
}

.pf-report-stock-grid strong.danger {
  color: #dc2626;
}

.pf-report-sales-panel {
  max-width: 1400px;
  margin: 0 auto 20px;
}

.pf-report-count-badge {
  background: #e6f5f2;
  color: #0f766e;
  padding: 6px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.pf-report-table-wrapper {
  overflow-x: auto;
}

.pf-report-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 760px;
}

.pf-report-table th {
  background: #f8fafc;
  color: #64748b;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: .05em;
  text-align: left;
  padding: 12px 16px;
  border-bottom: 1px solid #e2e8f0;
}

.pf-report-table td {
  padding: 14px 16px;
  border-bottom: 1px solid #f1f5f9;
  color: #475569;
  font-size: 12px;
}

.pf-report-table td strong {
  color: #0f172a;
}

.pf-report-empty {
  padding: 55px 20px;
  text-align: center;
}

.pf-report-empty-icon {
  width: 55px;
  height: 55px;
  margin: 0 auto 13px;
  border-radius: 16px;
  background: #f1f5f9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

.pf-report-empty h3 {
  margin: 0;
  font-size: 16px;
}

.pf-report-empty p {
  margin: 7px auto 0;
  max-width: 400px;
  color: #64748b;
  font-size: 12px;
}

.pf-report-print-actions {
  max-width: 1400px;
  margin: 0 auto 30px;
  background: #0f766e;
  color: #ffffff;
  border-radius: 16px;
  padding: 22px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
}

.pf-report-print-actions .pf-report-section-kicker {
  color: #bde7e1;
}

.pf-report-print-actions h2 {
  margin: 5px 0 4px;
  font-size: 18px;
}

.pf-report-print-actions p {
  margin: 0;
  color: #d8efec;
  font-size: 12px;
}

.pf-report-print-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.pf-report-print-buttons button {
  border: 0;
  background: #ffffff;
  color: #0f766e;
  border-radius: 9px;
  min-height: 40px;
  padding: 0 13px;
  font-weight: 800;
  font-size: 11px;
  cursor: pointer;
}

.pf-report-loading,
.pf-report-error-page {
  min-height: 100vh;
  background: #f5f8f8;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 25px;
}

.pf-report-loading-card,
.pf-report-error-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  padding: 35px;
  text-align: center;
  max-width: 500px;
  width: 100%;
}

.pf-report-spinner {
  width: 38px;
  height: 38px;
  border: 3px solid #d9eeee;
  border-top-color: #0f766e;
  border-radius: 50%;
  animation: pfReportSpin .8s linear infinite;
  margin: 0 auto 17px;
}

@keyframes pfReportSpin {
  to {
    transform: rotate(360deg);
  }
}

.pf-report-loading-card h2,
.pf-report-error-card h1 {
  margin: 0;
  font-size: 19px;
}

.pf-report-loading-card p,
.pf-report-error-card p {
  margin: 8px 0 0;
  color: #64748b;
  font-size: 13px;
}

.pf-report-error-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 15px;
  border-radius: 50%;
  background: #fee2e2;
  color: #dc2626;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  font-weight: 900;
}

.pf-report-error-actions {
  margin-top: 20px;
  display: flex;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* ============================================================
   DOCUMENT IMPRIMABLE
   ============================================================ */

.pf-report-print-page {
  display: none;
}

.pf-print-document {
  width: 100%;
  max-width: 190mm;
  margin: 0 auto;
  color: #111827;
  font-family: Arial, Helvetica, sans-serif;
}

.pf-print-header {
  display: flex;
  justify-content: space-between;
  gap: 25px;
  align-items: flex-start;
}

.pf-print-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pf-print-logo {
  width: 38px;
  height: 38px;
  border-radius: 9px;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
  font-weight: 900;
}

.pf-print-brand h1 {
  margin: 0;
  font-size: 20px;
}

.pf-print-brand p {
  margin: 2px 0 0;
  color: #64748b;
  font-size: 9px;
}

.pf-print-company {
  text-align: right;
}

.pf-print-company h2 {
  margin: 0;
  font-size: 15px;
}

.pf-print-company p {
  margin: 2px 0 0;
  color: #64748b;
  font-size: 9px;
}

.pf-print-divider {
  height: 1px;
  background: #d1d5db;
  margin: 15px 0;
}

.pf-print-title {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
}

.pf-print-title span {
  color: #0f766e;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .1em;
}

.pf-print-title h2 {
  margin: 4px 0 0;
  font-size: 20px;
}

.pf-print-date {
  color: #64748b;
  font-size: 9px;
}

.pf-print-summary {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin: 16px 0;
}

.pf-print-summary > div {
  border: 1px solid #dfe5e9;
  border-radius: 7px;
  padding: 10px;
}

.pf-print-summary span {
  display: block;
  color: #64748b;
  font-size: 8px;
}

.pf-print-summary strong {
  display: block;
  margin-top: 4px;
  font-size: 12px;
}

.pf-print-finance,
.pf-print-stock,
.pf-print-sales {
  margin-top: 15px;
}

.pf-print-finance h3,
.pf-print-stock h3,
.pf-print-sales h3 {
  font-size: 12px;
  margin: 0 0 8px;
}

.pf-print-finance-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border: 1px solid #dfe5e9;
}

.pf-print-finance-grid > div {
  padding: 9px;
  border-right: 1px solid #dfe5e9;
}

.pf-print-finance-grid > div:last-child {
  border-right: 0;
}

.pf-print-finance-grid span {
  display: block;
  color: #64748b;
  font-size: 8px;
}

.pf-print-finance-grid strong {
  display: block;
  margin-top: 3px;
  font-size: 10px;
}

.pf-print-finance-grid .grand-total {
  background: #f0fdfa;
}

.pf-print-finance-grid .grand-total strong {
  color: #0f766e;
  font-size: 12px;
}

.pf-print-stock-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  border: 1px solid #dfe5e9;
}

.pf-print-stock-grid > div {
  padding: 8px;
  border-right: 1px solid #dfe5e9;
}

.pf-print-stock-grid > div:last-child {
  border-right: 0;
}

.pf-print-stock-grid span {
  display: block;
  color: #64748b;
  font-size: 7px;
}

.pf-print-stock-grid strong {
  display: block;
  margin-top: 3px;
  font-size: 11px;
}

.pf-print-sales table {
  width: 100%;
  border-collapse: collapse;
}

.pf-print-sales th {
  background: #f1f5f9;
  text-align: left;
  padding: 7px 6px;
  font-size: 7px;
  color: #475569;
  border: 1px solid #dfe5e9;
}

.pf-print-sales td {
  padding: 7px 6px;
  font-size: 7px;
  border: 1px solid #dfe5e9;
}

.pf-print-sales td strong {
  font-size: 8px;
}

.pf-print-no-sales {
  border: 1px solid #dfe5e9;
  padding: 15px;
  text-align: center;
  color: #64748b;
  font-size: 9px;
}

.pf-print-footer {
  margin-top: 20px;
  padding-top: 9px;
  border-top: 1px solid #d1d5db;
  display: flex;
  justify-content: space-between;
  gap: 20px;
  color: #64748b;
  font-size: 8px;
}

.pf-print-footer strong,
.pf-print-footer span {
  display: block;
}

.pf-print-footer span + span {
  margin-top: 2px;
}

/* ============================================================
   IMPRESSION A4
   ============================================================ */

@media print {
  @page {
    size: A4 portrait;
    margin: 10mm;
  }

  html,
  body {
    margin: 0 !important;
    padding: 0 !important;
    background: #ffffff !important;
  }

  body {
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
  }

  .pf-report-screen {
    display: none !important;
  }

  .pf-report-print-page {
    display: block !important;
    width: 100% !important;
    min-height: auto !important;
    background: #ffffff !important;
  }

  .pf-print-document {
    display: block !important;
    width: 100% !important;
    max-width: none !important;
  }

  /*
   * On cache les éléments génériques du layout
   * susceptibles d'apparaître dans l'impression.
   */
  header:not(.pf-print-header),
  nav,
  aside,
  button,
  input,
  select,
  textarea,
  .pf-sidebar,
  .pf-topbar,
  .pf-main,
  .pf-content {
    visibility: hidden;
  }

  .pf-print-page,
  .pf-print-header,
  .pf-print-title,
  .pf-print-summary,
  .pf-print-finance,
  .pf-print-stock,
  .pf-print-sales,
  .pf-print-footer {
    visibility: visible !important;
  }

  .pf-print-header {
    display: flex !important;
  }

  .pf-print-sales tr {
    page-break-inside: avoid;
  }

  .pf-print-finance,
  .pf-print-stock {
    page-break-inside: avoid;
  }

  a {
    color: inherit !important;
    text-decoration: none !important;
  }
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 1100px) {
  .pf-report-sidebar {
    width: 235px;
    min-width: 235px;
  }

  .pf-report-main {
    padding: 24px;
  }

  .pf-report-stat-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 800px) {
  .pf-report-screen {
    display: block;
  }

  .pf-report-sidebar {
    width: 100%;
    min-width: 0;
    height: auto;
    min-height: auto;
    position: relative;
  }

  .pf-report-nav {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
  }

  .pf-report-user {
    margin-top: 15px;
  }

  .pf-report-header,
  .pf-report-period-card,
  .pf-report-print-actions {
    align-items: flex-start;
    flex-direction: column;
  }

  .pf-report-content-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 600px) {
  .pf-report-main {
    padding: 17px;
  }

  .pf-report-header h1 {
    font-size: 24px;
  }

  .pf-report-stat-grid {
    grid-template-columns: 1fr;
  }

  .pf-report-period-buttons {
    width: 100%;
  }

  .pf-report-period-buttons button {
    flex: 1;
    padding: 0 7px;
  }

  .pf-report-stock-grid {
    grid-template-columns: 1fr 1fr;
  }

  .pf-report-header-actions {
    width: 100%;
  }

  .pf-report-header-actions .pf-report-btn {
    flex: 1;
  }

  .pf-report-print-buttons {
    width: 100%;
    flex-direction: column;
  }

  .pf-report-print-buttons button {
    width: 100%;
  }
}
/* ============================================================
   PHARMAFLOW — SIDEBAR RAPPORTS
   CORRECTION DEFINITIVE DE LA MISE EN PAGE
   ============================================================ */

/* Conteneur général */
.pf-report-screen {
  width: 100%;
  min-width: 0;
  min-height: 100vh;
  display: flex !important;
  flex-direction: row !important;
  align-items: stretch;
  background: #f5f8f8;
