/* ============================================================
   IMPRESSION
   ============================================================ */

@media print {

  .pf-report-sidebar,
  .pf-report-main {
    position: static !important;
    width: auto !important;
    min-width: 0 !important;
    max-width: none !important;
    margin: 0 !important;
    padding: 0 !important;
  }

  .pf-report-screen {
    display: none !important;
  }

  .pf-report-print-page {
    display: block !important;
    width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
  }
}
