  display: flex;
  align-items: center;
  gap: 10px;
}

.pf-payments-user-avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 800;
  flex: 0 0 auto;
}

.pf-payments-user-info {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-payments-user-info strong {
  font-size: 12px;
  color: #0f172a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pf-payments-user-info span {
  margin-top: 2px;
  font-size: 10px;
  color: #64748b;
}

/* =========================================================
   MAIN
   ========================================================= */

.pf-payments-main {
  width: calc(100% - 270px);
  margin-left: 270px;
  min-height: 100vh;
  padding: 30px 38px 50px;
}

.pf-payments-header {
  max-width: 1320px;
  margin: 0 auto 22px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 25px;
}

.pf-payments-breadcrumb {
