  font-size: clamp(28px, 3vw, 38px);
  line-height: 1.1;
  font-weight: 850;
  letter-spacing: -0.025em;
}

.pf-payments-header p {
  margin: 9px 0 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.6;
}

.pf-payments-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* =========================================================
   BOUTONS
   ========================================================= */

.pf-payments-btn {
  min-height: 42px;
  padding: 0 16px;
  border-radius: 10px;
  border: 1px solid transparent;
