}

.pf-payments-btn.primary:hover {
  background: #115e59;
}

.pf-payments-btn.secondary {
  background: #ffffff;
  color: #334155;
  border-color: #dce4e7;
}

.pf-payments-btn.secondary:hover {
  border-color: #0f766e;
  color: #0f766e;
}

/* =========================================================
   INFO PHARMACIE
   ========================================================= */

.pf-payments-info-card {
  max-width: 1320px;
  margin: 0 auto 18px;
  padding: 16px 18px;
  border: 1px solid #dcebe8;
  border-radius: 15px;
  background: #ffffff;
  display: flex;
  align-items: center;
  gap: 13px;
  box-shadow: 0 3px 12px rgba(15, 23, 42, 0.025);
}

.pf-payments-info-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: #e6f5f2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex: 0 0 auto;
}

.pf-payments-info-card > div:nth-child(2) {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-payments-info-card span {
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.pf-payments-info-card strong {
  margin-top: 2px;
  color: #0f172a;
  font-size: 14px;
}

.pf-payments-info-card small {
  margin-top: 2px;
  color: #64748b;
  font-size: 11px;
}

.pf-payments-secure {
