  align-items: center;
  justify-content: center;
  font-size: 19px;
  flex: 0 0 auto;
}

.pf-payments-stat-card > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-payments-stat-card span {
  color: #64748b;
  font-size: 10px;
  font-weight: 700;
}

.pf-payments-stat-card strong {
  margin-top: 5px;
  color: #0f172a;
  font-size: 20px;
