  gap: 11px;
}

.pf-payments-method-icon {
  width: 39px;
  height: 39px;
  border-radius: 10px;
  background: #e6f5f2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  flex: 0 0 auto;
}

.pf-payments-method-card > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-payments-method-card span {
  color: #64748b;
  font-size: 10px;
  font-weight: 700;
}

.pf-payments-method-card strong {
