}

/* =========================================================
   RECHERCHE
   ========================================================= */

.pf-payments-search-panel {
  max-width: 1320px;
  margin: 0 auto 18px;
  padding: 20px;
  border: 1px solid #e2e8f0;
  border-radius: 15px;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.pf-payments-filters {
  flex: 1;
  max-width: 650px;
  display: flex;
  gap: 9px;
}

.pf-payments-search {
  flex: 1;
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid #dce4e7;
  border-radius: 10px;
  background: #ffffff;
  display: flex;
  align-items: center;
  gap: 8px;
}

.pf-payments-search:focus-within {
  border-color: #0f766e;
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.08);
}

.pf-payments-search > span {
  color: #94a3b8;
  font-size: 19px;
}

.pf-payments-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: #0f172a;
  font-family: inherit;
  font-size: 12px;
}

.pf-payments-search input::placeholder {
  color: #a3adb8;
}

.pf-payments-search button {
  width: 25px;
  height: 25px;
  border: 0;
  border-radius: 50%;
  background: #f1f5f5;
  color: #64748b;
  cursor: pointer;
}

.pf-payments-filter {
  min-width: 150px;
  min-height: 42px;
  padding: 0 11px;
  border: 1px solid #dce4e7;
  border-radius: 10px;
  outline: none;
  background: #ffffff;
  color: #334155;
  font-family: inherit;
  font-size: 11px;
  cursor: pointer;
}

.pf-payments-filter:focus {
  border-color: #0f766e;
}

/* =========================================================
   TABLEAU
   ========================================================= */

.pf-payments-table-panel {
  max-width: 1320px;
  margin: 0 auto 18px;
  border: 1px solid #e2e8f0;
  border-radius: 15px;
  background: #ffffff;
  overflow: hidden;
}

.pf-payments-table-header {
  padding: 20px;
