  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-bottom: 1px solid #eef2f3;
}

.pf-payments-table-header p {
  margin: 5px 0 0;
  color: #94a3b8;
  font-size: 10px;
}

.pf-payments-refresh {
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid #dce4e7;
  border-radius: 8px;
  background: #ffffff;
  color: #475569;
  font-family: inherit;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
}

.pf-payments-refresh:hover {
  border-color: #0f766e;
  color: #0f766e;
}

.pf-payments-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.pf-payments-table {
  width: 100%;
  min-width: 780px;
  border-collapse: collapse;
}

.pf-payments-table th {
  padding: 12px 18px;
  background: #f8fafb;
  color: #64748b;
  border-bottom: 1px solid #e2e8f0;
  font-size: 9px;
  font-weight: 850;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  white-space: nowrap;
}

.pf-payments-table td {
  padding: 15px 18px;
  border-bottom: 1px solid #f0f3f4;
  color: #475569;
  font-size: 11px;
  vertical-align: middle;
}

.pf-payments-table tbody tr:hover {
  background: #fbfdfd;
}

.pf-payments-table tbody tr:last-child td {
  border-bottom: 0;
}

.pf-payment-sale-number {
  color: #0f766e;
  font-size: 11px;
}

.pf-payment-client {
  display: flex;
  flex-direction: column;
}

.pf-payment-client strong {
  color: #334155;
  font-size: 11px;
}

.pf-payment-client small {
  margin-top: 3px;
  color: #94a3b8;
  font-size: 9px;
}

.pf-payment-method-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 8px;
  border-radius: 7px;
  background: #f1f7f6;
  color: #0f766e;
  font-size: 9px;
  font-weight: 750;
  white-space: nowrap;
}

.pf-payment-amount {
  color: #0f172a;
  font-size: 12px;
  white-space: nowrap;
}

/* =========================================================
   ÉTAT VIDE
   ========================================================= */

.pf-payments-empty {
  padding: 55px 20px;
  text-align: center;
}

.pf-payments-empty-icon {
  width: 60px;
  height: 60px;
  margin: 0 auto 13px;
  border-radius: 17px;
  background: #e6f5f2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 25px;
}

.pf-payments-empty h3 {
  margin: 0;
  color: #334155;
  font-size: 16px;
  font-weight: 800;
}

.pf-payments-empty p {
  max-width: 440px;
  margin: 7px auto 0;
  color: #94a3b8;
  font-size: 11px;
  line-height: 1.6;
}

/* =========================================================
   IMPRESSION RAPIDE
   ========================================================= */

.pf-payments-print-box {
  max-width: 1320px;
  margin: 0 auto;
  padding: 21px;
  border-radius: 15px;
  background: #0f766e;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
}

.pf-payments-print-box .pf-payments-kicker {
