  align-items: center;
  justify-content: center;
  padding: 25px;
}

.pf-payments-loading-card {
  width: min(420px, 100%);
  padding: 35px;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: #ffffff;
  text-align: center;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.05);
}

.pf-payments-spinner {
  width: 38px;
  height: 38px;
  margin: 0 auto 18px;
  border: 3px solid #d9efec;
  border-top-color: #0f766e;
  border-radius: 50%;
  animation: pfPaymentsSpin 0.8s linear infinite;
}

@keyframes pfPaymentsSpin {
  to {
    transform: rotate(360deg);
  }
}

.pf-payments-loading-card h2 {
  margin: 0;
  color: #0f172a;
  font-size: 18px;
}

.pf-payments-loading-card p {
