  align-items: center;
  justify-content: center;
}

.pf-payments-error-card {
  width: min(520px, 100%);
  padding: 35px;
  border: 1px solid #fee2e2;
  border-radius: 18px;
  background: #ffffff;
  text-align: center;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.05);
}

.pf-payments-error-icon {
  width: 50px;
  height: 50px;
  margin: 0 auto 15px;
  border-radius: 50%;
  background: #fef2f2;
  color: #dc2626;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  font-weight: 900;
}

.pf-payments-error-card h1 {
  margin: 0;
  color: #0f172a;
  font-size: 20px;
}

.pf-payments-error-card p {
  margin: 10px 0 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.7;
  word-break: break-word;
}

.pf-payments-error-actions {
  margin-top: 20px;
  display: flex;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* =========================================================
   VERSION IMPRIMABLE
   ========================================================= */

.pf-payments-print-page {
  display: none;
}

/* =========================================================
   TABLETTE
   ========================================================= */

@media (max-width: 1150px) {
  .pf-payments-main {
    padding: 25px;
  }

  .pf-payments-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pf-payments-method-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 820px) {
  .pf-payments-sidebar {
    transform: translateX(-105%);
    transition: transform 0.25s ease;
    box-shadow: 10px 0 30px rgba(15, 23, 42, 0.12);
  }

  .pf-payments-sidebar.mobile-open {
    transform: translateX(0);
  }

  .pf-payments-sidebar-close {
    display: flex;
    margin-left: auto;
    width: 32px;
    height: 32px;
    border: 0;
    border-radius: 8px;
    background: #f1f5f5;
    color: #475569;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    cursor: pointer;
  }

  .pf-payments-mobile-overlay {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 90;
    border: 0;
    background: rgba(15, 23, 42, 0.35);
    backdrop-filter: blur(2px);
  }

  .pf-payments-main {
    width: 100%;
    margin-left: 0;
    padding: 0 16px 35px;
  }

  .pf-payments-mobile-header {
    min-height: 64px;
    margin: 0 -16px 22px;
    padding: 10px 16px;
    background: #ffffff;
    border-bottom: 1px solid #e2e8f0;
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .pf-payments-menu-button {
    width: 40px;
    height: 40px;
    border: 1px solid #dce4e7;
    border-radius: 9px;
    background: #ffffff;
    color: #334155;
    font-size: 19px;
    cursor: pointer;
  }

  .pf-payments-mobile-header > div {
    display: flex;
    flex-direction: column;
  }

  .pf-payments-mobile-header strong {
    color: #0f172a;
    font-size: 14px;
  }

  .pf-payments-mobile-header span {
    margin-top: 2px;
    color: #64748b;
    font-size: 10px;
  }

  .pf-payments-header {
    flex-direction: column;
    margin-bottom: 18px;
  }

  .pf-payments-header h1 {
    font-size: 29px;
  }

  .pf-payments-header-actions {
    width: 100%;
  }

  .pf-payments-header-actions .pf-payments-btn {
    flex: 1;
  }

  .pf-payments-info-card {
    align-items: flex-start;
  }

  .pf-payments-secure {
    display: none;
  }

  .pf-payments-period-card {
    flex-direction: column;
    align-items: stretch;
  }

  .pf-payments-period-buttons {
    width: 100%;
  }

  .pf-payments-period-buttons button {
    flex: 1;
    padding: 0 7px;
  }

  .pf-payments-search-panel {
    flex-direction: column;
    align-items: stretch;
  }

  .pf-payments-filters {
    max-width: none;
    flex-direction: column;
  }

  .pf-payments-filter {
    width: 100%;
  }

  .pf-payments-print-box {
    flex-direction: column;
    align-items: stretch;
  }

  .pf-payments-print-buttons {
    justify-content: flex-start;
  }
}

/* =========================================================
   PETIT MOBILE
   ========================================================= */

@media (max-width: 520px) {
  .pf-payments-main {
    padding-left: 12px;
    padding-right: 12px;
  }

  .pf-payments-mobile-header {
    margin-left: -12px;
    margin-right: -12px;
  }

  .pf-payments-header h1 {
    font-size: 26px;
  }

  .pf-payments-header p {
    font-size: 12px;
  }

  .pf-payments-header-actions {
    flex-direction: column;
  }

  .pf-payments-header-actions .pf-payments-btn {
    width: 100%;
  }

  .pf-payments-info-card {
    padding: 13px;
  }

  .pf-payments-stats {
    grid-template-columns: 1fr;
  }

  .pf-payments-method-grid {
    grid-template-columns: 1fr;
  }

  .pf-payments-period-card,
  .pf-payments-methods,
  .pf-payments-search-panel,
  .pf-payments-table-header {
    padding: 16px;
  }

  .pf-payments-period-buttons button {
    font-size: 9px;
  }

  .pf-payments-stat-card strong {
    font-size: 18px;
  }

  .pf-payments-print-box {
    padding: 17px;
  }

  .pf-payments-print-buttons {
    flex-direction: column;
  }

  .pf-payments-print-buttons button {
    width: 100%;
  }

  .pf-payments-error-card {
    padding: 25px 18px;
  }
}

/* =========================================================
   IMPRESSION — RAPPORT PAIEMENTS
   ========================================================= */

@media print {
  @page {
    size: A4;
    margin: 12mm;
  }

  body {
    margin: 0 !important;
    padding: 0 !important;
    background: #ffffff !important;
  }

  body * {
    visibility: hidden !important;
  }

  .pf-payments-print-page,
  .pf-payments-print-page * {
    visibility: visible !important;
  }

  .pf-payments-screen {
    display: none !important;
  }

  .pf-payments-print-page {
    display: block !important;
    width: 100%;
    background: #ffffff;
    color: #0f172a;
  }

  .pf-payments-print-document {
    width: 100%;
    max-width: 190mm;
    margin: 0 auto;
    background: #ffffff;
  }

  .pf-payments-print-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 20px;
  }

  .pf-payments-print-brand {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .pf-payments-print-logo {
    width: 36px;
    height: 36px;
    border-radius: 9px;
    background: #0f766e !important;
    color: #ffffff !important;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 900;
    font-size: 18px;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .pf-payments-print-brand h1 {
    margin: 0;
    color: #0f172a;
    font-size: 18px;
    font-weight: 900;
  }

  .pf-payments-print-brand p {
    margin: 2px 0 0;
    color: #64748b;
    font-size: 8px;
  }

  .pf-payments-print-pharmacy {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    text-align: right;
  }

  .pf-payments-print-pharmacy strong {
    color: #0f172a;
    font-size: 11px;
  }

  .pf-payments-print-pharmacy span {
    margin-top: 2px;
    color: #64748b;
    font-size: 8px;
  }

  .pf-payments-print-divider {
    height: 1px;
    margin: 13px 0;
    background: #dce4e7 !important;
  }

  .pf-payments-print-title {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 20px;
  }

  .pf-payments-print-title span {
    color: #0f766e;
    font-size: 7px;
    font-weight: 900;
    letter-spacing: 0.1em;
  }

  .pf-payments-print-title h2 {
    margin: 3px 0 0;
    color: #0f172a;
    font-size: 17px;
    font-weight: 900;
  }

  .pf-payments-print-title > div:last-child {
    color: #64748b;
    font-size: 8px;
  }

  .pf-payments-print-summary {
    margin-top: 16px;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 8px;
  }

  .pf-payments-print-summary > div {
    padding: 10px;
    border: 1px solid #dce4e7;
    border-radius: 7px;
  }

  .pf-payments-print-summary span {
    display: block;
    color: #64748b;
    font-size: 7px;
  }

  .pf-payments-print-summary strong {
    display: block;
    margin-top: 4px;
    color: #0f172a;
    font-size: 12px;
  }

  .pf-payments-print-table-section {
    margin-top: 18px;
  }

  .pf-payments-print-table-section h3 {
    margin: 0 0 8px;
    color: #0f172a;
    font-size: 11px;
    font-weight: 850;
  }

  .pf-payments-print-table-section table {
    width: 100%;
    border-collapse: collapse;
  }

  .pf-payments-print-table-section th {
    padding: 7px 6px;
    background: #f1f7f6 !important;
    border-bottom: 1px solid #cbd5d7;
    color: #334155;
    font-size: 7px;
    font-weight: 850;
    text-align: left;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .pf-payments-print-table-section td {
    padding: 7px 6px;
    border-bottom: 1px solid #e2e8f0;
    color: #475569;
    font-size: 7px;
    vertical-align: top;
  }

  .pf-payments-print-table-section td strong {
    color: #0f172a;
  }

  .pf-payments-print-empty {
    padding: 20px;
    border: 1px dashed #cbd5e1;
    text-align: center;
    color: #64748b;
    font-size: 8px;
  }

  .pf-payments-print-footer {
    margin-top: 20px;
    padding-top: 9px;
    border-top: 1px solid #dce4e7;
    display: flex;
    justify-content: space-between;
    gap: 20px;
  }

  .pf-payments-print-footer > div {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  .pf-payments-print-footer > div:last-child {
    align-items: flex-end;
    text-align: right;
  }

  .pf-payments-print-footer strong {
    color: #0f172a;
    font-size: 8px;
  }

  .pf-payments-print-footer span {
    color: #64748b;
    font-size: 7px;
  }
}
/* =========================================================
   PHARMAFLOW — RAPPORTS ADMINISTRATEUR
   ========================================================= */

.pf-reports-screen {
  min-height: 100vh;
  display: flex;
  background: #f5f8f8;
  color: #0f172a;
}

/* SIDEBAR */

.pf-reports-sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: 270px;
  height: 100vh;
  z-index: 100;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  background: #fff;
  border-right: 1px solid #e2e8f0;
}

.pf-reports-brand {
  min-height: 82px;
  padding: 18px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid #eef2f3;
}

.pf-reports-brand-logo {
  width: 43px;
  height: 43px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: #0f766e;
  color: #fff;
  font-size: 21px;
  font-weight: 900;
}

.pf-reports-brand-text {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-reports-brand-text strong {
  font-size: 17px;
  font-weight: 850;
}

.pf-reports-brand-text span {
  margin-top: 3px;
  color: #64748b;
  font-size: 10px;
}

.pf-reports-pharmacy {
  margin: 17px 14px 10px;
  padding: 13px;
  display: flex;
  align-items: center;
  gap: 11px;
  border: 1px solid #d2eee9;
  border-radius: 14px;
  background: #e6f5f2;
}

.pf-reports-pharmacy-icon {
  width: 41px;
  height: 41px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: #fff;
}

.pf-reports-pharmacy > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-reports-pharmacy span {
  color: #0f766e;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .1em;
}

.pf-reports-pharmacy strong {
  margin-top: 3px;
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pf-reports-pharmacy small {
  margin-top: 2px;
  color: #64748b;
  font-size: 10px;
}

.pf-reports-nav {
  flex: 1;
  padding: 9px 12px;
}

.pf-reports-nav-title {
  padding: 13px 11px 7px;
  color: #94a3b8;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .11em;
}

.pf-reports-nav-title.tools {
  margin-top: 8px;
}

.pf-reports-nav-item {
  width: 100%;
  min-height: 43px;
  padding: 0 12px;
  display: flex;
  align-items: center;
  gap: 11px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #475569;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
}

.pf-reports-nav-item:hover {
  background: #f1f7f6;
  color: #0f766e;
}

.pf-reports-nav-item.active {
  background: #e6f5f2;
  color: #0f766e;
  font-weight: 800;
}

.pf-reports-nav-item .icon {
  width: 22px;
  text-align: center;
}

.pf-reports-user {
  margin: 10px 14px 14px;
  padding: 12px 0 0;
  display: flex;
  align-items: center;
  gap: 9px;
  border-top: 1px solid #e2e8f0;
}

.pf-reports-user-avatar {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #0f766e;
  color: #fff;
  font-size: 13px;
  font-weight: 850;
}

.pf-reports-user-info {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.pf-reports-user-info strong {
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pf-reports-user-info span {
  margin-top: 2px;
  color: #64748b;
  font-size: 9px;
}

.pf-reports-logout {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 8px;
  background: #f8fafb;
  color: #64748b;
  cursor: pointer;
}

/* MAIN */

.pf-reports-main {
  width: calc(100% - 270px);
  min-height: 100vh;
  margin-left: 270px;
  padding: 31px 38px 50px;
}

.pf-reports-header {
  max-width: 1320px;
  margin: 0 auto 22px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 25px;
}

.pf-reports-breadcrumb {
  margin-bottom: 8px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-reports-header h1 {
  margin: 0;
  font-size: clamp(29px,3vw,39px);
  font-weight: 900;
  letter-spacing: -.03em;
}

.pf-reports-header p {
  margin: 9px 0 0;
  color: #64748b;
  font-size: 13px;
}

.pf-reports-header-actions {
  display: flex;
  gap: 9px;
}

.pf-reports-btn {
  min-height: 42px;
  padding: 0 15px;
  border-radius: 10px;
  font-family: inherit;
  font-size: 11px;
  font-weight: 750;
  cursor: pointer;
}

.pf-reports-btn.primary {
  border: 0;
  background: #0f766e;
  color: #fff;
}

.pf-reports-btn.secondary {
  border: 1px solid #dce4e7;
  background: #fff;
  color: #334155;
}

/* PÉRIODE */

.pf-reports-period,
.pf-reports-card,
.pf-reports-print-box {
  max-width: 1320px;
  margin-left: auto;
  margin-right: auto;
}

.pf-reports-period {
  margin-bottom: 18px;
  padding: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  border: 1px solid #e2e8f0;
  border-radius: 15px;
  background: #fff;
}

.pf-reports-kicker {
  display: block;
  margin-bottom: 5px;
  color: #0f766e;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .12em;
}

.pf-reports-period h2 {
  margin: 0;
  font-size: 20px;
  font-weight: 850;
}

.pf-reports-period p {
  margin: 6px 0 0;
  color: #64748b;
  font-size: 11px;
}

.pf-reports-period-buttons {
  display: flex;
  gap: 4px;
  padding: 4px;
  border-radius: 10px;
  background: #f1f5f5;
}

.pf-reports-period-buttons button {
  min-height: 36px;
  padding: 0 14px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: #64748b;
  font-family: inherit;
  font-size: 10px;
  font-weight: 750;
  cursor: pointer;
}

.pf-reports-period-buttons button.active {
  background: #fff;
  color: #0f766e;
  box-shadow: 0 2px 7px rgba(15,23,42,.08);
}

/* STATS */

.pf-reports-stats {
  max-width: 1320px;
  margin: 0 auto 18px;
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 14px;
}

.pf-reports-stat {
  padding: 18px;
  border: 1px solid #e2e8f0;
  border-radius: 15px;
  background: #fff;
}

.pf-reports-stat > div {
  width: 42px;
  height: 42px;
  margin-bottom: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: #e6f5f2;
}

.pf-reports-stat span,
.pf-reports-stat small {
  display: block;
}

.pf-reports-stat span {
  color: #64748b;
  font-size: 9px;
  font-weight: 700;
}

.pf-reports-stat strong {
  display: block;
  margin-top: 5px;
  font-size: 20px;
  font-weight: 900;
}

.pf-reports-stat small {
  margin-top: 5px;
  color: #94a3b8;
  font-size: 9px;
}

/* GRID */

.pf-reports-grid {
  max-width: 1320px;
  margin: 0 auto 18px;
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 18px;
}

.pf-reports-card {
  margin-bottom: 18px;
  padding: 20px;
  border: 1px solid #e2e8f0;
  border-radius: 15px;
  background: #fff;
}

.pf-reports-grid .pf-reports-card {
  margin-bottom: 0;
}

.pf-reports-card-header {
  margin-bottom: 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.pf-reports-card-header h2 {
  margin: 0;
  font-size: 20px;
  font-weight: 850;
}

/* FINANCE */

.pf-reports-finance-list {
  display: flex;
  flex-direction: column;
}

.pf-reports-finance-list > div {
  padding: 12px 0;
  display: flex;
  justify-content: space-between;
  border-bottom: 1px solid #eef2f3;
}

.pf-reports-finance-list span {
  color: #64748b;
  font-size: 11px;
}

.pf-reports-finance-list strong {
  font-size: 11px;
}

.pf-reports-finance-list .total strong {
  color: #0f766e;
  font-size: 14px;
}

/* STOCK */

.pf-reports-stock-grid {
  display: grid;
  grid-template-columns: repeat(2,1fr);
  gap: 10px;
}

.pf-reports-stock-grid > div {
  padding: 15px;
  border-radius: 11px;
  background: #f8fafb;
}

.pf-reports-stock-grid strong,
.pf-reports-stock-grid span {
  display: block;
}

.pf-reports-stock-grid strong {
  font-size: 18px;
}

.pf-reports-stock-grid span {
  margin-top: 4px;
  color: #64748b;
  font-size: 9px;
}

/* ALERTES */

.pf-reports-alerts {
  max-width: 1320px;
  margin: 0 auto 18px;
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 10px;
}

.pf-reports-alert {
  padding: 13px;
  display: flex;
  gap: 10px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #fff;
}

.pf-reports-alert > span {
  font-size: 17px;
}

.pf-reports-alert strong,
.pf-reports-alert small {
  display: block;
}

.pf-reports-alert strong {
  font-size: 10px;
}

.pf-reports-alert small {
  margin-top: 4px;
  color: #64748b;
  font-size: 9px;
  line-height: 1.4;
}

.pf-reports-alert.warning {
  background: #fffbeb;
  border-color: #fde68a;
}

.pf-reports-alert.danger {
  background: #fef2f2;
  border-color: #fecaca;
}

.pf-reports-alert.info {
  background: #eff6ff;
  border-color: #bfdbfe;
}

/* PAIEMENTS */

.pf-reports-method-grid {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 12px;
}

.pf-reports-method {
  padding: 15px;
  border: 1px solid #edf1f2;
  border-radius: 11px;
  background: #fbfdfd;
}

.pf-reports-method > div {
  font-size: 19px;
}

.pf-reports-method span,
.pf-reports-method strong,
.pf-reports-method small {
  display: block;
}

.pf-reports-method span {
  margin-top: 8px;
  color: #64748b;
  font-size: 9px;
}

.pf-reports-method strong {
  margin-top: 4px;
  font-size: 14px;
}

.pf-reports-method small {
  margin-top: 3px;
  color: #94a3b8;
  font-size: 9px;
}

.pf-reports-link-button {
  border: 0;
  background: transparent;
  color: #0f766e;
  font-family: inherit;
  font-size: 10px;
  font-weight: 750;
  cursor: pointer;
}

/* TABLE */

.pf-reports-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.pf-reports-table {
  width: 100%;
  min-width: 720px;
  border-collapse: collapse;
}

.pf-reports-table th {
  padding: 11px 14px;
  background: #f8fafb;
  color: #64748b;
  font-size: 8px;
  text-align: left;
  text-transform: uppercase;
}

.pf-reports-table td {
  padding: 14px;
  border-bottom: 1px solid #eef2f3;
  color: #475569;
  font-size: 10px;
}

.pf-reports-sale-number {
  color: #0f766e;
}

.pf-reports-status {
  padding: 5px 8px;
  border-radius: 7px;
  background: #f0fdf4;
  color: #15803d;
  font-size: 8px;
  font-weight: 750;
}

/* EMPTY */

.pf-reports-empty {
  padding: 45px 20px;
  text-align: center;
}

.pf-reports-empty > div {
  font-size: 28px;
}

.pf-reports-empty h3 {
  margin: 10px 0 0;
  font-size: 15px;
}

.pf-reports-empty p,
.pf-reports-empty-small {
  color: #94a3b8;
  font-size: 10px;
}

.pf-reports-empty-small {
  padding: 20px;
  text-align: center;
}

/* PRINT BOX */

.pf-reports-print-box {
  margin-bottom: 18px;
  padding: 21px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  border-radius: 15px;
  background: #0f766e;
}

.pf-reports-print-box h2 {
  margin: 0;
  color: #fff;
  font-size: 20px;
}

.pf-reports-print-box p {
  margin: 6px 0 0;
  color: #d5f5f0;
  font-size: 10px;
}

.pf-reports-print-actions {
  display: flex;
  gap: 8px;
}

.pf-reports-print-actions button {
  min-height: 38px;
  padding: 0 13px;
  border: 0;
  border-radius: 8px;
  background: #fff;
  color: #0f766e;
  font-family: inherit;
  font-size: 9px;
  font-weight: 850;
  cursor: pointer;
}

/* LOADING */

.pf-reports-loading,
.pf-reports-error-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f5f8f8;
  padding: 25px;
}

.pf-reports-loading-card,
.pf-reports-error-card {
  width: min(440px,100%);
  padding: 35px;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: #fff;
  text-align: center;
}

.pf-reports-spinner {
  width: 38px;
  height: 38px;
  margin: 0 auto 18px;
  border: 3px solid #d9efec;
  border-top-color: #0f766e;
  border-radius: 50%;
  animation: pfReportsSpin .8s linear infinite;
}

@keyframes pfReportsSpin {
  to {
    transform: rotate(360deg);
  }
}

.pf-reports-loading-card h2,
.pf-reports-error-card h1 {
  margin: 0;
}

.pf-reports-loading-card p,
.pf-reports-error-card p {
  margin: 8px 0 0;
  color: #64748b;
  font-size: 11px;
}

.pf-reports-error-icon {
  width: 50px;
  height: 50px;
  margin: 0 auto 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #fef2f2;
  color: #dc2626;
  font-weight: 900;
}

/* PRINT PAGE */

.pf-reports-print-page {
  display: none;
}

/* TABLETTE */

@media (max-width: 1150px) {
  .pf-reports-main {
    padding-left: 24px;
    padding-right: 24px;
  }

  .pf-reports-stats {
    grid-template-columns: repeat(2,1fr);
  }

  .pf-reports-alerts {
    grid-template-columns: repeat(2,1fr);
  }

  .pf-reports-method-grid {
    grid-template-columns: repeat(2,1fr);
  }
}

/* MOBILE */

@media (max-width: 820px) {
  .pf-reports-sidebar {
    width: 270px;
    transform: translateX(-105%);
    transition: transform .25s ease;
  }

  .pf-reports-sidebar.mobile-open {
    transform: translateX(0);
  }

  .pf-reports-main {
    width: 100%;
    margin-left: 0;
    padding: 20px 16px 40px;
  }

  .pf-reports-header {
    flex-direction: column;
  }

  .pf-reports-header-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .pf-reports-header-actions .pf-reports-btn {
    flex: 1;
  }

  .pf-reports-period {
    flex-direction: column;
    align-items: stretch;
  }

  .pf-reports-period-buttons {
    width: 100%;
  }

  .pf-reports-period-buttons button {
    flex: 1;
  }

  .pf-reports-grid {
    grid-template-columns: 1fr;
  }

  .pf-reports-print-box {
    flex-direction: column;
    align-items: stretch;
  }

  .pf-reports-print-actions {
    flex-wrap: wrap;
  }
}

@media (max-width: 520px) {
  .pf-reports-main {
    padding-left: 12px;
    padding-right: 12px;
  }

  .pf-reports-header h1 {
    font-size: 27px;
  }

  .pf-reports-header-actions {
    flex-direction: column;
  }

  .pf-reports-header-actions .pf-reports-btn {
    width: 100%;
  }

  .pf-reports-stats {
    grid-template-columns: 1fr;
  }

  .pf-reports-alerts {
    grid-template-columns: 1fr;
  }

  .pf-reports-method-grid {
    grid-template-columns: 1fr;
  }

  .pf-reports-stock-grid {
    grid-template-columns: 1fr;
  }

  .pf-reports-period,
  .pf-reports-card {
    padding: 16px;
  }

  .pf-reports-print-actions {
    flex-direction: column;
  }

  .pf-reports-print-actions button {
    width: 100%;
  }
}

/* =========================================================
   IMPRESSION A4
   ========================================================= */

@media print {

  @page {
    size: A4;
    margin: 12mm;
  }

  body {
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
  }

  body * {
    visibility: hidden !important;
  }

  .pf-reports-print-page,
  .pf-reports-print-page * {
    visibility: visible !important;
  }

  .pf-reports-screen {
    display: none !important;
  }

  .pf-reports-print-page {
    display: block !important;
    width: 100%;
    background: #fff;
    color: #0f172a;
  }

  .pf-reports-print-document {
    width: 100%;
    max-width: 190mm;
    margin: 0 auto;
  }

  .pf-reports-print-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 20px;
  }

  .pf-reports-print-brand {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .pf-reports-print-logo {
    width: 36px;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    background: #0f766e !important;
    color: #fff !important;
    font-size: 18px;
    font-weight: 900;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .pf-reports-print-brand h1 {
    margin: 0;
    font-size: 18px;
  }

  .pf-reports-print-brand p {
    margin: 2px 0 0;
    color: #64748b;
    font-size: 8px;
  }

  .pf-reports-print-pharmacy {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    font-size: 8px;
  }

  .pf-reports-print-pharmacy span {
    color: #64748b;
  }

  .pf-reports-print-line {
    height: 1px;
    margin: 13px 0;
    background: #dce4e7;
  }

  .pf-reports-print-title {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
  }

  .pf-reports-print-title span {
    color: #0f766e;
    font-size: 7px;
    font-weight: 900;
    letter-spacing: .1em;
  }

  .pf-reports-print-title h2 {
    margin: 3px 0 0;
    font-size: 17px;
  }

  .pf-reports-print-title small {
    color: #64748b;
    font-size: 8px;
  }

  .pf-reports-print-stats {
    margin-top: 16px;
    display: grid;
    grid-template-columns: repeat(4,1fr);
    gap: 8px;
  }

  .pf-reports-print-stats > div {
    padding: 9px;
    border: 1px solid #dce4e7;
    border-radius: 7px;
  }

  .pf-reports-print-stats span {
    display: block;
    color: #64748b;
    font-size: 7px;
  }

  .pf-reports-print-stats strong {
    display: block;
    margin-top: 4px;
    font-size: 11px;
  }

  .pf-reports-print-section {
    margin-top: 18px;
  }

  .pf-reports-print-section h3 {
    margin: 0 0 8px;
    font-size: 11px;
  }

  .pf-reports-print-section table {
    width: 100%;
    border-collapse: collapse;
  }

  .pf-reports-print-section th {
    padding: 6px;
    background: #f1f7f6 !important;
    border-bottom: 1px solid #cbd5d7;
    font-size: 7px;
    text-align: left;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .pf-reports-print-section td {
    padding: 6px;
    border-bottom: 1px solid #e2e8f0;
    font-size: 7px;
  }

  .pf-reports-print-section .total td {
    font-weight: 900;
  }

  .pf-reports-print-footer {
    margin-top: 20px;
    padding-top: 9px;
    display: flex;
    justify-content: space-between;
    border-top: 1px solid #dce4e7;
    color: #64748b;
    font-size: 7px;
  }

  .pf-reports-print-footer strong {
    color: #0f172a;
  }
}
/* =========================================================
   PHARMAFLOW — RAPPORTS PHARMACIEN
   ========================================================= */

.pf-reports-app {
  min-height: 100vh;
  background: #f5f8f8;
}

.pf-reports-sidebar {
  background: #ffffff;
  border-right: 1px solid #e2e8f0;
}

.pf-reports-sidebar .pf-nav-item {
  border: 0;
  background: transparent;
  width: 100%;
  cursor: pointer;
  text-align: left;
}

.pf-reports-sidebar .pf-nav-item.active {
  background: #e6f5f2;
  color: #0f766e;
  font-weight: 700;
}

.pf-reports-sidebar .pf-nav-item.active span:first-child {
  color: #0f766e;
}

.pf-main {
  min-width: 0;
}

.pf-reports-app .pf-topbar {
  background: #ffffff;
  border-bottom: 1px solid #e2e8f0;
}

.pf-breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #94a3b8;
  font-size: 13px;
  font-weight: 500;
  margin-bottom: 7px;
}

.pf-breadcrumb span {
  color: #cbd5e1;
}

.pf-topbar h1 {
  margin: 0;
  color: #0f172a;
  font-size: 28px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.pf-topbar p {
  margin: 7px 0 0;
  color: #64748b;
  font-size: 14px;
}

.pf-topbar-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

/* ---------------------------------------------------------
   RAPPORTS — CONTAINER
   --------------------------------------------------------- */

.pf-reports-container {
  width: 100%;
  max-width: 1600px;
  margin: 0 auto;
}

/* ---------------------------------------------------------
   TOOLBAR PÉRIODE
   --------------------------------------------------------- */

.pf-reports-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 20px;
  padding: 18px 20px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.03);
}

.pf-toolbar-label {
  display: block;
  margin-bottom: 9px;
  color: #64748b;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.pf-period-buttons {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.pf-period-buttons button {
  min-height: 38px;
  padding: 0 16px;
  border: 1px solid #e2e8f0;
  border-radius: 9px;
  background: #ffffff;
  color: #475569;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}

.pf-period-buttons button:hover {
  border-color: #99d6ce;
  color: #0f766e;
  background: #f8fffd;
}

.pf-period-buttons button:active {
  transform: translateY(1px);
}

.pf-period-buttons button.active {
  border-color: #0f766e;
  background: #0f766e;
  color: #ffffff;
}

.pf-report-date {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
  white-space: nowrap;
}

.pf-report-date span {
  color: #94a3b8;
  font-size: 12px;
  font-weight: 600;
}

.pf-report-date strong {
  color: #334155;
  font-size: 13px;
}

/* ---------------------------------------------------------
   HERO RAPPORT
   --------------------------------------------------------- */

.pf-report-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  min-height: 190px;
  margin-bottom: 20px;
  padding: 30px 34px;
  border-radius: 20px;
  background:
    linear-gradient(
      135deg,
      #0f766e 0%,
      #115e59 100%
    );
  color: #ffffff;
  overflow: hidden;
  position: relative;
  box-shadow:
    0 12px 30px rgba(15, 118, 110, 0.16);
}

.pf-report-hero::before {
  content: "";
  position: absolute;
  width: 270px;
  height: 270px;
  right: -80px;
  top: -110px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 50%;
}

.pf-report-hero::after {
  content: "";
  position: absolute;
  width: 190px;
  height: 190px;
  right: 100px;
  bottom: -130px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 50%;
}

.pf-report-hero > div {
  position: relative;
  z-index: 2;
}

.pf-report-hero > div:first-child {
  max-width: 650px;
}

.pf-report-hero > div:first-child > span {
  display: inline-flex;
  align-items: center;
  min-height: 25px;
  padding: 0 9px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.82);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.pf-report-hero h2 {
  margin: 11px 0 5px;
  color: #ffffff;
  font-size: 30px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.pf-report-hero p {
  margin: 0;
  color: rgba(255, 255, 255, 0.76);
  font-size: 14px;
}

.pf-report-hero-value {
  min-width: 270px;
  padding-left: 30px;
  border-left: 1px solid rgba(255, 255, 255, 0.18);
  text-align: right;
}

.pf-report-hero-value span {
  display: block;
  margin-bottom: 7px;
  color: rgba(255, 255, 255, 0.68);
  font-size: 12px;
  font-weight: 600;
}

.pf-report-hero-value strong {
  display: block;
  color: #ffffff;
  font-size: 29px;
  line-height: 1.1;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.pf-report-hero-value small {
  display: block;
  margin-top: 7px;
  color: rgba(255, 255, 255, 0.68);
  font-size: 12px;
}

/* ---------------------------------------------------------
   STATISTIQUES
   --------------------------------------------------------- */

.pf-report-stats {
  margin-bottom: 20px;
}

.pf-report-stats .pf-stat-card {
  min-height: 125px;
  border: 1px solid #e2e8f0;
  background: #ffffff;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    border-color 0.2s ease;
}

.pf-report-stats .pf-stat-card:hover {
  transform: translateY(-2px);
  border-color: #cbd5e1;
  box-shadow:
    0 8px 22px rgba(15, 23, 42, 0.06);
}

.pf-report-stats .pf-stat-card > div:last-child {
  min-width: 0;
}

.pf-report-stats .pf-stat-card span {
  color: #64748b;
  font-size: 12px;
  font-weight: 600;
}

.pf-report-stats .pf-stat-card strong {
  display: block;
  margin-top: 5px;
  color: #0f172a;
  font-size: 21px;
  line-height: 1.15;
  font-weight: 800;
}

.pf-report-stats .pf-stat-card small {
  display: block;
  margin-top: 5px;
  color: #94a3b8;
  font-size: 11px;
}

.pf-stat-icon {
  flex-shrink: 0;
}

/* ---------------------------------------------------------
   GRILLE PRINCIPALE
   --------------------------------------------------------- */

.pf-reports-grid {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    minmax(0, 1fr);
  gap: 20px;
  margin-bottom: 20px;
}

.pf-card {
  min-width: 0;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  box-shadow:
    0 2px 8px rgba(15, 23, 42, 0.03);
}

.pf-report-financial-card,
.pf-payment-summary-card {
  min-height: 330px;
}

.pf-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding: 21px 22px;
  border-bottom: 1px solid #f1f5f9;
}

.pf-card-kicker {
  display: block;
  margin-bottom: 5px;
  color: #0f766e;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.09em;
}

.pf-card-header h3 {
  margin: 0;
  color: #0f172a;
  font-size: 17px;
  line-height: 1.25;
  font-weight: 800;
}

.pf-link-button {
  border: 0;
  background: transparent;
  padding: 4px 0;
  color: #0f766e;
  font-family: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}

.pf-link-button:hover {
  color: #115e59;
  text-decoration: underline;
}

/* ---------------------------------------------------------
   SYNTHÈSE FINANCIÈRE
   --------------------------------------------------------- */

.pf-financial-list {
  padding: 6px 22px 18px;
}

.pf-financial-list > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-height: 55px;
  border-bottom: 1px solid #f1f5f9;
}

.pf-financial-list > div:last-child {
  border-bottom: 0;
}

.pf-financial-list span {
  color: #64748b;
  font-size: 13px;
  font-weight: 500;
}

.pf-financial-list strong {
  color: #334155;
  font-size: 14px;
  font-weight: 700;
}

.pf-financial-list > div.total {
  margin-top: 6px;
  padding-top: 5px;
  border-top: 1px solid #e2e8f0;
  border-bottom: 0;
}

.pf-financial-list > div.total span {
  color: #0f172a;
  font-weight: 800;
}

.pf-financial-list > div.total strong {
  color: #0f766e;
  font-size: 18px;
  font-weight: 800;
}

/* ---------------------------------------------------------
   PAIEMENTS
   --------------------------------------------------------- */

.pf-payment-list {
  padding: 17px 22px 20px;
}

.pf-payment-row {
  margin-bottom: 17px;
}

.pf-payment-row:last-child {
  margin-bottom: 0;
}

.pf-payment-row-top,
.pf-payment-row-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.pf-payment-row-top span {
  color: #334155;
  font-size: 13px;
  font-weight: 600;
}

.pf-payment-row-top strong {
  color: #0f172a;
  font-size: 13px;
  font-weight: 800;
}

.pf-payment-progress {
  height: 7px;
  margin: 8px 0 6px;
  overflow: hidden;
  border-radius: 99px;
  background: #e2e8f0;
}

.pf-payment-progress span {
  display: block;
  height: 100%;
  min-width: 2px;
  border-radius: inherit;
  background: #0f766e;
}

.pf-payment-row-bottom span {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 500;
}

.pf-empty-small {
  min-height: 220px;
  padding: 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  text-align: center;
}

.pf-empty-small > div {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  margin-bottom: 12px;
  border-radius: 12px;
  background: #e6f5f2;
  font-size: 22px;
}

.pf-empty-small p {
  max-width: 260px;
  margin: 0;
  color: #94a3b8;
  font-size: 12px;
  line-height: 1.5;
}

/* ---------------------------------------------------------
   ÉTAT DU STOCK
   --------------------------------------------------------- */

.pf-stock-report-card {
  margin-bottom: 20px;
}

.pf-stock-report-grid {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 12px;
  padding: 20px 22px;
}

.pf-stock-metric {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  padding: 15px;
  border: 1px solid #eef2f6;
  border-radius: 12px;
  background: #fbfdfd;
}

.pf-stock-metric-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: #e6f5f2;
  font-size: 17px;
}

.pf-stock-metric > div {
  min-width: 0;
}

.pf-stock-metric > div > span {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 600;
}

.pf-stock-metric > div > strong {
  display: block;
  margin-top: 4px;
  color: #0f172a;
  font-size: 15px;
  line-height: 1.2;
  font-weight: 800;
}

.pf-stock-alerts {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 12px;
  padding: 0 22px 22px;
}

.pf-stock-alert {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
  padding: 13px;
  border: 1px solid #e2e8f0;
  border-radius: 11px;
  background: #ffffff;
}

.pf-stock-alert > span {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 31px;
  height: 31px;
  border-radius: 9px;
  background: #f1f5f9;
  color: #475569;
  font-size: 13px;
  font-weight: 800;
}

.pf-stock-alert > div {
  min-width: 0;
}

.pf-stock-alert strong {
  display: block;
  color: #334155;
  font-size: 11px;
  line-height: 1.3;
  font-weight: 800;
}

.pf-stock-alert small {
  display: block;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-stock-alert.warning > span {
  background: #fff7e6;
  color: #b45309;
}

.pf-stock-alert.danger > span {
  background: #fff0f0;
  color: #dc2626;
}

.pf-stock-alert.info > span {
  background: #eff6ff;
  color: #2563eb;
}
/* ---------------------------------------------------------
   TABLEAU DES VENTES
   --------------------------------------------------------- */

.pf-sales-report-card {
  margin-bottom: 20px;
  overflow: hidden;
}

.pf-table-wrap {
  width: 100%;
  overflow-x: auto;
}

.pf-table {
  width: 100%;
  border-collapse: collapse;
}

.pf-table th {
  height: 45px;
  padding: 0 22px;
  border-bottom: 1px solid #e2e8f0;
  background: #fafcfc;
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.pf-table td {
  min-height: 62px;
  padding: 13px 22px;
  border-bottom: 1px solid #f1f5f9;
  color: #475569;
  font-size: 12px;
  vertical-align: middle;
}

.pf-table tbody tr:last-child td {
  border-bottom: 0;
}

.pf-table tbody tr {
  transition: background 0.15s ease;
}

.pf-table tbody tr:hover {
  background: #fbfdfd;
}

.pf-table .text-right {
  text-align: right;
}

.pf-sale-number {
  color: #0f766e;
  font-size: 12px;
  font-weight: 800;
}

.pf-customer-cell {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.pf-customer-cell strong {
  color: #334155;
  font-size: 12px;
  font-weight: 700;
}

.pf-customer-cell small {
  color: #94a3b8;
  font-size: 10px;
}

.pf-status-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 25px;
  padding: 0 9px;
  border-radius: 99px;
  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
}

.pf-status-badge.success {
  background: #ecfdf5;
  color: #047857;
}

.pf-status-badge.warning {
  background: #fff7ed;
  color: #c2410c;
}

.pf-status-badge.danger {
  background: #fef2f2;
  color: #dc2626;
}

/* ---------------------------------------------------------
   EMPTY STATE
   --------------------------------------------------------- */

.pf-empty-state {
  min-height: 260px;
  padding: 35px 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  text-align: center;
}

.pf-empty-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin-bottom: 14px;
  border-radius: 15px;
  background: #e6f5f2;
  font-size: 24px;
}

.pf-empty-state h4 {
  margin: 0 0 6px;
  color: #334155;
  font-size: 15px;
  font-weight: 800;
}

.pf-empty-state p {
  max-width: 340px;
  margin: 0;
  color: #94a3b8;
  font-size: 12px;
}

/* ---------------------------------------------------------
   BAS DE PAGE
   --------------------------------------------------------- */

.pf-reports-bottom-grid {
  display: grid;
  grid-template-columns:
    minmax(0, 1.25fr)
    minmax(0, 0.75fr);
  gap: 20px;
  padding-bottom: 30px;
}

.pf-period-card {
  overflow: hidden;
}

.pf-quick-report-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding: 18px 22px 22px;
}

.pf-quick-report-grid button {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  padding: 14px;
  border: 1px solid #e2e8f0;
  border-radius: 11px;
  background: #ffffff;
  color: #334155;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease;
}

.pf-quick-report-grid button:hover {
  border-color: #99d6ce;
  background: #f8fffd;
  transform: translateY(-1px);
}

.pf-quick-report-grid button > span {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: #e6f5f2;
  color: #0f766e;
  font-size: 16px;
}

.pf-quick-report-grid button > div {
  min-width: 0;
}

.pf-quick-report-grid strong {
  display: block;
  color: #334155;
  font-size: 12px;
  font-weight: 800;
}

.pf-quick-report-grid small {
  display: block;
  margin-top: 4px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-report-note {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 25px;
  background: linear-gradient(
    145deg,
    #ffffff,
    #f8fcfb
  );
}

.pf-report-note-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: #e6f5f2;
  color: #0f766e;
  font-size: 19px;
  font-weight: 800;
}

.pf-report-note > div:last-child {
  min-width: 0;
}

.pf-report-note > div:last-child > span {
  display: block;
  margin-bottom: 6px;
  color: #0f766e;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.pf-report-note h3 {
  margin: 0;
  color: #0f172a;
  font-size: 17px;
  font-weight: 800;
}

.pf-report-note p {
  margin: 9px 0 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.65;
}

/* ---------------------------------------------------------
   PAGE CHARGEMENT
   --------------------------------------------------------- */

.pf-reports-loading {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  padding: 30px;
  background: #f5f8f8;
  text-align: center;
}

.pf-loading-spinner {
  width: 42px;
  height: 42px;
  margin-bottom: 18px;
  border: 4px solid #dcefeb;
  border-top-color: #0f766e;
  border-radius: 50%;
  animation: pf-report-spin 0.8s linear infinite;
}

.pf-reports-loading h2 {
  margin: 0;
  color: #0f172a;
  font-size: 18px;
  font-weight: 800;
}

.pf-reports-loading p {
  margin: 7px 0 0;
  color: #64748b;
  font-size: 13px;
}

@keyframes pf-report-spin {
  to {
    transform: rotate(360deg);
  }
}

/* ---------------------------------------------------------
   PAGE ERREUR
   --------------------------------------------------------- */

.pf-reports-error-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 30px;
  background: #f5f8f8;
}

.pf-error-card {
  width: 100%;
  max-width: 520px;
  padding: 35px;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: #ffffff;
  box-shadow:
    0 15px 40px rgba(15, 23, 42, 0.08);
  text-align: center;
}

.pf-error-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  margin: 0 auto 16px;
  border-radius: 50%;
  background: #fef2f2;
  color: #dc2626;
  font-size: 22px;
  font-weight: 900;
}

.pf-error-card h1 {
  margin: 0;
  color: #0f172a;
  font-size: 22px;
  font-weight: 800;
}

.pf-error-card p {
  margin: 10px 0 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.6;
}

.pf-error-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 22px;
}

/* ---------------------------------------------------------
   DOCUMENT D'IMPRESSION
   --------------------------------------------------------- */

.pf-reports-print-page {
  display: none;
}

/* ---------------------------------------------------------
   RESPONSIVE
   --------------------------------------------------------- */

@media (max-width: 1250px) {
  .pf-stock-report-grid,
  .pf-stock-alerts {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-reports-bottom-grid {
    grid-template-columns:
      minmax(0, 1fr);
  }
}

@media (max-width: 1050px) {
  .pf-reports-grid {
    grid-template-columns:
      minmax(0, 1fr);
  }

  .pf-report-hero {
    align-items: flex-start;
    flex-direction: column;
  }

  .pf-report-hero-value {
    width: 100%;
    min-width: 0;
    padding-top: 18px;
    padding-left: 0;
    border-top: 1px solid
      rgba(255, 255, 255, 0.18);
    border-left: 0;
    text-align: left;
  }

  .pf-reports-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .pf-report-date {
    align-items: flex-start;
  }
}

@media (max-width: 760px) {
  .pf-topbar {
    min-height: auto;
    padding: 18px 16px;
  }

  .pf-topbar h1 {
    font-size: 22px;
  }

  .pf-topbar p {
    font-size: 12px;
  }

  .pf-topbar-actions {
    width: 100%;
    justify-content: flex-start;
    margin-top: 12px;
  }

  .pf-topbar-actions .pf-btn {
    flex: 1;
    min-width: 120px;
  }

  .pf-content {
    padding: 16px;
  }

  .pf-reports-toolbar {
    padding: 15px;
    border-radius: 13px;
  }

  .pf-period-buttons {
    width: 100%;
  }

  .pf-period-buttons button {
    flex: 1;
    min-width: 0;
    padding: 0 9px;
    font-size: 11px;
  }

  .pf-report-hero {
    min-height: auto;
    padding: 24px;
    border-radius: 16px;
  }

  .pf-report-hero h2 {
    font-size: 24px;
  }

  .pf-report-hero-value strong {
    font-size: 24px;
  }

  .pf-report-stats {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-report-stats .pf-stat-card {
    min-height: 110px;
    padding: 14px;
  }

  .pf-report-stats .pf-stat-card strong {
    font-size: 17px;
  }

  .pf-stock-report-grid,
  .pf-stock-alerts {
    grid-template-columns:
      minmax(0, 1fr);
  }

  .pf-stock-report-grid {
    padding: 15px;
  }

  .pf-stock-alerts {
    padding: 0 15px 15px;
  }

  .pf-card-header {
    padding: 17px 15px;
  }

  .pf-quick-report-grid {
    grid-template-columns:
      minmax(0, 1fr);
    padding: 15px;
  }

  .pf-report-note {
    padding: 20px;
  }

  .pf-table {
    min-width: 700px;
  }

  .pf-table th,
  .pf-table td {
    padding-left: 14px;
    padding-right: 14px;
  }
}

@media (max-width: 480px) {
  .pf-report-stats {
    grid-template-columns:
      minmax(0, 1fr);
  }

  .pf-report-hero {
    padding: 20px;
  }

  .pf-report-hero h2 {
    font-size: 21px;
  }

  .pf-report-hero-value strong {
    font-size: 21px;
  }

  .pf-topbar-actions {
    display: grid;
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-topbar-actions .pf-btn {
    width: 100%;
  }

  .pf-error-card {
    padding: 25px 18px;
  }
}

/* ---------------------------------------------------------
   IMPRESSION — RAPPORT A4
   --------------------------------------------------------- */

@media print {
  @page {
    size: A4;
    margin: 12mm;
  }

  html,
  body {
    background: #ffffff !important;
    margin: 0 !important;
    padding: 0 !important;
  }

  body * {
    visibility: hidden !important;
  }

  .pf-reports-print-page,
  .pf-reports-print-page * {
    visibility: visible !important;
  }

  .pf-reports-print-page {
    display: block !important;
    position: relative !important;
    width: 100% !important;
    max-width: none !important;
    min-height: auto !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #ffffff !important;
    color: #0f172a !important;
  }

  .pf-print-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 25px;
    padding-bottom: 18px;
    border-bottom: 2px solid #0f766e;
  }

  .pf-print-brand {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 22px;
  }

  .pf-print-logo {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    border-radius: 9px;
    background: #0f766e;
    color: #ffffff;
    font-size: 17px;
    font-weight: 900;
  }

  .pf-print-brand strong {
    display: block;
    color: #0f172a;
    font-size: 17px;
    font-weight: 900;
  }

  .pf-print-brand small {
    display: block;
    margin-top: 2px;
    color: #64748b;
    font-size: 8px;
  }

  .pf-print-header h1 {
    margin: 0 0 5px;
    color: #0f172a;
    font-size: 24px;
    font-weight: 900;
  }

  .pf-print-header p {
    margin: 2px 0;
    color: #64748b;
    font-size: 9px;
  }

  .pf-print-meta {
    display: flex;
    align-items: flex-end;
    flex-direction: column;
    gap: 5px;
    text-align: right;
  }

  .pf-print-meta strong {
    color: #0f766e;
    font-size: 13px;
    font-weight: 900;
  }

  .pf-print-meta span {
    color: #64748b;
    font-size: 8px;
  }

  .pf-print-summary {
    display: grid;
    grid-template-columns:
      repeat(4, 1fr);
    gap: 8px;
    margin: 15px 0;
  }

  .pf-print-summary > div {
    padding: 10px;
    border: 1px solid #e2e8f0;
    border-radius: 7px;
  }

  .pf-print-summary span {
    display: block;
    color: #64748b;
    font-size: 8px;
  }

  .pf-print-summary strong {
    display: block;
    margin-top: 4px;
    color: #0f172a;
    font-size: 12px;
    font-weight: 900;
  }

  .pf-print-section {
    margin-top: 16px;
    page-break-inside: avoid;
  }

  .pf-print-section h2 {
    margin: 0 0 8px;
    padding-bottom: 5px;
    border-bottom: 1px solid #cbd5e1;
    color: #0f172a;
    font-size: 12px;
    font-weight: 900;
  }

  .pf-print-section table {
    width: 100%;
    border-collapse: collapse;
  }

  .pf-print-section th,
  .pf-print-section td {
    padding: 6px 7px;
    border-bottom: 1px solid #e2e8f0;
    color: #334155;
    font-size: 8px;
    text-align: left;
  }

  .pf-print-section th {
    background: #f1f5f9;
    color: #475569;
    font-size: 7px;
    font-weight: 900;
    text-transform: uppercase;
  }

  .pf-print-section td:last-child,
  .pf-print-section th:last-child {
    text-align: right;
  }

  .pf-print-section tr.print-total td {
    color: #0f766e;
    font-weight: 900;
  }

  .pf-print-stock-grid {
    display: grid;
    grid-template-columns:
      repeat(6, 1fr);
    gap: 7px;
  }

  .pf-print-stock-grid > div {
    padding: 8px;
    border: 1px solid #e2e8f0;
    border-radius: 6px;
  }

  .pf-print-stock-grid span {
    display: block;
    color: #64748b;
    font-size: 7px;
  }

  .pf-print-stock-grid strong {
    display: block;
    margin-top: 3px;
    color: #0f172a;
    font-size: 11px;
    font-weight: 900;
  }

  .pf-print-footer {
    display: flex;
    justify-content: space-between;
    gap: 20px;
    margin-top: 22px;
    padding-top: 8px;
    border-top: 1px solid #cbd5e1;
    color: #94a3b8;
    font-size: 7px;
  }
}
/* ============================================================
   PHARMAFLOW — RAPPORTS
   CSS COMPLET : INTERFACE + RESPONSIVE + IMPRESSION A4

   IMPORTANT :
   - Ce fichier contient UNIQUEMENT du CSS.
   - Ne jamais y coller le contenu de page.tsx.
   - Si tu l'integres a globals.css, place ce bloc a la fin.
   - Ne pas ajouter un autre @media print apres celui-ci.
   ============================================================ */

:root {
  --pf-report-primary: #0f766e;
  --pf-report-primary-dark: #115e59;
  --pf-report-primary-light: #e6f5f2;
  --pf-report-bg: #f5f8f8;
  --pf-report-surface: #ffffff;
  --pf-report-text: #0f172a;
  --pf-report-secondary: #334155;
  --pf-report-soft: #64748b;
  --pf-report-muted: #94a3b8;
  --pf-report-border: #e2e8f0;
  --pf-report-border-light: #edf2f7;
  --pf-report-success: #15803d;
  --pf-report-success-bg: #ecfdf3;
  --pf-report-warning: #b45309;
  --pf-report-warning-bg: #fff7ed;
  --pf-report-danger: #b91c1c;
  --pf-report-danger-bg: #fef2f2;
  --pf-report-info: #0369a1;
  --pf-report-info-bg: #eff6ff;
  --pf-report-sidebar-width: 270px;
  --pf-report-topbar-height: 76px;
  --pf-report-radius: 14px;
  --pf-report-shadow: 0 4px 18px rgba(15, 23, 42, 0.06);
}

/* ========================= BASE ========================= */

.pf-report-app {
  min-height: 100vh;
  width: 100%;
  display: flex;
  background: var(--pf-report-bg);
  color: var(--pf-report-text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.pf-report-app *,
.pf-print-report * {
  box-sizing: border-box;
}

/* ========================= SIDEBAR ========================= */

.pf-report-sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: var(--pf-report-sidebar-width);
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overflow-x: hidden;
  background: #fff;
  border-right: 1px solid var(--pf-report-border);
  z-index: 100;
}

.pf-report-brand {
  min-height: 88px;
  padding: 20px 22px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid var(--pf-report-border-light);
}

.pf-report-brand-icon,
.pf-report-pharmacy-logo {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 13px;
  background: var(--pf-report-primary);
  color: #fff;
  font-size: 23px;
  font-weight: 800;
}

.pf-report-brand strong {
  display: block;
  color: var(--pf-report-text);
  font-size: 17px;
  line-height: 1.2;
  font-weight: 800;
}

.pf-report-brand span {
  display: block;
  margin-top: 3px;
  color: var(--pf-report-muted);
  font-size: 10px;
  font-weight: 600;
}

.pf-report-sidebar-section {
  padding: 22px 14px 12px;
}

.pf-report-sidebar-section > span {
  display: block;
  padding: 0 12px 10px;
  color: var(--pf-report-muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
}

.pf-report-sidebar-section nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.pf-report-sidebar button {
  width: 100%;
  min-height: 45px;
  padding: 10px 13px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--pf-report-secondary);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: background .18s ease, color .18s ease;
}

.pf-report-sidebar button span {
  width: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--pf-report-soft);
  font-size: 17px;
}

.pf-report-sidebar button:hover {
  background: #f1f5f9;
  color: var(--pf-report-primary-dark);
}

.pf-report-sidebar button.active {
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary-dark);
  font-weight: 750;
}

.pf-report-sidebar button.active span {
  color: var(--pf-report-primary);
}

.pf-report-sidebar-bottom {
  margin-top: auto;
  padding: 14px;
  border-top: 1px solid var(--pf-report-border-light);
}

/* ========================= MAIN ========================= */

.pf-report-main {
  width: calc(100% - var(--pf-report-sidebar-width));
  min-width: 0;
  margin-left: var(--pf-report-sidebar-width);
}

.pf-report-topbar {
  min-height: var(--pf-report-topbar-height);
  padding: 18px 30px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255,255,255,.96);
  border-bottom: 1px solid var(--pf-report-border);
  backdrop-filter: blur(12px);
}

.pf-report-breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 5px;
  color: var(--pf-report-muted);
  font-size: 11px;
  font-weight: 600;
}

.pf-report-breadcrumb span {
  color: #cbd5e1;
}

.pf-report-topbar h1 {
  margin: 0;
  color: var(--pf-report-text);
  font-size: 26px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -.035em;
}

.pf-report-topbar p {
  margin: 4px 0 0;
  color: var(--pf-report-soft);
  font-size: 12px;
}

.pf-report-topbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ========================= BUTTONS ========================= */

.pf-report-primary-button,
.pf-report-secondary-button,
.pf-report-icon-button {
  min-height: 40px;
  border: 1px solid transparent;
  border-radius: 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 14px;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: transform .16s ease, background .16s ease, box-shadow .16s ease;
}

.pf-report-primary-button {
  background: var(--pf-report-primary);
  color: #fff;
  box-shadow: 0 4px 12px rgba(15,118,110,.18);
}

.pf-report-primary-button:hover {
  background: var(--pf-report-primary-dark);
  transform: translateY(-1px);
}

.pf-report-secondary-button,
.pf-report-icon-button {
  background: #fff;
  color: var(--pf-report-secondary);
  border-color: var(--pf-report-border);
}

.pf-report-secondary-button:hover,
.pf-report-icon-button:hover {
  background: #f8fafc;
  color: var(--pf-report-primary-dark);
}

.pf-report-icon-button {
  width: 40px;
  padding: 0;
  font-size: 18px;
}

/* ========================= CONTENT ========================= */

.pf-report-content {
  width: 100%;
  max-width: 1600px;
  margin: 0 auto;
  padding: 28px 30px 50px;
}

/* ========================= TOOLBAR ========================= */

.pf-report-toolbar {
  margin-bottom: 20px;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: #fff;
  border: 1px solid var(--pf-report-border);
  border-radius: var(--pf-report-radius);
  box-shadow: 0 1px 2px rgba(15,23,42,.04);
}

.pf-report-toolbar-label {
  display: block;
  margin-bottom: 8px;
  color: var(--pf-report-muted);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.pf-report-periods {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}

.pf-report-periods button {
  min-height: 34px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: #f1f5f9;
  color: var(--pf-report-soft);
  font: inherit;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.pf-report-periods button:hover {
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary-dark);
}

.pf-report-periods button.active {
  background: var(--pf-report-primary);
  color: #fff;
}

.pf-report-period-current {
  text-align: right;
}

.pf-report-period-current span {
  display: block;
  color: var(--pf-report-text);
  font-size: 13px;
  font-weight: 750;
}

.pf-report-period-current small {
  display: block;
  margin-top: 4px;
  color: var(--pf-report-primary);
  font-size: 10px;
}

/* ========================= HERO ========================= */

.pf-report-hero {
  min-height: 145px;
  margin-bottom: 20px;
  padding: 26px 28px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  overflow: hidden;
  border-radius: 20px;
  background: linear-gradient(135deg,#0f766e 0%,#115e59 100%);
  color: #fff;
  box-shadow: 0 14px 30px rgba(15,118,110,.18);
}

.pf-report-hero::after {
  content: "";
  position: absolute;
  width: 230px;
  height: 230px;
  right: -80px;
  top: -100px;
  border-radius: 50%;
  background: rgba(255,255,255,.08);
}

.pf-report-hero-copy,
.pf-report-hero-meta {
  position: relative;
  z-index: 1;
}

.pf-report-eyebrow {
  display: inline-block;
  margin-bottom: 8px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
  opacity: .75;
}

.pf-report-hero h2 {
  margin: 0;
  font-size: 25px;
  font-weight: 800;
  letter-spacing: -.03em;
}

.pf-report-hero p {
  margin: 5px 0 0;
  font-size: 12px;
  opacity: .78;
}

.pf-report-hero-meta {
  display: flex;
  align-items: center;
  gap: 30px;
}

.pf-report-hero-meta > div {
  min-width: 125px;
}

.pf-report-hero-meta span {
  display: block;
  margin-bottom: 5px;
  font-size: 9px;
  font-weight: 600;
  opacity: .68;
  text-transform: uppercase;
}

.pf-report-hero-meta strong {
  display: block;
  font-size: 12px;
  font-weight: 750;
}

/* ========================= KPI ========================= */

.pf-report-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 15px;
  margin-bottom: 20px;
}

.pf-report-kpi-card {
  min-height: 145px;
  padding: 18px;
  position: relative;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--pf-report-border);
  border-radius: var(--pf-report-radius);
  box-shadow: 0 1px 2px rgba(15,23,42,.04);
}

.pf-report-kpi-card::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 4px;
  height: 100%;
  background: var(--pf-report-primary);
}

.pf-report-kpi-card.sales::before { background: #2563eb; }
.pf-report-kpi-card.basket::before { background: #7c3aed; }
.pf-report-kpi-card.payment::before { background: #16a34a; }

.pf-report-kpi-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.pf-report-kpi-top > span {
  color: var(--pf-report-soft);
  font-size: 11px;
  font-weight: 700;
}

.pf-report-kpi-icon {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary);
  font-size: 16px;
  font-weight: 800;
}

.pf-report-kpi-card.sales .pf-report-kpi-icon { background: #eff6ff; color: #2563eb; }
.pf-report-kpi-card.basket .pf-report-kpi-icon { background: #f5f3ff; color: #7c3aed; }
.pf-report-kpi-card.payment .pf-report-kpi-icon { background: #f0fdf4; color: #16a34a; }

.pf-report-kpi-card > strong {
  display: block;
  margin-top: 17px;
  color: var(--pf-report-text);
  font-size: 23px;
  line-height: 1.1;
  font-weight: 800;
  letter-spacing: -.03em;
}

.pf-report-kpi-card > small {
  display: block;
  margin-top: 7px;
  color: var(--pf-report-muted);
  font-size: 10px;
}

/* ========================= PANELS ========================= */

.pf-report-panels,
.pf-report-two-columns {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 18px;
  margin-bottom: 18px;
}

.pf-report-panel {
  min-width: 0;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--pf-report-border);
  border-radius: 16px;
  box-shadow: 0 1px 2px rgba(15,23,42,.04);
}

.pf-report-panel-header {
  min-height: 72px;
  padding: 16px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-bottom: 1px solid var(--pf-report-border-light);
}

.pf-report-panel-heading {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.pf-report-panel-heading > div:last-child { min-width: 0; }

.pf-report-panel-heading h3 {
  margin: 0;
  color: var(--pf-report-text);
  font-size: 14px;
  line-height: 1.2;
  font-weight: 800;
}

.pf-report-panel-heading p {
  margin: 4px 0 0;
  color: var(--pf-report-muted);
  font-size: 10px;
  line-height: 1.4;
}

.pf-report-panel-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary);
  font-size: 17px;
  font-weight: 800;
}

.pf-report-panel-icon.finance { background: #ecfdf5; color: #047857; }
.pf-report-panel-icon.stock { background: #eff6ff; color: #2563eb; }
.pf-report-panel-icon.alert { background: #fff7ed; color: #c2410c; }
.pf-report-panel-icon.payment { background: #f0fdf4; color: #15803d; }
.pf-report-panel-icon.activity { background: #f5f3ff; color: #7c3aed; }
.pf-report-panel-icon.sales { background: #f0fdfa; color: #0f766e; }

/* ========================= FINANCE ========================= */

.pf-report-financial-list { padding: 5px 18px 10px; }

.pf-report-financial-row {
  min-height: 43px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-bottom: 1px solid var(--pf-report-border-light);
}

.pf-report-financial-row:last-child { border-bottom: 0; }
.pf-report-financial-row span { color: var(--pf-report-soft); font-size: 11px; font-weight: 600; }
.pf-report-financial-row strong { color: var(--pf-report-text); font-size: 12px; font-weight: 750; }
.pf-report-financial-row strong.negative { color: var(--pf-report-danger); }

.pf-report-financial-row.total {
  margin-top: 4px;
  padding-top: 5px;
  border-top: 1px solid var(--pf-report-border);
}

.pf-report-financial-row.total span,
.pf-report-financial-row.total strong {
  color: var(--pf-report-primary-dark);
  font-size: 13px;
  font-weight: 800;
}

.pf-report-financial-row.collected {
  margin-top: 3px;
  padding: 8px 10px;
  border: 0;
  border-radius: 8px;
  background: var(--pf-report-success-bg);
}

.pf-report-financial-row.collected span,
.pf-report-financial-row.collected strong { color: var(--pf-report-success); }

.pf-report-financial-footer { padding: 13px 18px 16px; }
.pf-report-financial-footer > div:first-child { display: flex; justify-content: space-between; margin-bottom: 7px; }
.pf-report-financial-footer span { color: var(--pf-report-muted); font-size: 10px; font-weight: 650; }
.pf-report-financial-footer strong { color: var(--pf-report-primary); font-size: 12px; }

.pf-report-mini-progress,
.pf-report-payment-bar {
  width: 100%;
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: #e2e8f0;
}

.pf-report-mini-progress span,
.pf-report-payment-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--pf-report-primary);
}

/* ========================= STOCK ========================= */

.pf-report-stock-grid {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 10px;
  padding: 16px 18px 18px;
}

.pf-report-stock-item {
  min-height: 100px;
  padding: 13px;
  border: 1px solid var(--pf-report-border-light);
  border-radius: 10px;
  background: #fafcfc;
}

.pf-report-stock-item span { display: block; color: var(--pf-report-soft); font-size: 10px; font-weight: 650; }
.pf-report-stock-item strong { display: block; margin-top: 8px; color: var(--pf-report-text); font-size: 21px; line-height: 1; font-weight: 800; }
.pf-report-stock-item small { display: block; margin-top: 7px; color: var(--pf-report-muted); font-size: 9px; }
.pf-report-stock-item.warning { background: var(--pf-report-warning-bg); border-color: #fed7aa; }
.pf-report-stock-item.warning strong { color: var(--pf-report-warning); }
.pf-report-stock-item.danger { background: var(--pf-report-danger-bg); border-color: #fecaca; }
.pf-report-stock-item.danger strong { color: var(--pf-report-danger); }
.pf-report-stock-item.info { background: var(--pf-report-info-bg); border-color: #bfdbfe; }
.pf-report-stock-item.info strong { color: var(--pf-report-info); }

/* ========================= ALERTS ========================= */

.pf-report-alert-panel { margin-bottom: 18px; }

.pf-report-alert-count {
  min-width: 27px;
  height: 27px;
  padding: 0 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: #f1f5f9;
  color: var(--pf-report-muted);
  font-size: 11px;
  font-weight: 800;
}

.pf-report-alert-count.has-alerts { background: var(--pf-report-danger-bg); color: var(--pf-report-danger); }

.pf-report-no-alerts {
  margin: 16px 18px 18px;
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 1px solid #bbf7d0;
  border-radius: 10px;
  background: var(--pf-report-success-bg);
}

.pf-report-success-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #dcfce7;
  color: var(--pf-report-success);
  font-weight: 800;
}

.pf-report-no-alerts strong { display: block; color: #166534; font-size: 11px; }
.pf-report-no-alerts span { display: block; margin-top: 3px; color: #4d7c5a; font-size: 10px; }

.pf-report-alert-list { display: grid; gap: 8px; padding: 15px 18px 18px; }

.pf-report-alert {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px;
  border: 1px solid transparent;
  border-radius: 10px;
}

.pf-report-alert.danger { background: var(--pf-report-danger-bg); border-color: #fecaca; }
.pf-report-alert.warning { background: var(--pf-report-warning-bg); border-color: #fed7aa; }
.pf-report-alert.info { background: var(--pf-report-info-bg); border-color: #bfdbfe; }

.pf-report-alert-symbol {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: #fff;
  font-size: 13px;
  font-weight: 900;
}

.pf-report-alert.danger .pf-report-alert-symbol { color: var(--pf-report-danger); }
.pf-report-alert.warning .pf-report-alert-symbol { color: var(--pf-report-warning); }
.pf-report-alert.info .pf-report-alert-symbol { color: var(--pf-report-info); }

.pf-report-alert-content { min-width: 0; }
.pf-report-alert-content strong { display: block; color: var(--pf-report-text); font-size: 11px; font-weight: 800; }
.pf-report-alert-content span { display: block; margin-top: 3px; color: var(--pf-report-soft); font-size: 10px; }

/* ========================= PAYMENT ========================= */

.pf-report-payment-list { padding: 15px 18px 18px; }
.pf-report-payment-item { padding: 10px 0; }
.pf-report-payment-item + .pf-report-payment-item { border-top: 1px solid var(--pf-report-border-light); }
.pf-report-payment-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.pf-report-payment-name { display: flex; align-items: center; gap: 8px; min-width: 0; }
.pf-report-payment-name strong,
.pf-report-payment-top > strong { color: var(--pf-report-text); font-size: 11px; }
.pf-report-payment-dot { width: 8px; height: 8px; flex: 0 0 8px; border-radius: 50%; background: var(--pf-report-primary); }
.pf-report-payment-bar { margin-top: 8px; height: 6px; }
.pf-report-payment-bottom { margin-top: 5px; display: flex; justify-content: space-between; color: var(--pf-report-muted); font-size: 9px; }

/* ========================= ACTIVITY ========================= */

.pf-report-activity-list { padding: 8px 18px 15px; }
.pf-report-activity-row { min-height: 55px; display: flex; align-items: center; gap: 11px; border-bottom: 1px solid var(--pf-report-border-light); }
.pf-report-activity-row:last-child { border-bottom: 0; }
.pf-report-activity-icon { width: 32px; height: 32px; flex: 0 0 32px; display: flex; align-items: center; justify-content: center; border-radius: 9px; background: var(--pf-report-primary-light); color: var(--pf-report-primary); font-size: 13px; font-weight: 800; }
.pf-report-activity-row strong { display: block; color: var(--pf-report-text); font-size: 12px; font-weight: 800; }
.pf-report-activity-row span { display: block; margin-top: 2px; color: var(--pf-report-muted); font-size: 9px; }

/* ========================= EMPTY ========================= */

.pf-report-empty { min-height: 145px; padding: 25px 18px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.pf-report-empty.large { min-height: 200px; }
.pf-report-empty-icon { width: 42px; height: 42px; margin-bottom: 10px; display: flex; align-items: center; justify-content: center; border-radius: 12px; background: #f1f5f9; color: var(--pf-report-muted); font-size: 18px; }
.pf-report-empty strong { color: var(--pf-report-secondary); font-size: 11px; }
.pf-report-empty span { margin-top: 4px; color: var(--pf-report-muted); font-size: 10px; }

/* ========================= SALES TABLE ========================= */

.pf-report-sales-panel { margin-bottom: 18px; }
.pf-report-panel-total { text-align: right; }
.pf-report-panel-total span { display: block; color: var(--pf-report-text); font-size: 15px; font-weight: 800; }
.pf-report-panel-total small { display: block; margin-top: 2px; color: var(--pf-report-muted); font-size: 9px; }

.pf-report-table-wrapper { width: 100%; overflow-x: auto; }
.pf-report-table { width: 100%; min-width: 720px; border-collapse: collapse; border-spacing: 0; }
.pf-report-table th { height: 39px; padding: 0 16px; background: #f8fafc; color: var(--pf-report-muted); border-bottom: 1px solid var(--pf-report-border); font-size: 9px; font-weight: 800; text-align: left; text-transform: uppercase; letter-spacing: .05em; white-space: nowrap; }
.pf-report-table td { height: 54px; padding: 8px 16px; color: var(--pf-report-secondary); border-bottom: 1px solid var(--pf-report-border-light); font-size: 10px; vertical-align: middle; }
.pf-report-table tbody tr:last-child td { border-bottom: 0; }
.pf-report-table tbody tr:hover td { background: #fbfefd; }
.pf-report-table .right { text-align: right; }
.pf-report-sale-number { color: var(--pf-report-text); font-size: 10px; font-weight: 800; }
.pf-report-date { color: var(--pf-report-soft); white-space: nowrap; }
.pf-report-customer { display: flex; align-items: center; gap: 8px; }
.pf-report-customer-avatar { width: 27px; height: 27px; flex: 0 0 27px; display: flex; align-items: center; justify-content: center; border-radius: 50%; background: var(--pf-report-primary-light); color: var(--pf-report-primary-dark); font-size: 9px; font-weight: 800; }
.pf-report-customer span { max-width: 180px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pf-report-payment-badge { display: inline-flex; align-items: center; min-height: 25px; padding: 0 8px; border-radius: 999px; background: #f1f5f9; color: var(--pf-report-secondary); font-size: 9px; font-weight: 700; white-space: nowrap; }
.pf-report-status { display: inline-flex; align-items: center; gap: 5px; min-height: 25px; padding: 0 8px; border-radius: 999px; font-size: 9px; font-weight: 750; white-space: nowrap; }
.pf-report-status i { width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
.pf-status-success { background: var(--pf-report-success-bg); color: var(--pf-report-success); }
.pf-status-warning { background: var(--pf-report-warning-bg); color: var(--pf-report-warning); }
.pf-status-danger { background: var(--pf-report-danger-bg); color: var(--pf-report-danger); }
.pf-status-neutral { background: #f1f5f9; color: var(--pf-report-soft); }
.pf-report-amount { color: var(--pf-report-text); font-size: 11px; font-weight: 800; }

/* ========================= PHARMACY ========================= */

.pf-report-pharmacy-card { margin-top: 18px; padding: 17px 18px; display: flex; align-items: center; gap: 13px; background: #fff; border: 1px solid var(--pf-report-border); border-radius: 16px; box-shadow: 0 1px 2px rgba(15,23,42,.04); }
.pf-report-pharmacy-info { min-width: 0; flex: 1; }
.pf-report-pharmacy-info strong { display: block; color: var(--pf-report-text); font-size: 12px; font-weight: 800; }
.pf-report-pharmacy-info span { display: block; margin-top: 3px; color: var(--pf-report-muted); font-size: 9px; }
.pf-report-pharmacy-meta { display: flex; align-items: center; gap: 24px; }
.pf-report-pharmacy-meta > div { min-width: 75px; }
.pf-report-pharmacy-meta span { display: block; color: var(--pf-report-muted); font-size: 9px; }
.pf-report-pharmacy-meta strong { display: block; margin-top: 4px; color: var(--pf-report-text); font-size: 11px; }

/* ========================= LOADING / ERROR ========================= */

.pf-report-loading-screen,
.pf-report-error-screen { min-height: 100vh; padding: 30px; display: flex; align-items: center; justify-content: center; background: #f5f8f8; }
.pf-report-loading-card,
.pf-report-error-card { width: min(420px,100%); padding: 38px 30px; text-align: center; background: #fff; border: 1px solid var(--pf-report-border); border-radius: 20px; box-shadow: 0 12px 30px rgba(15,23,42,.08); }
.pf-report-loading-logo { width: 58px; height: 58px; margin: 0 auto 18px; display: flex; align-items: center; justify-content: center; border-radius: 16px; background: var(--pf-report-primary); color: #fff; font-size: 30px; font-weight: 800; }
.pf-report-spinner { width: 30px; height: 30px; margin: 0 auto 18px; border: 3px solid #dbe7e6; border-top-color: var(--pf-report-primary); border-radius: 50%; animation: pf-report-spin .8s linear infinite; }
@keyframes pf-report-spin { to { transform: rotate(360deg); } }
.pf-report-loading-card h1,
.pf-report-error-card h1 { margin: 0; color: var(--pf-report-text); font-size: 18px; font-weight: 800; }
.pf-report-loading-card p,
.pf-report-error-card p { margin: 8px 0 0; color: var(--pf-report-soft); font-size: 11px; line-height: 1.6; }
.pf-report-error-icon { width: 48px; height: 48px; margin: 0 auto 16px; display: flex; align-items: center; justify-content: center; border-radius: 50%; background: var(--pf-report-danger-bg); color: var(--pf-report-danger); font-size: 20px; font-weight: 900; }

/* ========================= RESPONSIVE ========================= */

@media (max-width: 1200px) {
  .pf-report-kpi-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
}

@media (max-width: 980px) {
  .pf-report-sidebar { display: none; }
  .pf-report-main { width: 100%; margin-left: 0; }
  .pf-report-panels,
  .pf-report-two-columns { grid-template-columns: 1fr; }
  .pf-report-topbar { padding: 16px 20px; }
  .pf-report-content { padding: 22px 20px 40px; }
}

@media (max-width: 700px) {
  .pf-report-topbar { align-items: flex-start; flex-direction: column; }
  .pf-report-topbar-actions { width: 100%; flex-wrap: wrap; }
  .pf-report-primary-button,
  .pf-report-secondary-button { flex: 1; }
  .pf-report-toolbar { align-items: flex-start; flex-direction: column; }
  .pf-report-period-current { text-align: left; }
  .pf-report-hero { align-items: flex-start; flex-direction: column; }
  .pf-report-hero-meta { width: 100%; gap: 15px; flex-wrap: wrap; }
  .pf-report-kpi-grid { grid-template-columns: 1fr; }
  .pf-report-stock-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .pf-report-pharmacy-card { align-items: flex-start; flex-wrap: wrap; }
  .pf-report-pharmacy-meta { width: 100%; padding-top: 10px; border-top: 1px solid var(--pf-report-border-light); }
}

@media (max-width: 450px) {
  .pf-report-content { padding: 15px 12px 30px; }
  .pf-report-topbar { padding: 14px 12px; }
  .pf-report-topbar h1 { font-size: 22px; }
  .pf-report-stock-grid { grid-template-columns: 1fr; }
  .pf-report-hero { padding: 21px; }
  .pf-report-hero h2 { font-size: 21px; }
  .pf-report-panel-header { padding: 14px; }
}

.pf-report-app button:focus-visible { outline: 3px solid rgba(15,118,110,.22); outline-offset: 2px; }

/* ============================================================
   IMPRESSION A4 — IMPORTANT
   Le rapport imprimable existe dans page.tsx sous #pf-print-report.
   On masque toute l'application et on affiche seulement ce rapport.
   ============================================================ */

@media print {
  @page {
    size: A4 portrait;
    margin: 8mm 9mm 10mm;
  }

  html,
  body {
    width: 100% !important;
    min-width: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
    overflow: visible !important;
  }

  body {
    color: #0f172a !important;
    font-family: Arial, Helvetica, sans-serif !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
  }

  /* Masque toute l'application écran. */
  body * {
    visibility: hidden !important;
  }

  /* Affiche uniquement le rapport imprimable. */
  #pf-print-report,
  #pf-print-report * {
    visibility: visible !important;
  }

  #pf-print-report {
    position: absolute !important;
    left: 0 !important;
    top: 0 !important;
    z-index: 999999 !important;
    display: block !important;
    width: 100% !important;
    min-height: 100vh !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
    color: #0f172a !important;
    font-family: Arial, Helvetica, sans-serif !important;
  }

  .pf-report-app,
  .pf-report-sidebar,
  .pf-report-main,
  .pf-report-topbar,
  .pf-report-content,
  .pf-report-toolbar,
  .pf-report-topbar-actions,
  .pf-report-loading-screen,
  .pf-report-error-screen {
    display: none !important;
  }

  /* ==================== PRINT HEADER ==================== */

  .pf-print-header {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 8mm !important;
    margin-bottom: 5mm !important;
    padding-bottom: 4mm !important;
    border-bottom: 2px solid #0f766e !important;
  }

  .pf-print-brand {
    display: flex !important;
    align-items: center !important;
    gap: 3mm !important;
  }

  .pf-print-logo {
    width: 12mm !important;
    height: 12mm !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    border-radius: 3mm !important;
    background: #0f766e !important;
    color: #fff !important;
    font-size: 17pt !important;
    font-weight: 800 !important;
  }

  .pf-print-brand-name {
    color: #0f766e !important;
    font-size: 14pt !important;
    line-height: 1.1 !important;
    font-weight: 800 !important;
  }

  .pf-print-brand-subtitle {
    margin-top: 1mm !important;
    color: #64748b !important;
    font-size: 7pt !important;
  }

  .pf-print-title-block {
    text-align: right !important;
  }

  .pf-print-title-block h1 {
    margin: 0 !important;
    color: #0f172a !important;
    font-size: 17pt !important;
    line-height: 1.1 !important;
    font-weight: 800 !important;
  }

  .pf-print-title-block p {
    margin: 1.5mm 0 0 !important;
    color: #64748b !important;
    font-size: 8pt !important;
  }

  /* ==================== PRINT INFORMATION ==================== */

  .pf-print-information {
    display: grid !important;
    grid-template-columns: repeat(4,minmax(0,1fr)) !important;
    gap: 3mm !important;
    margin-bottom: 5mm !important;
  }

  .pf-print-information > div {
    min-width: 0 !important;
    padding: 3mm !important;
    border: 1px solid #dbe4e8 !important;
    border-radius: 2mm !important;
    background: #f8fafc !important;
  }

  .pf-print-information span {
    display: block !important;
    margin-bottom: 1mm !important;
    color: #64748b !important;
    font-size: 6.5pt !important;
    font-weight: 700 !important;
    text-transform: uppercase !important;
  }

  .pf-print-information strong {
    display: block !important;
    overflow-wrap: anywhere !important;
    color: #0f172a !important;
    font-size: 8pt !important;
  }

  /* ==================== PRINT KPIs ==================== */

  .pf-print-kpis {
    display: grid !important;
    grid-template-columns: repeat(4,minmax(0,1fr)) !important;
    gap: 3mm !important;
    margin-bottom: 5mm !important;
  }

  .pf-print-kpis > div {
    min-width: 0 !important;
    padding: 3.5mm !important;
    border: 1px solid #dbe4e8 !important;
    border-top: 2px solid #0f766e !important;
    border-radius: 2mm !important;
    background: #fff !important;
  }

  .pf-print-kpis span {
    display: block !important;
    color: #64748b !important;
    font-size: 6.8pt !important;
    font-weight: 700 !important;
  }

  .pf-print-kpis strong {
    display: block !important;
    margin-top: 1.5mm !important;
    color: #0f172a !important;
    font-size: 11pt !important;
    font-weight: 800 !important;
  }

  /* ==================== PRINT SECTIONS ==================== */

  .pf-print-section {
    display: block !important;
    width: 100% !important;
    margin: 0 0 5mm !important;
    padding: 0 !important;
    break-inside: avoid !important;
    page-break-inside: avoid !important;
  }

  .pf-print-section h2 {
    margin: 0 0 2.5mm !important;
    padding: 2.2mm 3mm !important;
    color: #0f172a !important;
    background: #f1f5f9 !important;
    border-left: 3px solid #0f766e !important;
    font-size: 9.5pt !important;
    line-height: 1.2 !important;
    font-weight: 800 !important;
    break-after: avoid !important;
    page-break-after: avoid !important;
  }

  .pf-print-section table {
    width: 100% !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    font-size: 7.4pt !important;
  }

  .pf-print-section thead {
    display: table-header-group !important;
  }

  .pf-print-section tfoot {
    display: table-footer-group !important;
  }

  .pf-print-section tr {
    break-inside: avoid !important;
    page-break-inside: avoid !important;
  }

  .pf-print-section th {
    padding: 2mm 2.5mm !important;
    background: #0f766e !important;
    color: #fff !important;
    border: 1px solid #0f766e !important;
    font-size: 6.8pt !important;
    line-height: 1.25 !important;
    font-weight: 800 !important;
    text-align: left !important;
    vertical-align: middle !important;
  }

  .pf-print-section td {
    padding: 1.8mm 2.5mm !important;
    color: #1e293b !important;
    border: 1px solid #dbe4e8 !important;
    font-size: 7.4pt !important;
    line-height: 1.3 !important;
    vertical-align: middle !important;
  }

  .pf-print-section tbody tr:nth-child(even) td {
    background: #f8fafc !important;
  }

  .pf-print-section td strong {
    font-weight: 800 !important;
  }

  .pf-print-section tr.total td {
    background: #e6f5f2 !important;
    color: #115e59 !important;
    font-weight: 800 !important;
  }

  .pf-print-section tr.collected td {
    background: #ecfdf3 !important;
    color: #166534 !important;
    font-weight: 800 !important;
  }

  /* ==================== PRINT EMPTY / SUCCESS ==================== */

  .pf-print-empty,
  .pf-print-success {
    padding: 4mm !important;
    border-radius: 2mm !important;
    font-size: 8pt !important;
  }

  .pf-print-empty {
    border: 1px solid #dbe4e8 !important;
    background: #f8fafc !important;
    color: #64748b !important;
    text-align: center !important;
  }

  .pf-print-success {
    border: 1px solid #bbf7d0 !important;
    background: #f0fdf4 !important;
    color: #166534 !important;
    font-weight: 700 !important;
  }

  /* ==================== PRINT SALES ==================== */

  .pf-print-sales {
    break-inside: auto !important;
    page-break-inside: auto !important;
  }

  .pf-print-sales table {
    break-inside: auto !important;
    page-break-inside: auto !important;
  }

  .pf-print-sales tr {
    break-inside: avoid !important;
    page-break-inside: avoid !important;
  }

  .pf-print-sales td:nth-child(1) { width: 14%; }
  .pf-print-sales td:nth-child(2) { width: 18%; }
  .pf-print-sales td:nth-child(3) { width: 22%; }
  .pf-print-sales td:nth-child(4) { width: 18%; }
  .pf-print-sales td:nth-child(5) { width: 14%; }
  .pf-print-sales td:nth-child(6) { width: 14%; text-align: right !important; }
  .pf-print-sales th:last-child { text-align: right !important; }

  /* ==================== PRINT FOOTER ==================== */

  .pf-print-footer {
    margin-top: 6mm !important;
    padding-top: 3mm !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-wrap: wrap !important;
    gap: 1.5mm !important;
    border-top: 1px solid #cbd5e1 !important;
    color: #64748b !important;
    font-size: 7pt !important;
    text-align: center !important;
  }

  .pf-print-footer strong {
    color: #0f766e !important;
    font-weight: 800 !important;
  }

  /* Sécurité contre les marges et ombres écran. */
  #pf-print-report h1,
  #pf-print-report h2,
  #pf-print-report h3,
  #pf-print-report p,
  #pf-print-report table {
    max-width: 100% !important;
  }

  #pf-print-report,
  #pf-print-report * {
    box-shadow: none !important;
    text-shadow: none !important;
  }
}

/* ============================================================
   FIN DU CSS PHARMAFLOW RAPPORTS
   ============================================================ */
/* ============================================================
   PHARMAFLOW — RAPPORTS
   CSS COMPLET : INTERFACE + RESPONSIVE + IMPRESSION A4

   IMPORTANT :
   - Ce fichier contient UNIQUEMENT du CSS.
   - Ne jamais y coller le contenu de page.tsx.
   - Si tu l'integres a globals.css, place ce bloc a la fin.
   - Ne pas ajouter un autre @media print apres celui-ci.
   ============================================================ */

:root {
  --pf-report-primary: #0f766e;
  --pf-report-primary-dark: #115e59;
  --pf-report-primary-light: #e6f5f2;
  --pf-report-bg: #f5f8f8;
  --pf-report-surface: #ffffff;
  --pf-report-text: #0f172a;
  --pf-report-secondary: #334155;
  --pf-report-soft: #64748b;
  --pf-report-muted: #94a3b8;
  --pf-report-border: #e2e8f0;
  --pf-report-border-light: #edf2f7;
  --pf-report-success: #15803d;
  --pf-report-success-bg: #ecfdf3;
  --pf-report-warning: #b45309;
  --pf-report-warning-bg: #fff7ed;
  --pf-report-danger: #b91c1c;
  --pf-report-danger-bg: #fef2f2;
  --pf-report-info: #0369a1;
  --pf-report-info-bg: #eff6ff;
  --pf-report-sidebar-width: 270px;
  --pf-report-topbar-height: 76px;
  --pf-report-radius: 14px;
  --pf-report-shadow: 0 4px 18px rgba(15, 23, 42, 0.06);
}

/* ========================= BASE ========================= */

/* IMPORTANT : la version imprimable doit être totalement invisible
   pendant l'affichage normal de /rapports. Elle ne doit apparaître
   que lorsque le navigateur passe en mode impression. */
.pf-print-report {
  display: none !important;
  position: absolute !important;
  width: 0 !important;
  height: 0 !important;
  overflow: hidden !important;
  visibility: hidden !important;
}


.pf-report-app {
  min-height: 100vh;
  width: 100%;
  display: flex;
  background: var(--pf-report-bg);
  color: var(--pf-report-text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.pf-report-app *,
.pf-print-report * {
  box-sizing: border-box;
}

/* ========================= SIDEBAR ========================= */

.pf-report-sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: var(--pf-report-sidebar-width);
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overflow-x: hidden;
  background: #fff;
  border-right: 1px solid var(--pf-report-border);
  z-index: 100;
}

.pf-report-brand {
  min-height: 88px;
  padding: 20px 22px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid var(--pf-report-border-light);
}

.pf-report-brand-icon,
.pf-report-pharmacy-logo {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 13px;
  background: var(--pf-report-primary);
  color: #fff;
  font-size: 23px;
  font-weight: 800;
}

.pf-report-brand strong {
  display: block;
  color: var(--pf-report-text);
  font-size: 17px;
  line-height: 1.2;
  font-weight: 800;
}

.pf-report-brand span {
  display: block;
  margin-top: 3px;
  color: var(--pf-report-muted);
  font-size: 10px;
  font-weight: 600;
}

.pf-report-sidebar-section {
  padding: 22px 14px 12px;
}

.pf-report-sidebar-section > span {
  display: block;
  padding: 0 12px 10px;
  color: var(--pf-report-muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
}

.pf-report-sidebar-section nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.pf-report-sidebar button {
  width: 100%;
  min-height: 45px;
  padding: 10px 13px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--pf-report-secondary);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: background .18s ease, color .18s ease;
}

.pf-report-sidebar button span {
  width: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--pf-report-soft);
  font-size: 17px;
}

.pf-report-sidebar button:hover {
  background: #f1f5f9;
  color: var(--pf-report-primary-dark);
}

.pf-report-sidebar button.active {
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary-dark);
  font-weight: 750;
}

.pf-report-sidebar button.active span {
  color: var(--pf-report-primary);
}

.pf-report-sidebar-bottom {
  margin-top: auto;
  padding: 14px;
  border-top: 1px solid var(--pf-report-border-light);
}

/* ========================= MAIN ========================= */

.pf-report-main {
  width: calc(100% - var(--pf-report-sidebar-width));
  min-width: 0;
  margin-left: var(--pf-report-sidebar-width);
}

.pf-report-topbar {
  min-height: var(--pf-report-topbar-height);
  padding: 18px 30px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255,255,255,.96);
  border-bottom: 1px solid var(--pf-report-border);
  backdrop-filter: blur(12px);
}

.pf-report-breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 5px;
  color: var(--pf-report-muted);
  font-size: 11px;
  font-weight: 600;
}

.pf-report-breadcrumb span {
  color: #cbd5e1;
}

.pf-report-topbar h1 {
  margin: 0;
  color: var(--pf-report-text);
  font-size: 26px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -.035em;
}

.pf-report-topbar p {
  margin: 4px 0 0;
  color: var(--pf-report-soft);
  font-size: 12px;
}

.pf-report-topbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ========================= BUTTONS ========================= */

.pf-report-primary-button,
.pf-report-secondary-button,
.pf-report-icon-button {
  min-height: 40px;
  border: 1px solid transparent;
  border-radius: 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 14px;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: transform .16s ease, background .16s ease, box-shadow .16s ease;
}

.pf-report-primary-button {
  background: var(--pf-report-primary);
  color: #fff;
  box-shadow: 0 4px 12px rgba(15,118,110,.18);
}

.pf-report-primary-button:hover {
  background: var(--pf-report-primary-dark);
  transform: translateY(-1px);
}

.pf-report-secondary-button,
.pf-report-icon-button {
  background: #fff;
  color: var(--pf-report-secondary);
  border-color: var(--pf-report-border);
}

.pf-report-secondary-button:hover,
.pf-report-icon-button:hover {
  background: #f8fafc;
  color: var(--pf-report-primary-dark);
}

.pf-report-icon-button {
  width: 40px;
  padding: 0;
  font-size: 18px;
}

/* ========================= CONTENT ========================= */

.pf-report-content {
  width: 100%;
  max-width: 1600px;
  margin: 0 auto;
  padding: 28px 30px 50px;
}

/* ========================= TOOLBAR ========================= */

.pf-report-toolbar {
  margin-bottom: 20px;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: #fff;
  border: 1px solid var(--pf-report-border);
  border-radius: var(--pf-report-radius);
  box-shadow: 0 1px 2px rgba(15,23,42,.04);
}

.pf-report-toolbar-label {
  display: block;
  margin-bottom: 8px;
  color: var(--pf-report-muted);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.pf-report-periods {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}

.pf-report-periods button {
  min-height: 34px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: #f1f5f9;
  color: var(--pf-report-soft);
  font: inherit;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.pf-report-periods button:hover {
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary-dark);
}

.pf-report-periods button.active {
  background: var(--pf-report-primary);
  color: #fff;
}

.pf-report-period-current {
  text-align: right;
}

.pf-report-period-current span {
  display: block;
  color: var(--pf-report-text);
  font-size: 13px;
  font-weight: 750;
}

.pf-report-period-current small {
  display: block;
  margin-top: 4px;
  color: var(--pf-report-primary);
  font-size: 10px;
}

/* ========================= HERO ========================= */

.pf-report-hero {
  min-height: 145px;
  margin-bottom: 20px;
  padding: 26px 28px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  overflow: hidden;
  border-radius: 20px;
  background: linear-gradient(135deg,#0f766e 0%,#115e59 100%);
  color: #fff;
  box-shadow: 0 14px 30px rgba(15,118,110,.18);
}

.pf-report-hero::after {
  content: "";
  position: absolute;
  width: 230px;
  height: 230px;
  right: -80px;
  top: -100px;
  border-radius: 50%;
  background: rgba(255,255,255,.08);
}

.pf-report-hero-copy,
.pf-report-hero-meta {
  position: relative;
  z-index: 1;
}

.pf-report-eyebrow {
  display: inline-block;
  margin-bottom: 8px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
  opacity: .75;
}

.pf-report-hero h2 {
  margin: 0;
  font-size: 25px;
  font-weight: 800;
  letter-spacing: -.03em;
}

.pf-report-hero p {
  margin: 5px 0 0;
  font-size: 12px;
  opacity: .78;
}

.pf-report-hero-meta {
  display: flex;
  align-items: center;
  gap: 30px;
}

.pf-report-hero-meta > div {
  min-width: 125px;
}

.pf-report-hero-meta span {
  display: block;
  margin-bottom: 5px;
  font-size: 9px;
  font-weight: 600;
  opacity: .68;
  text-transform: uppercase;
}

.pf-report-hero-meta strong {
  display: block;
  font-size: 12px;
  font-weight: 750;
}

/* ========================= KPI ========================= */

.pf-report-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 15px;
  margin-bottom: 20px;
}

.pf-report-kpi-card {
  min-height: 145px;
  padding: 18px;
  position: relative;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--pf-report-border);
  border-radius: var(--pf-report-radius);
  box-shadow: 0 1px 2px rgba(15,23,42,.04);
}

.pf-report-kpi-card::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 4px;
  height: 100%;
  background: var(--pf-report-primary);
}

.pf-report-kpi-card.sales::before { background: #2563eb; }
.pf-report-kpi-card.basket::before { background: #7c3aed; }
.pf-report-kpi-card.payment::before { background: #16a34a; }

.pf-report-kpi-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.pf-report-kpi-top > span {
  color: var(--pf-report-soft);
  font-size: 11px;
  font-weight: 700;
}

.pf-report-kpi-icon {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary);
  font-size: 16px;
  font-weight: 800;
}

.pf-report-kpi-card.sales .pf-report-kpi-icon { background: #eff6ff; color: #2563eb; }
.pf-report-kpi-card.basket .pf-report-kpi-icon { background: #f5f3ff; color: #7c3aed; }
.pf-report-kpi-card.payment .pf-report-kpi-icon { background: #f0fdf4; color: #16a34a; }

.pf-report-kpi-card > strong {
  display: block;
  margin-top: 17px;
  color: var(--pf-report-text);
  font-size: 23px;
  line-height: 1.1;
  font-weight: 800;
  letter-spacing: -.03em;
}

.pf-report-kpi-card > small {
  display: block;
  margin-top: 7px;
  color: var(--pf-report-muted);
  font-size: 10px;
}

/* ========================= PANELS ========================= */

.pf-report-panels,
.pf-report-two-columns {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 18px;
  margin-bottom: 18px;
}

.pf-report-panel {
  min-width: 0;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--pf-report-border);
  border-radius: 16px;
  box-shadow: 0 1px 2px rgba(15,23,42,.04);
}

.pf-report-panel-header {
  min-height: 72px;
  padding: 16px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-bottom: 1px solid var(--pf-report-border-light);
}

.pf-report-panel-heading {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.pf-report-panel-heading > div:last-child { min-width: 0; }

.pf-report-panel-heading h3 {
  margin: 0;
  color: var(--pf-report-text);
  font-size: 14px;
  line-height: 1.2;
  font-weight: 800;
}

.pf-report-panel-heading p {
  margin: 4px 0 0;
  color: var(--pf-report-muted);
  font-size: 10px;
  line-height: 1.4;
}

.pf-report-panel-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary);
  font-size: 17px;
  font-weight: 800;
}

.pf-report-panel-icon.finance { background: #ecfdf5; color: #047857; }
.pf-report-panel-icon.stock { background: #eff6ff; color: #2563eb; }
.pf-report-panel-icon.alert { background: #fff7ed; color: #c2410c; }
.pf-report-panel-icon.payment { background: #f0fdf4; color: #15803d; }
.pf-report-panel-icon.activity { background: #f5f3ff; color: #7c3aed; }
.pf-report-panel-icon.sales { background: #f0fdfa; color: #0f766e; }

/* ========================= FINANCE ========================= */

.pf-report-financial-list { padding: 5px 18px 10px; }

.pf-report-financial-row {
  min-height: 43px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-bottom: 1px solid var(--pf-report-border-light);
}

.pf-report-financial-row:last-child { border-bottom: 0; }
.pf-report-financial-row span { color: var(--pf-report-soft); font-size: 11px; font-weight: 600; }
.pf-report-financial-row strong { color: var(--pf-report-text); font-size: 12px; font-weight: 750; }
.pf-report-financial-row strong.negative { color: var(--pf-report-danger); }

.pf-report-financial-row.total {
  margin-top: 4px;
  padding-top: 5px;
  border-top: 1px solid var(--pf-report-border);
}

.pf-report-financial-row.total span,
.pf-report-financial-row.total strong {
  color: var(--pf-report-primary-dark);
  font-size: 13px;
  font-weight: 800;
}

.pf-report-financial-row.collected {
  margin-top: 3px;
  padding: 8px 10px;
  border: 0;
  border-radius: 8px;
  background: var(--pf-report-success-bg);
}

.pf-report-financial-row.collected span,
.pf-report-financial-row.collected strong { color: var(--pf-report-success); }

.pf-report-financial-footer { padding: 13px 18px 16px; }
.pf-report-financial-footer > div:first-child { display: flex; justify-content: space-between; margin-bottom: 7px; }
.pf-report-financial-footer span { color: var(--pf-report-muted); font-size: 10px; font-weight: 650; }
.pf-report-financial-footer strong { color: var(--pf-report-primary); font-size: 12px; }

.pf-report-mini-progress,
.pf-report-payment-bar {
  width: 100%;
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: #e2e8f0;
}

.pf-report-mini-progress span,
.pf-report-payment-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--pf-report-primary);
}

/* ========================= STOCK ========================= */

.pf-report-stock-grid {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 10px;
  padding: 16px 18px 18px;
}

.pf-report-stock-item {
  min-height: 100px;
  padding: 13px;
  border: 1px solid var(--pf-report-border-light);
  border-radius: 10px;
  background: #fafcfc;
}

.pf-report-stock-item span { display: block; color: var(--pf-report-soft); font-size: 10px; font-weight: 650; }
.pf-report-stock-item strong { display: block; margin-top: 8px; color: var(--pf-report-text); font-size: 21px; line-height: 1; font-weight: 800; }
.pf-report-stock-item small { display: block; margin-top: 7px; color: var(--pf-report-muted); font-size: 9px; }
.pf-report-stock-item.warning { background: var(--pf-report-warning-bg); border-color: #fed7aa; }
.pf-report-stock-item.warning strong { color: var(--pf-report-warning); }
.pf-report-stock-item.danger { background: var(--pf-report-danger-bg); border-color: #fecaca; }
.pf-report-stock-item.danger strong { color: var(--pf-report-danger); }
.pf-report-stock-item.info { background: var(--pf-report-info-bg); border-color: #bfdbfe; }
.pf-report-stock-item.info strong { color: var(--pf-report-info); }

/* ========================= ALERTS ========================= */

.pf-report-alert-panel { margin-bottom: 18px; }

.pf-report-alert-count {
  min-width: 27px;
  height: 27px;
  padding: 0 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: #f1f5f9;
  color: var(--pf-report-muted);
  font-size: 11px;
  font-weight: 800;
}

.pf-report-alert-count.has-alerts { background: var(--pf-report-danger-bg); color: var(--pf-report-danger); }

.pf-report-no-alerts {
  margin: 16px 18px 18px;
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 1px solid #bbf7d0;
  border-radius: 10px;
  background: var(--pf-report-success-bg);
}

.pf-report-success-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #dcfce7;
  color: var(--pf-report-success);
  font-weight: 800;
}

.pf-report-no-alerts strong { display: block; color: #166534; font-size: 11px; }
.pf-report-no-alerts span { display: block; margin-top: 3px; color: #4d7c5a; font-size: 10px; }

.pf-report-alert-list { display: grid; gap: 8px; padding: 15px 18px 18px; }

.pf-report-alert {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px;
  border: 1px solid transparent;
  border-radius: 10px;
}

.pf-report-alert.danger { background: var(--pf-report-danger-bg); border-color: #fecaca; }
.pf-report-alert.warning { background: var(--pf-report-warning-bg); border-color: #fed7aa; }
.pf-report-alert.info { background: var(--pf-report-info-bg); border-color: #bfdbfe; }

.pf-report-alert-symbol {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: #fff;
  font-size: 13px;
  font-weight: 900;
}

.pf-report-alert.danger .pf-report-alert-symbol { color: var(--pf-report-danger); }
.pf-report-alert.warning .pf-report-alert-symbol { color: var(--pf-report-warning); }
.pf-report-alert.info .pf-report-alert-symbol { color: var(--pf-report-info); }

.pf-report-alert-content { min-width: 0; }
.pf-report-alert-content strong { display: block; color: var(--pf-report-text); font-size: 11px; font-weight: 800; }
.pf-report-alert-content span { display: block; margin-top: 3px; color: var(--pf-report-soft); font-size: 10px; }

/* ========================= PAYMENT ========================= */

.pf-report-payment-list { padding: 15px 18px 18px; }
.pf-report-payment-item { padding: 10px 0; }
.pf-report-payment-item + .pf-report-payment-item { border-top: 1px solid var(--pf-report-border-light); }
.pf-report-payment-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.pf-report-payment-name { display: flex; align-items: center; gap: 8px; min-width: 0; }
.pf-report-payment-name strong,
.pf-report-payment-top > strong { color: var(--pf-report-text); font-size: 11px; }
.pf-report-payment-dot { width: 8px; height: 8px; flex: 0 0 8px; border-radius: 50%; background: var(--pf-report-primary); }
.pf-report-payment-bar { margin-top: 8px; height: 6px; }
.pf-report-payment-bottom { margin-top: 5px; display: flex; justify-content: space-between; color: var(--pf-report-muted); font-size: 9px; }

/* ========================= ACTIVITY ========================= */

.pf-report-activity-list { padding: 8px 18px 15px; }
.pf-report-activity-row { min-height: 55px; display: flex; align-items: center; gap: 11px; border-bottom: 1px solid var(--pf-report-border-light); }
.pf-report-activity-row:last-child { border-bottom: 0; }
.pf-report-activity-icon { width: 32px; height: 32px; flex: 0 0 32px; display: flex; align-items: center; justify-content: center; border-radius: 9px; background: var(--pf-report-primary-light); color: var(--pf-report-primary); font-size: 13px; font-weight: 800; }
.pf-report-activity-row strong { display: block; color: var(--pf-report-text); font-size: 12px; font-weight: 800; }
.pf-report-activity-row span { display: block; margin-top: 2px; color: var(--pf-report-muted); font-size: 9px; }

/* ========================= EMPTY ========================= */

.pf-report-empty { min-height: 145px; padding: 25px 18px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.pf-report-empty.large { min-height: 200px; }
.pf-report-empty-icon { width: 42px; height: 42px; margin-bottom: 10px; display: flex; align-items: center; justify-content: center; border-radius: 12px; background: #f1f5f9; color: var(--pf-report-muted); font-size: 18px; }
.pf-report-empty strong { color: var(--pf-report-secondary); font-size: 11px; }
.pf-report-empty span { margin-top: 4px; color: var(--pf-report-muted); font-size: 10px; }

/* ========================= SALES TABLE ========================= */

.pf-report-sales-panel { margin-bottom: 18px; }
.pf-report-panel-total { text-align: right; }
.pf-report-panel-total span { display: block; color: var(--pf-report-text); font-size: 15px; font-weight: 800; }
.pf-report-panel-total small { display: block; margin-top: 2px; color: var(--pf-report-muted); font-size: 9px; }

.pf-report-table-wrapper { width: 100%; overflow-x: auto; }
.pf-report-table { width: 100%; min-width: 720px; border-collapse: collapse; border-spacing: 0; }
.pf-report-table th { height: 39px; padding: 0 16px; background: #f8fafc; color: var(--pf-report-muted); border-bottom: 1px solid var(--pf-report-border); font-size: 9px; font-weight: 800; text-align: left; text-transform: uppercase; letter-spacing: .05em; white-space: nowrap; }
.pf-report-table td { height: 54px; padding: 8px 16px; color: var(--pf-report-secondary); border-bottom: 1px solid var(--pf-report-border-light); font-size: 10px; vertical-align: middle; }
.pf-report-table tbody tr:last-child td { border-bottom: 0; }
.pf-report-table tbody tr:hover td { background: #fbfefd; }
.pf-report-table .right { text-align: right; }
.pf-report-sale-number { color: var(--pf-report-text); font-size: 10px; font-weight: 800; }
.pf-report-date { color: var(--pf-report-soft); white-space: nowrap; }
.pf-report-customer { display: flex; align-items: center; gap: 8px; }
.pf-report-customer-avatar { width: 27px; height: 27px; flex: 0 0 27px; display: flex; align-items: center; justify-content: center; border-radius: 50%; background: var(--pf-report-primary-light); color: var(--pf-report-primary-dark); font-size: 9px; font-weight: 800; }
.pf-report-customer span { max-width: 180px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pf-report-payment-badge { display: inline-flex; align-items: center; min-height: 25px; padding: 0 8px; border-radius: 999px; background: #f1f5f9; color: var(--pf-report-secondary); font-size: 9px; font-weight: 700; white-space: nowrap; }
.pf-report-status { display: inline-flex; align-items: center; gap: 5px; min-height: 25px; padding: 0 8px; border-radius: 999px; font-size: 9px; font-weight: 750; white-space: nowrap; }
.pf-report-status i { width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
.pf-status-success { background: var(--pf-report-success-bg); color: var(--pf-report-success); }
.pf-status-warning { background: var(--pf-report-warning-bg); color: var(--pf-report-warning); }
.pf-status-danger { background: var(--pf-report-danger-bg); color: var(--pf-report-danger); }
.pf-status-neutral { background: #f1f5f9; color: var(--pf-report-soft); }
.pf-report-amount { color: var(--pf-report-text); font-size: 11px; font-weight: 800; }

/* ========================= PHARMACY ========================= */

.pf-report-pharmacy-card { margin-top: 18px; padding: 17px 18px; display: flex; align-items: center; gap: 13px; background: #fff; border: 1px solid var(--pf-report-border); border-radius: 16px; box-shadow: 0 1px 2px rgba(15,23,42,.04); }
.pf-report-pharmacy-info { min-width: 0; flex: 1; }
.pf-report-pharmacy-info strong { display: block; color: var(--pf-report-text); font-size: 12px; font-weight: 800; }
.pf-report-pharmacy-info span { display: block; margin-top: 3px; color: var(--pf-report-muted); font-size: 9px; }
.pf-report-pharmacy-meta { display: flex; align-items: center; gap: 24px; }
.pf-report-pharmacy-meta > div { min-width: 75px; }
.pf-report-pharmacy-meta span { display: block; color: var(--pf-report-muted); font-size: 9px; }
.pf-report-pharmacy-meta strong { display: block; margin-top: 4px; color: var(--pf-report-text); font-size: 11px; }

/* ========================= LOADING / ERROR ========================= */

.pf-report-loading-screen,
.pf-report-error-screen { min-height: 100vh; padding: 30px; display: flex; align-items: center; justify-content: center; background: #f5f8f8; }
.pf-report-loading-card,
.pf-report-error-card { width: min(420px,100%); padding: 38px 30px; text-align: center; background: #fff; border: 1px solid var(--pf-report-border); border-radius: 20px; box-shadow: 0 12px 30px rgba(15,23,42,.08); }
.pf-report-loading-logo { width: 58px; height: 58px; margin: 0 auto 18px; display: flex; align-items: center; justify-content: center; border-radius: 16px; background: var(--pf-report-primary); color: #fff; font-size: 30px; font-weight: 800; }
.pf-report-spinner { width: 30px; height: 30px; margin: 0 auto 18px; border: 3px solid #dbe7e6; border-top-color: var(--pf-report-primary); border-radius: 50%; animation: pf-report-spin .8s linear infinite; }
@keyframes pf-report-spin { to { transform: rotate(360deg); } }
.pf-report-loading-card h1,
.pf-report-error-card h1 { margin: 0; color: var(--pf-report-text); font-size: 18px; font-weight: 800; }
.pf-report-loading-card p,
.pf-report-error-card p { margin: 8px 0 0; color: var(--pf-report-soft); font-size: 11px; line-height: 1.6; }
.pf-report-error-icon { width: 48px; height: 48px; margin: 0 auto 16px; display: flex; align-items: center; justify-content: center; border-radius: 50%; background: var(--pf-report-danger-bg); color: var(--pf-report-danger); font-size: 20px; font-weight: 900; }

/* ========================= RESPONSIVE ========================= */

@media (max-width: 1200px) {
  .pf-report-kpi-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
}

@media (max-width: 980px) {
  .pf-report-sidebar { display: none; }
  .pf-report-main { width: 100%; margin-left: 0; }
  .pf-report-panels,
  .pf-report-two-columns { grid-template-columns: 1fr; }
  .pf-report-topbar { padding: 16px 20px; }
  .pf-report-content { padding: 22px 20px 40px; }
}

@media (max-width: 700px) {
  .pf-report-topbar { align-items: flex-start; flex-direction: column; }
  .pf-report-topbar-actions { width: 100%; flex-wrap: wrap; }
  .pf-report-primary-button,
  .pf-report-secondary-button { flex: 1; }
  .pf-report-toolbar { align-items: flex-start; flex-direction: column; }
  .pf-report-period-current { text-align: left; }
  .pf-report-hero { align-items: flex-start; flex-direction: column; }
  .pf-report-hero-meta { width: 100%; gap: 15px; flex-wrap: wrap; }
  .pf-report-kpi-grid { grid-template-columns: 1fr; }
  .pf-report-stock-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .pf-report-pharmacy-card { align-items: flex-start; flex-wrap: wrap; }
  .pf-report-pharmacy-meta { width: 100%; padding-top: 10px; border-top: 1px solid var(--pf-report-border-light); }
}

@media (max-width: 450px) {
  .pf-report-content { padding: 15px 12px 30px; }
  .pf-report-topbar { padding: 14px 12px; }
  .pf-report-topbar h1 { font-size: 22px; }
  .pf-report-stock-grid { grid-template-columns: 1fr; }
  .pf-report-hero { padding: 21px; }
  .pf-report-hero h2 { font-size: 21px; }
  .pf-report-panel-header { padding: 14px; }
}

.pf-report-app button:focus-visible { outline: 3px solid rgba(15,118,110,.22); outline-offset: 2px; }

