}

/* ============================================================
   IMPRESSION A4 — IMPORTANT
   Le rapport imprimable existe dans page.tsx sous #pf-print-report.
   On masque toute l'application et on affiche seulement ce rapport.
   ============================================================ */

@media print {
  @page {
    size: A4 portrait;
    margin: 8mm 9mm 10mm;
  }

  html,
  body {
    width: 100% !important;
    min-width: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
    overflow: visible !important;
  }

  body {
    color: #0f172a !important;
    font-family: Arial, Helvetica, sans-serif !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
  }

  /* Masque toute l'application écran. */
  body * {
    visibility: hidden !important;
  }

  /* Affiche uniquement le rapport imprimable. */
  #pf-print-report,
  #pf-print-report * {
    visibility: visible !important;
  }

  #pf-print-report {
    position: absolute !important;
    left: 0 !important;
    top: 0 !important;
    z-index: 999999 !important;
    display: block !important;
    width: 100% !important;
    min-height: 100vh !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
    color: #0f172a !important;
    font-family: Arial, Helvetica, sans-serif !important;
  }

  .pf-report-app,
  .pf-report-sidebar,
  .pf-report-main,
  .pf-report-topbar,
  .pf-report-content,
  .pf-report-toolbar,
  .pf-report-topbar-actions,
  .pf-report-loading-screen,
  .pf-report-error-screen {
    display: none !important;
  }

  /* ==================== PRINT HEADER ==================== */

  .pf-print-header {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 8mm !important;
    margin-bottom: 5mm !important;
    padding-bottom: 4mm !important;
    border-bottom: 2px solid #0f766e !important;
  }

  .pf-print-brand {
    display: flex !important;
    align-items: center !important;
    gap: 3mm !important;
  }

  .pf-print-logo {
    width: 12mm !important;
    height: 12mm !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    border-radius: 3mm !important;
    background: #0f766e !important;
    color: #fff !important;
    font-size: 17pt !important;
    font-weight: 800 !important;
  }

  .pf-print-brand-name {
    color: #0f766e !important;
    font-size: 14pt !important;
    line-height: 1.1 !important;
    font-weight: 800 !important;
  }

  .pf-print-brand-subtitle {
    margin-top: 1mm !important;
    color: #64748b !important;
    font-size: 7pt !important;
  }

  .pf-print-title-block {
    text-align: right !important;
  }

  .pf-print-title-block h1 {
    margin: 0 !important;
    color: #0f172a !important;
    font-size: 17pt !important;
    line-height: 1.1 !important;
    font-weight: 800 !important;
  }

  .pf-print-title-block p {
    margin: 1.5mm 0 0 !important;
    color: #64748b !important;
    font-size: 8pt !important;
  }

  /* ==================== PRINT INFORMATION ==================== */

  .pf-print-information {
    display: grid !important;
    grid-template-columns: repeat(4,minmax(0,1fr)) !important;
    gap: 3mm !important;
    margin-bottom: 5mm !important;
  }

  .pf-print-information > div {
    min-width: 0 !important;
    padding: 3mm !important;
    border: 1px solid #dbe4e8 !important;
    border-radius: 2mm !important;
    background: #f8fafc !important;
  }

  .pf-print-information span {
    display: block !important;
    margin-bottom: 1mm !important;
    color: #64748b !important;
    font-size: 6.5pt !important;
    font-weight: 700 !important;
    text-transform: uppercase !important;
  }

  .pf-print-information strong {
    display: block !important;
    overflow-wrap: anywhere !important;
    color: #0f172a !important;
    font-size: 8pt !important;
  }

  /* ==================== PRINT KPIs ==================== */

  .pf-print-kpis {
    display: grid !important;
    grid-template-columns: repeat(4,minmax(0,1fr)) !important;
    gap: 3mm !important;
    margin-bottom: 5mm !important;
  }

  .pf-print-kpis > div {
    min-width: 0 !important;
    padding: 3.5mm !important;
    border: 1px solid #dbe4e8 !important;
    border-top: 2px solid #0f766e !important;
    border-radius: 2mm !important;
    background: #fff !important;
  }

  .pf-print-kpis span {
    display: block !important;
    color: #64748b !important;
    font-size: 6.8pt !important;
    font-weight: 700 !important;
  }

  .pf-print-kpis strong {
    display: block !important;
    margin-top: 1.5mm !important;
    color: #0f172a !important;
    font-size: 11pt !important;
    font-weight: 800 !important;
  }

  /* ==================== PRINT SECTIONS ==================== */

  .pf-print-section {
    display: block !important;
    width: 100% !important;
    margin: 0 0 5mm !important;
    padding: 0 !important;
    break-inside: avoid !important;
    page-break-inside: avoid !important;
  }

  .pf-print-section h2 {
    margin: 0 0 2.5mm !important;
    padding: 2.2mm 3mm !important;
    color: #0f172a !important;
    background: #f1f5f9 !important;
    border-left: 3px solid #0f766e !important;
    font-size: 9.5pt !important;
    line-height: 1.2 !important;
    font-weight: 800 !important;
    break-after: avoid !important;
    page-break-after: avoid !important;
  }

  .pf-print-section table {
    width: 100% !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    font-size: 7.4pt !important;
  }

  .pf-print-section thead {
    display: table-header-group !important;
  }

  .pf-print-section tfoot {
    display: table-footer-group !important;
  }

  .pf-print-section tr {
    break-inside: avoid !important;
    page-break-inside: avoid !important;
  }

  .pf-print-section th {
    padding: 2mm 2.5mm !important;
    background: #0f766e !important;
    color: #fff !important;
    border: 1px solid #0f766e !important;
    font-size: 6.8pt !important;
    line-height: 1.25 !important;
    font-weight: 800 !important;
    text-align: left !important;
    vertical-align: middle !important;
  }

  .pf-print-section td {
    padding: 1.8mm 2.5mm !important;
    color: #1e293b !important;
    border: 1px solid #dbe4e8 !important;
    font-size: 7.4pt !important;
    line-height: 1.3 !important;
    vertical-align: middle !important;
  }

  .pf-print-section tbody tr:nth-child(even) td {
    background: #f8fafc !important;
  }

  .pf-print-section td strong {
    font-weight: 800 !important;
  }

  .pf-print-section tr.total td {
    background: #e6f5f2 !important;
    color: #115e59 !important;
    font-weight: 800 !important;
  }

  .pf-print-section tr.collected td {
    background: #ecfdf3 !important;
    color: #166534 !important;
    font-weight: 800 !important;
  }

  /* ==================== PRINT EMPTY / SUCCESS ==================== */

  .pf-print-empty,
  .pf-print-success {
    padding: 4mm !important;
    border-radius: 2mm !important;
    font-size: 8pt !important;
  }

  .pf-print-empty {
    border: 1px solid #dbe4e8 !important;
    background: #f8fafc !important;
    color: #64748b !important;
    text-align: center !important;
  }

  .pf-print-success {
    border: 1px solid #bbf7d0 !important;
    background: #f0fdf4 !important;
    color: #166534 !important;
    font-weight: 700 !important;
  }

  /* ==================== PRINT SALES ==================== */

  .pf-print-sales {
    break-inside: auto !important;
    page-break-inside: auto !important;
  }

  .pf-print-sales table {
    break-inside: auto !important;
    page-break-inside: auto !important;
  }

  .pf-print-sales tr {
    break-inside: avoid !important;
    page-break-inside: avoid !important;
  }

  .pf-print-sales td:nth-child(1) { width: 14%; }
  .pf-print-sales td:nth-child(2) { width: 18%; }
  .pf-print-sales td:nth-child(3) { width: 22%; }
  .pf-print-sales td:nth-child(4) { width: 18%; }
  .pf-print-sales td:nth-child(5) { width: 14%; }
  .pf-print-sales td:nth-child(6) { width: 14%; text-align: right !important; }
  .pf-print-sales th:last-child { text-align: right !important; }

  /* ==================== PRINT FOOTER ==================== */

  .pf-print-footer {
    margin-top: 6mm !important;
    padding-top: 3mm !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-wrap: wrap !important;
    gap: 1.5mm !important;
    border-top: 1px solid #cbd5e1 !important;
    color: #64748b !important;
    font-size: 7pt !important;
    text-align: center !important;
  }

  .pf-print-footer strong {
    color: #0f766e !important;
    font-weight: 800 !important;
  }

  /* Sécurité contre les marges et ombres écran. */
  #pf-print-report h1,
  #pf-print-report h2,
  #pf-print-report h3,
  #pf-print-report p,
  #pf-print-report table {
    max-width: 100% !important;
  }

  #pf-print-report,
  #pf-print-report * {
    box-shadow: none !important;
    text-shadow: none !important;
  }
}

/* ============================================================
   FIN DU CSS PHARMAFLOW RAPPORTS
   ============================================================ */
/* ============================================================
   PHARMAFLOW — RAPPORTS
   CSS COMPLET : INTERFACE + RESPONSIVE + IMPRESSION A4

   IMPORTANT :
   - Ce fichier contient UNIQUEMENT du CSS.
   - Ne jamais y coller le contenu de page.tsx.
   - Si tu l'integres a globals.css, place ce bloc a la fin.
   - Ne pas ajouter un autre @media print apres celui-ci.
   ============================================================ */

:root {
  --pf-report-primary: #0f766e;
  --pf-report-primary-dark: #115e59;
  --pf-report-primary-light: #e6f5f2;
  --pf-report-bg: #f5f8f8;
  --pf-report-surface: #ffffff;
  --pf-report-text: #0f172a;
  --pf-report-secondary: #334155;
  --pf-report-soft: #64748b;
  --pf-report-muted: #94a3b8;
  --pf-report-border: #e2e8f0;
  --pf-report-border-light: #edf2f7;
  --pf-report-success: #15803d;
  --pf-report-success-bg: #ecfdf3;
  --pf-report-warning: #b45309;
  --pf-report-warning-bg: #fff7ed;
  --pf-report-danger: #b91c1c;
  --pf-report-danger-bg: #fef2f2;
  --pf-report-info: #0369a1;
  --pf-report-info-bg: #eff6ff;
  --pf-report-sidebar-width: 270px;
  --pf-report-topbar-height: 76px;
  --pf-report-radius: 14px;
  --pf-report-shadow: 0 4px 18px rgba(15, 23, 42, 0.06);
}

/* ========================= BASE ========================= */

/* IMPORTANT : la version imprimable doit être totalement invisible
   pendant l'affichage normal de /rapports. Elle ne doit apparaître
   que lorsque le navigateur passe en mode impression. */
.pf-print-report {
  display: none !important;
  position: absolute !important;
  width: 0 !important;
  height: 0 !important;
  overflow: hidden !important;
  visibility: hidden !important;
}


.pf-report-app {
  min-height: 100vh;
  width: 100%;
  display: flex;
  background: var(--pf-report-bg);
  color: var(--pf-report-text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.pf-report-app *,
.pf-print-report * {
  box-sizing: border-box;
}

/* ========================= SIDEBAR ========================= */

.pf-report-sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: var(--pf-report-sidebar-width);
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overflow-x: hidden;
  background: #fff;
  border-right: 1px solid var(--pf-report-border);
  z-index: 100;
}

.pf-report-brand {
  min-height: 88px;
  padding: 20px 22px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid var(--pf-report-border-light);
}

.pf-report-brand-icon,
.pf-report-pharmacy-logo {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 13px;
  background: var(--pf-report-primary);
  color: #fff;
  font-size: 23px;
  font-weight: 800;
}

.pf-report-brand strong {
  display: block;
  color: var(--pf-report-text);
  font-size: 17px;
  line-height: 1.2;
  font-weight: 800;
}

.pf-report-brand span {
  display: block;
  margin-top: 3px;
  color: var(--pf-report-muted);
  font-size: 10px;
  font-weight: 600;
}

.pf-report-sidebar-section {
  padding: 22px 14px 12px;
}

.pf-report-sidebar-section > span {
  display: block;
  padding: 0 12px 10px;
  color: var(--pf-report-muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
}

.pf-report-sidebar-section nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.pf-report-sidebar button {
  width: 100%;
  min-height: 45px;
  padding: 10px 13px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--pf-report-secondary);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: background .18s ease, color .18s ease;
}

.pf-report-sidebar button span {
  width: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--pf-report-soft);
  font-size: 17px;
}

.pf-report-sidebar button:hover {
  background: #f1f5f9;
  color: var(--pf-report-primary-dark);
}

.pf-report-sidebar button.active {
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary-dark);
  font-weight: 750;
}

.pf-report-sidebar button.active span {
  color: var(--pf-report-primary);
}

.pf-report-sidebar-bottom {
  margin-top: auto;
  padding: 14px;
  border-top: 1px solid var(--pf-report-border-light);
}

/* ========================= MAIN ========================= */

.pf-report-main {
  width: calc(100% - var(--pf-report-sidebar-width));
  min-width: 0;
  margin-left: var(--pf-report-sidebar-width);
}

.pf-report-topbar {
  min-height: var(--pf-report-topbar-height);
  padding: 18px 30px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255,255,255,.96);
  border-bottom: 1px solid var(--pf-report-border);
  backdrop-filter: blur(12px);
}

.pf-report-breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 5px;
  color: var(--pf-report-muted);
  font-size: 11px;
  font-weight: 600;
}

.pf-report-breadcrumb span {
  color: #cbd5e1;
}

.pf-report-topbar h1 {
  margin: 0;
  color: var(--pf-report-text);
  font-size: 26px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -.035em;
}

.pf-report-topbar p {
  margin: 4px 0 0;
  color: var(--pf-report-soft);
  font-size: 12px;
}

.pf-report-topbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ========================= BUTTONS ========================= */

.pf-report-primary-button,
.pf-report-secondary-button,
.pf-report-icon-button {
  min-height: 40px;
  border: 1px solid transparent;
  border-radius: 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 14px;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: transform .16s ease, background .16s ease, box-shadow .16s ease;
}

.pf-report-primary-button {
  background: var(--pf-report-primary);
  color: #fff;
  box-shadow: 0 4px 12px rgba(15,118,110,.18);
}

.pf-report-primary-button:hover {
  background: var(--pf-report-primary-dark);
  transform: translateY(-1px);
}

.pf-report-secondary-button,
.pf-report-icon-button {
  background: #fff;
  color: var(--pf-report-secondary);
  border-color: var(--pf-report-border);
}

.pf-report-secondary-button:hover,
.pf-report-icon-button:hover {
  background: #f8fafc;
  color: var(--pf-report-primary-dark);
}

.pf-report-icon-button {
  width: 40px;
  padding: 0;
  font-size: 18px;
}

/* ========================= CONTENT ========================= */

.pf-report-content {
  width: 100%;
  max-width: 1600px;
  margin: 0 auto;
  padding: 28px 30px 50px;
}

/* ========================= TOOLBAR ========================= */

.pf-report-toolbar {
  margin-bottom: 20px;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: #fff;
  border: 1px solid var(--pf-report-border);
  border-radius: var(--pf-report-radius);
  box-shadow: 0 1px 2px rgba(15,23,42,.04);
}

.pf-report-toolbar-label {
  display: block;
  margin-bottom: 8px;
  color: var(--pf-report-muted);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.pf-report-periods {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}

.pf-report-periods button {
  min-height: 34px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: #f1f5f9;
  color: var(--pf-report-soft);
  font: inherit;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.pf-report-periods button:hover {
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary-dark);
}

.pf-report-periods button.active {
  background: var(--pf-report-primary);
  color: #fff;
}

.pf-report-period-current {
  text-align: right;
}

.pf-report-period-current span {
  display: block;
  color: var(--pf-report-text);
  font-size: 13px;
  font-weight: 750;
}

.pf-report-period-current small {
  display: block;
  margin-top: 4px;
  color: var(--pf-report-primary);
  font-size: 10px;
}

/* ========================= HERO ========================= */

.pf-report-hero {
  min-height: 145px;
  margin-bottom: 20px;
  padding: 26px 28px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  overflow: hidden;
  border-radius: 20px;
  background: linear-gradient(135deg,#0f766e 0%,#115e59 100%);
  color: #fff;
  box-shadow: 0 14px 30px rgba(15,118,110,.18);
}

.pf-report-hero::after {
  content: "";
  position: absolute;
  width: 230px;
  height: 230px;
  right: -80px;
  top: -100px;
  border-radius: 50%;
  background: rgba(255,255,255,.08);
}

.pf-report-hero-copy,
.pf-report-hero-meta {
  position: relative;
  z-index: 1;
}

.pf-report-eyebrow {
  display: inline-block;
  margin-bottom: 8px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
  opacity: .75;
}

.pf-report-hero h2 {
  margin: 0;
  font-size: 25px;
  font-weight: 800;
  letter-spacing: -.03em;
}

.pf-report-hero p {
  margin: 5px 0 0;
  font-size: 12px;
  opacity: .78;
}

.pf-report-hero-meta {
  display: flex;
  align-items: center;
  gap: 30px;
}

.pf-report-hero-meta > div {
  min-width: 125px;
}

.pf-report-hero-meta span {
  display: block;
  margin-bottom: 5px;
  font-size: 9px;
  font-weight: 600;
  opacity: .68;
  text-transform: uppercase;
}

.pf-report-hero-meta strong {
  display: block;
  font-size: 12px;
  font-weight: 750;
}

/* ========================= KPI ========================= */

.pf-report-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 15px;
  margin-bottom: 20px;
}

.pf-report-kpi-card {
  min-height: 145px;
  padding: 18px;
  position: relative;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--pf-report-border);
  border-radius: var(--pf-report-radius);
  box-shadow: 0 1px 2px rgba(15,23,42,.04);
}

.pf-report-kpi-card::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 4px;
  height: 100%;
  background: var(--pf-report-primary);
}

.pf-report-kpi-card.sales::before { background: #2563eb; }
.pf-report-kpi-card.basket::before { background: #7c3aed; }
.pf-report-kpi-card.payment::before { background: #16a34a; }

.pf-report-kpi-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.pf-report-kpi-top > span {
  color: var(--pf-report-soft);
  font-size: 11px;
  font-weight: 700;
}

.pf-report-kpi-icon {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary);
  font-size: 16px;
  font-weight: 800;
}

.pf-report-kpi-card.sales .pf-report-kpi-icon { background: #eff6ff; color: #2563eb; }
.pf-report-kpi-card.basket .pf-report-kpi-icon { background: #f5f3ff; color: #7c3aed; }
.pf-report-kpi-card.payment .pf-report-kpi-icon { background: #f0fdf4; color: #16a34a; }

.pf-report-kpi-card > strong {
  display: block;
  margin-top: 17px;
  color: var(--pf-report-text);
  font-size: 23px;
  line-height: 1.1;
  font-weight: 800;
  letter-spacing: -.03em;
}

.pf-report-kpi-card > small {
  display: block;
  margin-top: 7px;
  color: var(--pf-report-muted);
  font-size: 10px;
}

/* ========================= PANELS ========================= */

.pf-report-panels,
.pf-report-two-columns {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 18px;
  margin-bottom: 18px;
}

.pf-report-panel {
  min-width: 0;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--pf-report-border);
  border-radius: 16px;
  box-shadow: 0 1px 2px rgba(15,23,42,.04);
}

.pf-report-panel-header {
  min-height: 72px;
  padding: 16px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-bottom: 1px solid var(--pf-report-border-light);
}

.pf-report-panel-heading {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.pf-report-panel-heading > div:last-child { min-width: 0; }

.pf-report-panel-heading h3 {
  margin: 0;
  color: var(--pf-report-text);
  font-size: 14px;
  line-height: 1.2;
  font-weight: 800;
}

.pf-report-panel-heading p {
  margin: 4px 0 0;
  color: var(--pf-report-muted);
  font-size: 10px;
  line-height: 1.4;
}

.pf-report-panel-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: var(--pf-report-primary-light);
  color: var(--pf-report-primary);
  font-size: 17px;
  font-weight: 800;
}

.pf-report-panel-icon.finance { background: #ecfdf5; color: #047857; }
.pf-report-panel-icon.stock { background: #eff6ff; color: #2563eb; }
.pf-report-panel-icon.alert { background: #fff7ed; color: #c2410c; }
.pf-report-panel-icon.payment { background: #f0fdf4; color: #15803d; }
.pf-report-panel-icon.activity { background: #f5f3ff; color: #7c3aed; }
.pf-report-panel-icon.sales { background: #f0fdfa; color: #0f766e; }

/* ========================= FINANCE ========================= */

.pf-report-financial-list { padding: 5px 18px 10px; }

.pf-report-financial-row {
  min-height: 43px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-bottom: 1px solid var(--pf-report-border-light);
}

.pf-report-financial-row:last-child { border-bottom: 0; }
.pf-report-financial-row span { color: var(--pf-report-soft); font-size: 11px; font-weight: 600; }
.pf-report-financial-row strong { color: var(--pf-report-text); font-size: 12px; font-weight: 750; }
.pf-report-financial-row strong.negative { color: var(--pf-report-danger); }

.pf-report-financial-row.total {
  margin-top: 4px;
  padding-top: 5px;
  border-top: 1px solid var(--pf-report-border);
}

.pf-report-financial-row.total span,
.pf-report-financial-row.total strong {
  color: var(--pf-report-primary-dark);
  font-size: 13px;
  font-weight: 800;
}

.pf-report-financial-row.collected {
  margin-top: 3px;
  padding: 8px 10px;
  border: 0;
  border-radius: 8px;
  background: var(--pf-report-success-bg);
}

.pf-report-financial-row.collected span,
.pf-report-financial-row.collected strong { color: var(--pf-report-success); }

.pf-report-financial-footer { padding: 13px 18px 16px; }
.pf-report-financial-footer > div:first-child { display: flex; justify-content: space-between; margin-bottom: 7px; }
.pf-report-financial-footer span { color: var(--pf-report-muted); font-size: 10px; font-weight: 650; }
.pf-report-financial-footer strong { color: var(--pf-report-primary); font-size: 12px; }

.pf-report-mini-progress,
.pf-report-payment-bar {
  width: 100%;
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: #e2e8f0;
}

.pf-report-mini-progress span,
.pf-report-payment-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--pf-report-primary);
}

/* ========================= STOCK ========================= */

.pf-report-stock-grid {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 10px;
  padding: 16px 18px 18px;
}

.pf-report-stock-item {
  min-height: 100px;
  padding: 13px;
  border: 1px solid var(--pf-report-border-light);
  border-radius: 10px;
  background: #fafcfc;
}

.pf-report-stock-item span { display: block; color: var(--pf-report-soft); font-size: 10px; font-weight: 650; }
.pf-report-stock-item strong { display: block; margin-top: 8px; color: var(--pf-report-text); font-size: 21px; line-height: 1; font-weight: 800; }
.pf-report-stock-item small { display: block; margin-top: 7px; color: var(--pf-report-muted); font-size: 9px; }
.pf-report-stock-item.warning { background: var(--pf-report-warning-bg); border-color: #fed7aa; }
.pf-report-stock-item.warning strong { color: var(--pf-report-warning); }
.pf-report-stock-item.danger { background: var(--pf-report-danger-bg); border-color: #fecaca; }
.pf-report-stock-item.danger strong { color: var(--pf-report-danger); }
.pf-report-stock-item.info { background: var(--pf-report-info-bg); border-color: #bfdbfe; }
.pf-report-stock-item.info strong { color: var(--pf-report-info); }

/* ========================= ALERTS ========================= */

.pf-report-alert-panel { margin-bottom: 18px; }

.pf-report-alert-count {
  min-width: 27px;
  height: 27px;
  padding: 0 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: #f1f5f9;
  color: var(--pf-report-muted);
  font-size: 11px;
  font-weight: 800;
}

.pf-report-alert-count.has-alerts { background: var(--pf-report-danger-bg); color: var(--pf-report-danger); }

.pf-report-no-alerts {
  margin: 16px 18px 18px;
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 1px solid #bbf7d0;
  border-radius: 10px;
  background: var(--pf-report-success-bg);
}

.pf-report-success-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #dcfce7;
  color: var(--pf-report-success);
  font-weight: 800;
}

.pf-report-no-alerts strong { display: block; color: #166534; font-size: 11px; }
.pf-report-no-alerts span { display: block; margin-top: 3px; color: #4d7c5a; font-size: 10px; }

.pf-report-alert-list { display: grid; gap: 8px; padding: 15px 18px 18px; }

.pf-report-alert {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px;
  border: 1px solid transparent;
  border-radius: 10px;
}

.pf-report-alert.danger { background: var(--pf-report-danger-bg); border-color: #fecaca; }
.pf-report-alert.warning { background: var(--pf-report-warning-bg); border-color: #fed7aa; }
.pf-report-alert.info { background: var(--pf-report-info-bg); border-color: #bfdbfe; }

.pf-report-alert-symbol {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: #fff;
  font-size: 13px;
  font-weight: 900;
}

.pf-report-alert.danger .pf-report-alert-symbol { color: var(--pf-report-danger); }
.pf-report-alert.warning .pf-report-alert-symbol { color: var(--pf-report-warning); }
.pf-report-alert.info .pf-report-alert-symbol { color: var(--pf-report-info); }

.pf-report-alert-content { min-width: 0; }
.pf-report-alert-content strong { display: block; color: var(--pf-report-text); font-size: 11px; font-weight: 800; }
.pf-report-alert-content span { display: block; margin-top: 3px; color: var(--pf-report-soft); font-size: 10px; }

/* ========================= PAYMENT ========================= */

.pf-report-payment-list { padding: 15px 18px 18px; }
.pf-report-payment-item { padding: 10px 0; }
.pf-report-payment-item + .pf-report-payment-item { border-top: 1px solid var(--pf-report-border-light); }
.pf-report-payment-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.pf-report-payment-name { display: flex; align-items: center; gap: 8px; min-width: 0; }
.pf-report-payment-name strong,
.pf-report-payment-top > strong { color: var(--pf-report-text); font-size: 11px; }
.pf-report-payment-dot { width: 8px; height: 8px; flex: 0 0 8px; border-radius: 50%; background: var(--pf-report-primary); }
.pf-report-payment-bar { margin-top: 8px; height: 6px; }
.pf-report-payment-bottom { margin-top: 5px; display: flex; justify-content: space-between; color: var(--pf-report-muted); font-size: 9px; }

/* ========================= ACTIVITY ========================= */

.pf-report-activity-list { padding: 8px 18px 15px; }
.pf-report-activity-row { min-height: 55px; display: flex; align-items: center; gap: 11px; border-bottom: 1px solid var(--pf-report-border-light); }
.pf-report-activity-row:last-child { border-bottom: 0; }
.pf-report-activity-icon { width: 32px; height: 32px; flex: 0 0 32px; display: flex; align-items: center; justify-content: center; border-radius: 9px; background: var(--pf-report-primary-light); color: var(--pf-report-primary); font-size: 13px; font-weight: 800; }
.pf-report-activity-row strong { display: block; color: var(--pf-report-text); font-size: 12px; font-weight: 800; }
.pf-report-activity-row span { display: block; margin-top: 2px; color: var(--pf-report-muted); font-size: 9px; }

/* ========================= EMPTY ========================= */

.pf-report-empty { min-height: 145px; padding: 25px 18px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.pf-report-empty.large { min-height: 200px; }
.pf-report-empty-icon { width: 42px; height: 42px; margin-bottom: 10px; display: flex; align-items: center; justify-content: center; border-radius: 12px; background: #f1f5f9; color: var(--pf-report-muted); font-size: 18px; }
.pf-report-empty strong { color: var(--pf-report-secondary); font-size: 11px; }
.pf-report-empty span { margin-top: 4px; color: var(--pf-report-muted); font-size: 10px; }

/* ========================= SALES TABLE ========================= */

.pf-report-sales-panel { margin-bottom: 18px; }
.pf-report-panel-total { text-align: right; }
.pf-report-panel-total span { display: block; color: var(--pf-report-text); font-size: 15px; font-weight: 800; }
.pf-report-panel-total small { display: block; margin-top: 2px; color: var(--pf-report-muted); font-size: 9px; }

.pf-report-table-wrapper { width: 100%; overflow-x: auto; }
.pf-report-table { width: 100%; min-width: 720px; border-collapse: collapse; border-spacing: 0; }
.pf-report-table th { height: 39px; padding: 0 16px; background: #f8fafc; color: var(--pf-report-muted); border-bottom: 1px solid var(--pf-report-border); font-size: 9px; font-weight: 800; text-align: left; text-transform: uppercase; letter-spacing: .05em; white-space: nowrap; }
.pf-report-table td { height: 54px; padding: 8px 16px; color: var(--pf-report-secondary); border-bottom: 1px solid var(--pf-report-border-light); font-size: 10px; vertical-align: middle; }
.pf-report-table tbody tr:last-child td { border-bottom: 0; }
.pf-report-table tbody tr:hover td { background: #fbfefd; }
.pf-report-table .right { text-align: right; }
.pf-report-sale-number { color: var(--pf-report-text); font-size: 10px; font-weight: 800; }
.pf-report-date { color: var(--pf-report-soft); white-space: nowrap; }
.pf-report-customer { display: flex; align-items: center; gap: 8px; }
.pf-report-customer-avatar { width: 27px; height: 27px; flex: 0 0 27px; display: flex; align-items: center; justify-content: center; border-radius: 50%; background: var(--pf-report-primary-light); color: var(--pf-report-primary-dark); font-size: 9px; font-weight: 800; }
.pf-report-customer span { max-width: 180px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pf-report-payment-badge { display: inline-flex; align-items: center; min-height: 25px; padding: 0 8px; border-radius: 999px; background: #f1f5f9; color: var(--pf-report-secondary); font-size: 9px; font-weight: 700; white-space: nowrap; }
.pf-report-status { display: inline-flex; align-items: center; gap: 5px; min-height: 25px; padding: 0 8px; border-radius: 999px; font-size: 9px; font-weight: 750; white-space: nowrap; }
.pf-report-status i { width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
.pf-status-success { background: var(--pf-report-success-bg); color: var(--pf-report-success); }
.pf-status-warning { background: var(--pf-report-warning-bg); color: var(--pf-report-warning); }
.pf-status-danger { background: var(--pf-report-danger-bg); color: var(--pf-report-danger); }
.pf-status-neutral { background: #f1f5f9; color: var(--pf-report-soft); }
.pf-report-amount { color: var(--pf-report-text); font-size: 11px; font-weight: 800; }

/* ========================= PHARMACY ========================= */

.pf-report-pharmacy-card { margin-top: 18px; padding: 17px 18px; display: flex; align-items: center; gap: 13px; background: #fff; border: 1px solid var(--pf-report-border); border-radius: 16px; box-shadow: 0 1px 2px rgba(15,23,42,.04); }
.pf-report-pharmacy-info { min-width: 0; flex: 1; }
.pf-report-pharmacy-info strong { display: block; color: var(--pf-report-text); font-size: 12px; font-weight: 800; }
.pf-report-pharmacy-info span { display: block; margin-top: 3px; color: var(--pf-report-muted); font-size: 9px; }
.pf-report-pharmacy-meta { display: flex; align-items: center; gap: 24px; }
.pf-report-pharmacy-meta > div { min-width: 75px; }
.pf-report-pharmacy-meta span { display: block; color: var(--pf-report-muted); font-size: 9px; }
.pf-report-pharmacy-meta strong { display: block; margin-top: 4px; color: var(--pf-report-text); font-size: 11px; }

/* ========================= LOADING / ERROR ========================= */

.pf-report-loading-screen,
.pf-report-error-screen { min-height: 100vh; padding: 30px; display: flex; align-items: center; justify-content: center; background: #f5f8f8; }
.pf-report-loading-card,
.pf-report-error-card { width: min(420px,100%); padding: 38px 30px; text-align: center; background: #fff; border: 1px solid var(--pf-report-border); border-radius: 20px; box-shadow: 0 12px 30px rgba(15,23,42,.08); }
.pf-report-loading-logo { width: 58px; height: 58px; margin: 0 auto 18px; display: flex; align-items: center; justify-content: center; border-radius: 16px; background: var(--pf-report-primary); color: #fff; font-size: 30px; font-weight: 800; }
.pf-report-spinner { width: 30px; height: 30px; margin: 0 auto 18px; border: 3px solid #dbe7e6; border-top-color: var(--pf-report-primary); border-radius: 50%; animation: pf-report-spin .8s linear infinite; }
@keyframes pf-report-spin { to { transform: rotate(360deg); } }
.pf-report-loading-card h1,
.pf-report-error-card h1 { margin: 0; color: var(--pf-report-text); font-size: 18px; font-weight: 800; }
.pf-report-loading-card p,
.pf-report-error-card p { margin: 8px 0 0; color: var(--pf-report-soft); font-size: 11px; line-height: 1.6; }
.pf-report-error-icon { width: 48px; height: 48px; margin: 0 auto 16px; display: flex; align-items: center; justify-content: center; border-radius: 50%; background: var(--pf-report-danger-bg); color: var(--pf-report-danger); font-size: 20px; font-weight: 900; }

/* ========================= RESPONSIVE ========================= */

@media (max-width: 1200px) {
  .pf-report-kpi-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
}

@media (max-width: 980px) {
  .pf-report-sidebar { display: none; }
  .pf-report-main { width: 100%; margin-left: 0; }
  .pf-report-panels,
  .pf-report-two-columns { grid-template-columns: 1fr; }
  .pf-report-topbar { padding: 16px 20px; }
  .pf-report-content { padding: 22px 20px 40px; }
}

@media (max-width: 700px) {
  .pf-report-topbar { align-items: flex-start; flex-direction: column; }
  .pf-report-topbar-actions { width: 100%; flex-wrap: wrap; }
  .pf-report-primary-button,
  .pf-report-secondary-button { flex: 1; }
  .pf-report-toolbar { align-items: flex-start; flex-direction: column; }
  .pf-report-period-current { text-align: left; }
  .pf-report-hero { align-items: flex-start; flex-direction: column; }
  .pf-report-hero-meta { width: 100%; gap: 15px; flex-wrap: wrap; }
  .pf-report-kpi-grid { grid-template-columns: 1fr; }
  .pf-report-stock-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .pf-report-pharmacy-card { align-items: flex-start; flex-wrap: wrap; }
  .pf-report-pharmacy-meta { width: 100%; padding-top: 10px; border-top: 1px solid var(--pf-report-border-light); }
}

@media (max-width: 450px) {
  .pf-report-content { padding: 15px 12px 30px; }
  .pf-report-topbar { padding: 14px 12px; }
  .pf-report-topbar h1 { font-size: 22px; }
  .pf-report-stock-grid { grid-template-columns: 1fr; }
  .pf-report-hero { padding: 21px; }
  .pf-report-hero h2 { font-size: 21px; }
  .pf-report-panel-header { padding: 14px; }
}

.pf-report-app button:focus-visible { outline: 3px solid rgba(15,118,110,.22); outline-offset: 2px; }

/* ============================================================
   CORRECTION ÉCRAN — FLUX NORMAL
   ============================================================ */

.pf-report-app {
  position: relative !important;
  display: flex !important;
  align-items: stretch !important;
  min-height: 100vh !important;
  height: auto !important;
  overflow-x: hidden !important;
  overflow-y: visible !important;
}

.pf-report-main {
  position: relative !important;
  display: block !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  width: calc(100% - var(--pf-report-sidebar-width)) !important;
  margin-left: var(--pf-report-sidebar-width) !important;
  height: auto !important;
  min-height: 100vh !important;
  overflow: visible !important;
}

.pf-report-content {
  position: relative !important;
  display: block !important;
  width: 100% !important;
  max-width: 1600px !important;
  height: auto !important;
  min-height: 0 !important;
  margin: 0 auto !important;
  padding: 24px 30px 48px !important;
  overflow: visible !important;
}

.pf-report-toolbar,
.pf-report-hero,
.pf-report-kpi-grid,
.pf-report-panels,
.pf-report-panel,
.pf-report-alert-panel,
.pf-report-sales-panel,
.pf-report-pharmacy-card {
  position: relative !important;
  top: auto !important;
  right: auto !important;
  bottom: auto !important;
  left: auto !important;
  transform: none !important;
}

.pf-report-toolbar {
  height: auto !important;
  min-height: 0 !important;
}

.pf-report-hero {
  height: auto !important;
  min-height: 145px !important;
}

.pf-report-kpi-grid {
  height: auto !important;
  min-height: 0 !important;
  grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
}

.pf-report-panels {
  height: auto !important;
  min-height: 0 !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
}

.pf-report-panel {
  height: auto !important;
  min-height: 0 !important;
}

.pf-report-sales-panel {
  margin-bottom: 18px !important;
}

@media (max-width: 1200px) {
  .pf-report-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
}

@media (max-width: 980px) {
  .pf-report-sidebar {
    display: none !important;
  }

  .pf-report-main {
    width: 100% !important;
    margin-left: 0 !important;
  }

  .pf-report-panels {
    grid-template-columns: 1fr !important;
  }
}

@media (max-width: 700px) {
  .pf-report-content {
    padding: 18px 14px 36px !important;
  }

  .pf-report-topbar {
    padding: 16px 18px !important;
    align-items: flex-start !important;
    flex-direction: column !important;
  }

  .pf-report-topbar-actions {
    width: 100% !important;
    flex-wrap: wrap !important;
  }

  .pf-report-kpi-grid {
    grid-template-columns: 1fr !important;
  }

  .pf-report-hero {
    align-items: flex-start !important;
    flex-direction: column !important;
  }

  .pf-report-hero-copy {
    max-width: 100% !important;
  }
}

/* ============================================================
   IMPRESSION A4 — IMPORTANT
   Le rapport imprimable existe dans page.tsx sous #pf-print-report.
   On masque toute l'application et on affiche seulement ce rapport.
   ============================================================ */

@media print {
  @page {
    size: A4 portrait;
    margin: 8mm 9mm 10mm;
  }

  html,
  body {
    width: 100% !important;
    min-width: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
    overflow: visible !important;
  }

  body {
    color: #0f172a !important;
    font-family: Arial, Helvetica, sans-serif !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
  }

  /* Masque toute l'application écran. */
  body * {
    visibility: hidden !important;
  }

  /* Affiche uniquement le rapport imprimable. */
  #pf-print-report,
  #pf-print-report * {
    visibility: visible !important;
  }

  #pf-print-report {
    position: absolute !important;
    left: 0 !important;
    top: 0 !important;
    z-index: 999999 !important;
    display: block !important;
    width: 100% !important;
    min-height: 100vh !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
    color: #0f172a !important;
    font-family: Arial, Helvetica, sans-serif !important;
  }

  .pf-report-app,
  .pf-report-sidebar,
  .pf-report-main,
  .pf-report-topbar,
  .pf-report-content,
  .pf-report-toolbar,
  .pf-report-topbar-actions,
  .pf-report-loading-screen,
  .pf-report-error-screen {
    display: none !important;
  }

  /* ==================== PRINT HEADER ==================== */

  .pf-print-header {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 8mm !important;
    margin-bottom: 5mm !important;
    padding-bottom: 4mm !important;
    border-bottom: 2px solid #0f766e !important;
  }

  .pf-print-brand {
    display: flex !important;
    align-items: center !important;
    gap: 3mm !important;
  }

  .pf-print-logo {
    width: 12mm !important;
    height: 12mm !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    border-radius: 3mm !important;
    background: #0f766e !important;
    color: #fff !important;
    font-size: 17pt !important;
    font-weight: 800 !important;
  }

  .pf-print-brand-name {
    color: #0f766e !important;
    font-size: 14pt !important;
    line-height: 1.1 !important;
    font-weight: 800 !important;
  }

  .pf-print-brand-subtitle {
    margin-top: 1mm !important;
    color: #64748b !important;
    font-size: 7pt !important;
  }

  .pf-print-title-block {
    text-align: right !important;
  }

  .pf-print-title-block h1 {
    margin: 0 !important;
    color: #0f172a !important;
    font-size: 17pt !important;
    line-height: 1.1 !important;
    font-weight: 800 !important;
  }

  .pf-print-title-block p {
    margin: 1.5mm 0 0 !important;
    color: #64748b !important;
    font-size: 8pt !important;
  }

  /* ==================== PRINT INFORMATION ==================== */

  .pf-print-information {
    display: grid !important;
    grid-template-columns: repeat(4,minmax(0,1fr)) !important;
    gap: 3mm !important;
    margin-bottom: 5mm !important;
  }

  .pf-print-information > div {
    min-width: 0 !important;
    padding: 3mm !important;
    border: 1px solid #dbe4e8 !important;
    border-radius: 2mm !important;
    background: #f8fafc !important;
  }

  .pf-print-information span {
    display: block !important;
    margin-bottom: 1mm !important;
    color: #64748b !important;
    font-size: 6.5pt !important;
    font-weight: 700 !important;
    text-transform: uppercase !important;
  }

  .pf-print-information strong {
    display: block !important;
    overflow-wrap: anywhere !important;
    color: #0f172a !important;
    font-size: 8pt !important;
  }

  /* ==================== PRINT KPIs ==================== */

  .pf-print-kpis {
    display: grid !important;
    grid-template-columns: repeat(4,minmax(0,1fr)) !important;
    gap: 3mm !important;
    margin-bottom: 5mm !important;
  }

  .pf-print-kpis > div {
    min-width: 0 !important;
    padding: 3.5mm !important;
    border: 1px solid #dbe4e8 !important;
    border-top: 2px solid #0f766e !important;
    border-radius: 2mm !important;
    background: #fff !important;
  }

  .pf-print-kpis span {
    display: block !important;
    color: #64748b !important;
    font-size: 6.8pt !important;
    font-weight: 700 !important;
  }

  .pf-print-kpis strong {
    display: block !important;
    margin-top: 1.5mm !important;
    color: #0f172a !important;
    font-size: 11pt !important;
    font-weight: 800 !important;
  }

  /* ==================== PRINT SECTIONS ==================== */

  .pf-print-section {
    display: block !important;
    width: 100% !important;
    margin: 0 0 5mm !important;
    padding: 0 !important;
    break-inside: avoid !important;
    page-break-inside: avoid !important;
  }

  .pf-print-section h2 {
    margin: 0 0 2.5mm !important;
    padding: 2.2mm 3mm !important;
    color: #0f172a !important;
    background: #f1f5f9 !important;
    border-left: 3px solid #0f766e !important;
    font-size: 9.5pt !important;
    line-height: 1.2 !important;
    font-weight: 800 !important;
    break-after: avoid !important;
    page-break-after: avoid !important;
  }

  .pf-print-section table {
    width: 100% !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    font-size: 7.4pt !important;
  }

  .pf-print-section thead {
    display: table-header-group !important;
  }

  .pf-print-section tfoot {
    display: table-footer-group !important;
  }

  .pf-print-section tr {
    break-inside: avoid !important;
    page-break-inside: avoid !important;
  }

  .pf-print-section th {
    padding: 2mm 2.5mm !important;
    background: #0f766e !important;
    color: #fff !important;
    border: 1px solid #0f766e !important;
    font-size: 6.8pt !important;
    line-height: 1.25 !important;
    font-weight: 800 !important;
    text-align: left !important;
    vertical-align: middle !important;
  }

  .pf-print-section td {
    padding: 1.8mm 2.5mm !important;
    color: #1e293b !important;
    border: 1px solid #dbe4e8 !important;
    font-size: 7.4pt !important;
    line-height: 1.3 !important;
    vertical-align: middle !important;
  }

  .pf-print-section tbody tr:nth-child(even) td {
    background: #f8fafc !important;
  }

  .pf-print-section td strong {
    font-weight: 800 !important;
  }

  .pf-print-section tr.total td {
    background: #e6f5f2 !important;
    color: #115e59 !important;
    font-weight: 800 !important;
  }

  .pf-print-section tr.collected td {
    background: #ecfdf3 !important;
    color: #166534 !important;
    font-weight: 800 !important;
  }

  /* ==================== PRINT EMPTY / SUCCESS ==================== */

  .pf-print-empty,
  .pf-print-success {
    padding: 4mm !important;
    border-radius: 2mm !important;
    font-size: 8pt !important;
  }

  .pf-print-empty {
    border: 1px solid #dbe4e8 !important;
    background: #f8fafc !important;
    color: #64748b !important;
    text-align: center !important;
  }

  .pf-print-success {
    border: 1px solid #bbf7d0 !important;
    background: #f0fdf4 !important;
    color: #166534 !important;
    font-weight: 700 !important;
  }

  /* ==================== PRINT SALES ==================== */

  .pf-print-sales {
    break-inside: auto !important;
    page-break-inside: auto !important;
  }

  .pf-print-sales table {
    break-inside: auto !important;
    page-break-inside: auto !important;
  }

  .pf-print-sales tr {
    break-inside: avoid !important;
    page-break-inside: avoid !important;
  }

  .pf-print-sales td:nth-child(1) { width: 14%; }
  .pf-print-sales td:nth-child(2) { width: 18%; }
  .pf-print-sales td:nth-child(3) { width: 22%; }
  .pf-print-sales td:nth-child(4) { width: 18%; }
  .pf-print-sales td:nth-child(5) { width: 14%; }
  .pf-print-sales td:nth-child(6) { width: 14%; text-align: right !important; }
  .pf-print-sales th:last-child { text-align: right !important; }

  /* ==================== PRINT FOOTER ==================== */

  .pf-print-footer {
    margin-top: 6mm !important;
    padding-top: 3mm !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-wrap: wrap !important;
    gap: 1.5mm !important;
    border-top: 1px solid #cbd5e1 !important;
    color: #64748b !important;
    font-size: 7pt !important;
    text-align: center !important;
  }

  .pf-print-footer strong {
    color: #0f766e !important;
    font-weight: 800 !important;
  }

  /* Sécurité contre les marges et ombres écran. */
  #pf-print-report h1,
  #pf-print-report h2,
  #pf-print-report h3,
  #pf-print-report p,
  #pf-print-report table {
    max-width: 100% !important;
  }

  #pf-print-report,
  #pf-print-report * {
    box-shadow: none !important;
    text-shadow: none !important;
  }
}

/* ============================================================
   FIN DU CSS PHARMAFLOW RAPPORTS
   ============================================================ */
/* ============================================================
   PHARMAFLOW — AUTHENTICATION
   LOGIN / FORGOT PASSWORD / RESET PASSWORD
   ============================================================ */

/* ============================================================
   VARIABLES AUTH
   ============================================================ */

:root {
  --pf-auth-radius: 18px;
  --pf-auth-input-radius: 11px;
  --pf-auth-shadow:
    0 24px 70px rgba(15, 23, 42, 0.08);
  --pf-auth-shadow-soft:
    0 10px 35px rgba(15, 23, 42, 0.06);
}

/* ============================================================
   PAGE AUTHENTIFICATION
   ============================================================ */

.pf-auth-page {
  min-height: 100vh;
  width: 100%;
  display: grid;
  grid-template-columns: minmax(420px, 0.92fr) minmax(520px, 1.08fr);
  background: var(--pf-background);
}

/* ============================================================
   PANNEAU BRAND
   ============================================================ */

.pf-auth-brand {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  background:
    radial-gradient(
      circle at 15% 15%,
      rgba(20, 184, 166, 0.18),
      transparent 34%
    ),
    linear-gradient(
      145deg,
      #0f766e 0%,
      #115e59 52%,
      #134e4a 100%
    );
  color: #ffffff;
}

.pf-auth-brand::before {
  content: "";
  position: absolute;
  width: 420px;
  height: 420px;
  right: -180px;
  bottom: -180px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 50%;
}

.pf-auth-brand::after {
  content: "";
  position: absolute;
  width: 280px;
  height: 280px;
  right: -100px;
  bottom: -100px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 50%;
}

.pf-auth-brand-content {
  position: relative;
  z-index: 2;
  width: min(100%, 590px);
  padding: 64px;
  margin: 0 auto;
}

/* ============================================================
   LOGO
   ============================================================ */

.pf-auth-page .pf-logo {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  text-decoration: none;
  color: inherit;
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.pf-auth-page .pf-logo > span {
  display: inline-flex;
  align-items: center;
}

.pf-auth-page .pf-logo > span > span {
  color: #5eead4;
}

.pf-auth-page .pf-logo-icon {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: #ffffff;
  box-shadow:
    0 8px 25px rgba(0, 0, 0, 0.12);
}

.pf-auth-page .pf-logo-icon svg {
  width: 22px;
  height: 22px;
}

/* ============================================================
   TEXTE BRAND
   ============================================================ */

.pf-auth-brand h1 {
  max-width: 540px;
  margin: 72px 0 22px;
  color: #ffffff;
  font-size: clamp(38px, 4vw, 58px);
  line-height: 1.04;
  font-weight: 800;
  letter-spacing: -2px;
}

.pf-auth-brand-description {
  max-width: 500px;
  margin: 0;
  color: rgba(255, 255, 255, 0.76);
  font-size: 16px;
  line-height: 1.75;
}

/* ============================================================
   AVANTAGES
   ============================================================ */

.pf-auth-benefits {
  display: grid;
  gap: 15px;
  margin-top: 42px;
}

.pf-auth-benefit {
  display: flex;
  align-items: center;
  gap: 12px;
  color: rgba(255, 255, 255, 0.9);
  font-size: 14px;
  line-height: 1.5;
}

.pf-auth-benefit-check {
  flex: 0 0 auto;
  width: 25px;
  height: 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.14);
  color: #99f6e4;
  font-size: 13px;
  font-weight: 800;
}

/* ============================================================
   PANNEAU FORMULAIRE
   ============================================================ */

.pf-auth-form-side {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #ffffff;
}

.pf-auth-form-container {
  width: min(100%, 470px);
  padding: 56px 40px;
}

/* ============================================================
   LOGO MOBILE
   ============================================================ */

.pf-auth-mobile-logo {
  display: none !important;
}

/* ============================================================
   HEADER FORMULAIRE
   ============================================================ */

.pf-auth-header {
  margin-bottom: 32px;
}

.pf-auth-title {
  margin: 0;
  color: var(--pf-text);
  font-size: 32px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: -1px;
}

.pf-auth-description {
  margin: 10px 0 0;
  color: var(--pf-text-soft);
  font-size: 14px;
  line-height: 1.65;
}

/* ============================================================
   FORMULAIRE
   ============================================================ */

.pf-auth-form {
  display: flex;
  flex-direction: column;
  gap: 21px;
}

.pf-auth-form .pf-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pf-auth-form .pf-label {
  color: var(--pf-text);
  font-size: 13px;
  line-height: 1.4;
  font-weight: 700;
}

/* ============================================================
   INPUTS
   ============================================================ */

.pf-auth-form .pf-input {
  width: 100%;
  min-height: 48px;
  padding: 0 14px;
  border: 1px solid #dbe3e8;
  border-radius: var(--pf-auth-input-radius);
  outline: none;
  background: #ffffff;
  color: var(--pf-text);
  font-family: inherit;
  font-size: 14px;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease;
  box-sizing: border-box;
}

.pf-auth-form .pf-input::placeholder {
  color: #a0aab5;
}

.pf-auth-form .pf-input:hover {
  border-color: #c7d2d9;
}

.pf-auth-form .pf-input:focus {
  border-color: var(--pf-primary);
  box-shadow:
    0 0 0 3px rgba(15, 118, 110, 0.1);
}

.pf-auth-form .pf-input:disabled {
  opacity: 0.65;
  cursor: not-allowed;
  background: #f8fafb;
}

/* ============================================================
   MOT DE PASSE
   ============================================================ */

.pf-auth-password-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.pf-auth-forgot {
  color: var(--pf-primary);
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
}

.pf-auth-forgot:hover {
  color: var(--pf-primary-dark);
  text-decoration: underline;
}

.pf-auth-password-wrapper {
  position: relative;
}

.pf-auth-password-wrapper .pf-input {
  padding-right: 48px;
}

.pf-auth-password-toggle {
  position: absolute;
  top: 50%;
  right: 7px;
  width: 35px;
  height: 35px;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--pf-text-muted);
  cursor: pointer;
  transition:
    color 150ms ease,
    background 150ms ease;
}

.pf-auth-password-toggle:hover {
  color: var(--pf-primary);
  background: var(--pf-primary-light);
}

.pf-auth-password-toggle:focus-visible {
  outline: 2px solid var(--pf-primary);
  outline-offset: 2px;
}

.pf-auth-password-toggle:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ============================================================
   SE SOUVENIR DE MOI
   ============================================================ */

.pf-auth-remember {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  width: fit-content;
  color: var(--pf-text-secondary);
  font-size: 12px;
  line-height: 1.4;
  cursor: pointer;
  user-select: none;
}

.pf-auth-remember input {
  width: 16px;
  height: 16px;
  margin: 0;
  accent-color: var(--pf-primary);
  cursor: pointer;
}

.pf-auth-remember input:disabled {
  cursor: not-allowed;
}

/* ============================================================
   BOUTON LOGIN
   ============================================================ */

.pf-auth-submit {
  width: 100%;
  min-height: 50px;
  margin-top: 2px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 0;
  border-radius: 11px;
  font-size: 14px;
  font-weight: 750;
  cursor: pointer;
  transition:
    transform 150ms ease,
    box-shadow 150ms ease,
    opacity 150ms ease;
}

.pf-auth-submit:not(:disabled):hover {
  transform: translateY(-1px);
  box-shadow:
    0 10px 24px rgba(15, 118, 110, 0.18);
}

.pf-auth-submit:not(:disabled):active {
  transform: translateY(0);
}

.pf-auth-submit:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}

/* ============================================================
   SPINNER AUTH
   ============================================================ */

.pf-auth-submit .pf-spinner {
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
  border: 2px solid rgba(255, 255, 255, 0.35);
  border-top-color: #ffffff;
  border-radius: 50%;
  animation: pf-auth-spin 700ms linear infinite;
}

@keyframes pf-auth-spin {
  to {
    transform: rotate(360deg);
  }
}

/* ============================================================
   ALERTES
   ============================================================ */

.pf-auth-form-container .pf-alert {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  width: 100%;
  padding: 12px 14px;
  border-radius: 11px;
  box-sizing: border-box;
  font-size: 13px;
  line-height: 1.5;
}

.pf-auth-form-container .pf-alert > span {
  flex: 0 0 auto;
  width: 21px;
  height: 21px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 11px;
  font-weight: 800;
}

.pf-auth-form-container .pf-alert-danger {
  color: #991b1b;
  background: #fef2f2;
  border: 1px solid #fecaca;
}

.pf-auth-form-container .pf-alert-danger > span {
  color: #ffffff;
  background: #dc2626;
}

.pf-auth-form-container .pf-alert-success {
  color: #166534;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
}

.pf-auth-form-container .pf-alert-success > span {
  color: #ffffff;
  background: #16a34a;
}

/* ============================================================
   FOOTER AUTH
   ============================================================ */

.pf-auth-footer {
  margin-top: 30px;
  color: var(--pf-text-soft);
  font-size: 13px;
  line-height: 1.6;
  text-align: center;
}

.pf-auth-footer a {
  color: var(--pf-primary);
  font-weight: 750;
  text-decoration: none;
}

.pf-auth-footer a:hover {
  color: var(--pf-primary-dark);
  text-decoration: underline;
}

.pf-auth-back-home {
  margin-top: 18px;
  text-align: center;
}

.pf-auth-back-home a {
  color: var(--pf-text-muted);
  font-size: 12px;
  font-weight: 600;
  text-decoration: none;
}

.pf-auth-back-home a:hover {
  color: var(--pf-primary);
}

/* ============================================================
   FORGOT PASSWORD / RESET PASSWORD
   ============================================================ */

.pf-password-page {
  min-height: 100vh;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px 20px;
  box-sizing: border-box;
  background:
    radial-gradient(
      circle at 50% 0%,
      rgba(15, 118, 110, 0.08),
      transparent 40%
    ),
    var(--pf-background);
}

.pf-password-card {
  width: min(100%, 460px);
  padding: 42px;
  border: 1px solid #e5e9ed;
  border-radius: 20px;
  background: #ffffff;
  box-shadow: var(--pf-auth-shadow);
  box-sizing: border-box;
}

.pf-password-logo {
  display: flex;
  justify-content: center;
  margin-bottom: 30px;
}

.pf-password-logo .pf-logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--pf-text);
  font-size: 23px;
  font-weight: 800;
  text-decoration: none;
}

.pf-password-logo .pf-logo > span > span {
  color: var(--pf-primary);
}

.pf-password-logo .pf-logo-icon {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: var(--pf-primary-light);
  color: var(--pf-primary);
}

.pf-password-header {
  margin-bottom: 28px;
  text-align: center;
}

.pf-password-header h1,
.pf-password-header h2 {
  margin: 0;
  color: var(--pf-text);
  font-size: 28px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: -0.7px;
}

.pf-password-header p {
  margin: 10px auto 0;
  max-width: 370px;
  color: var(--pf-text-soft);
  font-size: 14px;
  line-height: 1.65;
}

/* ============================================================
   FORMULAIRE PASSWORD
   ============================================================ */

.pf-password-form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.pf-password-form .pf-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pf-password-form label {
  color: var(--pf-text);
  font-size: 13px;
  font-weight: 700;
}

.pf-password-form input {
  width: 100%;
  min-height: 48px;
  padding: 0 14px;
  border: 1px solid #dbe3e8;
  border-radius: var(--pf-auth-input-radius);
  outline: none;
  background: #ffffff;
  color: var(--pf-text);
  font-family: inherit;
  font-size: 14px;
  box-sizing: border-box;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.pf-password-form input::placeholder {
  color: #a0aab5;
}

.pf-password-form input:focus {
  border-color: var(--pf-primary);
  box-shadow:
    0 0 0 3px rgba(15, 118, 110, 0.1);
}

.pf-password-form button[type="submit"] {
  width: 100%;
  min-height: 49px;
  margin-top: 3px;
}

/* ============================================================
   RETOUR LOGIN
   ============================================================ */

.pf-password-back {
  margin-top: 24px;
  text-align: center;
}

.pf-password-back a {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--pf-primary);
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
}

.pf-password-back a:hover {
  color: var(--pf-primary-dark);
  text-decoration: underline;
}

/* ============================================================
   INDICATEUR MOT DE PASSE
   ============================================================ */

.pf-password-strength {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-top: -2px;
}

.pf-password-strength-bars {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
}

.pf-password-strength-bar {
  height: 4px;
  border-radius: 999px;
  background: #e2e8f0;
}

.pf-password-strength-label {
  color: var(--pf-text-muted);
  font-size: 11px;
  font-weight: 600;
}

/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 980px) {
  .pf-auth-page {
    grid-template-columns: 1fr;
  }

  .pf-auth-brand {
    display: none;
  }

  .pf-auth-form-side {
    min-height: 100vh;
    padding: 30px 20px;
    box-sizing: border-box;
  }

  .pf-auth-form-container {
    width: min(100%, 470px);
    padding: 30px 0;
  }

  .pf-auth-mobile-logo {
    display: inline-flex !important;
    margin-bottom: 45px;
    color: var(--pf-text) !important;
  }

  .pf-auth-mobile-logo .pf-logo-icon {
    background: var(--pf-primary-light);
    color: var(--pf-primary);
    border-color: rgba(15, 118, 110, 0.1);
  }

  .pf-auth-mobile-logo > span > span {
    color: var(--pf-primary) !important;
  }
}

@media (max-width: 560px) {
  .pf-auth-form-side {
    align-items: flex-start;
    padding: 20px 16px;
  }

  .pf-auth-form-container {
    padding: 18px 0 30px;
  }

  .pf-auth-mobile-logo {
    margin-bottom: 34px;
  }

  .pf-auth-title {
    font-size: 28px;
  }

  .pf-auth-header {
    margin-bottom: 27px;
  }

  .pf-auth-form {
    gap: 18px;
  }

  .pf-auth-footer {
    margin-top: 26px;
  }

  .pf-password-page {
    align-items: flex-start;
    padding: 18px 14px;
  }

  .pf-password-card {
    padding: 30px 20px;
    border-radius: 16px;
    box-shadow: var(--pf-auth-shadow-soft);
  }

  .pf-password-header h1,
  .pf-password-header h2 {
    font-size: 25px;
  }
}

/* ============================================================
   TRÈS PETITS ÉCRANS
   ============================================================ */

@media (max-width: 380px) {
  .pf-auth-form-side {
    padding-left: 13px;
    padding-right: 13px;
  }

  .pf-auth-title {
    font-size: 25px;
  }

  .pf-auth-password-header {
    align-items: flex-start;
    flex-direction: column;
    gap: 5px;
  }

  .pf-password-card {
    padding: 26px 17px;
  }
}

/* ============================================================
   ACCESSIBILITÉ
   ============================================================ */

.pf-auth-page a:focus-visible,
.pf-password-page a:focus-visible,
.pf-auth-form button:focus-visible,
.pf-password-form button:focus-visible,
.pf-auth-form input:focus-visible,
.pf-password-form input:focus-visible {
  outline: 2px solid var(--pf-primary);
  outline-offset: 3px;
}

/* ============================================================
   RÉDUCTION DES ANIMATIONS
   ============================================================ */

@media (prefers-reduced-motion: reduce) {
  .pf-auth-submit,
  .pf-auth-password-toggle,
  .pf-auth-form .pf-input,
  .pf-password-form input {
    transition: none;
  }

  .pf-auth-submit .pf-spinner {
    animation: none;
  }
}

/* ============================================================
   IMPRESSION
   ============================================================ */

@media print {
  .pf-auth-page,
  .pf-password-page {
    min-height: auto;
    background: #ffffff;
  }

  .pf-auth-brand {
    display: none;
  }

  .pf-auth-form-side {
    min-height: auto;
  }

  .pf-auth-form-container,
  .pf-password-card {
    box-shadow: none;
    border: 0;
  }
}
/* ============================================================
   PHARMAFLOW — RESET PASSWORD
   CSS ADAPTÉ AU FICHIER reset-password/page.tsx
   ============================================================ */

/* ============================================================
   PAGE PRINCIPALE
   ============================================================ */

.pf-auth-page {
  position: relative;
  min-height: 100vh;
  width: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 40px 20px;

  background:
    radial-gradient(
      circle at 15% 15%,
      rgba(15, 118, 110, 0.10),
      transparent 34%
    ),
    radial-gradient(
      circle at 85% 85%,
      rgba(20, 184, 166, 0.08),
      transparent 32%
    ),
    linear-gradient(
      135deg,
      #f5f8f8 0%,
      #eef7f5 50%,
      #f8fafc 100%
    );

  box-sizing: border-box;
  overflow: hidden;
}

/* ============================================================
   ARRIÈRE-PLAN
   ============================================================ */

.pf-auth-background {
  position: absolute;
  inset: 0;

  width: 100%;
  height: 100%;

  pointer-events: none;
  overflow: hidden;
}

.pf-auth-orb {
  position: absolute;

  border-radius: 999px;

  filter: blur(1px);

  pointer-events: none;
}

.pf-auth-orb-one {
  width: 420px;
  height: 420px;

  top: -210px;
  left: -150px;

  background:
    radial-gradient(
      circle,
      rgba(15, 118, 110, 0.10) 0%,
      rgba(15, 118, 110, 0.035) 45%,
      transparent 72%
    );
}

.pf-auth-orb-two {
  width: 500px;
  height: 500px;

  right: -220px;
  bottom: -260px;

  background:
    radial-gradient(
      circle,
      rgba(20, 184, 166, 0.09) 0%,
      rgba(20, 184, 166, 0.025) 48%,
      transparent 72%
    );
}

/* ============================================================
   CONTENEUR
   ============================================================ */

.pf-auth-container {
  position: relative;
  z-index: 2;

  width: 100%;
  max-width: 560px;

  display: flex;
  flex-direction: column;
  align-items: center;
}

/* ============================================================
   CARTE
   ============================================================ */

.pf-auth-card {
  width: 100%;

  padding: 42px 46px;

  background: rgba(255, 255, 255, 0.97);

  border: 1px solid #e2e8f0;
  border-radius: 24px;

  box-shadow:
    0 24px 60px rgba(15, 23, 42, 0.09),
    0 6px 20px rgba(15, 23, 42, 0.04);

  box-sizing: border-box;
}

/* ============================================================
   LOGO PHARMAFLOW
   ============================================================ */

.pf-auth-logo {
  display: flex;
  align-items: center;
  justify-content: center;

  gap: 13px;

  margin-bottom: 30px;
}

.pf-auth-logo-icon {
  width: 52px;
  height: 52px;

  flex: 0 0 52px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 15px;

  background: linear-gradient(
    135deg,
    #0f766e 0%,
    #115e59 100%
  );

  color: #ffffff;

  font-size: 27px;
  font-weight: 800;

  box-shadow:
    0 10px 24px rgba(15, 118, 110, 0.22);
}

.pf-auth-logo-icon span {
  display: flex;
  align-items: center;
  justify-content: center;

  line-height: 1;
}

.pf-auth-logo-name {
  color: #0f172a;

  font-size: 20px;
  line-height: 1.2;
  font-weight: 800;

  letter-spacing: -0.02em;
}

.pf-auth-logo-subtitle {
  margin-top: 3px;

  color: #64748b;

  font-size: 12px;
  line-height: 1.4;
  font-weight: 500;
}

/* ============================================================
   HEADER
   ============================================================ */

.pf-auth-header {
  text-align: center;

  margin-bottom: 28px;
}

.pf-auth-badge {
  width: fit-content;

  margin: 0 auto 16px;
  padding: 7px 12px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 7px;

  border: 1px solid #ccfbf1;
  border-radius: 999px;

  background: #f0fdfa;

  color: #0f766e;

  font-size: 12px;
  line-height: 1;
  font-weight: 700;
}

.pf-auth-badge-icon {
  font-size: 13px;
  line-height: 1;
}

.pf-auth-header h1 {
  margin: 0 0 11px;

  color: #0f172a;

  font-size: 31px;
  line-height: 1.2;
  font-weight: 800;

  letter-spacing: -0.03em;
}

.pf-auth-header p {
  max-width: 465px;

  margin: 0 auto;

  color: #64748b;

  font-size: 14px;
  line-height: 1.65;
}

/* ============================================================
   FORMULAIRE
   ============================================================ */

.pf-auth-form {
  width: 100%;

  display: flex;
  flex-direction: column;

  gap: 20px;
}

.pf-form-group {
  width: 100%;

  display: flex;
  flex-direction: column;

  gap: 8px;
}

/* ============================================================
   LABELS
   ============================================================ */

.pf-form-label {
  display: block;

  color: #334155;

  font-size: 14px;
  line-height: 1.4;
  font-weight: 700;
}

/* ============================================================
   CONTENEUR INPUT
   ============================================================ */

.pf-input-wrapper {
  position: relative;

  width: 100%;
}

/* ============================================================
   ICÔNE INPUT
   ============================================================ */

.pf-input-icon {
  position: absolute;

  top: 50%;
  left: 15px;

  transform: translateY(-50%);

  width: 20px;
  height: 20px;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #64748b;

  font-size: 15px;

  pointer-events: none;

  z-index: 2;
}

/* ============================================================
   INPUT
   ============================================================ */

.pf-form-input {
  width: 100%;
  height: 52px;

  padding: 0 15px;

  border: 1px solid #cbd5e1;
  border-radius: 12px;

  background: #ffffff;

  color: #0f172a;

  font-family: inherit;
  font-size: 14px;
  line-height: 1.4;

  outline: none;

  box-sizing: border-box;

  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.pf-form-input-with-icon {
  padding-left: 45px;
}

.pf-form-input-with-action {
  padding-right: 55px;
}

.pf-form-input::placeholder {
  color: #94a3b8;
}

.pf-form-input:hover {
  border-color: #94a3b8;
}

.pf-form-input:focus {
  border-color: #0f766e;

  background: #ffffff;

  box-shadow:
    0 0 0 4px rgba(15, 118, 110, 0.10);
}

.pf-form-input:disabled {
  background: #f8fafc;

  color: #94a3b8;

  cursor: not-allowed;

  opacity: 0.8;
}

/* ============================================================
   BOUTON AFFICHER / MASQUER
   ============================================================ */

.pf-input-action {
  position: absolute;

  top: 50%;
  right: 9px;

  width: 36px;
  height: 36px;

  transform: translateY(-50%);

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 0;

  border: 0;
  border-radius: 9px;

  background: transparent;

  color: #64748b;

  font-size: 16px;

  cursor: pointer;

  transition:
    background 0.2s ease,
    color 0.2s ease;
}

.pf-input-action:hover {
  background: #f1f5f9;

  color: #0f766e;
}

.pf-input-action:active {
  transform: translateY(-50%) scale(0.96);
}

.pf-input-action:disabled {
  opacity: 0.5;

  cursor: not-allowed;
}

/* ============================================================
   INDICATION MOT DE PASSE
   ============================================================ */

.pf-form-hint {
  margin: 0;

  color: #64748b;

  font-size: 12px;
  line-height: 1.5;
}

/* ============================================================
   BOUTON PRINCIPAL
   ============================================================ */

.pf-btn {
  min-height: 50px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 8px;

  padding: 0 18px;

  border-radius: 12px;

  font-family: inherit;

  font-size: 14px;
  font-weight: 700;

  cursor: pointer;

  box-sizing: border-box;

  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.15s ease,
    box-shadow 0.2s ease;
}

.pf-btn-primary {
  border: 1px solid #0f766e;

  background: #0f766e;

  color: #ffffff;

  box-shadow:
    0 8px 18px rgba(15, 118, 110, 0.18);
}

.pf-btn-primary:hover {
  border-color: #115e59;

  background: #115e59;

  box-shadow:
    0 10px 22px rgba(15, 118, 110, 0.24);
}

.pf-btn-primary:active {
  transform: translateY(1px);
}

.pf-btn-primary:disabled {
  opacity: 0.65;

  cursor: not-allowed;

  transform: none;

  box-shadow: none;
}

.pf-btn-full {
  width: 100%;
}

/* ============================================================
   BOUTON SUBMIT AUTH
   ============================================================ */

.pf-auth-submit {
  margin-top: 3px;

  min-height: 52px;
}

.pf-auth-submit span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ============================================================
   SPINNER
   ============================================================ */

.pf-spinner {
  width: 19px;
  height: 19px;

  display: inline-block;

  border: 2px solid rgba(255, 255, 255, 0.35);

  border-top-color: #ffffff;

  border-radius: 50%;

  animation: pf-auth-spin 0.75s linear infinite;
}

.pf-spinner-small {
  width: 17px;
  height: 17px;

  border-width: 2px;
}

@keyframes pf-auth-spin {
  to {
    transform: rotate(360deg);
  }
}

/* ============================================================
   ALERTE
   ============================================================ */

.pf-alert {
  width: 100%;

  margin-bottom: 20px;

  padding: 13px 15px;

  display: flex;
  align-items: flex-start;

  gap: 10px;

  border-radius: 12px;

  font-size: 13px;
  line-height: 1.55;

  box-sizing: border-box;
}

.pf-alert-danger {
  border: 1px solid #fecaca;

  background: #fef2f2;

  color: #991b1b;
}

.pf-alert-icon {
  width: 20px;
  height: 20px;

  flex: 0 0 20px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #fee2e2;

  color: #b91c1c;

  font-size: 12px;
  font-weight: 800;
}

/* ============================================================
   ÉTAT DE SUCCÈS
   ============================================================ */

.pf-auth-success {
  width: 100%;

  text-align: center;
}

.pf-auth-success-icon {
  width: 68px;
  height: 68px;

  margin: 0 auto 20px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #dcfce7;

  color: #15803d;

  font-size: 31px;
  font-weight: 800;

  box-shadow:
    0 8px 22px rgba(22, 163, 74, 0.12);
}

.pf-auth-success h2 {
  margin: 0 0 10px;

  color: #0f172a;

  font-size: 23px;
  line-height: 1.25;
  font-weight: 800;
}

.pf-auth-success p {
  margin: 0 0 24px;

  color: #64748b;

  font-size: 14px;
  line-height: 1.65;
}

/* ============================================================
   RETOUR CONNEXION
   ============================================================ */

.pf-auth-footer-link {
  margin-top: 23px;

  text-align: center;
}

.pf-auth-back-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 6px;

  color: #0f766e;

  font-size: 14px;
  font-weight: 700;

  text-decoration: none;

  transition:
    color 0.2s ease,
    transform 0.15s ease;
}

.pf-auth-back-link:hover {
  color: #115e59;

  text-decoration: underline;
}

.pf-auth-back-link:active {
  transform: translateX(-1px);
}

/* ============================================================
   SÉCURITÉ
   ============================================================ */

.pf-auth-security {
  margin-top: 27px;
  padding-top: 20px;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 8px;

  border-top: 1px solid #e2e8f0;

  color: #64748b;

  font-size: 12px;
  line-height: 1.5;

  text-align: center;
}

.pf-auth-security-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  font-size: 15px;
}

/* ============================================================
   CHARGEMENT
   ============================================================ */

.pf-auth-loading {
  min-height: 150px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 14px;

  text-align: center;
}

.pf-auth-loading .pf-spinner {
  width: 32px;
  height: 32px;

  border-width: 3px;

  border-color: rgba(15, 118, 110, 0.18);
  border-top-color: #0f766e;
}

.pf-auth-loading p {
  margin: 0;

  color: #64748b;

  font-size: 14px;
  font-weight: 600;
}

/* ============================================================
   FOOTER PAGE
   ============================================================ */

.pf-auth-page-footer {
  margin-top: 20px;

  color: #94a3b8;

  font-size: 12px;
  line-height: 1.5;

  text-align: center;
}

/* ============================================================
   FOCUS ACCESSIBLE
   ============================================================ */

.pf-form-input:focus-visible,
.pf-input-action:focus-visible,
.pf-btn:focus-visible,
.pf-auth-back-link:focus-visible {
  outline: 3px solid rgba(15, 118, 110, 0.22);

  outline-offset: 2px;
}

/* ============================================================
   TABLETTE
   ============================================================ */

@media (max-width: 700px) {
  .pf-auth-page {
    padding: 30px 16px;
  }

  .pf-auth-container {
    max-width: 540px;
  }

  .pf-auth-card {
    padding: 36px 32px;

    border-radius: 21px;
  }

  .pf-auth-header h1 {
    font-size: 28px;
  }
}

/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 520px) {
  .pf-auth-page {
    min-height: 100dvh;

    padding: 20px 12px;
  }

  .pf-auth-card {
    padding: 30px 22px;

    border-radius: 19px;
  }

  .pf-auth-logo {
    margin-bottom: 25px;
  }

  .pf-auth-logo-icon {
