    border-radius: 14px;

    font-size: 25px;
  }

  .pf-auth-logo-name {
    font-size: 19px;
  }

  .pf-auth-logo-subtitle {
    font-size: 11px;
  }

  .pf-auth-header {
    margin-bottom: 25px;
  }

  .pf-auth-header h1 {
    font-size: 25px;
  }

  .pf-auth-header p {
    font-size: 13px;
  }

  .pf-auth-form {
    gap: 18px;
  }

  .pf-form-input {
    height: 51px;
  }

  .pf-auth-security {
    margin-top: 24px;
