   ============================================================ */

@media (max-width: 380px) {
  .pf-auth-page {
    padding: 14px 9px;
  }

  .pf-auth-card {
    padding: 26px 17px;

    border-radius: 17px;
  }

  .pf-auth-logo {
    gap: 10px;
    margin-bottom: 22px;
  }

  .pf-auth-logo-icon {
    width: 44px;
    height: 44px;

    flex-basis: 44px;

    border-radius: 12px;

    font-size: 23px;
  }

  .pf-auth-logo-name {
    font-size: 18px;
  }

  .pf-auth-header h1 {
    font-size: 22px;
  }

