  }

  .pf-auth-security {
    font-size: 11px;
  }
}

/* ============================================================
   RÉDUCTION DES ANIMATIONS
   ============================================================ */

@media (prefers-reduced-motion: reduce) {
  .pf-auth-page *,
  .pf-auth-page *::before,
  .pf-auth-page *::after {
    scroll-behavior: auto !important;
  }

  .pf-spinner {
    animation: none;
  }

  .pf-form-input,
  .pf-input-action,
  .pf-btn,
  .pf-auth-back-link {
    transition: none;
  }
}

/* ============================================================
   IMPRESSION
