/* =========================================================
   PHARMAFLOW — STOCK
   ========================================================= */

.pf-page {
  width: 100%;
  min-height: 100vh;
  padding: 28px;
  background: var(--pf-background);
  color: var(--pf-text);
}

.pf-page-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 20px;
  margin-bottom: 24px;
}

.pf-page-header h1 {
  margin: 0;
  font-size: 30px;
  line-height: 1.2;
  font-weight: 800;
  color: var(--pf-text);
}

.pf-page-header p {
  margin: 8px 0 0;
  color: var(--pf-text-soft);
  font-size: 14px;
  line-height: 1.6;
}

.pf-breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  color: var(--pf-text-soft);
  font-size: 13px;
}

.pf-breadcrumb a {
  color: var(--pf-primary);
  text-decoration: none;
  font-weight: 600;
}

.pf-breadcrumb a:hover {
  text-decoration: underline;
}

.pf-page-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

/* =========================================================
   BOUTONS
   ========================================================= */

.pf-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 42px;
  padding: 10px 16px;
  border: 1px solid transparent;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  transition:
    background-color 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.15s ease,
    box-shadow 0.2s ease;
}

.pf-btn:hover {
  transform: translateY(-1px);
}

.pf-btn:active {
  transform: translateY(0);
}

.pf-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
}

.pf-btn-primary {
  background: var(--pf-primary);
  border-color: var(--pf-primary);
  color: #ffffff;
}

.pf-btn-primary:hover {
  background: var(--pf-primary-dark);
  border-color: var(--pf-primary-dark);
}

.pf-btn-secondary {
  background: #ffffff;
  border-color: var(--pf-border);
  color: var(--pf-text);
}

.pf-btn-secondary:hover {
  border-color: var(--pf-primary);
  color: var(--pf-primary);
}

.pf-btn-sm {
  min-height: 36px;
  padding: 8px 12px;
  font-size: 13px;
}

.pf-btn-xs {
  min-width: 34px;
  min-height: 32px;
  padding: 6px 9px;
  border-radius: 8px;
  font-size: 13px;
}

/* =========================================================
   ALERTES
   ========================================================= */

.pf-alert {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  margin-bottom: 20px;
  padding: 13px 15px;
  border: 1px solid transparent;
  border-radius: 12px;
  font-size: 14px;
}

.pf-alert strong {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  border-radius: 50%;
  font-weight: 800;
}

.pf-alert span {
  flex: 1;
}

.pf-alert button {
  border: 0;
  background: transparent;
  color: inherit;
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
}

.pf-alert-danger {
  background: #fff1f2;
  border-color: #fecdd3;
  color: #9f1239;
}

.pf-alert-danger strong {
  background: #ffe4e6;
}

.pf-alert-success {
  background: #ecfdf5;
  border-color: #a7f3d0;
  color: #047857;
}

.pf-alert-success strong {
  background: #d1fae5;
}

/* =========================================================
   ONGLETS STOCK
   ========================================================= */

.pf-stock-tabs {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
  margin-bottom: 22px;
  padding: 5px;
  background: #ffffff;
  border: 1px solid var(--pf-border);
  border-radius: 12px;
  overflow-x: auto;
}

.pf-stock-tabs button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 40px;
  padding: 8px 15px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--pf-text-soft);
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color 0.2s ease,
    color 0.2s ease;
}

.pf-stock-tabs button:hover {
  background: var(--pf-primary-light);
  color: var(--pf-primary-dark);
}

.pf-stock-tabs button.active {
  background: var(--pf-primary);
  color: #ffffff;
}

.pf-tab-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 21px;
  height: 21px;
  padding: 0 6px;
  border-radius: 999px;
  background: #fee2e2;
  color: #b91c1c;
  font-size: 11px;
  font-weight: 800;
}

.pf-stock-tabs button.active .pf-tab-count {
  background: #ffffff;
  color: var(--pf-primary);
}

/* =========================================================
   STATISTIQUES
   ========================================================= */

.pf-stock-stats {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

.pf-stock-stats .pf-stat-card {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
  padding: 20px;
  background: #ffffff;
  border: 1px solid var(--pf-border);
  border-radius: 14px;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.pf-stock-stats .pf-stat-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  border-radius: 12px;
  background: var(--pf-primary-light);
  font-size: 22px;
}

.pf-stock-stats .pf-stat-card > div:last-child {
  min-width: 0;
}

.pf-stock-stats .pf-stat-card span {
  display: block;
  margin-bottom: 5px;
  color: var(--pf-text-soft);
  font-size: 12px;
  font-weight: 700;
}

.pf-stock-stats .pf-stat-card strong {
  display: block;
  color: var(--pf-text);
  font-size: 21px;
  line-height: 1.2;
  font-weight: 800;
  word-break: break-word;
}

/* =========================================================
   CARTES ALERTES
   ========================================================= */

.pf-stock-alert-grid {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

.pf-stock-alert-card {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 18px;
  border: 1px solid var(--pf-border);
  border-radius: 14px;
  background: #ffffff;
  text-align: left;
  cursor: pointer;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    border-color 0.2s ease;
}

.pf-stock-alert-card:hover {
  transform: translateY(-2px);
  box-shadow:
    0 8px 24px rgba(15, 23, 42, 0.08);
}

.pf-stock-alert-card.danger {
  border-color: #fecaca;
  background: #fffafa;
}

.pf-stock-alert-card.warning {
  border-color: #fde68a;
  background: #fffdf5;
}

.pf-stock-alert-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  border-radius: 12px;
  background: #f8fafc;
  font-size: 21px;
}

.pf-stock-alert-card > span:last-child {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.pf-stock-alert-card strong {
  color: var(--pf-text);
  font-size: 24px;
  line-height: 1.1;
  font-weight: 800;
}

.pf-stock-alert-card small {
  margin-top: 4px;
  color: var(--pf-text-soft);
  font-size: 12px;
  font-weight: 700;
}

/* =========================================================
   GRILLES ET CARTES
   ========================================================= */

.pf-grid {
  display: grid;
  gap: 20px;
}

.pf-grid-2 {
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
}

.pf-card {
  min-width: 0;
  padding: 22px;
  background: #ffffff;
  border: 1px solid var(--pf-border);
  border-radius: 14px;
  box-shadow:
    0 4px 14px rgba(15, 23, 42, 0.04);
}

.pf-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}

.pf-card-header h2 {
  margin: 0;
  color: var(--pf-text);
  font-size: 18px;
  font-weight: 800;
}

.pf-card-header p {
  margin: 5px 0 0;
  color: var(--pf-text-soft);
  font-size: 13px;
}

/* =========================================================
   LISTES STOCK
   ========================================================= */

.pf-stock-mini-list {
  display: flex;
  flex-direction: column;
}

.pf-stock-mini-row {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    auto
    auto;
  align-items: center;
  gap: 14px;
  padding: 14px 0;
  border-bottom: 1px solid var(--pf-border);
}

.pf-stock-mini-row:last-child {
  border-bottom: 0;
}

.pf-stock-mini-row > div:first-child {
  min-width: 0;
}

.pf-stock-mini-row strong {
  display: block;
  color: var(--pf-text);
  font-size: 14px;
  font-weight: 700;
}

.pf-stock-mini-row small {
  display: block;
  margin-top: 4px;
  color: var(--pf-text-soft);
  font-size: 12px;
}

.pf-stock-mini-row > div:nth-child(2) {
  text-align: right;
}

.pf-stock-mini-row > div:nth-child(2) strong {
  display: inline;
}

.pf-stock-mini-row > div:nth-child(2) small {
  display: inline;
  margin-left: 3px;
}

/* =========================================================
   STATUT DU STOCK
   ========================================================= */

.pf-stock-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 26px;
  padding: 5px 9px;
  border-radius: 999px;
  font-size: 11px;
  line-height: 1;
  font-weight: 800;
  white-space: nowrap;
}

.pf-stock-status-success {
  background: #dcfce7;
  color: #166534;
}

.pf-stock-status-warning {
  background: #fef3c7;
  color: #92400e;
}

.pf-stock-status-danger {
  background: #fee2e2;
  color: #b91c1c;
}

/* =========================================================
   MOUVEMENTS
   ========================================================= */

.pf-movement-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
  padding: 5px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.pf-movement-badge.entry {
  background: #dcfce7;
  color: #166534;
}

.pf-movement-badge.exit {
  background: #fee2e2;
  color: #b91c1c;
}

.pf-product-cell {
  display: flex;
  flex-direction: column;
  min-width: 160px;
}

.pf-product-cell strong {
  color: var(--pf-text);
  font-size: 14px;
  font-weight: 700;
}

.pf-product-cell small {
  margin-top: 3px;
  color: var(--pf-text-soft);
  font-size: 12px;
}

.pf-inline-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* =========================================================
   BARRE DE RECHERCHE / FILTRES
   ========================================================= */

.pf-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}

.pf-input {
  width: 100%;
  min-height: 42px;
  padding: 10px 13px;
  border: 1px solid var(--pf-border);
  border-radius: 9px;
  outline: none;
  background: #ffffff;
  color: var(--pf-text);
  font-family: inherit;
  font-size: 14px;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.pf-input::placeholder {
  color: var(--pf-text-muted);
}

.pf-input:focus {
  border-color: var(--pf-primary);
  box-shadow:
    0 0 0 3px
    rgba(15, 118, 110, 0.10);
}

.pf-toolbar .pf-input {
  max-width: 520px;
}

.pf-filter-btn {
  min-height: 38px;
  padding: 8px 13px;
  border: 1px solid var(--pf-border);
  border-radius: 9px;
  background: #ffffff;
  color: var(--pf-text-soft);
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}

.pf-filter-btn:hover {
  border-color: var(--pf-primary);
  color: var(--pf-primary);
}

.pf-filter-btn.active {
  border-color: var(--pf-primary);
  background: var(--pf-primary);
  color: #ffffff;
}

/* =========================================================
   TABLEAUX
   ========================================================= */

.pf-table-wrapper {
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--pf-border);
  border-radius: 10px;
}

.pf-table {
  width: 100%;
  min-width: 850px;
  border-collapse: collapse;
  background: #ffffff;
}

.pf-table thead {
  background: #f8fafc;
}

.pf-table th {
  padding: 13px 14px;
  border-bottom: 1px solid var(--pf-border);
  color: var(--pf-text-soft);
  font-size: 11px;
  font-weight: 800;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.pf-table td {
  padding: 14px;
  border-bottom: 1px solid var(--pf-border);
  color: var(--pf-text-secondary);
  font-size: 13px;
  vertical-align: middle;
}

.pf-table tbody tr:last-child td {
  border-bottom: 0;
}

.pf-table tbody tr:hover {
  background: #f8fafc;
}

.pf-table td strong {
  color: var(--pf-text);
  font-weight: 700;
}

/* =========================================================
   EXPIRATION
   ========================================================= */

.pf-expiry-warning {
  color: #b45309;
  font-weight: 700;
}

.pf-expiry-danger {
  color: #b91c1c;
  font-weight: 800;
}

/* =========================================================
   ÉTAT VIDE
   ========================================================= */

.pf-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 150px;
  padding: 28px 20px;
  color: var(--pf-text-soft);
  text-align: center;
  font-size: 14px;
}

.pf-empty-state h3 {
  margin: 8px 0 5px;
  color: var(--pf-text);
  font-size: 16px;
}

.pf-empty-state p {
  max-width: 520px;
  margin: 0;
  line-height: 1.6;
}

.pf-empty-icon {
  font-size: 28px;
}

/* =========================================================
   CHARGEMENT
   ========================================================= */

.pf-loading-card {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 240px;
  padding: 30px;
  background: #ffffff;
  border: 1px solid var(--pf-border);
  border-radius: 14px;
  color: var(--pf-text-soft);
  font-size: 14px;
}

.pf-spinner {
  width: 24px;
  height: 24px;
  border: 3px solid #dbe7e5;
  border-top-color: var(--pf-primary);
  border-radius: 50%;
  animation: pf-stock-spin 0.8s linear infinite;
}

@keyframes pf-stock-spin {
  to {
    transform: rotate(360deg);
  }
}
