  .pf-countdown-grid strong {
    font-size: 20px;
  }

  .pf-countdown-grid small {
    font-size: 9px;
  }

  .pf-plan-price strong {
    font-size: 27px;
  }

  .pf-payment-actions {
    flex-direction: column-reverse;
  }

  .pf-payment-actions .pf-btn {
    width: 100%;
  }
