@media print {
  .pf-subscription-header,
  .pf-subscription-footer,
  .pf-subscription-header-actions {
    display: none !important;
  }

  .pf-subscription-page {
    background: #ffffff !important;
  }

  .pf-subscription-container {
    width: 100% !important;
    padding: 0 !important;
  }
}
