.pf-home-support-card h3 {
  margin: 0 0 9px;
  color: #1b3249;
  font-size: 18px;
  font-weight: 850;
}

.pf-home-support-card p {
  margin: 0;
  color: #77889a;
  font-size: 13px;
  line-height: 1.7;
}

.pf-home-support-card a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 25px;
  color: #1167d8;
  font-size: 11px;
  font-weight: 850;
}

.pf-home-support-cta {
  margin-top: 22px;
  padding: 25px 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  border: 1px solid #dfe8ef;
  border-radius: 20px;
  background: white;
}

.pf-home-support-cta div {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.pf-home-support-cta strong {
  color: #1b334a;
  font-size: 15px;
  font-weight: 850;
}

.pf-home-support-cta span {
  color: #7a8a9a;
  font-size: 12px;
}

/* ============================================================
   PRICING
   ============================================================ */

.pf-home-pricing {
  padding-top: 110px;
  padding-bottom: 120px;
}

.pf-home-billing-switch {
  width: fit-content;
  display: flex;
  margin: -15px auto 42px;
  padding: 5px;
  border: 1px solid #e0e7ee;
  border-radius: 13px;
  background: #f5f8fb;
}

.pf-home-billing-switch button {
  min-width: 105px;
  padding: 9px 15px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #778798;
  cursor: pointer;
  font-size: 11px;
  font-weight: 850;
}

.pf-home-billing-switch button.active {
  background: white;
  color: #1167d8;
  box-shadow:
    0 4px 12px rgba(15, 43, 70, 0.08);
}

.pf-home-pricing-grid {
  width: min(850px, 100%);
  margin: 0 auto;
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.pf-home-price-card {
  position: relative;
  overflow: hidden;
  padding: 32px;
  border: 1px solid #dfe7ee;
  border-radius: 24px;
  background: white;
  box-shadow:
    0 14px 38px rgba(15, 43, 70, 0.05);
}

.pf-home-price-card.selected {
  border-color: #bcd7ed;
  box-shadow:
    0 20px 50px rgba(17, 103, 216, 0.1);
}

.pf-home-price-card.popular {
  border-color: #1167d8;
}

.pf-home-popular {
  position: absolute;
  top: 0;
  right: 0;
  padding: 7px 12px;
  border-radius:
    0 0 0 12px;
  background: #1167d8;
  color: white;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.pf-home-price-top > span {
  color: #718397;
  font-size: 12px;
  font-weight: 800;
}

.pf-home-price-top h3 {
  margin: 17px 0 3px;
  color: #142b41;
  font-size: 42px;
  line-height: 1;
  font-weight: 900;
  letter-spacing: -0.05em;
}

.pf-home-price-top h3 small {
  margin-left: 7px;
  color: #77899b;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0;
}

.pf-home-price-top p {
  margin: 0;
  color: #8998a8;
  font-size: 11px;
}

.pf-home-price-features {
  display: grid;
  gap: 12px;
  margin: 30px 0;
  padding-top: 25px;
  border-top: 1px solid #edf1f5;
}

.pf-home-price-features div {
  color: #64768a;
  font-size: 11px;
  line-height: 1.4;
}

.pf-home-price-button {
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 1px solid #d9e3ec;
  border-radius: 12px;
  background: #f8fafc;
  color: #1167d8;
  font-size: 12px;
  font-weight: 850;
  transition:
    transform 0.2s ease,
    background 0.2s ease;
}

.pf-home-price-card.popular
  .pf-home-price-button,
.pf-home-price-card.selected
  .pf-home-price-button {
  border-color: #1167d8;
  background: #1167d8;
  color: white;
}

.pf-home-price-button:hover {
  transform: translateY(-2px);
}

/* ============================================================
   FINAL CTA
   ============================================================ */

.pf-home-final-cta {
  position: relative;
  overflow: hidden;
  padding: 105px 20px;
  background:
    linear-gradient(
      135deg,
      #0b3155,
      #087c7b
    );
  color: white;
  text-align: center;
}

.pf-home-final-cta-glow {
  position: absolute;
  width: 450px;
  height: 450px;
  left: 50%;
  top: -300px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.09);
  filter: blur(10px);
}

.pf-home-final-cta-content {
  position: relative;
  z-index: 1;
  max-width: 760px;
  margin: 0 auto;
}

.pf-home-final-badge {
  width: fit-content;
  margin: 0 auto 17px;
  padding: 7px 12px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.09);
  color: #dffffb;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.pf-home-final-cta h2 {
  margin: 0 0 15px;
  color: white;
  font-size: clamp(
    34px,
    5vw,
    55px
  );
  line-height: 1.04;
  letter-spacing: -0.055em;
  font-weight: 900;
}

.pf-home-final-cta p {
  max-width: 600px;
  margin: 0 auto;
  color: rgba(255, 255, 255, 0.72);
  font-size: 15px;
  line-height: 1.7;
}

.pf-home-final-buttons {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  gap: 13px;
  margin-top: 30px;
}

.pf-home-final-support {
  min-height: 52px;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 0 20px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 13px;
  color: white;
  font-size: 13px;
  font-weight: 800;
}

/* ============================================================
   FOOTER
   ============================================================ */

.pf-home-footer {
  background: #081d31;
  color: white;
}

.pf-home-footer-main {
  width: min(1240px, calc(100% - 40px));
  margin: 0 auto;
  padding: 70px 0 55px;
  display: grid;
  grid-template-columns:
    1.5fr
    repeat(4, 1fr);
  gap: 40px;
}

.pf-home-footer-brand {
  max-width: 280px;
}

.pf-home-footer-brand .pf-home-logo {
  color: white;
}

.pf-home-footer-brand p {
  margin: 18px 0;
  color: rgba(255, 255, 255, 0.5);
  font-size: 11px;
  line-height: 1.7;
}

.pf-home-footer-status {
  display: flex;
  align-items: center;
  gap: 8px;
  color: rgba(255, 255, 255, 0.55);
  font-size: 9px;
  font-weight: 700;
}

.pf-home-footer-status span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #1bc39b;
}

.pf-home-footer-column {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
}

.pf-home-footer-column h3 {
  margin: 0 0 7px;
  color: white;
  font-size: 11px;
  font-weight: 850;
}

.pf-home-footer-column a,
.pf-home-footer-column button {
  padding: 0;
  border: 0;
  background: transparent;
  color: rgba(255, 255, 255, 0.48);
  cursor: pointer;
  font-size: 10px;
  text-align: left;
  transition: color 0.2s ease;
}

.pf-home-footer-column a:hover,
.pf-home-footer-column button:hover {
  color: white;
}

.pf-home-footer-bottom {
  width: min(1240px, calc(100% - 40px));
  margin: 0 auto;
  padding: 20px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.pf-home-footer-bottom > span {
  color: rgba(255, 255, 255, 0.4);
  font-size: 9px;
}

.pf-home-footer-bottom > div {
  display: flex;
  gap: 3px;
}

/* ============================================================
   DEMO MODAL
   ============================================================ */

.pf-home-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(5, 21, 35, 0.72);
  backdrop-filter: blur(9px);
}

.pf-home-demo-modal {
  position: relative;
  width: min(540px, 100%);
  padding: 36px;
  border: 1px solid rgba(255, 255, 255, 0.7);
  border-radius: 26px;
  background: white;
  box-shadow:
    0 35px 90px rgba(0, 0, 0, 0.28);
  text-align: center;
}

.pf-home-modal-close {
  position: absolute;
  top: 15px;
  right: 15px;
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 50%;
  background: #f1f5f8;
  color: #526579;
  cursor: pointer;
  font-size: 20px;
}

.pf-home-demo-icon {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  margin: 0 auto 15px;
  border-radius: 17px;
  background: #edf6ff;
  font-size: 25px;
}

.pf-home-demo-modal > span {
  color: #1167d8;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.pf-home-demo-modal h2 {
  margin: 9px 0;
  color: #142c42;
  font-size: 29px;
  font-weight: 900;
}

.pf-home-demo-modal > p {
  margin: 0;
  color: #78899a;
  font-size: 13px;
  line-height: 1.7;
}

.pf-home-demo-preview {
  margin: 25px 0;
  padding: 18px;
  border: 1px solid #e4ebf1;
  border-radius: 17px;
  background: #f8fafc;
}

.pf-home-demo-preview > div:first-child {
  display: flex;
  gap: 5px;
  margin-bottom: 18px;
}

.pf-home-demo-preview
  > div:first-child span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #ccd8e3;
}

.pf-home-demo-bars {
  height: 90px;
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  gap: 9px;
}

.pf-home-demo-bars i {
  width: 100%;
  max-width: 35px;
  border-radius:
    7px 7px 2px 2px;
  background:
    linear-gradient(
      180deg,
      #1167d8,
      #69b9e8
    );
}

.pf-home-demo-bars i:nth-child(1) {
  height: 40%;
}

.pf-home-demo-bars i:nth-child(2) {
  height: 65%;
}

.pf-home-demo-bars i:nth-child(3) {
  height: 48%;
}

.pf-home-demo-bars i:nth-child(4) {
  height: 80%;
}

.pf-home-demo-bars i:nth-child(5) {
  height: 68%;
}

.pf-home-demo-row {
  display: grid;
  grid-template-columns:
    1fr 1fr 1fr;
  gap: 7px;
  margin-top: 15px;
}

.pf-home-demo-row span {
  height: 7px;
  border-radius: 10px;
  background: #dce6ef;
}

/* ============================================================
   RESPONSIVE — TABLET
   ============================================================ */

@media (max-width: 1100px) {
  .pf-home-nav {
    gap: 17px;
  }

  .pf-home-nav button,
  .pf-home-nav a {
    font-size: 12px;
  }

  .pf-home-header-cta {
    padding: 0 13px;
  }

  .pf-home-hero-inner {
    gap: 40px;
  }

  .pf-home-dashboard {
    padding: 17px;
  }

  .pf-home-stat-card {
    padding: 11px;
  }

  .pf-home-stat-card strong {
    font-size: 17px;
  }

  .pf-home-footer-main {
    grid-template-columns:
      1.4fr
      repeat(2, 1fr);
  }
}

@media (max-width: 900px) {
  .pf-home-nav {
    position: fixed;
    top: 76px;
    left: 20px;
    right: 20px;
    display: none;
    flex-direction: column;
    align-items: stretch;
    gap: 5px;
    padding: 13px;
    border: 1px solid #e1e8ef;
    border-radius: 17px;
    background: white;
    box-shadow:
      0 20px 50px rgba(15, 43, 70, 0.13);
  }

  .pf-home-nav.is-open {
    display: flex;
  }

  .pf-home-nav button,
  .pf-home-nav a {
    width: 100%;
    padding: 13px;
    border-radius: 9px;
    text-align: left;
  }

  .pf-home-nav button:hover,
  .pf-home-nav a:hover {
    background: #f4f8fb;
  }

  .pf-home-menu-button {
    display: grid;
    place-items: center;
  }

  .pf-home-login,
  .pf-home-header-cta {
    display: none;
  }

  .pf-home-hero-inner {
    grid-template-columns: 1fr;
  }

  .pf-home-hero-copy {
    max-width: 720px;
  }

  .pf-home-dashboard-wrap {
    width: min(760px, 100%);
    margin: 0 auto;
  }

  .pf-home-feature-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-home-solutions-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-home-global-inner,
  .pf-home-security-grid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .pf-home-global-copy,
  .pf-home-security-copy {
    max-width: 760px;
  }

  .pf-home-security-visual {
    min-height: 350px;
  }

  .pf-home-support-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-home-support-card.payment {
    grid-column: span 2;
  }
}

/* ============================================================
   RESPONSIVE — MOBILE
   ============================================================ */

@media (max-width: 650px) {
  .pf-home-header-inner {
    width: min(
      100% - 28px,
      1240px
    );
    min-height: 68px;
  }

  .pf-home-logo {
    font-size: 18px;
  }

  .pf-home-logo-mark {
    width: 35px;
    height: 35px;
    border-radius: 11px;
  }

  .pf-home-actions {
    gap: 7px;
  }

  .pf-home-language {
    transform: scale(0.9);
    transform-origin: right center;
  }

  .pf-home-hero {
    min-height: auto;
    padding: 120px 0 65px;
  }

  .pf-home-hero-inner,
  .pf-home-section,
  .pf-home-global-inner,
  .pf-home-footer-main,
  .pf-home-footer-bottom {
    width: calc(100% - 28px);
  }

  .pf-home-hero h1 {
    font-size: 46px;
  }

  .pf-home-hero-copy > p {
    font-size: 15px;
  }

  .pf-home-hero-buttons {
    align-items: stretch;
    flex-direction: column;
  }

  .pf-home-primary-button,
  .pf-home-secondary-button {
    width: 100%;
  }

  .pf-home-trust-line {
    line-height: 1.7;
  }

  .pf-home-dashboard {
    padding: 13px;
    border-radius: 20px;
  }

  .pf-home-dashboard-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-home-dashboard-chart {
    padding: 13px;
  }

  .pf-home-chart {
    height: 100px;
  }

  .pf-home-section {
    padding: 75px 0;
  }

  .pf-home-section-heading {
    margin-bottom: 34px;
  }

  .pf-home-section-heading h2,
  .pf-home-security-copy h2,
  .pf-home-global-copy h2 {
    font-size: 34px;
  }

  .pf-home-feature-grid,
  .pf-home-solutions-grid,
  .pf-home-support-grid,
  .pf-home-pricing-grid {
    grid-template-columns: 1fr;
  }

  .pf-home-feature-card {
    min-height: 235px;
  }

  .pf-home-solution-card {
    min-height: 275px;
  }

  .pf-home-support-card.payment {
    grid-column: auto;
  }

  .pf-home-global {
    padding: 75px 0;
  }

  .pf-home-global-grid {
    grid-template-columns: 1fr;
  }

  .pf-home-global-card {
    min-height: 110px;
  }

  .pf-home-security-visual {
    min-height: 280px;
  }

  .pf-home-security-orbit {
    width: 260px;
    height: 260px;
  }

  .pf-home-security-lock {
    width: 82px;
    height: 82px;
    border-radius: 23px;
    font-size: 34px;
  }

  .pf-home-security-list {
    grid-template-columns: 1fr;
  }

  .pf-home-support-cta {
    flex-direction: column;
    align-items: stretch;
  }

  .pf-home-support-cta
    .pf-home-primary-button {
    width: 100%;
  }

  .pf-home-pricing {
    padding-bottom: 85px;
  }

  .pf-home-price-card {
    padding: 27px;
  }

  .pf-home-final-cta {
    padding: 80px 14px;
  }

  .pf-home-final-buttons {
    flex-direction: column;
  }

  .pf-home-final-buttons
    > * {
    width: 100%;
  }

  .pf-home-footer-main {
    grid-template-columns: 1fr 1fr;
    gap: 35px 25px;
    padding: 55px 0 40px;
  }

  .pf-home-footer-brand {
    grid-column: span 2;
    max-width: none;
  }

  .pf-home-footer-bottom {
    flex-direction: column;
    align-items: flex-start;
  }

  .pf-home-demo-modal {
    padding: 30px 20px;
    border-radius: 21px;
  }
}

/* ============================================================
   RESPONSIVE — SMALL PHONES
   ============================================================ */

@media (max-width: 430px) {
  .pf-home-language {
    display: none;
  }

  .pf-home-hero h1 {
    font-size: 39px;
  }

  .pf-home-badge {
    font-size: 9px;
  }

  .pf-home-dashboard-grid {
    gap: 7px;
  }

  .pf-home-stat-card {
    padding: 10px;
    border-radius: 12px;
  }

  .pf-home-stat-card strong {
    font-size: 16px;
  }

  .pf-home-dashboard-bottom {
    flex-direction: column;
    align-items: flex-start;
  }

  .pf-home-dashboard-bottom button {
    padding: 0;
  }

  .pf-home-security-orbit {
    width: 225px;
    height: 225px;
  }

  .pf-home-security-orbit .orbit-one {
    top: 13px;
    right: 35px;
  }

  .pf-home-security-orbit .orbit-two {
    right: -3px;
    bottom: 48px;
  }

  .pf-home-security-orbit .orbit-three {
    bottom: 10px;
    left: 37px;
  }

  .pf-home-footer-main {
    grid-template-columns: 1fr;
  }

  .pf-home-footer-brand {
    grid-column: auto;
  }
}

/* ============================================================
   ACCESSIBILITY / REDUCED MOTION
   ============================================================ */

@media (prefers-reduced-motion: reduce) {
  .pf-home *,
  .pf-home *::before,
  .pf-home *::after {
    scroll-behavior: auto !important;
    transition: none !important;
    animation: none !important;
  }
}
/* =========================================================
   PHARMAFLOW — SUPER ADMIN
   DESIGN SYSTEM
   ========================================================= */

.sa-layout {
  --sa-primary: #0f4c81;
  --sa-primary-dark: #083b66;
  --sa-primary-light: #eaf3fb;

  --sa-success: #16845b;
  --sa-success-light: #eaf8f2;

  --sa-warning: #c77b18;
  --sa-warning-light: #fff6e5;

  --sa-danger: #c63c4a;
  --sa-danger-light: #fff0f2;

  --sa-text: #172033;
  --sa-text-soft: #596579;
  --sa-text-muted: #8993a5;

  --sa-border: #e4e9f0;
  --sa-border-light: #eef1f5;

  --sa-bg: #f5f7fa;
  --sa-white: #ffffff;

  --sa-sidebar-width: 272px;

  min-height: 100vh;
  display: flex;

  background: var(--sa-bg);
  color: var(--sa-text);

  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.sa-sidebar {
  position: fixed;
  inset: 0 auto 0 0;

  width: var(--sa-sidebar-width);

  display: flex;
  flex-direction: column;

  background:
    linear-gradient(
      180deg,
      #092f52 0%,
      #0b3d68 48%,
      #082c4c 100%
    );

  color: #ffffff;

  border-right: 1px solid
    rgba(255, 255, 255, 0.08);

  z-index: 100;
}


.sa-brand {
  min-height: 82px;

  display: flex;
  align-items: center;

  gap: 12px;

  padding: 18px 20px;

  border-bottom: 1px solid
    rgba(255, 255, 255, 0.09);
}


.sa-brand-logo {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  background: rgba(255, 255, 255, 0.14);

  border: 1px solid
    rgba(255, 255, 255, 0.18);

  color: #ffffff;

  font-size: 20px;
  font-weight: 800;

  box-shadow:
    0 8px 20px rgba(0, 0, 0, 0.14);
}


.sa-brand-text {
  min-width: 0;
}


.sa-brand-name {
  font-size: 17px;
  font-weight: 800;

  letter-spacing: -0.02em;
}


.sa-brand-subtitle {
  margin-top: 3px;

  color: rgba(255, 255, 255, 0.62);

  font-size: 11px;
  font-weight: 500;
}


.sa-sidebar-scroll {
  flex: 1;

  overflow-y: auto;

  padding: 20px 14px 24px;
}


.sa-sidebar-scroll::-webkit-scrollbar {
  width: 5px;
}


.sa-sidebar-scroll::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.14);

  border-radius: 999px;
}


/* =========================================================
   NAVIGATION
   ========================================================= */

.sa-nav-title {
  margin: 19px 10px 8px;

  color: rgba(255, 255, 255, 0.42);

  font-size: 10px;
  font-weight: 800;

  letter-spacing: 0.12em;

  text-transform: uppercase;
}


.sa-nav {
  display: flex;
  flex-direction: column;

  gap: 4px;
}


.sa-nav-link {
  min-height: 44px;

  display: flex;
  align-items: center;

  gap: 11px;

  padding: 10px 11px;

  border-radius: 10px;

  color: rgba(255, 255, 255, 0.72);

  text-decoration: none;

  font-size: 13px;
  font-weight: 600;

  transition:
    background 160ms ease,
    color 160ms ease,
    transform 160ms ease;
}


.sa-nav-link:hover {
  color: #ffffff;

  background: rgba(255, 255, 255, 0.09);

  transform: translateX(2px);
}


.sa-nav-link.active {
  color: #ffffff;

  background:
    linear-gradient(
      90deg,
      rgba(255, 255, 255, 0.16),
      rgba(255, 255, 255, 0.08)
    );

  box-shadow:
    inset 3px 0 0 #ffffff;
}


.sa-nav-icon {
  width: 25px;
  min-width: 25px;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 16px;
}


.sa-nav-count {
  margin-left: auto;

  padding: 3px 7px;

  border-radius: 999px;

  background: rgba(255, 255, 255, 0.1);

  color: rgba(255, 255, 255, 0.7);

  font-size: 9px;
  font-weight: 800;

  text-transform: uppercase;
}


/* =========================================================
   SIDEBAR FOOTER
   ========================================================= */

.sa-sidebar-footer {
  padding: 15px;

  border-top: 1px solid
    rgba(255, 255, 255, 0.09);
}


.sa-security-status {
  display: flex;
  align-items: center;

  gap: 10px;

  padding: 11px;

  border-radius: 10px;

  background: rgba(255, 255, 255, 0.055);
}


.sa-security-status strong,
.sa-security-status span {
  display: block;
}


.sa-security-status strong {
  color: rgba(255, 255, 255, 0.88);

  font-size: 11px;
  font-weight: 700;
}


.sa-security-status div span {
  margin-top: 2px;

  color: rgba(255, 255, 255, 0.46);

  font-size: 10px;
}


.sa-security-dot {
  width: 8px;
  height: 8px;

  flex: 0 0 8px;

  border-radius: 50%;

  background: #39c88b;

  box-shadow:
    0 0 0 4px rgba(57, 200, 139, 0.12);
}
/* =========================================================
   MAIN CONTENT
   ========================================================= */

.sa-main {
  flex: 1;

  min-width: 0;

  margin-left: var(--sa-sidebar-width);

  min-height: 100vh;

  background: var(--sa-bg);
}


/* =========================================================
   HEADER
   ========================================================= */

.sa-header {
  height: 72px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 30px;

  background: var(--sa-white);

  border-bottom: 1px solid var(--sa-border);

  position: sticky;
  top: 0;

  z-index: 50;
}


.sa-header-left {
  min-width: 0;

  display: flex;
  align-items: center;
}


.sa-breadcrumb {
  display: flex;
  align-items: center;

  gap: 9px;

  color: var(--sa-text-soft);

  font-size: 12px;
  font-weight: 600;
}


.sa-breadcrumb-separator {
  color: var(--sa-text-muted);

  font-size: 14px;
}


.sa-header-right {
  display: flex;
  align-items: center;

  gap: 14px;
}


.sa-header-icon-button {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid var(--sa-border);

  border-radius: 10px;

  background: var(--sa-white);

  color: var(--sa-text-soft);

  cursor: pointer;

  transition:
    background 160ms ease,
    border-color 160ms ease,
    color 160ms ease,
    transform 160ms ease;
}


.sa-header-icon-button:hover {
  background: var(--sa-primary-light);

  border-color: #cbddeb;

  color: var(--sa-primary);

  transform: translateY(-1px);
}


.sa-admin-profile {
  display: flex;
  align-items: center;

  gap: 10px;

  padding-left: 12px;

  border-left: 1px solid var(--sa-border);
}


.sa-admin-avatar {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background:
    linear-gradient(
      135deg,
      var(--sa-primary),
      var(--sa-primary-dark)
    );

  color: #ffffff;

  font-size: 13px;
  font-weight: 800;

  box-shadow:
    0 5px 12px rgba(15, 76, 129, 0.18);
}


.sa-admin-info {
  min-width: 0;
}


.sa-admin-info strong {
  display: block;

  max-width: 180px;

  overflow: hidden;

  color: var(--sa-text);

  font-size: 12px;
  font-weight: 700;

  text-overflow: ellipsis;
  white-space: nowrap;
}


.sa-admin-info span {
  display: block;

  margin-top: 2px;

  color: var(--sa-text-muted);

  font-size: 10px;
  font-weight: 600;
}


/* =========================================================
   PAGE CONTENT
   ========================================================= */

.sa-content {
  width: 100%;

  max-width: 1680px;

  margin: 0 auto;

  padding: 30px;
}


/* =========================================================
   WELCOME SECTION
   ========================================================= */

.sa-welcome {
  position: relative;

  overflow: hidden;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 30px;

  min-height: 190px;

  padding: 30px 34px;

  margin-bottom: 28px;

  border: 1px solid #dbe6ef;

  border-radius: 18px;

  background:
    linear-gradient(
      120deg,
      #ffffff 0%,
      #f7fbfe 55%,
      #eef6fb 100%
    );

  box-shadow:
    0 8px 28px rgba(23, 32, 51, 0.045);
}


.sa-welcome::after {
  content: "";

  position: absolute;

  width: 280px;
  height: 280px;

  right: -95px;
  top: -135px;

  border-radius: 50%;

  border: 45px solid
    rgba(15, 76, 129, 0.045);

  pointer-events: none;
}


.sa-welcome-content {
  position: relative;

  z-index: 1;

  max-width: 760px;
}


.sa-eyebrow {
  display: inline-flex;
  align-items: center;

  gap: 7px;

  margin-bottom: 9px;

  color: var(--sa-primary);

  font-size: 10px;
  font-weight: 800;

  letter-spacing: 0.11em;

  text-transform: uppercase;
}


.sa-eyebrow::before {
  content: "";

  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: var(--sa-success);

  box-shadow:
    0 0 0 4px rgba(22, 132, 91, 0.1);
}


.sa-welcome h1 {
  margin: 0;

  color: var(--sa-text);

  font-size: clamp(25px, 3vw, 36px);

  font-weight: 800;

  line-height: 1.12;

  letter-spacing: -0.035em;
}


.sa-welcome p {
  max-width: 700px;

  margin: 10px 0 0;

  color: var(--sa-text-soft);

  font-size: 13px;

  line-height: 1.65;
}


.sa-welcome-actions {
  position: relative;

  z-index: 2;

  display: flex;
  align-items: center;

  gap: 10px;

  flex-shrink: 0;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.sa-primary-button,
.sa-secondary-button {
  min-height: 42px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 8px;

  padding: 0 16px;

  border-radius: 10px;

  font-size: 12px;
  font-weight: 700;

  text-decoration: none;

  cursor: pointer;

  transition:
    transform 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease,
    border-color 160ms ease;
}


.sa-primary-button {
  border: 1px solid var(--sa-primary);

  background: var(--sa-primary);

  color: #ffffff;

  box-shadow:
    0 5px 14px rgba(15, 76, 129, 0.16);
}


.sa-primary-button:hover {
  background: var(--sa-primary-dark);

  border-color: var(--sa-primary-dark);

  transform: translateY(-1px);

  box-shadow:
    0 8px 18px rgba(15, 76, 129, 0.2);
}


.sa-secondary-button {
  border: 1px solid var(--sa-border);

  background: var(--sa-white);

  color: var(--sa-text-soft);
}


.sa-secondary-button:hover {
  border-color: #c8d7e4;

  background: #f9fbfd;

  color: var(--sa-primary);

  transform: translateY(-1px);
}


/* =========================================================
   GLOBAL STATISTICS
   ========================================================= */

.sa-stats-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 16px;

  margin-bottom: 32px;
}


.sa-stat-card {
  min-width: 0;

  padding: 20px;

  border: 1px solid var(--sa-border);

  border-radius: 14px;

  background: var(--sa-white);

  box-shadow:
    0 5px 20px rgba(23, 32, 51, 0.035);

  transition:
    transform 160ms ease,
    box-shadow 160ms ease,
    border-color 160ms ease;
}


.sa-stat-card:hover {
  transform: translateY(-2px);

  border-color: #d3dfe9;

  box-shadow:
    0 10px 26px rgba(23, 32, 51, 0.065);
}


.sa-stat-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 12px;
}


.sa-stat-title {
  color: var(--sa-text-muted);

  font-size: 11px;
  font-weight: 700;

  text-transform: uppercase;

  letter-spacing: 0.045em;
}


.sa-stat-value {
  margin-top: 9px;

  color: var(--sa-text);

  font-size: 27px;
  font-weight: 800;

  line-height: 1.1;

  letter-spacing: -0.035em;
}


.sa-stat-description {
  margin-top: 7px;

  color: var(--sa-text-muted);

  font-size: 10px;
  font-weight: 500;

  line-height: 1.45;
}


.sa-stat-icon {
  width: 42px;
  height: 42px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  font-size: 18px;
}


/* =========================================================
   STAT ICON TONES
   ========================================================= */

.sa-stat-icon.blue {
  background: var(--sa-primary-light);

  color: var(--sa-primary);
}


.sa-stat-icon.green {
  background: var(--sa-success-light);

  color: var(--sa-success);
}


.sa-stat-icon.orange {
  background: var(--sa-warning-light);

  color: var(--sa-warning);
}


.sa-stat-icon.red {
  background: var(--sa-danger-light);

  color: var(--sa-danger);
}
/* =========================================================
   SECTIONS
   ========================================================= */

.sa-section {
  margin-bottom: 32px;
}


.sa-section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;

  gap: 20px;

  margin-bottom: 15px;
}


.sa-section-header h2 {
  margin: 0;

  color: var(--sa-text);

  font-size: 17px;
  font-weight: 800;

  letter-spacing: -0.02em;
}


.sa-section-header p {
  margin: 4px 0 0;

  color: var(--sa-text-muted);

  font-size: 11px;

  line-height: 1.5;
}


/* =========================================================
   OPERATION / MODULE CARDS
   ========================================================= */

.sa-module-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 15px;
}


.sa-module-card {
  position: relative;

  min-width: 0;

  display: flex;
  align-items: flex-start;

  gap: 13px;

  padding: 18px;

  border: 1px solid var(--sa-border);

  border-radius: 14px;

  background: var(--sa-white);

  color: inherit;

  text-decoration: none;

  box-shadow:
    0 5px 18px rgba(23, 32, 51, 0.03);

  transition:
    transform 170ms ease,
    border-color 170ms ease,
    box-shadow 170ms ease;
}


.sa-module-card:hover {
  transform: translateY(-3px);

  border-color: #ccdbe7;

  box-shadow:
    0 12px 28px rgba(23, 32, 51, 0.075);
}


.sa-module-icon {
  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  font-size: 18px;

  background: var(--sa-primary-light);

  color: var(--sa-primary);
}


.sa-module-icon.blue {
  background: var(--sa-primary-light);
  color: var(--sa-primary);
}


.sa-module-icon.green {
  background: var(--sa-success-light);
  color: var(--sa-success);
}


.sa-module-icon.orange {
  background: var(--sa-warning-light);
  color: var(--sa-warning);
}


.sa-module-icon.red {
  background: var(--sa-danger-light);
  color: var(--sa-danger);
}


.sa-module-content {
  min-width: 0;

  flex: 1;
}


.sa-module-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 8px;
}


.sa-module-title-row h3 {
  min-width: 0;

  margin: 0;

  overflow: hidden;

  color: var(--sa-text);

  font-size: 13px;
  font-weight: 750;

  text-overflow: ellipsis;
  white-space: nowrap;
}


.sa-module-content p {
  margin: 7px 0 0;

  color: var(--sa-text-muted);

  font-size: 10px;

  line-height: 1.55;
}


.sa-module-badge {
  flex-shrink: 0;

  padding: 3px 7px;

  border-radius: 999px;

  background: #f0f3f7;

  color: var(--sa-text-muted);

  font-size: 8px;
  font-weight: 800;

  text-transform: uppercase;

  letter-spacing: 0.04em;
}


.sa-module-badge.success {
  background: var(--sa-success-light);

  color: var(--sa-success);
}


.sa-module-badge.warning {
  background: var(--sa-warning-light);

  color: var(--sa-warning);
}


.sa-module-badge.danger {
  background: var(--sa-danger-light);

  color: var(--sa-danger);
}


.sa-module-arrow {
  position: absolute;

  right: 15px;
  bottom: 14px;

  color: #aeb7c4;

  font-size: 13px;

  transition:
    color 170ms ease,
    transform 170ms ease;
}


.sa-module-card:hover .sa-module-arrow {
  color: var(--sa-primary);

  transform: translateX(3px);
}


/* =========================================================
   QUICK ACTIONS
   ========================================================= */

.sa-quick-actions {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 12px;
}


.sa-quick-action {
  min-width: 0;

  display: flex;
  align-items: center;

  gap: 12px;

  padding: 14px;

  border: 1px solid var(--sa-border);

  border-radius: 12px;

  background: var(--sa-white);

  color: inherit;

  text-decoration: none;

  transition:
    transform 160ms ease,
    border-color 160ms ease,
    background 160ms ease;
}


.sa-quick-action:hover {
  transform: translateY(-2px);

  border-color: #ccdbe7;

  background: #fbfdff;
}


.sa-quick-icon {
  width: 36px;
  height: 36px;

  flex: 0 0 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  background: var(--sa-primary-light);

  color: var(--sa-primary);

  font-size: 15px;
}


.sa-quick-content {
  min-width: 0;

  flex: 1;
}


.sa-quick-content strong {
  display: block;

  color: var(--sa-text);

  font-size: 11px;
  font-weight: 700;
}


.sa-quick-content span {
  display: block;

  margin-top: 3px;

  overflow: hidden;

  color: var(--sa-text-muted);

  font-size: 9px;

  text-overflow: ellipsis;
  white-space: nowrap;
}


.sa-quick-arrow {
  color: #adb6c2;

  font-size: 13px;

  transition:
    color 160ms ease,
    transform 160ms ease;
}


.sa-quick-action:hover .sa-quick-arrow {
  color: var(--sa-primary);

  transform: translateX(3px);
}


/* =========================================================
   GOVERNANCE / SECURITY
   ========================================================= */

.sa-governance-grid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 15px;
}


.sa-governance-card {
  display: flex;
  align-items: flex-start;

  gap: 13px;

  min-width: 0;

  padding: 18px;

  border: 1px solid var(--sa-border);

  border-radius: 14px;

  background: var(--sa-white);

  box-shadow:
    0 5px 18px rgba(23, 32, 51, 0.03);
}


.sa-governance-icon {
  width: 40px;
  height: 40px;

  flex: 0 0 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  background: var(--sa-success-light);

  color: var(--sa-success);

  font-size: 16px;
}


.sa-governance-content {
  min-width: 0;

  flex: 1;
}


.sa-governance-content strong {
  display: block;

  color: var(--sa-text);

  font-size: 12px;
  font-weight: 750;
}


.sa-governance-content p {
  margin: 6px 0 0;

  color: var(--sa-text-muted);

  font-size: 10px;

  line-height: 1.55;
}


/* =========================================================
   STATUS BADGES
   ========================================================= */

.sa-status-badge {
  display: inline-flex;
  align-items: center;

  gap: 6px;

  padding: 5px 9px;

  border-radius: 999px;

  background: #f0f3f7;

  color: var(--sa-text-muted);

  font-size: 9px;
  font-weight: 750;
}


.sa-status-badge::before {
  content: "";

  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: currentColor;
}


.sa-status-badge.success {
  background: var(--sa-success-light);

  color: var(--sa-success);
}


.sa-status-badge.warning {
  background: var(--sa-warning-light);

  color: var(--sa-warning);
}


.sa-status-badge.danger {
  background: var(--sa-danger-light);

  color: var(--sa-danger);
}


/* =========================================================
   LINKS / GENERAL INTERACTION
   ========================================================= */

.sa-layout a {
  -webkit-tap-highlight-color: transparent;
}


.sa-layout button,
.sa-layout a {
  -webkit-touch-callout: none;
}


.sa-layout button:focus-visible,
.sa-layout a:focus-visible {
  outline: 3px solid rgba(15, 76, 129, 0.2);

  outline-offset: 2px;
}
/* =========================================================
   INTEGRATIONS & API
   ========================================================= */

.sa-integration-grid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 15px;
}


.sa-integration-card {
  display: flex;
  align-items: flex-start;

  gap: 13px;

  padding: 18px;

  border: 1px solid var(--sa-border);

  border-radius: 14px;

  background: var(--sa-white);

  box-shadow:
    0 5px 18px rgba(23, 32, 51, 0.03);

  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;
}


.sa-integration-card:hover {
  transform: translateY(-2px);

  border-color: #ccdbe7;

  box-shadow:
    0 10px 24px rgba(23, 32, 51, 0.06);
}


.sa-integration-icon {
  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  background: var(--sa-primary-light);

  color: var(--sa-primary);

  font-size: 17px;
}


.sa-integration-content {
  min-width: 0;

  flex: 1;
}


.sa-integration-content strong {
  display: block;

  color: var(--sa-text);

  font-size: 12px;
  font-weight: 750;
}


.sa-integration-content p {
  margin: 6px 0 0;

  color: var(--sa-text-muted);

  font-size: 10px;

  line-height: 1.55;
}


/* =========================================================
   INTERNATIONAL DEPLOYMENT
   ========================================================= */

.sa-international-card {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 24px;

  padding: 22px;

  border: 1px solid #dbe6ef;

  border-radius: 15px;

  background:
    linear-gradient(
      110deg,
      #ffffff 0%,
      #f7fbfe 100%
    );

  box-shadow:
    0 5px 20px rgba(23, 32, 51, 0.035);
}


.sa-international-main {
  display: flex;
  align-items: flex-start;

  gap: 14px;

  min-width: 0;
}


.sa-international-icon {
  width: 44px;
  height: 44px;

  flex: 0 0 44px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  background: var(--sa-primary-light);

  color: var(--sa-primary);

  font-size: 19px;
}


.sa-international-main strong {
  display: block;

  color: var(--sa-text);

  font-size: 13px;
  font-weight: 800;
}


.sa-international-main p {
  max-width: 720px;

  margin: 6px 0 0;

  color: var(--sa-text-muted);

  font-size: 10px;

  line-height: 1.6;
}


.sa-international-items {
  display: flex;
  align-items: center;

  gap: 8px;

  flex-wrap: wrap;

  justify-content: flex-end;
}


.sa-international-item {
  display: inline-flex;
  align-items: center;

  gap: 6px;

  padding: 7px 9px;

  border: 1px solid var(--sa-border);

  border-radius: 8px;

  background: var(--sa-white);

  color: var(--sa-text-soft);

  font-size: 9px;
  font-weight: 700;

  white-space: nowrap;
}


.sa-international-item::before {
  content: "";

  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: var(--sa-success);
}


/* =========================================================
   PLATFORM CONTROL CENTER
   ========================================================= */

.sa-control-grid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 15px;
}


.sa-control-card {
  position: relative;

  min-height: 150px;

  padding: 20px;

  overflow: hidden;

  border: 1px solid var(--sa-border);

  border-radius: 14px;

  background: var(--sa-white);

  box-shadow:
    0 5px 18px rgba(23, 32, 51, 0.03);
}


.sa-control-card::after {
  content: "";

  position: absolute;

  width: 120px;
  height: 120px;

  right: -55px;
  bottom: -55px;

  border-radius: 50%;

  background: rgba(15, 76, 129, 0.035);

  pointer-events: none;
}


.sa-control-number {
  color: var(--sa-primary);

  font-size: 27px;
  font-weight: 850;

  line-height: 1;

  letter-spacing: -0.04em;
}


.sa-control-card strong {
  display: block;

  margin-top: 10px;

  color: var(--sa-text);

  font-size: 12px;
  font-weight: 750;
}


.sa-control-card p {
  max-width: 270px;

  margin: 6px 0 0;

  color: var(--sa-text-muted);

  font-size: 10px;

  line-height: 1.55;
}


.sa-control-icon {
  position: absolute;

  top: 18px;
  right: 18px;

  width: 36px;
  height: 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  background: var(--sa-primary-light);

  color: var(--sa-primary);

  font-size: 15px;

  z-index: 1;
}


/* =========================================================
   FOOTER
   ========================================================= */

.sa-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 20px;

  margin-top: 12px;
  padding: 24px 0 10px;

  border-top: 1px solid var(--sa-border);

  color: var(--sa-text-muted);

  font-size: 10px;
}


.sa-footer-brand {
  display: flex;
  align-items: center;

  gap: 9px;
}


.sa-footer-logo {
  width: 27px;
  height: 27px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 7px;

  background: var(--sa-primary-light);

  color: var(--sa-primary);

  font-size: 11px;
  font-weight: 800;
}


.sa-footer-brand strong {
  color: var(--sa-text-soft);

  font-size: 10px;
  font-weight: 750;
}


.sa-footer-center {
  text-align: center;

  color: var(--sa-text-muted);

  font-size: 9px;
}


.sa-footer-status {
  display: inline-flex;
  align-items: center;

  gap: 7px;

  padding: 6px 9px;

  border: 1px solid #dceee6;

  border-radius: 999px;

  background: var(--sa-success-light);

  color: var(--sa-success);

  font-size: 9px;
  font-weight: 750;
}


.sa-footer-status::before {
  content: "";

  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: currentColor;
}


/* =========================================================
   RESPONSIVE — LARGE TABLETS
   ========================================================= */

@media (max-width: 1200px) {
  .sa-stats-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .sa-module-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .sa-quick-actions {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .sa-integration-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .sa-control-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }
}


/* =========================================================
   RESPONSIVE — TABLETS / MOBILE
   ========================================================= */

@media (max-width: 800px) {
  .sa-sidebar {
    position: fixed;

    width: 235px;

    transform: translateX(-100%);

    transition: transform 220ms ease;
  }

  .sa-main {
    margin-left: 0;
  }

  .sa-header {
    height: 64px;

    padding: 0 18px;
  }

  .sa-content {
    padding: 22px 18px;
  }

  .sa-welcome {
    align-items: flex-start;
    flex-direction: column;

    padding: 24px;
  }

  .sa-welcome-actions {
    width: 100%;
  }

  .sa-welcome-actions .sa-primary-button,
  .sa-welcome-actions .sa-secondary-button {
    flex: 1;
  }

  .sa-governance-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .sa-international-card {
    align-items: flex-start;
    flex-direction: column;
  }

  .sa-international-items {
    justify-content: flex-start;
  }

  .sa-footer {
    align-items: flex-start;
    flex-direction: column;
  }

  .sa-footer-center {
    text-align: left;
  }
}


/* =========================================================
   RESPONSIVE — SMALL MOBILE
   ========================================================= */

@media (max-width: 560px) {
  .sa-header {
    padding: 0 14px;
  }

  .sa-breadcrumb {
    font-size: 10px;
  }

  .sa-header-icon-button {
    display: none;
  }

  .sa-admin-profile {
    padding-left: 0;

    border-left: 0;
  }

  .sa-admin-info {
    display: none;
  }

  .sa-admin-avatar {
    width: 35px;
    height: 35px;
  }

  .sa-content {
    padding: 18px 14px;
  }

  .sa-welcome {
    min-height: 0;

    padding: 21px;
  }

  .sa-welcome h1 {
    font-size: 25px;
  }

  .sa-welcome p {
    font-size: 11px;
  }

  .sa-welcome-actions {
    flex-direction: column;
  }

  .sa-welcome-actions .sa-primary-button,
  .sa-welcome-actions .sa-secondary-button {
    width: 100%;
  }

  .sa-stats-grid,
  .sa-module-grid,
  .sa-quick-actions,
  .sa-governance-grid,
  .sa-integration-grid,
  .sa-control-grid {
    grid-template-columns: 1fr;
  }

  .sa-section-header {
    align-items: flex-start;
    flex-direction: column;

    gap: 5px;
  }

  .sa-module-card {
    padding: 16px;
  }

  .sa-international-card {
    padding: 18px;
  }

  .sa-international-items {
    width: 100%;
  }

  .sa-international-item {
    flex: 1;
    justify-content: center;
  }

  .sa-footer {
    padding-bottom: 20px;
  }
}


/* =========================================================
   VERY SMALL SCREENS
   ========================================================= */

@media (max-width: 380px) {
  .sa-content {
    padding: 14px 10px;
  }

  .sa-welcome {
    padding: 18px;
  }

  .sa-stat-card {
    padding: 16px;
  }

  .sa-stat-value {
    font-size: 23px;
  }

  .sa-module-card,
  .sa-governance-card,
  .sa-integration-card,
  .sa-control-card {
    padding: 15px;
  }
}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

.sa-layout button:focus-visible,
.sa-layout a:focus-visible {
  outline: 3px solid rgba(15, 76, 129, 0.22);

  outline-offset: 3px;
}


.sa-layout ::selection {
  background: rgba(15, 76, 129, 0.16);

  color: var(--sa-text);
}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {
  .sa-layout *,
  .sa-layout *::before,
  .sa-layout *::after {
    scroll-behavior: auto !important;

    transition-duration: 0.01ms !important;

    animation-duration: 0.01ms !important;

    animation-iteration-count: 1 !important;
  }
}
/* ============================================================
   ABONNEMENT — DASHBOARD
