/* ============================================================
   PHARMAFLOW — SUPER ADMIN — DEVISES INTERNATIONALES
============================================================ */

.currency-page {
  min-height: 100vh;
  padding: 28px;
  background:
    radial-gradient(
      circle at top right,
      rgba(59, 130, 246, 0.08),
      transparent 30%
    ),
    #f8fafc;
  color: #0f172a;
}

.currency-container {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}

/* ============================================================
   HEADER
============================================================ */

.currency-topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
}

.currency-title-wrap {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}

.currency-back {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #ffffff;
  color: #334155;
  text-decoration: none;
  font-size: 20px;
  transition:
    background 0.2s ease,
    transform 0.2s ease,
    border-color 0.2s ease;
}

.currency-back:hover {
  background: #f1f5f9;
  border-color: #cbd5e1;
  transform: translateX(-2px);
}

.currency-title {
  margin: 0;
  color: #0f172a;
  font-size: 30px;
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.currency-subtitle {
  max-width: 760px;
  margin: 8px 0 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.65;
}

.admin-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #ffffff;
  color: #475569;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  box-shadow:
    0 6px 20px rgba(15, 23, 42, 0.04);
}

/* ============================================================
   STATISTIQUES
============================================================ */

.stats-grid {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.stat-card {
  padding: 20px;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: #ffffff;
  box-shadow:
    0 8px 30px rgba(15, 23, 42, 0.04);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.stat-card:hover {
  transform: translateY(-2px);
  box-shadow:
    0 12px 35px rgba(15, 23, 42, 0.07);
}

.stat-label {
  margin-bottom: 8px;
  color: #64748b;
  font-size: 13px;
  font-weight: 700;
}

.stat-value {
  margin: 0;
  color: #0f172a;
  font-size: 30px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: -0.025em;
}

/* ============================================================
   INFORMATION
============================================================ */

.info-card {
  margin-bottom: 24px;
  padding: 18px 20px;
  border: 1px solid #bfdbfe;
  border-radius: 16px;
  background: #eff6ff;
  color: #1e3a8a;
}

.info-card-title {
  display: block;
  margin-bottom: 6px;
  font-size: 14px;
  font-weight: 800;
}

.info-card-text {
  margin: 0;
  font-size: 13px;
  line-height: 1.65;
}

/* ============================================================
   ERREUR
============================================================ */

.error-card {
  margin-bottom: 24px;
  padding: 18px 20px;
  border: 1px solid #fecaca;
  border-radius: 16px;
  background: #fef2f2;
  color: #991b1b;
}

.error-card-title {
  display: block;
  margin-bottom: 5px;
  font-weight: 800;
}

.error-card-text {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
}

/* ============================================================
   TABLEAU
============================================================ */

.currency-table-card {
  overflow: hidden;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: #ffffff;
  box-shadow:
    0 8px 30px rgba(15, 23, 42, 0.04);
}

.table-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 21px 22px;
  border-bottom: 1px solid #e2e8f0;
}

.table-title {
  margin: 0;
  color: #0f172a;
  font-size: 18px;
  font-weight: 800;
}

.table-description {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.5;
}

.table-wrapper {
  overflow-x: auto;
}

.currency-page table {
  width: 100%;
  min-width: 1120px;
  border-collapse: collapse;
}

.currency-page th {
  padding: 14px 18px;
  border-bottom: 1px solid #e2e8f0;
  background: #f8fafc;
  color: #64748b;
  text-align: left;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  white-space: nowrap;
}

.currency-page td {
  padding: 17px 18px;
  border-bottom: 1px solid #f1f5f9;
  vertical-align: middle;
  color: #334155;
  font-size: 14px;
}

.currency-page tbody tr:last-child td {
  border-bottom: none;
}

.currency-page tbody tr {
  transition: background 0.15s ease;
}

.currency-page tbody tr:hover {
  background: #fafcff;
}

/* ============================================================
   CODE DEVISE
============================================================ */

.currency-code {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 60px;
  padding: 7px 10px;
  border-radius: 9px;
  background: #0f172a;
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.05em;
}

/* ============================================================
   NOM DEVISE
============================================================ */

.currency-name {
  color: #0f172a;
  font-weight: 700;
}

/* ============================================================
   SYMBOLE
============================================================ */

.currency-symbol {
  color: #0f172a;
  font-size: 18px;
  font-weight: 800;
}

/* ============================================================
   PAYS
============================================================ */

.country-list {
  display: flex;
  flex-wrap: wrap;
