   RESPONSIVE — TABLETTE
============================================================ */

@media (max-width: 1000px) {
  .currency-page {
    padding: 20px;
  }

  .currency-topbar {
    flex-direction: column;
  }

  .admin-badge {
    white-space: normal;
  }

  .stats-grid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }
}

/* ============================================================
   RESPONSIVE — MOBILE
============================================================ */

@media (max-width: 760px) {
  .currency-page {
    padding: 15px;
  }

  .currency-title {
    font-size: 25px;
  }

  .currency-subtitle {
    font-size: 13px;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .table-header {
    padding: 18px;
  }

  .currency-table-card {
    border-radius: 16px;
  }
}

/* ============================================================
   PETIT MOBILE
============================================================ */

@media (max-width: 500px) {
  .currency-title-wrap {
    gap: 10px;
  }

  .currency-back {
    width: 40px;
    height: 40px;
  }

  .currency-title {
    font-size: 22px;
  }

  .currency-subtitle {
    font-size: 12px;
  }

  .admin-badge {
    width: 100%;
    justify-content: flex-start;
  }
}
/* ============================================================
   PHARMAFLOW — SUPER ADMIN — TARIFS INTERNATIONAUX
============================================================ */

.sa-pricing-page {
  min-height: 100vh;
  padding: 32px;
  background:
    radial-gradient(
      circle at 90% 0%,
      rgba(37, 99, 235, 0.08),
      transparent 30%
    ),
    #f8fafc;
  color: #0f172a;
}

.sa-pricing-container {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}

/* ============================================================
   HEADER
============================================================ */

.sa-pricing-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 30px;
}

.sa-pricing-title-area {
  display: flex;
  align-items: flex-start;
  gap: 15px;
}

.sa-pricing-back {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  border: 1px solid #e2e8f0;
  border-radius: 13px;
  background: #ffffff;
  color: #334155;
  text-decoration: none;
  font-size: 21px;
  box-shadow:
    0 5px 20px rgba(15, 23, 42, 0.04);
  transition:
    transform 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease;
}

.sa-pricing-back:hover {
  background: #f1f5f9;
  border-color: #cbd5e1;
  transform: translateX(-3px);
}

.sa-pricing-eyebrow {
  margin-bottom: 7px;
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.sa-pricing-header h1 {
  margin: 0;
  color: #0f172a;
  font-size: 32px;
  line-height: 1.15;
  font-weight: 850;
  letter-spacing: -0.035em;
}

.sa-pricing-header p {
  max-width: 760px;
  margin: 9px 0 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.65;
}

.sa-pricing-admin {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px 15px;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 6px 22px rgba(15, 23, 42, 0.04);
}

.sa-pricing-lock {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 35px;
  height: 35px;
  border-radius: 10px;
  background: #f1f5f9;
  font-size: 17px;
}

.sa-pricing-admin div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sa-pricing-admin strong {
  color: #0f172a;
  font-size: 13px;
  font-weight: 800;
}

.sa-pricing-admin span {
  color: #64748b;
  font-size: 11px;
}

/* ============================================================
   ERREUR
============================================================ */

.sa-pricing-error {
  margin-bottom: 22px;
  padding: 17px 19px;
  border: 1px solid #fecaca;
  border-radius: 15px;
  background: #fef2f2;
  color: #991b1b;
}

.sa-pricing-error strong {
  display: block;
  margin-bottom: 5px;
  font-size: 14px;
}

.sa-pricing-error p {
  margin: 0;
  font-size: 13px;
  line-height: 1.55;
}

/* ============================================================
   STATISTIQUES
============================================================ */

.sa-pricing-stats {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.sa-pricing-stat {
  position: relative;
  overflow: hidden;
  padding: 21px;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: #ffffff;
  box-shadow:
    0 8px 30px rgba(15, 23, 42, 0.045);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.sa-pricing-stat:hover {
  transform: translateY(-2px);
  box-shadow:
    0 13px 35px rgba(15, 23, 42, 0.07);
}

.sa-pricing-stat::after {
  content: "";
  position: absolute;
  right: -30px;
  bottom: -40px;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: rgba(59, 130, 246, 0.055);
}

.sa-pricing-stat > span {
  display: block;
  margin-bottom: 9px;
  color: #64748b;
  font-size: 12px;
  font-weight: 750;
}

.sa-pricing-stat > strong {
  display: block;
  color: #0f172a;
  font-size: 30px;
  line-height: 1;
  font-weight: 850;
  letter-spacing: -0.03em;
}

.sa-pricing-stat > small {
  display: block;
  margin-top: 8px;
  color: #94a3b8;
  font-size: 11px;
}

/* ============================================================
   INFORMATION
============================================================ */

.sa-pricing-info {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 28px;
  padding: 18px 20px;
  border: 1px solid #bfdbfe;
  border-radius: 17px;
  background: #eff6ff;
}

.sa-pricing-info-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 39px;
  height: 39px;
  flex: 0 0 auto;
  border-radius: 11px;
  background: #dbeafe;
  font-size: 18px;
}

.sa-pricing-info strong {
  display: block;
  margin-bottom: 5px;
  color: #1e3a8a;
  font-size: 13px;
  font-weight: 800;
}

.sa-pricing-info p {
  margin: 0;
  color: #1e40af;
  font-size: 12px;
  line-height: 1.65;
}

/* ============================================================
   SECTIONS
============================================================ */

.sa-pricing-plan-overview,
.sa-pricing-table-section,
.sa-pricing-rules {
  margin-bottom: 34px;
}

.sa-pricing-section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 16px;
}

.sa-pricing-section-heading > div > span {
  display: block;
  margin-bottom: 5px;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.12em;
}

.sa-pricing-section-heading h2 {
  margin: 0;
  color: #0f172a;
  font-size: 21px;
  line-height: 1.25;
  font-weight: 850;
  letter-spacing: -0.025em;
}

.sa-pricing-section-heading p {
  margin: 6px 0 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.55;
}

.sa-pricing-secondary-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 13px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #ffffff;
  color: #334155;
  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}

.sa-pricing-secondary-link:hover {
  background: #f8fafc;
  border-color: #cbd5e1;
  transform: translateY(-1px);
}

/* ============================================================
   CARTES DES PLANS
============================================================ */

.sa-pricing-plan-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.sa-pricing-plan-card {
  display: flex;
  align-items: center;
  gap: 15px;
  min-height: 118px;
  padding: 19px;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: #ffffff;
  box-shadow:
    0 8px 28px rgba(15, 23, 42, 0.04);
}

.sa-pricing-plan-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 50px;
  height: 50px;
  flex: 0 0 auto;
  border-radius: 14px;
  background: #f1f5f9;
  font-size: 22px;
}

.sa-pricing-plan-card > div:nth-child(2) {
  flex: 1;
  min-width: 0;
}

.sa-pricing-plan-code {
  display: inline-block;
  margin-bottom: 3px;
  color: #64748b;
  font-size: 10px;
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.sa-pricing-plan-card h3 {
  margin: 0;
  color: #0f172a;
  font-size: 16px;
  font-weight: 850;
}

.sa-pricing-plan-card p {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.45;
}

.sa-pricing-plan-duration {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  flex: 0 0 auto;
}

.sa-pricing-plan-duration strong {
  color: #0f172a;
  font-size: 21px;
  font-weight: 850;
}

.sa-pricing-plan-duration span {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 700;
}

/* ============================================================
   TABLEAU DES TARIFS
============================================================ */

.sa-pricing-table-card {
  overflow: hidden;
  border: 1px solid #e2e8f0;
  border-radius: 19px;
  background: #ffffff;
  box-shadow:
    0 8px 30px rgba(15, 23, 42, 0.045);
}

.sa-pricing-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.sa-pricing-table {
  width: 100%;
  min-width: 1180px;
  border-collapse: collapse;
}

.sa-pricing-table th {
  padding: 14px 17px;
  border-bottom: 1px solid #e2e8f0;
  background: #f8fafc;
  color: #64748b;
  text-align: left;
  font-size: 10px;
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  white-space: nowrap;
}

.sa-pricing-table td {
  padding: 16px 17px;
  border-bottom: 1px solid #f1f5f9;
  vertical-align: middle;
  color: #334155;
  font-size: 13px;
}

.sa-pricing-table tbody tr {
  transition: background 0.15s ease;
}

.sa-pricing-table tbody tr:hover {
  background: #fafcff;
}

.sa-pricing-table tbody tr:last-child td {
  border-bottom: none;
}

/* ============================================================
   DEVISE
============================================================ */

.sa-pricing-currency {
  display: flex;
  align-items: center;
  gap: 10px;
}

.sa-pricing-currency-code {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 56px;
  height: 32px;
  padding: 0 8px;
  border-radius: 8px;
  background: #0f172a;
  color: #ffffff;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.05em;
}

.sa-pricing-currency > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sa-pricing-currency strong {
  color: #0f172a;
  font-size: 12px;
  font-weight: 800;
}

.sa-pricing-currency > div > span {
  color: #94a3b8;
  font-size: 11px;
}

/* ============================================================
   MARCHÉ
============================================================ */

.sa-pricing-market {
  color: #64748b;
  font-size: 11px;
}

/* ============================================================
   FORMULAIRE PRIX
============================================================ */

.sa-price-form {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
}

.sa-price-input-wrap {
  display: flex;
  align-items: center;
  width: 145px;
  height: 38px;
  overflow: hidden;
  border: 1px solid #cbd5e1;
  border-radius: 9px;
  background: #ffffff;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.sa-price-input-wrap:focus-within {
  border-color: #64748b;
  box-shadow:
    0 0 0 3px rgba(100, 116, 139, 0.11);
}

.sa-price-input {
  width: 100%;
  height: 100%;
  min-width: 0;
  padding: 0 8px 0 10px;
  border: none;
  outline: none;
  background: transparent;
  color: #0f172a;
  font-size: 13px;
  font-weight: 700;
}

.sa-price-input::placeholder {
  color: #94a3b8;
  font-size: 11px;
  font-weight: 500;
}

.sa-price-input-wrap > span {
  padding-right: 9px;
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.sa-price-save {
  height: 38px;
  padding: 0 11px;
  border: none;
  border-radius: 9px;
  background: #0f172a;
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  transition:
    background 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.sa-price-save:hover {
  background: #1e293b;
  transform: translateY(-1px);
  box-shadow:
    0 5px 14px rgba(15, 23, 42, 0.15);
}

.sa-price-save:active {
  transform: translateY(0);
}

.sa-price-missing {
  color: #94a3b8;
  font-size: 11px;
  font-style: italic;
}

/* ============================================================
   STATUT DES TARIFS
============================================================ */

.sa-pricing-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 10px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 850;
  white-space: nowrap;
}

.sa-pricing-status > span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.sa-pricing-status.complete {
  background: #dcfce7;
  color: #166534;
}

.sa-pricing-status.incomplete {
  background: #fef3c7;
  color: #92400e;
}

/* ============================================================
   AVERTISSEMENT
============================================================ */

.sa-pricing-warning {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  margin-bottom: 30px;
  padding: 18px 20px;
  border: 1px solid #fde68a;
  border-radius: 16px;
  background: #fffbeb;
  color: #92400e;
}

.sa-pricing-warning-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  border-radius: 10px;
  background: #fef3c7;
  font-size: 17px;
}

.sa-pricing-warning strong {
  display: block;
  margin-bottom: 5px;
  font-size: 13px;
  font-weight: 850;
}

.sa-pricing-warning p {
  margin: 0;
  font-size: 12px;
  line-height: 1.6;
}

/* ============================================================
   RÈGLES COMMERCIALES
============================================================ */

.sa-pricing-rules-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.sa-pricing-rule {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  padding: 18px;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #ffffff;
  box-shadow:
    0 7px 25px rgba(15, 23, 42, 0.035);
}

.sa-pricing-rule > span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  border-radius: 9px;
  background: #f1f5f9;
  color: #475569;
  font-size: 10px;
  font-weight: 850;
}

.sa-pricing-rule strong {
  display: block;
  margin-bottom: 4px;
  color: #0f172a;
  font-size: 13px;
  font-weight: 850;
}

.sa-pricing-rule p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.55;
}

/* ============================================================
   FOOTER
============================================================ */

.sa-pricing-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: 35px;
  padding-top: 20px;
  border-top: 1px solid #e2e8f0;
  color: #94a3b8;
  font-size: 11px;
}

.sa-pricing-footer > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.sa-pricing-footer strong {
  color: #475569;
  font-size: 12px;
}

.sa-pricing-footer span {
  color: #94a3b8;
}

/* ============================================================
   RESPONSIVE — TABLETTE
============================================================ */

@media (max-width: 1100px) {
  .sa-pricing-page {
    padding: 24px;
  }

  .sa-pricing-header {
    flex-direction: column;
  }

  .sa-pricing-admin {
    width: fit-content;
  }

  .sa-pricing-stats {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .sa-pricing-plan-grid {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   RESPONSIVE — MOBILE
============================================================ */

@media (max-width: 700px) {
  .sa-pricing-page {
    padding: 15px;
  }

  .sa-pricing-header {
    gap: 18px;
    margin-bottom: 22px;
  }

  .sa-pricing-title-area {
    gap: 10px;
  }

  .sa-pricing-back {
    width: 40px;
    height: 40px;
    font-size: 18px;
  }

  .sa-pricing-header h1 {
    font-size: 25px;
  }

  .sa-pricing-header p {
    font-size: 13px;
  }

  .sa-pricing-admin {
    width: 100%;
  }

  .sa-pricing-stats {
    grid-template-columns: 1fr;
  }

  .sa-pricing-info {
    padding: 15px;
  }

  .sa-pricing-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .sa-pricing-secondary-link {
    width: 100%;
  }

  .sa-pricing-rules-grid {
    grid-template-columns: 1fr;
  }

  .sa-pricing-footer {
    align-items: flex-start;
    flex-direction: column;
  }
}

/* ============================================================
   PETIT MOBILE
============================================================ */

@media (max-width: 430px) {
  .sa-pricing-page {
    padding: 12px;
  }

  .sa-pricing-header h1 {
    font-size: 22px;
  }

  .sa-pricing-plan-card {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .sa-pricing-plan-duration {
    width: 100%;
    align-items: flex-start;
    padding-left: 65px;
  }
}
