/* ============================================================
   24 — REDUCED MOTION
============================================================ */

@media (prefers-reduced-motion: reduce) {

  .pf-home *,
  .pf-home *::before,
  .pf-home *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

}
/* =========================================================
   PHARMAFLOW — MENU MOBILE AU PREMIER PLAN
   ========================================================= */

@media (max-width: 768px) {

  /* La page ne doit jamais créer de débordement */
  html,
  body {
    overflow-x: hidden !important;
  }

  /* Le header reste au-dessus du contenu */
  header {
    position: relative !important;
    z-index: 1000 !important;
  }

  /* =======================================================
     BOUTON HAMBURGER
     ======================================================= */

  .menu-button,
  .menuButton,
  .hamburger,
  .hamburger-button,
  .mobile-menu-button,
  .mobileMenuButton {
    position: relative !important;
    z-index: 10000 !important;
  }

  /* =======================================================
     PANNEAU DU MENU
     ======================================================= */

  .sidebar,
  .sideBar,
  .side-menu,
  .sideMenu,
  .mobile-sidebar,
  .mobileSidebar {
    position: fixed !important;

    top: 0 !important;
    right: 0 !important;
    bottom: 0 !important;

    width: min(340px, 88vw) !important;
    max-width: 88vw !important;
    height: 100dvh !important;

    z-index: 99999 !important;

    background: #ffffff !important;

    overflow-y: auto !important;
    overflow-x: hidden !important;

    box-shadow:
      -12px 0 40px rgba(0, 0, 0, 0.15) !important;

    transform: translateX(0) !important;

    visibility: visible !important;
    opacity: 1 !important;
  }

  /* =======================================================
     OVERLAY DERRIÈRE LE MENU
     ======================================================= */

  .menu-overlay,
  .menuOverlay,
  .mobile-overlay,
  .mobileOverlay,
  .sidebar-overlay,
  .sidebarOverlay {
    position: fixed !important;

    inset: 0 !important;

    width: 100vw !important;
    height: 100dvh !important;

    background: rgba(2, 20, 15, 0.45) !important;

    z-index: 99990 !important;
  }

  /* =======================================================
     CONTENU DU MENU
     ======================================================= */

  .sidebar nav,
