  height: 150px;
  border-radius: 50%;
  background: rgba(37, 99, 235, 0.05);
  pointer-events: none;
}

.pf-dashboard-support-icon {
  position: relative;
  z-index: 1;
  width: 56px;
  height: 56px;
  min-width: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 15px;
  background: #eaf3ff;
  color: #2563eb;
  font-size: 25px;
}

.pf-dashboard-support-content {
  position: relative;
  z-index: 1;
  flex: 1;
  min-width: 0;
}

.pf-dashboard-support-content > span {
  display: block;
  margin-bottom: 4px;
  color: #2563eb;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.pf-dashboard-support-content h3 {
  margin: 0 0 5px;
  color: #172033;
  font-size: 18px;
  font-weight: 800;
}

.pf-dashboard-support-content p {
