/* ------------------------------------------------------------
   KPI
------------------------------------------------------------ */

.pf-kpi-grid {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 15px;
  margin-bottom: 20px;
}

.pf-kpi-card {
  min-width: 0;
  padding: 18px;
  border: 1px solid #e3e9f0;
  border-radius: 15px;
  background: #ffffff;
  text-align: left;
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(15, 23, 42, 0.035);
  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.pf-kpi-card:hover {
  transform: translateY(-2px);
  border-color: #cbd5e1;
  box-shadow:
    0 10px 25px rgba(15, 23, 42, 0.07);
}

.pf-kpi-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 15px;
}

.pf-kpi-icon {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  font-size: 17px;
  font-weight: 800;
}

.pf-kpi-teal {
  background: #e6fffb;
  color: #0f9f91;
}

.pf-kpi-blue {
  background: #eaf2ff;
  color: #2563eb;
}

.pf-kpi-orange {
  background: #fff4e5;
  color: #ea8a00;
}

.pf-kpi-green {
  background: #eaf9ef;
  color: #16a34a;
}

.pf-kpi-arrow {
  color: #98a2b3;
  font-size: 15px;
}

.pf-kpi-label {
  margin-bottom: 5px;
  color: #667085;
  font-size: 12px;
  font-weight: 600;
}

.pf-kpi-value {
  margin-bottom: 5px;
  color: #172033;
  font-size: 24px;
  line-height: 1.15;
  font-weight: 800;
}

.pf-kpi-description {
  color: #98a2b3;
  font-size: 11px;
  line-height: 1.4;
}


/* ------------------------------------------------------------
   PANELS
------------------------------------------------------------ */

.pf-main-dashboard-grid {
  display: grid;
  grid-template-columns:
    minmax(0, 1.4fr)
    minmax(340px, 0.8fr);
  gap: 18px;
  margin-bottom: 25px;
}

.pf-panel {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #e3e9f0;
  border-radius: 15px;
  background: #ffffff;
  box-shadow: 0 4px 15px rgba(15, 23, 42, 0.035);
}

.pf-panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
  padding: 20px 20px 15px;
}

.pf-panel-eyebrow {
  color: #98a2b3;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.pf-panel-header h3 {
  margin: 4px 0;
  color: #172033;
  font-size: 16px;
  font-weight: 800;
}

.pf-panel-header p {
  margin: 0;
  color: #98a2b3;
  font-size: 11px;
}

.pf-link-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 0;
  border: 0;
  background: transparent;
  color: #2563eb;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
