/* ------------------------------------------------------------
   TABLE VENTES
------------------------------------------------------------ */

.pf-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.pf-dashboard-table {
  width: 100%;
  min-width: 580px;
  border-collapse: collapse;
}

.pf-dashboard-table th {
  padding: 10px 20px;
  border-top: 1px solid #edf0f4;
  border-bottom: 1px solid #edf0f4;
