  /* ----------------------------------------------------------
     PHARMACY BANNER
     ---------------------------------------------------------- */

  .pf-pharmacy-banner {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 16px;
    padding: 17px;
    border-radius: 16px;
  }

  .pf-banner-main {
    min-width: 0;
  }

  .pf-banner-status {
    width: 100%;
  }

  /* ----------------------------------------------------------
     ABONNEMENT
     ---------------------------------------------------------- */

  .pf-subscription-card {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 18px;
    padding: 18px;
    border-radius: 16px;
  }

  .pf-subscription-main {
    min-width: 0;
  }

  .pf-subscription-content {
    min-width: 0;
  }

  .pf-subscription-content h3 {
    font-size: 17px;
    line-height: 1.35;
  }

  .pf-subscription-right {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
  }

  .pf-subscription-button {
    flex: 1 1 auto;
    min-height: 46px;
  }

  /* ----------------------------------------------------------
     KPI
     ---------------------------------------------------------- */

  .pf-kpi-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .pf-kpi-card {
    width: 100%;
    min-height: 150px;
  }

  .pf-kpi-value {
    font-size: 28px;
  }

  /* ----------------------------------------------------------
     PANELS
     ---------------------------------------------------------- */

  .pf-main-dashboard-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 14px;
  }

  .pf-panel {
    width: 100%;
    min-width: 0;
    border-radius: 16px;
  }

  .pf-panel-header {
    gap: 12px;
    padding: 16px;
  }

  .pf-panel-header h3 {
    font-size: 17px;
  }

  .pf-panel-header p {
    font-size: 12px;
  }

  /* ----------------------------------------------------------
     TABLE
     ---------------------------------------------------------- */

  .pf-table-wrapper {
    width: 100%;
    max-width: 100%;
    margin: 0;
    padding: 0;
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch;
  }

  .pf-dashboard-table {
    min-width: 580px;
  }

  /* ----------------------------------------------------------
     STOCK
     ---------------------------------------------------------- */

  .pf-stock-summary {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 7px;
  }

  .pf-stock-summary-card {
    min-width: 0;
    padding: 10px 6px;
  }

  .pf-stock-summary-card span {
    font-size: 9px;
  }

  .pf-stock-summary-card strong {
    font-size: 20px;
  }

  .pf-stock-list {
    min-width: 0;
  }

  .pf-stock-item {
    gap: 10px;
    padding: 12px 14px;
  }

  .pf-stock-product {
    min-width: 0;
  }

  .pf-stock-product strong {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* ----------------------------------------------------------
     QUICK ACTIONS
     ---------------------------------------------------------- */

  .pf-quick-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .pf-quick-card {
    width: 100%;
    min-height: 76px;
  }

  .pf-quick-content {
    min-width: 0;
  }

  .pf-quick-content strong,
  .pf-quick-content span {
    overflow: hidden;
    text-overflow: ellipsis;
  }

  /* ----------------------------------------------------------
     SUPPORT
     ---------------------------------------------------------- */

  .pf-dashboard-support-card {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 14px;
    padding: 17px;
    border-radius: 16px;
  }

  .pf-dashboard-support-content {
    width: 100%;
    min-width: 0;
  }

  .pf-dashboard-support-content h3 {
    font-size: 17px;
    line-height: 1.3;
  }

  .pf-dashboard-support-content p {
    font-size: 13px;
  }

  .pf-dashboard-support-actions {
    display: grid;
    grid-template-columns: 1fr;
    width: 100%;
    gap: 8px;
  }

  .pf-dashboard-support-actions button {
    width: 100% !important;
    min-height: 46px;
    justify-content: center;
  }

  /* ----------------------------------------------------------
     FOOTER
     ---------------------------------------------------------- */

  .pf-dashboard-footer {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
    padding-bottom:
      calc(18px + env(safe-area-inset-bottom));
  }

}


/* ============================================================
   11. TRÈS PETITS TÉLÉPHONES — 390 PX ET MOINS
   ============================================================ */

@media (max-width: 390px) {

  .pf-sidebar {
    width: 90vw !important;
    max-width: 310px !important;
  }

  .pf-dashboard-content {
    padding-left: 13px;
    padding-right: 13px;
  }

  .pf-header-left {
    max-width: calc(100% - 92px);
  }

  .pf-mobile-menu-button {
    width: 40px !important;
    height: 40px !important;
    min-width: 40px !important;
  }

  .pf-header-icon-button {
    width: 38px !important;
    height: 38px !important;
    min-width: 38px !important;
  }

  .pf-dashboard-intro h2 {
    font-size: 23px;
  }

  .pf-stock-summary {
    gap: 5px;
  }

  .pf-stock-summary-card {
    padding-left: 4px;
    padding-right: 4px;
  }

}


/* ============================================================
   12. IPHONE / IOS : SAFE AREA
   ============================================================ */

@supports (padding: max(0px)) {

  .pf-sidebar {
    padding-bottom:
      max(16px, env(safe-area-inset-bottom));
  }

  .pf-app-header {
    padding-left:
      max(14px, env(safe-area-inset-left));

    padding-right:
      max(14px, env(safe-area-inset-right));
  }

}


/* ============================================================
   13. PAYSAGE MOBILE
   ============================================================ */

@media (max-width: 900px) and (orientation: landscape) {

  .pf-sidebar {
    width: min(360px, 72vw) !important;
  }

  .pf-dashboard-content {
    padding-top: 16px;
  }

  .pf-kpi-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .pf-quick-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}


/* ============================================================
   14. ACCESSIBILITÉ / RÉDUCTION DES ANIMATIONS
   ============================================================ */

@media (prefers-reduced-motion: reduce) {

  .pf-sidebar,
  .pf-mobile-overlay,
  .pf-nav-item,
  .pf-kpi-card,
  .pf-quick-card,
  .pf-mobile-menu-button {
    transition: none !important;
    animation: none !important;
  }

}


/* ============================================================
   15. CORRECTION DES ÉLÉMENTS QUI POURRAIENT FORCER
       LA LARGEUR DE L'ÉCRAN
   ============================================================ */

@media (max-width: 900px) {

  .pf-dashboard-content img,
  .pf-dashboard-content video,
  .pf-dashboard-content iframe,
  .pf-dashboard-content svg,
  .pf-dashboard-content canvas {
    max-width: 100%;
  }

  .pf-dashboard-content pre,
  .pf-dashboard-content code {
    max-width: 100%;
    overflow-x: auto;
  }

  .pf-dashboard-content input,
  .pf-dashboard-content select,
  .pf-dashboard-content textarea {
    max-width: 100%;
  }

}

/* ==========================================================================
   PHARMAFLOW AFRICA
   CENTRE DES PAIEMENTS — PREMIUM GLOBAL UI
   Desktop • Laptop • Tablet • iPhone • Android
   ========================================================================== */

:root {
  --pf-payment-primary: #0f766e;
  --pf-payment-primary-dark: #115e59;
  --pf-payment-primary-light: #ccfbf1;

  --pf-payment-success: #059669;
  --pf-payment-warning: #d97706;
  --pf-payment-danger: #dc2626;
  --pf-payment-info: #2563eb;

  --pf-payment-text: #0f172a;
  --pf-payment-text-secondary: #475569;
  --pf-payment-text-muted: #64748b;

  --pf-payment-border: #e2e8f0;
  --pf-payment-border-light: #f1f5f9;

  --pf-payment-bg: #f7fafc;
  --pf-payment-white: #ffffff;

  --pf-payment-radius-sm: 8px;
  --pf-payment-radius-md: 12px;
  --pf-payment-radius-lg: 16px;
  --pf-payment-radius-xl: 20px;

  --pf-payment-shadow-sm:
    0 1px 2px rgba(15, 23, 42, 0.04);

  --pf-payment-shadow:
    0 8px 30px rgba(15, 23, 42, 0.06);

  --pf-payment-shadow-lg:
    0 18px 50px rgba(15, 23, 42, 0.09);
}


/* ==========================================================================
   PAGE
   ========================================================================== */

.agent-payments-page {
  position: relative;

  width: 100%;
  min-height: 100vh;

  padding: 24px;

  color: var(--pf-payment-text);

  background:
    radial-gradient(
      circle at 100% 0%,
      rgba(20, 184, 166, 0.09),
      transparent 28%
    ),
    radial-gradient(
      circle at 0% 100%,
      rgba(59, 130, 246, 0.035),
      transparent 28%
    ),
    #f8fafc;
}

.agent-payments-page *,
.agent-payments-page *::before,
.agent-payments-page *::after {
  box-sizing: border-box;
}

.agent-payments-container {
  position: relative;

  width: 100%;
  max-width: 1800px;

  margin: 0 auto;
}


/* ==========================================================================
   HEADER PREMIUM
   ========================================================================== */

.agent-payments-header {
  position: relative;

  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 28px;

  margin-bottom: 24px;
  padding: 28px;

  overflow: hidden;

  background:
    linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.98),
      rgba(248, 250, 252, 0.98)
    );

  border: 1px solid rgba(226, 232, 240, 0.95);

  border-radius: 22px;

  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.03),
    0 14px 40px rgba(15, 23, 42, 0.055);
}

.agent-payments-header::before {
  content: "";

  position: absolute;

  width: 280px;
  height: 280px;

  top: -170px;
  right: -100px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(20, 184, 166, 0.13),
      transparent 68%
    );

  pointer-events: none;
}

.agent-payments-header::after {
  content: "";

  position: absolute;

  left: 0;
  top: 0;
  bottom: 0;

  width: 4px;

  background:
    linear-gradient(
      180deg,
      #14b8a6,
      #0f766e
    );

  border-radius: 22px 0 0 22px;
}

.agent-payments-header-content {
  position: relative;
  z-index: 2;

  min-width: 0;
}

.agent-payments-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  margin-bottom: 9px;

  color: var(--pf-payment-primary);

  font-size: 11px;
  font-weight: 850;

  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.agent-payments-eyebrow span {
  display: inline-block;

  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #14b8a6;

  box-shadow:
    0 0 0 4px rgba(20, 184, 166, 0.12);
}

.agent-payments-title {
  margin: 0;

  color: #020617;

  font-size: clamp(26px, 3vw, 38px);

  font-weight: 850;

  line-height: 1.08;

  letter-spacing: -0.035em;
}

.agent-payments-description {
  max-width: 780px;

  margin: 10px 0 0;

  color: var(--pf-payment-text-secondary);

  font-size: 14px;

  line-height: 1.7;
}

.agent-payments-header
a {
  position: relative;
  z-index: 3;
}


/* ==========================================================================
   KPI CARDS
   ========================================================================== */

.agent-payments-stats {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 16px;

  margin-bottom: 22px;
}

.agent-payment-stat {
  position: relative;

  min-width: 0;

  padding: 22px;

  overflow: hidden;

  background: rgba(255, 255, 255, 0.97);

  border: 1px solid var(--pf-payment-border);

  border-radius: 18px;

  box-shadow: var(--pf-payment-shadow-sm);

  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease;
}

.agent-payment-stat::before {
  content: "";

  position: absolute;

  top: 0;
  left: 0;
  right: 0;

  height: 3px;

  background:
    linear-gradient(
      90deg,
      #14b8a6,
      #0f766e
    );

  opacity: 0.85;
}

.agent-payment-stat::after {
  content: "";

  position: absolute;

  right: -35px;
  bottom: -45px;

  width: 125px;
  height: 125px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(20, 184, 166, 0.08),
      transparent 70%
    );

  pointer-events: none;
}

.agent-payment-stat:hover {
  transform: translateY(-3px);

  border-color: rgba(20, 184, 166, 0.3);

  box-shadow:
    0 12px 35px rgba(15, 118, 110, 0.08);
}

.agent-payment-stat-label {
  position: relative;
  z-index: 2;

  color: var(--pf-payment-text-muted);

  font-size: 11px;

  font-weight: 800;

  letter-spacing: 0.055em;

  text-transform: uppercase;
}

.agent-payment-stat-value {
  position: relative;
  z-index: 2;

  margin-top: 9px;

  color: #020617;

  font-size: clamp(25px, 2.4vw, 34px);

  font-weight: 850;

  line-height: 1.1;

  letter-spacing: -0.035em;

  overflow-wrap: anywhere;
}

.agent-payment-stat-meta {
  position: relative;
  z-index: 2;

  margin-top: 9px;

  color: var(--pf-payment-text-muted);

  font-size: 11px;

  font-weight: 600;

  line-height: 1.5;
}


/* ==========================================================================
   FILTRES
   ========================================================================== */

.agent-payments-filters {
  display: grid;

  grid-template-columns:
    minmax(230px, 2fr)
    minmax(150px, 1fr)
    minmax(150px, 1fr)
    minmax(150px, 1fr)
    auto;

  gap: 12px;

  margin-bottom: 20px;

  padding: 18px;

  background: rgba(255, 255, 255, 0.98);

  border: 1px solid var(--pf-payment-border);

  border-radius: 18px;

  box-shadow: var(--pf-payment-shadow-sm);
}

.agent-payments-filter-group {
  min-width: 0;
}

.agent-payments-filter-label {
  display: block;

  margin-bottom: 7px;

  color: #475569;

  font-size: 10px;

  font-weight: 850;

  letter-spacing: 0.07em;

  text-transform: uppercase;
}

.agent-payments-filter-input,
.agent-payments-filter-select {
  width: 100%;

  height: 44px;

  padding: 0 13px;

  color: #0f172a;

  background: #f8fafc;

  border: 1px solid #e2e8f0;

  border-radius: 11px;

  outline: none;

  font-family: inherit;

  font-size: 13px;

  font-weight: 500;

  transition:
    border-color 150ms ease,
    background 150ms ease,
    box-shadow 150ms ease,
    transform 150ms ease;
}

.agent-payments-filter-input::placeholder {
  color: #94a3b8;
}

.agent-payments-filter-input:hover,
.agent-payments-filter-select:hover {
  background: #ffffff;

  border-color: #cbd5e1;
}

.agent-payments-filter-input:focus,
.agent-payments-filter-select:focus {
  background: #ffffff;

  border-color: #0f766e;

  box-shadow:
    0 0 0 4px rgba(15, 118, 110, 0.1);
}

.agent-payments-filter-button {
  min-height: 44px;

  padding: 0 19px;

  color: white;

  background:
    linear-gradient(
      135deg,
      #0f766e,
      #0d9488
    );

  border: 0;

  border-radius: 11px;

  font-family: inherit;

  font-size: 13px;

  font-weight: 800;

  cursor: pointer;

  box-shadow:
    0 5px 14px rgba(15, 118, 110, 0.18);

  transition:
    transform 150ms ease,
    box-shadow 150ms ease,
    filter 150ms ease;
}

.agent-payments-filter-button:hover {
  filter: brightness(1.04);

  transform: translateY(-1px);

  box-shadow:
    0 8px 20px rgba(15, 118, 110, 0.23);
}

.agent-payments-filter-button:active {
  transform: translateY(0);
}


/* ==========================================================================
   ACTIVE FILTERS
   ========================================================================== */

.agent-payments-container
section
+ section {
  scroll-margin-top: 20px;
}


/* ==========================================================================
   TABLE CARD
   ========================================================================== */

.agent-payments-table-card {
  position: relative;

  width: 100%;

  overflow: hidden;

  background: #ffffff;

  border: 1px solid var(--pf-payment-border);

  border-radius: 20px;

  box-shadow:
    0 8px 32px rgba(15, 23, 42, 0.055);
}

.agent-payments-table-header {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 18px;

  padding: 20px 22px;

  background:
    linear-gradient(
      180deg,
      #ffffff,
      #fcfdfd
    );

  border-bottom: 1px solid #eef2f7;
}

.agent-payments-table-title {
  margin: 0;

  color: #0f172a;

  font-size: 16px;

  font-weight: 850;

  letter-spacing: -0.015em;
}

.agent-payments-table-count {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  min-height: 28px;

  padding: 5px 11px;

  color: #0f766e;

  background: #f0fdfa;

  border: 1px solid #ccfbf1;

  border-radius: 999px;

  font-size: 10px;

  font-weight: 850;

  white-space: nowrap;
}


/* ==========================================================================
   TABLE WRAPPER
   ========================================================================== */

.agent-payments-table-wrapper {
  width: 100%;

  overflow-x: auto;
  overflow-y: hidden;

  -webkit-overflow-scrolling: touch;

  scrollbar-width: thin;

  scrollbar-color:
    #cbd5e1
    transparent;
}

.agent-payments-table-wrapper::-webkit-scrollbar {
  height: 8px;
}

.agent-payments-table-wrapper::-webkit-scrollbar-track {
  background: #f8fafc;
}

.agent-payments-table-wrapper::-webkit-scrollbar-thumb {
  background: #cbd5e1;

  border-radius: 999px;
}

.agent-payments-table-wrapper::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}


/* ==========================================================================
   TABLE
   ========================================================================== */

.agent-payments-table {
  width: 100%;

  min-width: 1180px;

  border-collapse: separate;

  border-spacing: 0;

  text-align: left;
}

.agent-payments-table thead {
  position: sticky;

  top: 0;

  z-index: 5;
}

.agent-payments-table thead tr {
  background:
    linear-gradient(
      180deg,
      #f8fafc,
      #f1f5f9
    );
}

.agent-payments-table th {
  padding: 13px 16px;

  color: #64748b;

  border-bottom: 1px solid #e2e8f0;

  font-size: 9px;

  font-weight: 850;

  letter-spacing: 0.075em;

  text-transform: uppercase;

  white-space: nowrap;
}

.agent-payments-table td {
  padding: 16px;

  color: #475569;

  background: #ffffff;

  border-bottom: 1px solid #f1f5f9;

  font-size: 12px;

  vertical-align: top;

  transition:
    background 120ms ease;
}

.agent-payments-table tbody tr {
  transition:
    background 120ms ease,
    box-shadow 120ms ease;
}

.agent-payments-table tbody tr:hover td {
  background: #f8fafc;
}

.agent-payments-table tbody tr:last-child td {
  border-bottom: 0;
}


/* ==========================================================================
   TRANSACTION
   ========================================================================== */

.agent-payment-reference {
  display: flex;

  flex-direction: column;

  gap: 5px;

  min-width: 190px;
}

.agent-payment-reference strong {
  color: #0f172a;

  font-family:
    ui-monospace,
    SFMono-Regular,
    Menlo,
    Monaco,
    Consolas,
    monospace;

  font-size: 11px;

  font-weight: 800;

  line-height: 1.45;

  overflow-wrap: anywhere;
}

.agent-payment-reference span:not(.inline-flex) {
  color: #94a3b8;

  font-family:
    ui-monospace,
    SFMono-Regular,
    Menlo,
    Monaco,
    Consolas,
    monospace;

  font-size: 9px;

  line-height: 1.4;

  overflow-wrap: anywhere;
}


/* ==========================================================================
   CLIENT
   ========================================================================== */

.agent-payment-client {
  display: flex;

  flex-direction: column;

  gap: 4px;

  min-width: 190px;
}

.agent-payment-client-name {
  color: #0f172a;

  font-size: 12px;

  font-weight: 800;

  line-height: 1.4;
}

.agent-payment-client-email {
  max-width: 210px;

  color: #64748b;

  font-size: 10px;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}


/* ==========================================================================
   PHARMACIE
   ========================================================================== */

.agent-payment-pharmacy {
  display: flex;

  flex-direction: column;

  gap: 4px;

  min-width: 160px;
}

.agent-payment-pharmacy-name {
  color: #0f172a;

  font-size: 12px;

  font-weight: 800;

  line-height: 1.4;
}

.agent-payment-pharmacy-location {
  color: #64748b;

  font-size: 10px;

  font-weight: 500;
}


/* ==========================================================================
   FOURNISSEUR
   ========================================================================== */

.agent-payment-provider {
  display: flex;

  flex-direction: column;

  gap: 5px;

  min-width: 140px;
}

.agent-payment-provider-name {
  color: #0f172a;

  font-size: 12px;

  font-weight: 800;

  line-height: 1.4;
}


/* ==========================================================================
   MÉTHODE DE PAIEMENT
   ========================================================================== */

.agent-payment-method {
  display: inline-flex;

  align-items: center;

  width: fit-content;

  min-height: 27px;

  padding: 5px 9px;

  color: #475569;

  background: #f8fafc;

  border: 1px solid #e2e8f0;

  border-radius: 8px;

  font-size: 9px;

  font-weight: 850;

  letter-spacing: 0.04em;

  text-transform: uppercase;

  white-space: nowrap;
}


/* ==========================================================================
   MONTANT
   ========================================================================== */

.agent-payment-amount {
  min-width: 125px;

  color: #0f172a;

  font-size: 13px;

  font-weight: 850;

  line-height: 1.4;

  white-space: nowrap;
}


/* ==========================================================================
   STATUTS
   ========================================================================== */

.agent-payment-status {
  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 6px;

  min-height: 27px;

  padding: 5px 10px;

  border-radius: 999px;

  font-size: 9px;

  font-weight: 850;

  letter-spacing: 0.015em;

  white-space: nowrap;
}

.agent-payment-status::before {
  content: "";

  width: 6px;
  height: 6px;

  flex-shrink: 0;

  border-radius: 999px;
}


/* SUCCESS */

.agent-payment-status-success {
  color: #047857;

  background: #ecfdf5;

  border: 1px solid #a7f3d0;
}

.agent-payment-status-success::before {
  background: #10b981;

  box-shadow:
    0 0 0 3px rgba(16, 185, 129, 0.1);
}


/* PENDING */

.agent-payment-status-pending {
  color: #b45309;

  background: #fffbeb;

  border: 1px solid #fde68a;
}

.agent-payment-status-pending::before {
  background: #f59e0b;

  box-shadow:
    0 0 0 3px rgba(245, 158, 11, 0.1);
}


/* PROCESSING */

.agent-payment-status-processing {
  color: #1d4ed8;

  background: #eff6ff;

  border: 1px solid #bfdbfe;
}

.agent-payment-status-processing::before {
  background: #3b82f6;

  box-shadow:
    0 0 0 3px rgba(59, 130, 246, 0.1);
}


/* FAILED */

.agent-payment-status-failed {
  color: #b91c1c;

  background: #fef2f2;

  border: 1px solid #fecaca;
}

.agent-payment-status-failed::before {
  background: #ef4444;

  box-shadow:
    0 0 0 3px rgba(239, 68, 68, 0.1);
}


/* CANCELLED */

.agent-payment-status-cancelled {
  color: #64748b;

  background: #f8fafc;

  border: 1px solid #e2e8f0;
}

.agent-payment-status-cancelled::before {
  background: #94a3b8;
}


/* DEFAULT */

.agent-payment-status-default {
  color: #475569;

  background: #f8fafc;

  border: 1px solid #e2e8f0;
}

.agent-payment-status-default::before {
  background: #94a3b8;
}


/* ==========================================================================
   DATE
   ========================================================================== */

.agent-payment-date {
  display: flex;

  flex-direction: column;

  gap: 4px;

  min-width: 125px;
}

.agent-payment-date-main {
  color: #334155;

  font-size: 10px;

  font-weight: 750;

  white-space: nowrap;
}

.agent-payment-date-time {
  color: #94a3b8;

  font-size: 9px;

  white-space: nowrap;
}


/* ==========================================================================
   EMPTY STATE
   ========================================================================== */

.agent-payments-empty {
  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  min-height: 330px;

  padding: 50px 24px;

  text-align: center;
}

.agent-payments-empty-icon {
  display: flex;

  align-items: center;

  justify-content: center;

  width: 68px;
  height: 68px;

  color: #0f766e;

  background:
    linear-gradient(
      135deg,
      #ecfdf5,
      #ccfbf1
    );

  border: 1px solid #a7f3d0;

  border-radius: 20px;

  font-size: 25px;

  box-shadow:
    0 10px 25px rgba(15, 118, 110, 0.08);
}

.agent-payments-empty-title {
  margin: 17px 0 0;

  color: #0f172a;

  font-size: 17px;

  font-weight: 850;
}

.agent-payments-empty-description {
  max-width: 450px;

  margin: 8px 0 0;

  color: #64748b;

  font-size: 13px;

  line-height: 1.7;
}


/* ==========================================================================
   INFORMATION
   ========================================================================== */

.agent-payments-info {
  display: flex;

  align-items: flex-start;

  gap: 13px;

  margin-top: 18px;

  padding: 16px 18px;

  color: #475569;

  background:
    linear-gradient(
      135deg,
      #f0fdfa,
      #ffffff
    );

  border: 1px solid #ccfbf1;

  border-radius: 15px;

  box-shadow:
    0 4px 18px rgba(15, 118, 110, 0.035);

  font-size: 11px;

  line-height: 1.65;
}

.agent-payments-info-icon {
  display: flex;

  align-items: center;

  justify-content: center;

  flex-shrink: 0;

  width: 32px;
  height: 32px;

  color: #0f766e;

  background: #ffffff;

  border: 1px solid #ccfbf1;

  border-radius: 9px;

  box-shadow: 0 2px 7px rgba(15, 118, 110, 0.06);
}


/* ==========================================================================
   FOOTER
   ========================================================================== */

.agent-payments-page footer {
  opacity: 0.85;
}


/* ==========================================================================
   RESPONSIVE — GRAND TABLET / PETIT LAPTOP
   ========================================================================== */

@media (max-width: 1200px) {

  .agent-payments-page {
    padding: 20px;
  }

  .agent-payments-stats {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .agent-payments-filters {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}


/* ==========================================================================
   RESPONSIVE — TABLETTE
   ========================================================================== */

@media (max-width: 900px) {

  .agent-payments-header {
    flex-direction: column;

    padding: 22px;
  }

  .agent-payments-header
  > div:last-child {
    width: 100%;
  }

  .agent-payments-header
  > div:last-child
  a {
    flex: 1;
  }

  .agent-payments-filters {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}


/* ==========================================================================
   RESPONSIVE — MOBILE
   ========================================================================== */

@media (max-width: 640px) {

  .agent-payments-page {
    min-height: 100vh;

    padding: 10px;
  }

  .agent-payments-header {
    gap: 20px;

    margin-bottom: 12px;

    padding: 18px;

    border-radius: 17px;
  }

  .agent-payments-header::after {
    border-radius: 17px 0 0 17px;
  }

  .agent-payments-title {
    font-size: 25px;

    letter-spacing: -0.03em;
  }

  .agent-payments-description {
    font-size: 12px;

    line-height: 1.65;
  }

  .agent-payments-stats {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));

    gap: 9px;

    margin-bottom: 12px;
  }

  .agent-payment-stat {
    padding: 15px;

    border-radius: 14px;
  }

  .agent-payment-stat-label {
    font-size: 9px;
  }

  .agent-payment-stat-value {
    margin-top: 7px;

    font-size: 21px;
  }

  .agent-payment-stat-meta {
    margin-top: 6px;

    font-size: 9px;
  }

  .agent-payments-filters {
    grid-template-columns: 1fr;

    gap: 10px;

    margin-bottom: 12px;

    padding: 13px;

    border-radius: 15px;
  }

  .agent-payments-filter-input,
  .agent-payments-filter-select {
    height: 43px;

    font-size: 12px;
  }

  .agent-payments-filter-button {
    width: 100%;

    min-height: 43px;
  }

  .agent-payments-table-card {
    border-radius: 15px;
  }

  .agent-payments-table-header {
    align-items: flex-start;

    flex-direction: column;

    padding: 15px;
  }

  .agent-payments-table-title {
    font-size: 14px;
  }

  .agent-payments-table-count {
    align-self: flex-start;
  }

  .agent-payments-info {
    margin-top: 12px;

    padding: 13px;

    border-radius: 13px;

    font-size: 10px;
  }

}


/* ==========================================================================
   RESPONSIVE — PETIT IPHONE
   ========================================================================== */

@media (max-width: 400px) {

  .agent-payments-page {
    padding: 7px;
  }

  .agent-payments-header {
    padding: 15px;

    border-radius: 15px;
  }

  .agent-payments-title {
    font-size: 22px;
  }

  .agent-payments-eyebrow {
    font-size: 9px;
  }

  .agent-payments-stats {
    grid-template-columns: 1fr 1fr;

    gap: 7px;
  }

  .agent-payment-stat {
    padding: 12px;

    border-radius: 12px;
  }

  .agent-payment-stat-value {
    font-size: 18px;
  }

  .agent-payment-stat-meta {
    font-size: 8px;
  }

  .agent-payments-header
  > div:last-child {
    flex-direction: column;
  }

  .agent-payments-header
  > div:last-child
  a {
    width: 100%;
  }

}


/* ==========================================================================
   TRÈS PETIT ÉCRAN
   ========================================================================== */

@media (max-width: 340px) {

  .agent-payments-stats {
    grid-template-columns: 1fr;
  }

  .agent-payments-title {
    font-size: 21px;
  }

}


/* ==========================================================================
   TOUCH / IPHONE
   ========================================================================== */

.agent-payments-page button,
.agent-payments-page a,
.agent-payments-page input,
.agent-payments-page select {
  -webkit-tap-highlight-color: transparent;
}

.agent-payments-page button,
.agent-payments-page a {
  touch-action: manipulation;
}


/* ==========================================================================
   ACCESSIBILITÉ
   ========================================================================== */

.agent-payments-page
button:focus-visible,
.agent-payments-page
a:focus-visible,
.agent-payments-page
input:focus-visible,
.agent-payments-page
select:focus-visible {
  outline: 3px solid rgba(20, 184, 166, 0.22);

  outline-offset: 2px;
}


/* ==========================================================================
   RÉDUCTION DES ANIMATIONS
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {

  .agent-payments-page *,
  .agent-payments-page *::before,
  .agent-payments-page *::after {
    animation-duration: 0.01ms !important;

    animation-iteration-count: 1 !important;

    transition-duration: 0.01ms !important;

    scroll-behavior: auto !important;
  }

}


/* ==========================================================================
   MODE SOMBRE — SI TON GLOBAL L'ACTIVE
   ========================================================================== */

@media (prefers-color-scheme: dark) {

  /*
   * On ne force volontairement pas un dark mode complet ici.
   * Cela évite de casser le thème global PharmaFlow si ton application
   * possède déjà son propre système de thème.
   */

}


/* ==========================================================================
   IMPRESSION
   ========================================================================== */

@media print {

  .agent-payments-page {
    padding: 0;

    background: #ffffff;
  }

  .agent-payments-header,
  .agent-payment-stat,
  .agent-payments-filters,
  .agent-payments-table-card,
  .agent-payments-info {
    box-shadow: none !important;
  }

  .agent-payments-filters {
    display: none;
  }

  .agent-payments-table-wrapper {
    overflow: visible;
  }

  .agent-payments-table {
    min-width: 0;
  }

}

/* ============================================================
   PHARMAFLOW — AGENT TECHNIQUE / ESPACE ÉQUIPE
   ============================================================ */

.pf-agent-page {
  min-height: 100vh;
  width: 100%;
  background: #f5f8f8;
  color: #0f172a;
  overflow-x: hidden;
}

.pf-agent-shell {
  width: 100%;
  min-height: 100vh;
}

/* ============================================================
   HEADER
   ============================================================ */

.pf-agent-header {
  position: sticky;
  top: 0;
  z-index: 100;
  width: 100%;
  min-height: 74px;
  padding: 0 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  background: rgba(255, 255, 255, 0.96);
  border-bottom: 1px solid #e2e8f0;
  backdrop-filter: blur(14px);
}

.pf-agent-header-left,
.pf-agent-header-right {
  min-width: 0;
  display: flex;
  align-items: center;
}

.pf-agent-header-left {
  gap: 15px;
}

.pf-agent-header-right {
  gap: 20px;
}

.pf-agent-back {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dce5e7;
  border-radius: 11px;
  background: #ffffff;
  color: #475569;
  font-size: 19px;
  font-weight: 700;
  text-decoration: none;
  transition:
    background 0.18s ease,
    color 0.18s ease,
    transform 0.18s ease;
}

.pf-agent-back:hover {
  background: #eaf7f4;
  color: #0f766e;
  transform: translateX(-2px);
}

.pf-agent-brand {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.pf-agent-brand-mark {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: #0f766e;
  color: #ffffff;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.3px;
  box-shadow: 0 6px 18px rgba(15, 118, 110, 0.18);
}

.pf-agent-brand > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-agent-brand strong {
  color: #0f172a;
  font-size: 15px;
  font-weight: 850;
}

.pf-agent-brand span {
  margin-top: 2px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-agent-online {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #047857;
  font-size: 11px;
  font-weight: 750;
}

.pf-agent-online i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #10b981;
  box-shadow: 0 0 0 4px #d1fae5;
}

.pf-agent-user-mini {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
}

.pf-agent-avatar-small {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: #dff3ef;
  color: #0f766e;
  font-size: 11px;
  font-weight: 900;
}

.pf-agent-user-mini > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-agent-user-mini strong {
  max-width: 180px;
  overflow: hidden;
  color: #1e293b;
  font-size: 11px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-agent-user-mini span {
  margin-top: 2px;
  color: #94a3b8;
  font-size: 9px;
}

/* ============================================================
   CONTENT
   ============================================================ */

.pf-agent-content {
  width: min(100% - 48px, 1440px);
  margin: 0 auto;
  padding: 25px 0 45px;
}

.pf-agent-breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 17px;
  color: #94a3b8;
  font-size: 11px;
}

.pf-agent-breadcrumb a {
  color: #64748b;
  text-decoration: none;
}

.pf-agent-breadcrumb a:hover {
  color: #0f766e;
}

.pf-agent-breadcrumb strong {
  color: #0f766e;
  font-weight: 750;
}

/* ============================================================
   HERO
   ============================================================ */

.pf-agent-hero {
  position: relative;
  overflow: hidden;
  min-height: 245px;
  padding: 36px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  border-radius: 24px;
  background:
    radial-gradient(
      circle at 88% 20%,
      rgba(45, 212, 191, 0.22),
      transparent 30%
    ),
    linear-gradient(
      135deg,
      #0f172a 0%,
      #102d32 55%,
      #0f766e 100%
    );
  box-shadow:
    0 20px 50px rgba(15, 23, 42, 0.13);
}

.pf-agent-hero::after {
  content: "";
  position: absolute;
  width: 240px;
  height: 240px;
  right: -80px;
  bottom: -130px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 50%;
  pointer-events: none;
}

.pf-agent-hero-content {
  position: relative;
  z-index: 2;
  min-width: 0;
  max-width: 800px;
}

.pf-agent-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: #ccfbf1;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.12em;
}

.pf-agent-hero h1 {
  margin: 17px 0 0;
  color: #ffffff;
  font-size: clamp(27px, 4vw, 43px);
  line-height: 1.08;
  font-weight: 900;
  letter-spacing: -1px;
}

.pf-agent-hero p {
  max-width: 700px;
  margin: 13px 0 0;
  color: #cbd5e1;
  font-size: 13px;
  line-height: 1.75;
}

.pf-agent-hero-meta {
  margin-top: 22px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.pf-agent-hero-meta span {
  min-height: 31px;
  padding: 7px 10px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.07);
  color: #cbd5e1;
  font-size: 9px;
}

.pf-agent-hero-meta span i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #34d399;
}

.pf-agent-hero-meta strong {
  color: #ffffff;
}

.pf-agent-hero-role {
  position: relative;
  z-index: 2;
  width: 235px;
  flex: 0 0 235px;
  padding: 19px;
  display: flex;
  align-items: center;
  gap: 13px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 17px;
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(12px);
}

.pf-agent-role-icon {
  width: 50px;
  height: 50px;
  flex: 0 0 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.11);
  font-size: 24px;
}

.pf-agent-hero-role > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-agent-hero-role span {
  color: #99f6e4;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: 0.13em;
}

.pf-agent-hero-role strong {
  margin-top: 5px;
  color: #ffffff;
  font-size: 18px;
  font-weight: 850;
}

.pf-agent-hero-role small {
  margin-top: 3px;
  color: #94a3b8;
  font-size: 9px;
}

/* ============================================================
   KPI
   ============================================================ */

.pf-agent-kpi-grid {
  margin-top: 20px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 15px;
}

.pf-agent-kpi-card {
  min-width: 0;
  padding: 19px;
  display: flex;
  align-items: center;
  gap: 13px;
  border: 1px solid #e2e8f0;
  border-radius: 17px;
  background: #ffffff;
  box-shadow: 0 7px 25px rgba(15, 23, 42, 0.045);
}

.pf-agent-kpi-icon {
  width: 45px;
  height: 45px;
  flex: 0 0 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 13px;
  background: #e8f6f3;
  font-size: 19px;
}

.pf-agent-kpi-card > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-agent-kpi-card span {
  color: #64748b;
  font-size: 10px;
  font-weight: 650;
}

.pf-agent-kpi-card strong {
  margin-top: 3px;
  color: #0f172a;
  font-size: 23px;
  font-weight: 900;
}

.pf-agent-kpi-card small {
  margin-top: 2px;
  color: #94a3b8;
  font-size: 8px;
}

.pf-agent-kpi-warning .pf-agent-kpi-icon {
  background: #fff7df;
}

.pf-agent-kpi-success .pf-agent-kpi-icon {
  background: #eaf8f0;
}

.pf-agent-kpi-info .pf-agent-kpi-icon {
  background: #edf4ff;
}

/* ============================================================
   DATA WARNING
   ============================================================ */

.pf-agent-data-warning {
  margin-top: 18px;
  padding: 13px 15px;
  display: flex;
  align-items: flex-start;
  gap: 11px;
  border: 1px solid #fde68a;
  border-radius: 14px;
  background: #fffbeb;
}

.pf-agent-data-warning > span {
  font-size: 18px;
}

.pf-agent-data-warning strong {
  color: #92400e;
  font-size: 11px;
}

.pf-agent-data-warning p {
  margin: 4px 0 0;
  color: #a16207;
  font-size: 9px;
  line-height: 1.5;
}

/* ============================================================
   SECTIONS
   ============================================================ */

.pf-agent-section {
  margin-top: 32px;
}

.pf-agent-section-heading {
  margin-bottom: 15px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}

.pf-agent-section-heading > div:first-child {
  min-width: 0;
}

.pf-agent-section-heading > div:first-child > span {
  color: #0f766e;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.13em;
}

.pf-agent-section-heading h2 {
  margin: 5px 0 0;
  color: #0f172a;
  font-size: 22px;
  font-weight: 900;
  letter-spacing: -0.4px;
}

.pf-agent-section-heading p {
  max-width: 700px;
  margin: 5px 0 0;
  color: #64748b;
  font-size: 10px;
  line-height: 1.6;
}

.pf-agent-task-count {
  min-width: 105px;
  padding: 9px 12px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  border: 1px solid #d8ebe8;
  border-radius: 11px;
  background: #f0f9f7;
}

.pf-agent-task-count strong {
  color: #0f766e;
  font-size: 17px;
  font-weight: 900;
}

.pf-agent-task-count span {
  color: #64748b;
  font-size: 8px;
}

/* ============================================================
   TASKS
   ============================================================ */

.pf-agent-task-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 15px;
}

.pf-agent-task-card {
  min-width: 0;
  min-height: 225px;
  padding: 19px;
  display: flex;
  flex-direction: column;
  border: 1px solid #e2e8f0;
  border-radius: 17px;
  background: #ffffff;
  color: inherit;
  text-decoration: none;
  box-shadow: 0 6px 24px rgba(15, 23, 42, 0.035);
  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.pf-agent-task-card:hover {
  transform: translateY(-3px);
  border-color: #99dcd4;
  box-shadow: 0 15px 35px rgba(15, 118, 110, 0.10);
}

.pf-agent-task-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pf-agent-task-icon {
  width: 47px;
  height: 47px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 13px;
  background: #eaf7f4;
  font-size: 21px;
}

.pf-agent-task-arrow {
  color: #94a3b8;
  font-size: 19px;
  transition: transform 0.2s ease, color 0.2s ease;
}

.pf-agent-task-card:hover .pf-agent-task-arrow {
  color: #0f766e;
  transform: translateX(3px);
}

.pf-agent-task-card h3 {
  margin: 19px 0 0;
  color: #0f172a;
  font-size: 15px;
  font-weight: 850;
}

.pf-agent-task-card p {
  flex: 1;
  margin: 7px 0 0;
  color: #64748b;
  font-size: 10px;
  line-height: 1.65;
}

.pf-agent-task-action {
  margin-top: 16px;
  padding-top: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #edf2f3;
  color: #0f766e;
  font-size: 9px;
  font-weight: 800;
}

.pf-agent-task-action b {
  font-size: 13px;
}

/* ============================================================
   TICKETS
   ============================================================ */

.pf-agent-section-link {
  padding: 8px 11px;
  border: 1px solid #dbe9e7;
  border-radius: 9px;
  color: #0f766e;
  background: #ffffff;
  font-size: 9px;
  font-weight: 750;
  text-decoration: none;
  white-space: nowrap;
}

.pf-agent-section-link:hover {
  background: #eaf7f4;
}

.pf-agent-ticket-panel {
  overflow: hidden;
  border: 1px solid #e2e8f0;
  border-radius: 17px;
  background: #ffffff;
  box-shadow: 0 6px 24px rgba(15, 23, 42, 0.035);
}

.pf-agent-ticket-list {
  width: 100%;
}

.pf-agent-ticket-row {
  min-width: 900px;
  padding: 14px 17px;
  display: grid;
  grid-template-columns: 1.2fr 1.5fr 125px 100px 20px;
  align-items: center;
  gap: 15px;
  border-bottom: 1px solid #edf1f2;
  color: inherit;
  text-decoration: none;
  transition: background 0.16s ease;
}

.pf-agent-ticket-row:last-child {
  border-bottom: 0;
}

.pf-agent-ticket-row:hover {
  background: #f7fbfa;
}

.pf-agent-ticket-number {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.pf-agent-ticket-number > span {
  width: 35px;
  height: 35px;
  flex: 0 0 35px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: #eaf7f4;
  font-size: 15px;
}

.pf-agent-ticket-number > div,
.pf-agent-ticket-subject {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-agent-ticket-number strong,
.pf-agent-ticket-subject strong {
  overflow: hidden;
  color: #1e293b;
  font-size: 10px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-agent-ticket-number small {
  margin-top: 3px;
  overflow: hidden;
  color: #94a3b8;
  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-agent-ticket-subject span {
  margin-top: 3px;
  color: #94a3b8;
  font-size: 8px;
}

.pf-agent-status,
.pf-agent-priority {
  width: fit-content;
  padding: 5px 8px;
  border-radius: 999px;
  font-size: 8px;
  font-weight: 800;
  white-space: nowrap;
}

.pf-agent-status-open,
.pf-agent-status-opened,
.pf-agent-status-new {
  background: #e0f2fe;
  color: #0369a1;
}

.pf-agent-status-pending {
  background: #fff7ed;
  color: #c2410c;
}

.pf-agent-status-inprogress,
.pf-agent-status-processing,
.pf-agent-status-assigned,
.pf-agent-status-in-progress {
  background: #ecfeff;
  color: #0e7490;
}

.pf-agent-status-resolved,
.pf-agent-status-completed,
.pf-agent-status-done,
.pf-agent-status-closed {
  background: #ecfdf5;
  color: #047857;
}

.pf-agent-priority-critical,
.pf-agent-priority-urgent {
  background: #fee2e2;
  color: #b91c1c;
}

.pf-agent-priority-high {
  background: #ffedd5;
  color: #c2410c;
}

.pf-agent-priority-normal,
.pf-agent-priority-medium {
  background: #f1f5f9;
  color: #475569;
}

.pf-agent-priority-low {
  background: #ecfdf5;
  color: #047857;
}

.pf-agent-ticket-arrow {
  color: #94a3b8;
  font-size: 15px;
}

.pf-agent-empty {
  min-height: 210px;
  padding: 30px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.pf-agent-empty > span {
  width: 50px;
  height: 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  background: #eaf7f4;
  font-size: 22px;
}

.pf-agent-empty strong {
  margin-top: 12px;
  color: #334155;
  font-size: 13px;
}

.pf-agent-empty p {
  margin: 5px 0 0;
  color: #94a3b8;
  font-size: 9px;
}

/* ============================================================
   COMPTE
   ============================================================ */

.pf-agent-account-grid {
  margin-top: 30px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 15px;
}

.pf-agent-account-card {
  min-width: 0;
  padding: 17px;
  display: flex;
  align-items: center;
  gap: 11px;
  border: 1px solid #e2e8f0;
  border-radius: 15px;
  background: #ffffff;
}

.pf-agent-account-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: #f1f5f9;
  font-size: 17px;
}

.pf-agent-account-card > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.pf-agent-account-card span {
  color: #94a3b8;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: 0.1em;
}

.pf-agent-account-card strong {
  margin-top: 3px;
  overflow: hidden;
  color: #334155;
  font-size: 11px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pf-agent-account-card small {
  margin-top: 2px;
  overflow: hidden;
  color: #94a3b8;
  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ============================================================
   FOOTER
   ============================================================ */

.pf-agent-footer {
  margin-top: 35px;
  padding-top: 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  border-top: 1px solid #e2e8f0;
  color: #94a3b8;
  font-size: 9px;
}

.pf-agent-footer span:first-child {
  color: #475569;
  font-weight: 800;
}

.pf-agent-footer a {
  color: #0f766e;
  font-weight: 750;
  text-decoration: none;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 1200px) {
  .pf-agent-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pf-agent-task-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .pf-agent-header {
    padding: 0 18px;
  }

  .pf-agent-header-right {
    gap: 10px;
  }

  .pf-agent-online {
    display: none;
  }

  .pf-agent-content {
    width: min(100% - 30px, 720px);
    padding-top: 19px;
  }

  .pf-agent-hero {
    padding: 27px;
    flex-direction: column;
    align-items: stretch;
  }

  .pf-agent-hero-role {
    width: 100%;
    flex-basis: auto;
  }

  .pf-agent-account-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .pf-agent-header {
    min-height: 64px;
    padding: 0 12px;
  }

  .pf-agent-back {
    width: 36px;
    height: 36px;
    flex-basis: 36px;
  }

  .pf-agent-brand-mark {
    width: 35px;
    height: 35px;
    flex-basis: 35px;
  }

  .pf-agent-brand strong {
    font-size: 13px;
  }

  .pf-agent-brand span {
    font-size: 8px;
  }

  .pf-agent-user-mini > div {
    display: none;
  }

  .pf-agent-avatar-small {
    width: 35px;
    height: 35px;
    flex-basis: 35px;
  }

  .pf-agent-content {
    width: calc(100% - 22px);
    padding-bottom: 28px;
  }

  .pf-agent-breadcrumb {
    margin-bottom: 12px;
  }

  .pf-agent-hero {
    min-height: auto;
    padding: 23px 19px;
    border-radius: 19px;
  }

  .pf-agent-hero h1 {
    font-size: 27px;
  }

  .pf-agent-hero p {
    font-size: 11px;
  }

  .pf-agent-hero-meta {
    flex-direction: column;
    align-items: stretch;
  }

  .pf-agent-hero-meta span {
    width: 100%;
  }

  .pf-agent-kpi-grid {
    grid-template-columns: 1fr 1fr;
    gap: 9px;
  }

  .pf-agent-kpi-card {
    padding: 13px;
    gap: 9px;
    border-radius: 13px;
  }

  .pf-agent-kpi-icon {
    width: 36px;
    height: 36px;
    flex-basis: 36px;
    border-radius: 10px;
    font-size: 15px;
  }

  .pf-agent-kpi-card strong {
    font-size: 18px;
  }

  .pf-agent-kpi-card small {
    font-size: 7px;
  }

  .pf-agent-section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }

  .pf-agent-task-count {
    align-items: flex-start;
  }

  .pf-agent-task-grid {
    grid-template-columns: 1fr;
  }

  .pf-agent-task-card {
    min-height: 190px;
  }

  .pf-agent-section-link {
    width: 100%;
    text-align: center;
  }

  .pf-agent-ticket-panel {
    overflow-x: auto;
  }

  .pf-agent-footer {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 420px) {
  .pf-agent-kpi-grid {
    grid-template-columns: 1fr;
  }

  .pf-agent-hero {
    padding: 20px 16px;
  }

  .pf-agent-hero-role {
    padding: 14px;
  }

  .pf-agent-section-heading h2 {
    font-size: 19px;
  }
}

/* ============================================================
   ACCESSIBILITÉ / MOTION
   ============================================================ */

@media (prefers-reduced-motion: reduce) {
  .pf-agent-task-card,
  .pf-agent-task-arrow,
  .pf-agent-back {
    transition: none;
  }
}

/* ============================================================
   PHARMAFLOW — SUPER ADMIN
   GREEN DESIGN SYSTEM
   ============================================================ */

:root {
  --pf-sa-primary: #0f766e;
  --pf-sa-primary-dark: #115e59;
  --pf-sa-primary-deep: #134e4a;
  --pf-sa-primary-light: #ccfbf1;
  --pf-sa-primary-soft: #f0fdfa;

  --pf-sa-success: #15803d;
  --pf-sa-success-light: #f0fdf4;

  --pf-sa-text: #101828;
  --pf-sa-text-secondary: #475467;
  --pf-sa-text-muted: #667085;

  --pf-sa-border: #e4e7ec;
  --pf-sa-border-soft: #eaecf0;

  --pf-sa-background: #f5f8f8;
  --pf-sa-surface: #ffffff;

  --pf-sa-shadow:
    0 8px 30px rgba(15, 118, 110, .07);

  --pf-sa-shadow-hover:
    0 16px 40px rgba(15, 118, 110, .12);

  --pf-sa-radius: 16px;
}


/* ============================================================
   SUPER ADMIN — GLOBAL PAGE
   ============================================================ */

.sa-layout,
.pf-super-admin,
.pf-super-admin-page,
.pf-sa-page {
  --sa-primary: var(--pf-sa-primary);
  --sa-primary-dark: var(--pf-sa-primary-dark);
  --sa-primary-light: var(--pf-sa-primary-light);

  --sa-success: var(--pf-sa-success);

  --sa-text: var(--pf-sa-text);
  --sa-text-secondary: var(--pf-sa-text-secondary);
  --sa-text-soft: var(--pf-sa-text-muted);

  --sa-border: var(--pf-sa-border);
  --sa-background: var(--pf-sa-background);

  background:
    linear-gradient(
      180deg,
      #f8fafc 0%,
      #f5f8f8 100%
    );
}


/* ============================================================
   SUPER ADMIN — LIENS
   ============================================================ */

.sa-layout a,
.pf-super-admin a,
.pf-super-admin-page a,
.pf-sa-page a {
  -webkit-tap-highlight-color: transparent;
}


/* ============================================================
   SUPER ADMIN — BOUTONS PRIMAIRES
   ============================================================ */

.sa-layout .sa-primary-button,
.sa-layout .sa-primary-btn,
.pf-super-admin .pf-primary-button,
.pf-super-admin-page .pf-primary-button,
.pf-sa-page .pf-primary-button {
  background:
    linear-gradient(
      135deg,
      #0f766e,
      #14b8a6
    );

  border-color: #0f766e;

  color: #ffffff;

  box-shadow:
    0 8px 20px rgba(15, 118, 110, .16);

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    background .18s ease;
}

.sa-layout .sa-primary-button:hover,
.sa-layout .sa-primary-btn:hover,
.pf-super-admin .pf-primary-button:hover,
.pf-super-admin-page .pf-primary-button:hover,
.pf-sa-page .pf-primary-button:hover {
  background:
    linear-gradient(
      135deg,
      #115e59,
      #0f766e
    );

  transform: translateY(-1px);

  box-shadow:
    0 12px 26px rgba(15, 118, 110, .22);
}


/* ============================================================
   SUPER ADMIN — LIENS D'ACTION
   ============================================================ */

.sa-layout a:hover,
.pf-super-admin a:hover,
.pf-super-admin-page a:hover,
.pf-sa-page a:hover {
  color: #0f766e;
}


/* ============================================================
   SUPER ADMIN — CARTES
   ============================================================ */

.sa-layout .sa-stat-card,
.sa-layout .sa-module-card,
.sa-layout .sa-governance-card,
.sa-layout .sa-integration-card,
.sa-layout .sa-control-card,
.pf-super-admin .pf-card,
.pf-super-admin-page .pf-card,
.pf-sa-page .pf-card {
  border-color: #e4e7ec;

  background: #ffffff;

  box-shadow:
    0 6px 24px rgba(16, 24, 40, .045);

  transition:
    transform .18s ease,
    border-color .18s ease,
    box-shadow .18s ease;
}

.sa-layout .sa-stat-card:hover,
.sa-layout .sa-module-card:hover,
.sa-layout .sa-governance-card:hover,
.sa-layout .sa-integration-card:hover,
.sa-layout .sa-control-card:hover,
.pf-super-admin .pf-card:hover,
.pf-super-admin-page .pf-card:hover,
.pf-sa-page .pf-card:hover {
  border-color: #b7ddd8;

  transform: translateY(-2px);

  box-shadow:
    0 15px 38px rgba(15, 118, 110, .10);
}


/* ============================================================
   SUPER ADMIN — ICÔNES
   ============================================================ */

.sa-layout .sa-stat-icon,
.sa-layout .sa-module-icon,
.sa-layout .sa-governance-icon,
.sa-layout .sa-integration-icon,
.sa-layout .sa-control-icon {
  background:
    linear-gradient(
      135deg,
      #ecfdf5,
      #ccfbf1
    );

  border-color: #ccefe8;

  color: #0f766e;
}


/* ============================================================
   SUPER ADMIN — TITRES
   ============================================================ */

.sa-layout h1,
.sa-layout h2,
.sa-layout h3,
.pf-super-admin h1,
.pf-super-admin h2,
.pf-super-admin h3,
.pf-super-admin-page h1,
.pf-super-admin-page h2,
.pf-super-admin-page h3,
.pf-sa-page h1,
.pf-sa-page h2,
.pf-sa-page h3 {
  color: var(--pf-sa-text);
}


/* ============================================================
   SUPER ADMIN — TEXTE VERT
   ============================================================ */

.sa-layout .sa-primary-text,
.sa-layout .sa-accent,
.pf-super-admin .pf-primary-text,
.pf-super-admin-page .pf-primary-text,
.pf-sa-page .pf-primary-text {
  color: #0f766e;
}


/* ============================================================
   SUPER ADMIN — BADGES SUCCESS
   ============================================================ */

.sa-layout .sa-badge-success,
.sa-layout .sa-status-success,
.pf-super-admin .pf-badge-success,
.pf-super-admin-page .pf-badge-success,
.pf-sa-page .pf-badge-success {
  background: #f0fdf4;

  border: 1px solid #bbf7d0;

  color: #15803d;
}


/* ============================================================
   SUPER ADMIN — NAVIGATION ACTIVE
   ============================================================ */

.sa-layout .sa-nav-item.active,
.sa-layout .sa-sidebar-link.active,
.sa-layout .sa-menu-item.active,
.pf-super-admin .pf-nav-item.active,
.pf-super-admin-page .pf-nav-item.active,
.pf-sa-page .pf-nav-item.active {
  background:
    linear-gradient(
      135deg,
      #ecfdf5,
      #f0fdfa
    );

  color: #0f766e;

  border-color: #ccefe8;

  box-shadow:
    inset 3px 0 0 #0f766e;
}


/* ============================================================
   SUPER ADMIN — SIDEBAR
   ============================================================ */

.sa-layout .sa-sidebar {
  background:
    linear-gradient(
      180deg,
      #ffffff 0%,
      #f8fffd 100%
    );

  border-right-color: #e1e9e7;
}

.sa-layout .sa-sidebar-link:hover,
.sa-layout .sa-nav-item:hover,
.sa-layout .sa-menu-item:hover {
  background: #f0fdfa;

  color: #0f766e;
}


/* ============================================================
   SUPER ADMIN — HEADER
   ============================================================ */

.sa-layout .sa-header {
  background: rgba(255, 255, 255, .96);

  border-bottom-color: #e4e7ec;

  box-shadow:
    0 2px 15px rgba(16, 24, 40, .035);
}


/* ============================================================
   SUPER ADMIN — AVATAR
   ============================================================ */

.sa-layout .sa-admin-avatar {
  background:
    linear-gradient(
      135deg,
      #0f766e,
      #14b8a6
    );

  color: #ffffff;

  box-shadow:
    0 6px 16px rgba(15, 118, 110, .18);
}


/* ============================================================
   SUPER ADMIN — WELCOME
   ============================================================ */

.sa-layout .sa-welcome {
  background:
    linear-gradient(
      135deg,
      #0f766e 0%,
      #115e59 55%,
      #134e4a 100%
    );

  border-color: #0f766e;

  box-shadow:
    0 16px 40px rgba(15, 118, 110, .17);
}

.sa-layout .sa-welcome h1,
.sa-layout .sa-welcome h2,
.sa-layout .sa-welcome p {
  color: #ffffff;
}


/* ============================================================
   SUPER ADMIN — STAT CARDS
   ============================================================ */

.sa-layout .sa-stat-value {
  color: #0f766e;
}

.sa-layout .sa-stat-label {
  color: #667085;
}


/* ============================================================
   SUPER ADMIN — PROGRESS
   ============================================================ */

.sa-layout .sa-progress,
.pf-super-admin .pf-progress,
.pf-super-admin-page .pf-progress {
  background: #e6f4f1;
}

.sa-layout .sa-progress-bar,
.pf-super-admin .pf-progress-bar,
.pf-super-admin-page .pf-progress-bar {
  background:
    linear-gradient(
      90deg,
      #0f766e,
      #14b8a6
    );
}


/* ============================================================
   SUPER ADMIN — TABLEAUX
   ============================================================ */

.sa-layout table,
.pf-super-admin table,
.pf-super-admin-page table,
.pf-sa-page table {
  border-color: #e4e7ec;
}

.sa-layout th,
.pf-super-admin th,
.pf-super-admin-page th,
.pf-sa-page th {
  background: #f0fdfa;

  color: #475467;

  border-bottom-color: #dcebe8;
}

.sa-layout td,
.pf-super-admin td,
.pf-super-admin-page td,
.pf-sa-page td {
  border-bottom-color: #eaecf0;
}

.sa-layout tbody tr:hover,
.pf-super-admin tbody tr:hover,
.pf-super-admin-page tbody tr:hover,
.pf-sa-page tbody tr:hover {
  background: #f8fffd;
}


/* ============================================================
   SUPER ADMIN — INPUTS
   ============================================================ */

.sa-layout input,
.sa-layout select,
.sa-layout textarea,
.pf-super-admin input,
.pf-super-admin select,
.pf-super-admin textarea,
.pf-super-admin-page input,
.pf-super-admin-page select,
.pf-super-admin-page textarea,
