   /* ============================================================
   PHARMAFLOW — CORRECTION FINALE MOBILE
   NAVIGATION + DÉBORDEMENT HORIZONTAL
   ============================================================ */

/*
 * Cette section doit rester à la toute fin de globals.css.
 * Elle surcharge les anciennes règles responsive sans modifier
 * le fonctionnement du menu dans page.tsx.
 */

@media (max-width: 760px) {

  /* ==========================================================
     1. EMPÊCHER TOUT DÉBORDEMENT HORIZONTAL
     ========================================================== */

  html {
    width: 100%;
    max-width: 100%;
    overflow-x: hidden !important;
  }

  body {
    width: 100%;
    max-width: 100%;
    margin: 0;
    overflow-x: hidden !important;
  }

  .pf-home {
    width: 100%;
    max-width: 100%;
    min-width: 0;
    overflow-x: hidden !important;
  }

  /*
   * Tous les éléments principaux de la page doivent pouvoir
   * rétrécir correctement sur téléphone.
   */

  .pf-home *,
  .pf-home *::before,
  .pf-home *::after {
    box-sizing: border-box;
    max-width: 100%;
  }


  /* ==========================================================
     2. HEADER MOBILE
     ========================================================== */

  .pf-home-header {
    width: 100% !important;
    max-width: 100% !important;
    overflow: visible !important;
    position: relative !important;
    z-index: 1200 !important;
  }

  .pf-home-header-inner {
    width: calc(100% - 28px) !important;
    max-width: 1240px !important;
    min-width: 0 !important;
    margin-left: auto !important;
    margin-right: auto !important;

    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;

    gap: 10px !important;
  }


  /* ==========================================================
     3. LOGO
     ========================================================== */

  .pf-home-logo {
    min-width: 0 !important;
    max-width: calc(100% - 60px) !important;

    display: inline-flex !important;
    align-items: center !important;

    overflow: hidden !important;
    white-space: nowrap !important;
    text-overflow: ellipsis !important;
  }

  .pf-home-logo > span:last-child {
    min-width: 0 !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
  }

  .pf-home-logo-mark {
    flex: 0 0 auto !important;
  }


  /* ==========================================================
     4. ACTIONS / HAMBURGER
     ========================================================== */

  .pf-home-actions {
    min-width: 0 !important;
    flex: 0 0 auto !important;

    display: flex !important;
    align-items: center !important;
    justify-content: flex-end !important;

    margin-left: auto !important;
  }

  .pf-home-menu-button {
    position: relative !important;

    width: 48px !important;
    min-width: 48px !important;
    max-width: 48px !important;

    height: 48px !important;
    min-height: 48px !important;
    max-height: 48px !important;

    flex: 0 0 48px !important;

    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;

    z-index: 10000 !important;
  }


  /* ==========================================================
     5. NAVIGATION MOBILE
     
     IMPORTANT :
     Le menu est complètement caché lorsqu'il n'est pas ouvert.
     Lorsqu'il est ouvert, il reste entièrement dans l'écran.
     ========================================================== */

  .pf-home-nav {
    position: fixed !important;

    top: 0 !important;
    right: 0 !important;
    left: auto !important;
    bottom: 0 !important;

    width: min(320px, calc(100vw - 20px)) !important;
    max-width: calc(100vw - 20px) !important;
    min-width: 0 !important;

    height: 100dvh !important;
    max-height: 100dvh !important;

    margin: 0 !important;

    padding: 88px 16px 28px !important;

    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    justify-content: flex-start !important;

    gap: 5px !important;

    background: #ffffff !important;

    border: 0 !important;
    border-radius: 0 !important;

    overflow-x: hidden !important;
    overflow-y: auto !important;

    box-sizing: border-box !important;

    /*
     * Menu fermé :
     * il est totalement hors de l'écran.
     */

    transform: translate3d(
      calc(100% + 20px),
      0,
      0
    ) !important;

    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;

    box-shadow:
      -18px 0 50px rgba(15, 23, 42, 0.16) !important;

    transition:
      transform 0.25s ease,
      opacity 0.20s ease,
      visibility 0.25s ease !important;

    z-index: 9999 !important;
  }


  /* ==========================================================
     6. MENU OUVERT
     ========================================================== */

  .pf-home-nav.is-open {
    transform: translate3d(0, 0, 0) !important;

    visibility: visible !important;
    opacity: 1 !important;

    pointer-events: auto !important;
  }


  /* ==========================================================
     7. LIENS DU MENU
     ========================================================== */

  .pf-home-nav button,
  .pf-home-nav a {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;

    min-height: 46px !important;

    margin: 0 !important;

    padding: 12px 13px !important;

    display: flex !important;
    align-items: center !important;

    border: 0 !important;
    border-radius: 10px !important;

    background: transparent !important;

    color: #0f172a !important;

    font-family: inherit !important;
    font-size: 14px !important;
    font-weight: 650 !important;

    text-align: left !important;
    text-decoration: none !important;

    white-space: normal !important;
    overflow: hidden !important;

    box-sizing: border-box !important;
  }

  .pf-home-nav button:hover,
  .pf-home-nav a:hover {
    background: #f0fdfa !important;
    color: #0f766e !important;
  }

  .pf-home-nav button:active,
  .pf-home-nav a:active {
    transform: scale(0.99);
  }


  /* ==========================================================
     8. OVERLAY
     ========================================================== */

  .pf-home-mobile-overlay {
    position: fixed !important;

    inset: 0 !important;

    width: 100vw !important;
    height: 100dvh !important;

    margin: 0 !important;
    padding: 0 !important;

    border: 0 !important;

    background: rgba(
      2,
      6,
      23,
      0.42
    ) !important;

    backdrop-filter: blur(3px) !important;
    -webkit-backdrop-filter: blur(3px) !important;

    z-index: 9990 !important;
  }


  /* ==========================================================
     9. HERO
     ========================================================== */

  .pf-home-hero {
    width: 100% !important;
    max-width: 100% !important;
    overflow: hidden !important;
  }

  .pf-home-hero-inner {
    width: calc(100% - 28px) !important;
    max-width: 1240px !important;
    min-width: 0 !important;

    margin-left: auto !important;
    margin-right: auto !important;
  }

  .pf-home-hero-copy {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
  }

  .pf-home-hero-copy h1,
  .pf-home-hero h1 {
    width: 100% !important;
    max-width: 100% !important;

    overflow-wrap: anywhere !important;
    word-break: normal !important;
  }

  .pf-home-hero-copy > p {
    width: 100% !important;
    max-width: 100% !important;

    overflow-wrap: anywhere !important;
  }


  /* ==========================================================
     10. BOUTONS HERO
     ========================================================== */

  .pf-home-hero-buttons {
    width: 100% !important;
    max-width: 100% !important;

    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;

    gap: 10px !important;
  }

  .pf-home-primary-button,
  .pf-home-secondary-button {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;

    box-sizing: border-box !important;

    white-space: normal !important;
  }


  /* ==========================================================
     11. DASHBOARD / VISUELS
     ========================================================== */

  .pf-home-dashboard-wrap,
  .pf-home-dashboard,
  .pf-home-dashboard-grid {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
  }

  .pf-home-dashboard {
    overflow: hidden !important;
  }


  /* ==========================================================
     12. SECTIONS
     ========================================================== */

  .pf-home-section,
  .pf-home-global-inner,
  .pf-home-security-grid,
  .pf-home-support-grid,
  .pf-home-contact-inner,
  .pf-home-pricing,
  .pf-home-final-cta {
    max-width: 100% !important;
    min-width: 0 !important;
  }

  .pf-home-feature-grid,
  .pf-home-solutions-grid,
  .pf-home-support-grid,
  .pf-home-pricing-grid {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
  }


  /* ==========================================================
     13. CARTES
     ========================================================== */

  .pf-home-feature-card,
  .pf-home-solution-card,
  .pf-home-support-card,
  .pf-home-price-card {
    min-width: 0 !important;
    max-width: 100% !important;

    overflow: hidden !important;

    box-sizing: border-box !important;
  }

  .pf-home-feature-card *,
  .pf-home-solution-card *,
  .pf-home-support-card *,
  .pf-home-price-card * {
    max-width: 100% !important;
  }


  /* ==========================================================
     14. TABLEAUX / ÉLÉMENTS LARGES
     ========================================================== */

  .pf-home table {
    width: 100% !important;
    max-width: 100% !important;
  }

  .pf-home img,
  .pf-home video,
  .pf-home iframe,
  .pf-home svg,
  .pf-home canvas {
    max-width: 100% !important;
  }

  .pf-home img,
  .pf-home video,
  .pf-home iframe {
    height: auto;
  }


  /* ==========================================================
     15. FOOTER
     ========================================================== */

  .pf-home-footer {
    width: 100% !important;
    max-width: 100% !important;
    overflow: hidden !important;
  }

  .pf-home-footer-main,
  .pf-home-footer-contact,
  .pf-home-footer-bottom {
    max-width: calc(100% - 28px) !important;
    min-width: 0 !important;
  }

  .pf-home-footer-column {
    min-width: 0 !important;
    max-width: 100% !important;
  }

  .pf-home-footer-column a,
  .pf-home-footer-column button {
    max-width: 100% !important;
    overflow-wrap: anywhere !important;
  }


  /* ==========================================================
     16. TRÈS PETITS ÉCRANS
     ========================================================== */

  @media (max-width: 430px) {

    .pf-home-header-inner {
      width: calc(100% - 24px) !important;
    }

    .pf-home-hero-inner,
    .pf-home-section,
    .pf-home-global-inner {
      width: calc(100% - 24px) !important;
    }

    .pf-home-hero h1,
    .pf-home-hero-copy h1 {
      font-size: clamp(
        38px,
        11vw,
        46px
      ) !important;

      line-height: 0.98 !important;
      letter-spacing: -0.045em !important;
    }

    .pf-home-badge {
      max-width: 100% !important;
      white-space: normal !important;
      text-align: center !important;
    }

    .pf-home-nav {
      width: min(
        310px,
        calc(100vw - 16px)
      ) !important;

      max-width: calc(
        100vw - 16px
      ) !important;

      padding-left: 14px !important;
      padding-right: 14px !important;
    }
  }


  /* ==========================================================
     17. IPHONE TRÈS ÉTROIT
     ========================================================== */

  @media (max-width: 360px) {

    .pf-home-header-inner {
      width: calc(100% - 20px) !important;
    }

    .pf-home-hero-inner,
    .pf-home-section,
    .pf-home-global-inner {
      width: calc(100% - 20px) !important;
    }

    .pf-home-logo {
      font-size: 17px !important;
    }

    .pf-home-logo-mark {
      width: 34px !important;
      height: 34px !important;
    }

    .pf-home-menu-button {
      width: 44px !important;
      min-width: 44px !important;
      max-width: 44px !important;

      height: 44px !important;
      min-height: 44px !important;
      max-height: 44px !important;
    }

    .pf-home-nav {
      width: calc(100vw - 12px) !important;
      max-width: calc(100vw - 12px) !important;
    }
  }
}


/* ============================================================
   PHARMAFLOW — SÉCURITÉ SUPPLÉMENTAIRE CONTRE LE DÉBORDEMENT
   ============================================================ */

@media (max-width: 760px) {

  /*
   * Empêche les éléments positionnés, transformés ou trop larges
   * de créer une largeur virtuelle supérieure au viewport.
   */

  .pf-home {
    contain: layout paint;
  }

  .pf-home-header,
  .pf-home-hero,
  .pf-home-section,
  .pf-home-global,
  .pf-home-security,
  .pf-home-support,
  .pf-home-pricing,
  .pf-home-contact-section,
  .pf-home-final-cta,
  .pf-home-footer {
    max-width: 100vw !important;
    overflow-x: clip !important;
  }

  /*
   * Compatibilité avec les navigateurs qui ne supportent pas
   * encore correctement overflow: clip.
   */

  @supports not (overflow: clip) {
    .pf-home-header,
    .pf-home-hero,
    .pf-home-section,
    .pf-home-global,
    .pf-home-security,
    .pf-home-support,
    .pf-home-pricing,
    .pf-home-contact-section,
    .pf-home-final-cta,
    .pf-home-footer {
      overflow-x: hidden !important;
    }
  }
}
/* =========================================================
   PHARMAFLOW — VENTES / CAISSE / SCANNER CODE-BARRES
   Global CSS
   ========================================================= */

.pf-sales-scanner {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    minmax(280px, 420px)
    auto;
  gap: 12px;
  align-items: center;

  width: 100%;
  margin: 0 0 16px;
  padding: 14px;

  border: 1px solid rgba(15, 118, 110, 0.16);
  border-radius: 16px;

  background:
    linear-gradient(
      135deg,
      #f0fdfa 0%,
      #ffffff 100%
    );

  box-shadow:
    0 8px 24px rgba(15, 118, 110, 0.08);

  box-sizing: border-box;
}

/* =========================================================
   ZONE PRINCIPALE DU SCANNER
   ========================================================= */

.pf-sales-scanner-main {
  min-width: 0;

  display: flex;
  align-items: center;
  gap: 10px;
}

/* =========================================================
   ICÔNE SCANNER
   ========================================================= */

.pf-sales-scanner-icon {
  width: 40px;
  height: 40px;
  min-width: 40px;

  display: grid;
  place-items: center;

  border-radius: 12px;

  background: #0f766e;
  color: #ffffff;

  font-size: 18px;
  font-weight: 800;

  box-shadow:
    0 6px 16px rgba(15, 118, 110, 0.22);

  user-select: none;
}

/* =========================================================
   TEXTE DU SCANNER
   ========================================================= */

.pf-sales-scanner-copy {
  min-width: 0;

  display: grid;
  gap: 3px;
}

.pf-sales-scanner-copy strong {
  display: block;

  color: #134e4a;

  font-size: 13px;
  font-weight: 800;
  line-height: 1.3;
}

.pf-sales-scanner-copy span {
  display: block;

  color: #64748b;

  font-size: 11px;
  font-weight: 500;
  line-height: 1.4;
}

/* =========================================================
   BADGE MODE SCANNER
   ========================================================= */

.pf-sales-scanner-mode {
  margin-left: auto;

  flex: 0 0 auto;

  padding: 7px 10px;

  border: 1px solid rgba(15, 118, 110, 0.15);
  border-radius: 999px;

  background: #ffffff;
  color: #0f766e;

  font-size: 10px;
  font-weight: 800;

  line-height: 1;
  white-space: nowrap;

  box-shadow:
    0 2px 8px rgba(15, 118, 110, 0.06);
}

/* =========================================================
   CHAMP CODE-BARRES
   ========================================================= */

.pf-sales-scanner-input {
  width: 100%;
  min-width: 0;
  min-height: 46px;

  box-sizing: border-box;

  border: 1px solid #cbd5e1;
  border-radius: 12px;

  outline: none;

  padding: 0 14px;

  background: #ffffff;
  color: #0f172a;

  font-family: inherit;
  font-size: 14px;
  font-weight: 700;

  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    background 0.18s ease;
}

.pf-sales-scanner-input::placeholder {
  color: #94a3b8;
  font-weight: 500;
}

.pf-sales-scanner-input:hover {
  border-color: #94a3b8;
}

.pf-sales-scanner-input:focus {
  border-color: #0f766e;

  box-shadow:
    0 0 0 3px rgba(15, 118, 110, 0.13);
}

.pf-sales-scanner-input:disabled {
  cursor: not-allowed;
  opacity: 0.65;
  background: #f8fafc;
}

/* =========================================================
   BOUTON AJOUTER AU PANIER
   ========================================================= */

.pf-sales-scanner-button {
  min-height: 46px;

  border: 0;
  border-radius: 12px;

  padding: 0 17px;

  background: #0f766e;
  color: #ffffff;

  font-family: inherit;
  font-size: 12px;
  font-weight: 800;

  cursor: pointer;
  white-space: nowrap;

  box-shadow:
    0 6px 16px rgba(15, 118, 110, 0.16);

  transition:
    transform 0.15s ease,
    opacity 0.15s ease,
    background 0.15s ease,
    box-shadow 0.15s ease;
}

.pf-sales-scanner-button:hover:not(:disabled) {
  background: #115e59;

  transform: translateY(-1px);

  box-shadow:
    0 8px 18px rgba(15, 118, 110, 0.22);
}

.pf-sales-scanner-button:active:not(:disabled) {
  transform: translateY(0);

  box-shadow:
    0 4px 10px rgba(15, 118, 110, 0.14);
}

.pf-sales-scanner-button:focus-visible {
  outline: 3px solid rgba(15, 118, 110, 0.18);
  outline-offset: 2px;
}

.pf-sales-scanner-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

/* =========================================================
   ÉTAT SCANNER ACTIF
   ========================================================= */

.pf-sales-scanner.is-active {
  border-color: rgba(15, 118, 110, 0.35);

  box-shadow:
    0 0 0 3px rgba(15, 118, 110, 0.06),
    0 10px 28px rgba(15, 118, 110, 0.10);
}

/* =========================================================
   RESPONSIVE — TABLETTE
   ========================================================= */

@media (max-width: 900px) {
  .pf-sales-scanner {
    grid-template-columns:
      minmax(0, 1fr)
      minmax(220px, 1fr);
  }

  .pf-sales-scanner-main {
    grid-column: 1 / -1;
  }

  .pf-sales-scanner-button {
    width: 100%;
  }
}

/* =========================================================
   RESPONSIVE — MOBILE
   ========================================================= */

@media (max-width: 560px) {
  .pf-sales-scanner {
    grid-template-columns: 1fr;

    gap: 10px;

    padding: 12px;

    border-radius: 14px;
  }

  .pf-sales-scanner-main {
    grid-column: auto;

    align-items: flex-start;

    flex-wrap: wrap;
  }

  .pf-sales-scanner-icon {
    width: 40px;
    height: 40px;
    min-width: 40px;
  }

  .pf-sales-scanner-copy {
    flex: 1 1 calc(100% - 52px);
  }

  .pf-sales-scanner-mode {
    width: 100%;

    margin-left: 50px;

    box-sizing: border-box;

    text-align: center;
  }

  .pf-sales-scanner-input,
  .pf-sales-scanner-button {
    min-height: 48px;
  }

  .pf-sales-scanner-input {
    font-size: 14px;
  }

  .pf-sales-scanner-button {
    font-size: 13px;
  }
}

/* =========================================================
   PETITS ÉCRANS
   ========================================================= */

@media (max-width: 380px) {
  .pf-sales-scanner {
    padding: 10px;
  }

  .pf-sales-scanner-main {
    gap: 8px;
  }

  .pf-sales-scanner-icon {
    width: 36px;
    height: 36px;
    min-width: 36px;

    border-radius: 10px;

    font-size: 16px;
  }

  .pf-sales-scanner-copy strong {
    font-size: 12px;
  }

  .pf-sales-scanner-copy span {
    font-size: 10px;
  }

  .pf-sales-scanner-mode {
    margin-left: 44px;
  }
}

/* =========================================================
   ACCESSIBILITÉ
   ========================================================= */

.pf-sales-scanner-input:focus-visible,
.pf-sales-scanner-button:focus-visible {
  outline: 3px solid rgba(15, 118, 110, 0.18);
  outline-offset: 2px;
}

/* =========================================================
   IMPRESSION
   ========================================================= */

@media print {
  .pf-sales-scanner {
    display: none !important;
  }
}

/* =========================================================
   PHARMAFLOW — COMMENT ÇA MARCHE
   ========================================================= */

.pf-home-how {
  position: relative;
  overflow: hidden;
}

.pf-home-how-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  margin-top: 36px;
}

.pf-home-how-card {
  position: relative;
  min-width: 0;
  padding: 26px;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: #ffffff;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.05);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    border-color 0.2s ease;
}

.pf-home-how-card:hover {
  transform: translateY(-4px);
  border-color: rgba(15, 118, 110, 0.28);
  box-shadow: 0 16px 36px rgba(15, 118, 110, 0.10);
}

.pf-home-how-card.featured {
  border-color: rgba(15, 118, 110, 0.30);
  background: linear-gradient(145deg, #f0fdfa 0%, #ffffff 100%);
}

.pf-home-how-number {
  position: absolute;
  top: 20px;
  right: 20px;
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.08em;
}

.pf-home-how-icon {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  margin-bottom: 18px;
  border-radius: 15px;
  background: #f0fdfa;
  border: 1px solid rgba(15, 118, 110, 0.10);
  font-size: 24px;
}

.pf-home-how-card h3 {
  margin: 0 0 10px;
  color: #134e4a;
  font-size: 17px;
  font-weight: 820;
  line-height: 1.3;
}

.pf-home-how-card p {
  min-height: 70px;
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.7;
}

.pf-home-how-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 18px;
  color: #0f766e;
  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
}

.pf-home-how-link span {
  transition: transform 0.15s ease;
}

.pf-home-how-link:hover span {
  transform: translateX(4px);
}

.pf-home-how-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-top: 28px;
  padding: 22px 24px;
  border: 1px solid rgba(15, 118, 110, 0.16);
  border-radius: 18px;
  background: linear-gradient(135deg, #f0fdfa 0%, #ffffff 100%);
}

.pf-home-how-bottom-copy {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.pf-home-how-bottom-icon {
  width: 46px;
  height: 46px;
  min-width: 46px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: #0f766e;
  color: #ffffff;
  font-size: 21px;
}

.pf-home-how-bottom-copy strong {
  display: block;
  color: #134e4a;
  font-size: 14px;
  font-weight: 820;
}

.pf-home-how-bottom-copy p {
  margin: 4px 0 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.5;
}

.pf-home-how-bottom-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 0 0 auto;
}

.pf-home-how-bottom-actions .pf-home-secondary-button {
  min-height: 46px;
  padding: 0 16px;
  border: 1px solid #cbd5e1;
  border-radius: 12px;
  background: #ffffff;
  color: #134e4a;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.pf-home-how-bottom-actions .pf-home-secondary-button:hover {
  border-color: #0f766e;
  color: #0f766e;
}

@media (max-width: 1000px) {
  .pf-home-how-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pf-home-how-bottom {
    align-items: flex-start;
    flex-direction: column;
  }

  .pf-home-how-bottom-actions {
    width: 100%;
  }
}

@media (max-width: 640px) {
  .pf-home-how-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .pf-home-how-card {
    padding: 21px;
  }

  .pf-home-how-card p {
    min-height: auto;
  }

  .pf-home-how-bottom {
    padding: 18px;
  }

  .pf-home-how-bottom-copy {
    align-items: flex-start;
  }

  .pf-home-how-bottom-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .pf-home-how-bottom-actions .pf-home-primary-button,
  .pf-home-how-bottom-actions .pf-home-secondary-button {
    width: 100%;
    box-sizing: border-box;
    justify-content: center;
    text-align: center;
  }
}

/* =========================================================
   PHARMAFLOW — PAGE COMMENT ÇA MARCHE
   ========================================================= */

.pf-guide-page {
  min-height: 100vh;
  background: #f8fafc;
  color: #134e4a;
  overflow-x: hidden;
}

.pf-guide-container {
