.pf-guide-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255, 255, 255, 0.96);
  border-bottom: 1px solid #e2e8f0;
  backdrop-filter: blur(14px);
}

.pf-guide-header-inner {
  width: min(1180px, calc(100% - 40px));
  min-height: 76px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
}

.pf-guide-logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: #134e4a;
  text-decoration: none;
  font-size: 21px;
  font-weight: 900;
}

.pf-guide-logo-mark {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: linear-gradient(135deg, #0f766e, #115e59);
  color: #ffffff;
  font-size: 25px;
  font-weight: 900;
  box-shadow: 0 8px 18px rgba(15, 118, 110, 0.20);
}

.pf-guide-nav {
  display: flex;
  align-items: center;
  gap: 8px;
}

.pf-guide-nav a {
  display: inline-flex;
  align-items: center;
  min-height: 40px;
  padding: 0 13px;
  border-radius: 10px;
  color: #475569;
  text-decoration: none;
  font-size: 12px;
  font-weight: 750;
}

.pf-guide-nav a:hover {
  color: #0f766e;
  background: #f0fdfa;
}

.pf-guide-nav .pf-guide-login {
  border: 1px solid #cbd5e1;
}

.pf-guide-nav .pf-guide-register {
  background: #0f766e;
  color: #ffffff;
  border: 1px solid #0f766e;
}

.pf-guide-nav .pf-guide-register:hover {
  background: #115e59;
  color: #ffffff;
}

/* HERO */

.pf-guide-hero {
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 90px 20px;
  overflow: hidden;
  background:
    radial-gradient(circle at 20% 20%, rgba(45, 212, 191, 0.13), transparent 30%),
    radial-gradient(circle at 80% 70%, rgba(15, 118, 110, 0.16), transparent 34%),
    linear-gradient(135deg, #063f3b 0%, #0f766e 55%, #115e59 100%);
}

.pf-guide-hero-glow {
  position: absolute;
  width: 520px;
  height: 520px;
  right: -170px;
  top: -190px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.10);
  box-shadow:
    0 0 0 70px rgba(255,255,255,0.025),
    0 0 0 140px rgba(255,255,255,0.02);
}

.pf-guide-hero-content {
  position: relative;
  z-index: 2;
  width: min(900px, 100%);
  text-align: center;
}

.pf-guide-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 13px;
  border: 1px solid rgba(255,255,255,0.20);
  border-radius: 999px;
  background: rgba(255,255,255,0.08);
  color: #ccfbf1;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.08em;
}

.pf-guide-hero h1 {
  margin: 24px 0 20px;
  color: #ffffff;
  font-size: clamp(42px, 6vw, 72px);
  line-height: 1.02;
  letter-spacing: -0.045em;
  font-weight: 900;
}

.pf-guide-hero h1 span {
  display: block;
  color: #99f6e4;
}

.pf-guide-hero p {
  max-width: 730px;
  margin: 0 auto;
  color: rgba(255,255,255,0.78);
  font-size: 16px;
  line-height: 1.8;
}

.pf-guide-hero-actions {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  margin-top: 32px;
}

.pf-guide-primary,
.pf-guide-secondary {
  min-height: 48px;
  padding: 0 19px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  text-decoration: none;
  font-size: 12px;
  font-weight: 850;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.pf-guide-primary {
  background: #ffffff;
  color: #0f766e;
  box-shadow: 0 12px 28px rgba(0,0,0,0.16);
}

.pf-guide-primary:hover {
  transform: translateY(-2px);
}

.pf-guide-secondary {
  border: 1px solid #cbd5e1;
  background: #ffffff;
  color: #134e4a;
}

.pf-guide-hero .pf-guide-secondary {
  border-color: rgba(255,255,255,0.22);
  background: rgba(255,255,255,0.08);
  color: #ffffff;
}

.pf-guide-hero-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 20px;
  color: rgba(255,255,255,0.70);
  font-size: 11px;
}

.pf-guide-hero-note span {
  color: #5eead4;
  font-weight: 900;
}

/* INTRO */

.pf-guide-intro {
  padding: 90px 0;
  background: #ffffff;
}

.pf-guide-section-heading {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.pf-guide-section-heading > span,
.pf-guide-eyebrow {
  color: #0f766e;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.pf-guide-section-heading h2 {
  margin: 12px 0;
  color: #134e4a;
  font-size: clamp(28px, 4vw, 43px);
  line-height: 1.1;
  letter-spacing: -0.035em;
}

.pf-guide-section-heading p {
  margin: 0 auto;
  color: #64748b;
  font-size: 14px;
  line-height: 1.8;
}

.pf-guide-benefits {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-top: 45px;
}

.pf-guide-benefit {
  padding: 25px;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 10px 28px rgba(15,23,42,0.04);
}

.pf-guide-benefit > div {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  margin-bottom: 17px;
  border-radius: 14px;
  background: #f0fdfa;
  font-size: 22px;
}

.pf-guide-benefit h3 {
  margin: 0 0 8px;
  color: #134e4a;
  font-size: 15px;
}

.pf-guide-benefit p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.7;
}

/* STEPS */

.pf-guide-step-section {
  padding: 100px 0;
  background: #f8fafc;
}

.pf-guide-step-section.alternate {
  background: #ffffff;
}

.pf-guide-step-grid {
  display: grid;
  grid-template-columns: 70px minmax(0, 1fr) minmax(360px, 0.9fr);
  align-items: center;
  gap: 45px;
}

.pf-guide-step-number {
  align-self: start;
  color: #0f766e;
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.pf-guide-step-content h2 {
  margin: 10px 0 17px;
  color: #134e4a;
  font-size: clamp(28px, 4vw, 42px);
  line-height: 1.08;
  letter-spacing: -0.035em;
}

.pf-guide-step-content > p {
  margin: 0;
  max-width: 620px;
  color: #64748b;
  font-size: 14px;
  line-height: 1.85;
}

.pf-guide-list {
  display: grid;
  gap: 11px;
  margin-top: 25px;
}

.pf-guide-list div {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  color: #475569;
  font-size: 12px;
  line-height: 1.55;
}

.pf-guide-list span {
  width: 20px;
  height: 20px;
  min-width: 20px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #ccfbf1;
  color: #0f766e;
  font-size: 11px;
  font-weight: 900;
}

.pf-guide-inline-button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 25px;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 11px;
  background: #0f766e;
  color: #ffffff;
  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
}

.pf-guide-inline-button:hover {
  background: #115e59;
}

/* MOCKUPS */

.pf-guide-visual {
  min-width: 0;
}

.pf-guide-mockup,
.pf-guide-dashboard-mini,
.pf-guide-product-card,
.pf-guide-team-card,
.pf-guide-stat-dashboard {
  border: 1px solid #dbe5e7;
  border-radius: 22px;
  background: #ffffff;
  box-shadow: 0 22px 55px rgba(15,23,42,0.08);
}

.pf-guide-mockup {
  padding: 24px;
}

.pf-guide-mockup-top {
  display: flex;
  gap: 5px;
  margin-bottom: 24px;
}

.pf-guide-mockup-top span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #cbd5e1;
}

.pf-guide-form-icon {
  width: 55px;
  height: 55px;
  display: grid;
  place-items: center;
  margin-bottom: 14px;
  border-radius: 16px;
  background: #f0fdfa;
  font-size: 24px;
}

.pf-guide-mockup strong {
  display: block;
  color: #134e4a;
  font-size: 17px;
}

.pf-guide-input {
  height: 43px;
  display: flex;
  align-items: center;
  margin-top: 11px;
  padding: 0 13px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  color: #94a3b8;
  font-size: 11px;
}

.pf-guide-mockup-button {
  height: 43px;
  display: grid;
  place-items: center;
  margin-top: 13px;
  border-radius: 10px;
  background: #0f766e;
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
}

.pf-guide-dashboard-mini {
  padding: 22px;
}

.pf-guide-mini-header,
.pf-guide-team-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.pf-guide-mini-header strong,
.pf-guide-team-header strong {
  color: #134e4a;
  font-size: 14px;
}

.pf-guide-mini-header span {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #f0fdfa;
}

.pf-guide-mini-title {
  margin: 26px 0 15px;
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
}

.pf-guide-mini-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 13px 0;
  border-bottom: 1px solid #f1f5f9;
}

.pf-guide-mini-row span {
  color: #94a3b8;
  font-size: 11px;
}

.pf-guide-mini-row strong {
  color: #334155;
  font-size: 11px;
}

.pf-guide-success {
  margin-top: 17px;
  padding: 11px;
  border-radius: 10px;
  background: #ecfdf5;
  color: #047857;
  text-align: center;
  font-size: 11px;
  font-weight: 800;
}

/* PRODUCTS */

.pf-guide-product-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px;
  margin-bottom: 12px;
}

.pf-guide-product-icon {
  width: 48px;
  height: 48px;
  min-width: 48px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: #f0fdfa;
  font-size: 21px;
}

.pf-guide-product-info {
  min-width: 0;
  flex: 1;
}

.pf-guide-product-info strong {
  display: block;
  color: #134e4a;
  font-size: 12px;
}

.pf-guide-product-info span,
.pf-guide-product-info small {
  display: block;
  margin-top: 4px;
  color: #94a3b8;
  font-size: 10px;
}

.pf-guide-product-stock {
  text-align: right;
}

.pf-guide-product-stock strong {
  display: block;
  color: #0f766e;
  font-size: 18px;
}

.pf-guide-product-stock span {
  color: #94a3b8;
  font-size: 9px;
}

/* TEAM */

.pf-guide-role-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 25px;
}

.pf-guide-role-grid div {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px;
  border: 1px solid #e2e8f0;
  border-radius: 11px;
  background: #ffffff;
}

.pf-guide-role-grid span {
  font-size: 17px;
}

.pf-guide-role-grid strong {
  color: #334155;
  font-size: 11px;
}

.pf-guide-team-card {
  padding: 22px;
}

.pf-guide-team-header span {
  color: #0f766e;
  font-size: 10px;
  font-weight: 850;
}

.pf-guide-team-member {
  display: grid;
  grid-template-columns: 38px 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 13px 0;
  border-bottom: 1px solid #f1f5f9;
}

.pf-guide-team-member > div {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #f0fdfa;
}

.pf-guide-team-member span {
  color: #334155;
  font-size: 11px;
  font-weight: 800;
}

.pf-guide-team-member small {
  color: #94a3b8;
  font-size: 9px;
}

/* SCANNER */

.pf-guide-scanner-section {
  padding: 100px 0;
  background:
    radial-gradient(circle at 20% 20%, rgba(45,212,191,0.10), transparent 30%),
    linear-gradient(135deg, #063f3b, #0f766e);
}

.pf-guide-section-heading.light > span {
  color: #99f6e4;
}

.pf-guide-section-heading.light h2 {
  color: #ffffff;
}

.pf-guide-section-heading.light p {
  color: rgba(255,255,255,0.72);
}

.pf-guide-scanner-flow {
  display: grid;
  grid-template-columns: 1fr auto 1fr auto 1fr auto 1fr;
  align-items: center;
  gap: 10px;
  margin-top: 48px;
}

.pf-guide-scanner-card {
  position: relative;
  min-width: 0;
  min-height: 190px;
  padding: 22px;
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 18px;
  background: rgba(255,255,255,0.08);
  backdrop-filter: blur(10px);
}

.pf-guide-scanner-icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  margin-bottom: 20px;
  border-radius: 13px;
  background: rgba(255,255,255,0.10);
  font-size: 22px;
}

.pf-guide-scanner-number {
  position: absolute;
  top: 17px;
  right: 17px;
  color: rgba(255,255,255,0.35);
  font-size: 10px;
  font-weight: 900;
}

.pf-guide-scanner-card h3 {
  margin: 0 0 8px;
  color: #ffffff;
  font-size: 14px;
}

.pf-guide-scanner-card p {
  margin: 0;
  color: rgba(255,255,255,0.65);
  font-size: 11px;
  line-height: 1.6;
}

.pf-guide-scanner-arrow {
  color: #99f6e4;
  font-size: 23px;
  font-weight: 900;
}

.pf-guide-scanner-example {
  width: min(650px, 100%);
  margin: 45px auto 0;
  padding: 22px;
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 20px;
  background: #ffffff;
  box-shadow: 0 25px 60px rgba(0,0,0,0.18);
}

.pf-guide-scanner-example-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding-bottom: 15px;
  border-bottom: 1px solid #e2e8f0;
}

.pf-guide-scanner-example-header span {
  display: block;
  color: #94a3b8;
  font-size: 10px;
}

.pf-guide-scanner-example-header strong {
  display: block;
  margin-top: 4px;
  color: #134e4a;
  font-size: 14px;
}

.pf-guide-cart-count {
  padding: 7px 10px;
  border-radius: 8px;
  background: #f0fdfa;
  color: #0f766e;
  font-size: 10px;
  font-weight: 800;
}

.pf-guide-cart-item {
  display: grid;
  grid-template-columns: 38px 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 14px 0;
  border-bottom: 1px solid #f1f5f9;
}

.pf-guide-cart-item > span {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #f0fdfa;
}

.pf-guide-cart-item strong {
  color: #334155;
  font-size: 11px;
}

.pf-guide-cart-item small {
  display: block;
  margin-top: 3px;
  color: #94a3b8;
  font-size: 9px;
}

.pf-guide-cart-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 17px 0;
}

.pf-guide-cart-total span {
  color: #64748b;
  font-size: 11px;
}

.pf-guide-cart-total strong {
  color: #0f766e;
  font-size: 19px;
}

.pf-guide-cart-button {
  min-height: 44px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #0f766e;
  color: #ffffff;
  font-size: 11px;
  font-weight: 850;
}

/* STATS */

.pf-guide-stat-dashboard {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 18px;
}

.pf-guide-stat {
  padding: 17px;
  border-radius: 13px;
  background: #f8fafc;
}

.pf-guide-stat span {
  display: block;
  color: #64748b;
  font-size: 10px;
}

.pf-guide-stat strong {
  display: block;
  margin: 6px 0 2px;
  color: #134e4a;
  font-size: 22px;
}

.pf-guide-stat small {
  color: #94a3b8;
  font-size: 9px;
}

.pf-guide-stat.warning {
  background: #fffbeb;
}

.pf-guide-chart-box {
  grid-column: 1 / -1;
  padding: 17px;
  border-radius: 13px;
  background: #f8fafc;
}

.pf-guide-chart-title {
  color: #64748b;
  font-size: 10px;
  font-weight: 800;
}

.pf-guide-chart-bars {
  height: 90px;
  display: flex;
  align-items: flex-end;
  gap: 8px;
  margin-top: 14px;
}

.pf-guide-chart-bars i {
  flex: 1;
  min-width: 8px;
  height: 40%;
  border-radius: 5px 5px 2px 2px;
  background: #0f766e;
}

.pf-guide-chart-bars i:nth-child(2) {
  height: 62%;
}

.pf-guide-chart-bars i:nth-child(3) {
  height: 48%;
}

.pf-guide-chart-bars i:nth-child(4) {
  height: 75%;
}

.pf-guide-chart-bars i:nth-child(5) {
  height: 58%;
}

.pf-guide-chart-bars i:nth-child(6) {
  height: 88%;
}

.pf-guide-chart-bars i:nth-child(7) {
  height: 70%;
}

/* SUMMARY */

.pf-guide-summary {
  padding: 90px 0;
  background: #ffffff;
}

.pf-guide-summary-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 25px;
  padding: 32px;
  border: 1px solid rgba(15,118,110,0.15);
  border-radius: 22px;
  background: linear-gradient(135deg, #f0fdfa, #ffffff);
}

.pf-guide-summary-icon {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: #0f766e;
  color: #ffffff;
  font-size: 25px;
}

.pf-guide-summary-card > div:nth-child(2) > span {
  color: #0f766e;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.pf-guide-summary-card h2 {
  margin: 7px 0;
  color: #134e4a;
  font-size: 21px;
}

.pf-guide-summary-card p {
  max-width: 680px;
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.7;
}

.pf-guide-summary-actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

/* FOOTER */

.pf-guide-footer {
  background: #073f3b;
  color: #ffffff;
}

.pf-guide-footer-inner {
  width: min(1180px, calc(100% - 40px));
  padding: 50px 0;
  margin: 0 auto;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 40px;
}

.pf-guide-footer .pf-guide-logo {
  color: #ffffff;
}

.pf-guide-footer .pf-guide-logo-mark {
  background: #ffffff;
  color: #0f766e;
}

.pf-guide-footer p {
  max-width: 350px;
  margin: 13px 0 0;
  color: rgba(255,255,255,0.58);
  font-size: 11px;
  line-height: 1.6;
}

.pf-guide-footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.pf-guide-footer-links a {
  color: rgba(255,255,255,0.72);
  text-decoration: none;
  font-size: 11px;
  font-weight: 700;
}

.pf-guide-footer-links a:hover {
  color: #99f6e4;
}

.pf-guide-footer-bottom {
  padding: 18px 20px;
  border-top: 1px solid rgba(255,255,255,0.10);
  color: rgba(255,255,255,0.45);
  text-align: center;
  font-size: 10px;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1050px) {
  .pf-guide-benefits {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pf-guide-step-grid {
    grid-template-columns: 50px minmax(0, 1fr);
    gap: 28px;
  }

  .pf-guide-visual {
    grid-column: 2;
  }

  .pf-guide-scanner-flow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pf-guide-scanner-arrow {
    display: none;
  }
}

@media (max-width: 760px) {
  .pf-guide-container,
  .pf-guide-header-inner,
  .pf-guide-footer-inner {
    width: min(100% - 28px, 600px);
  }

  .pf-guide-header-inner {
    min-height: 65px;
  }

  .pf-guide-nav {
    gap: 3px;
  }

  .pf-guide-nav a {
    padding: 0 8px;
    font-size: 10px;
  }

  .pf-guide-nav a:not(.pf-guide-login):not(.pf-guide-register) {
    display: none;
  }

  .pf-guide-hero {
    min-height: auto;
    padding: 70px 14px;
  }

  .pf-guide-hero h1 {
    font-size: 43px;
  }

  .pf-guide-hero p {
    font-size: 13px;
  }

  .pf-guide-hero-actions {
    flex-direction: column;
  }

  .pf-guide-hero-actions a {
    width: 100%;
    box-sizing: border-box;
  }

  .pf-guide-intro,
  .pf-guide-step-section,
  .pf-guide-scanner-section,
  .pf-guide-summary {
    padding: 65px 0;
  }

  .pf-guide-benefits {
    grid-template-columns: 1fr;
  }

  .pf-guide-step-grid {
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .pf-guide-step-number {
    font-size: 13px;
  }

  .pf-guide-step-content h2 {
    font-size: 30px;
  }

  .pf-guide-visual {
    grid-column: auto;
  }

  .pf-guide-product-card {
    padding: 14px;
  }

  .pf-guide-scanner-flow {
    grid-template-columns: 1fr;
  }

  .pf-guide-scanner-card {
    min-height: auto;
  }

  .pf-guide-summary-card {
    grid-template-columns: 1fr;
    padding: 23px;
  }

  .pf-guide-summary-actions {
    width: 100%;
  }

  .pf-guide-summary-actions a {
    width: 100%;
    box-sizing: border-box;
  }

  .pf-guide-footer-inner {
    flex-direction: column;
    padding: 38px 0;
  }
}

@media (max-width: 480px) {
  .pf-guide-logo {
    font-size: 17px;
  }

  .pf-guide-logo-mark {
    width: 33px;
    height: 33px;
    font-size: 21px;
  }

  .pf-guide-nav .pf-guide-login {
    display: none;
  }

  .pf-guide-hero h1 {
    font-size: 36px;
  }

  .pf-guide-section-heading h2 {
    font-size: 29px;
  }

  .pf-guide-role-grid {
    grid-template-columns: 1fr;
  }

  .pf-guide-stat-dashboard {
    grid-template-columns: 1fr;
  }

  .pf-guide-chart-box {
    grid-column: auto;
  }

  .pf-guide-cart-item {
    grid-template-columns: 34px 1fr;
  }

  .pf-guide-cart-item > strong {
    grid-column: 2;
  }

  .pf-guide-footer-links {
    flex-direction: column;
  }
}